  FT["PH-H1766"] = {"id":"PH-H1766","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1957/ra_2020_1957.html","fetchedAt":"2026-10-06","articleCount":2,"structureMode":"ARTICLE","title":{"zh":"将碧瑶市Loakan小学的名称正式变更为Malvar小学的法案","en":"An Act Changing the Name of the Loakan Elementary School in the City of Baguio to Malvar Elementary School","orig":"An Act Changing the Name of the Loakan Elementary School in the City of Baguio to Malvar Elementary School"},"level":"law","status":"active","topics":["education"],"docNumber":"Republic Act No. 2020","issuingBody":"Congress of the Philippines","promulgatedDate":"1957-06-22","completenessNote":"全文，共 2 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1957/ra_2020_1957.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H1766-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"The name of the Loakan Elementary School in the City of Baguio is hereby changed to Malvar Elementary School."}},{"id":"PH-H1766-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 22, 1957."}}],"pack":"ph-p25","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act Changing the Name of the Loakan Elementary School in the City of Baguio to Malvar Elementary School","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H1767"] = {"id":"PH-H1767","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1957/ra_2021_1957.html","fetchedAt":"2026-10-06","articleCount":6,"structureMode":"ARTICLE","title":{"zh":"在东米萨米斯省设立卡米金次省的法案","en":"An Act Creating the Subprovince of Camiguin in the Province of Misamis Oriental","orig":"An Act Creating the Subprovince of Camiguin in the Province of Misamis Oriental"},"level":"law","status":"active","topics":["general"],"docNumber":"Republic Act No. 2021","issuingBody":"Congress of the Philippines","promulgatedDate":"1957-06-22","completenessNote":"全文，共 6 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1957/ra_2021_1957.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H1767-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"The island of Camiguin and all the municipalities comprised therein are constituted into a subprovince of the Province of Misamis Oriental to be known as the Subprovince of Camiguin, with the seat of government in the Municipality of Mambajao."}},{"id":"PH-H1767-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"The provisions of sections twenty-one hundred thirty-seven, twenty-one hundred thirty-eight, twenty-one hundred thirty-nine, twenty-one hundred forty, twenty-one hundred forty-one, twenty-one hundred forty-two, and twenty-one hundred forty-three of the Administrative Code, as amended, shall apply to the Subprovince of Camiguin."}},{"id":"PH-H1767-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"The Subprovince of Camiguin shall constitute a separate engineering district."}},{"id":"PH-H1767-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"The lieutenant-governor of the Subprovince of Camiguin shall receive a compensation of three thousand six hundred pesos per annum."}},{"id":"PH-H1767-A5","no":5,"noLabel":{"en":"Section 5."},"text":{"en":"The first lieutenant-governor of the Subprovince of Camiguin shall be elected in the elections immediately following the approval of this Act, and shall hold office until his successor shall have been elected in the next general elections for provincial and municipal officials and shall have qualified to said office."}},{"id":"PH-H1767-A6","no":6,"noLabel":{"en":"Section 6."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 22, 1957."}}],"pack":"ph-p25","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act Creating the Subprovince of Camiguin in the Province of Misamis Oriental","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H1768"] = {"id":"PH-H1768","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1957/ra_2022_1957.html","fetchedAt":"2026-10-06","articleCount":2,"structureMode":"ARTICLE","title":{"zh":"将巴拉望省Balabac市镇区改设为正规市镇的法案","en":"An Act Converting the Municipal District of Balabac, Province of Palawan, into a Regular Municipality","orig":"An Act Converting the Municipal District of Balabac, Province of Palawan, into a Regular Municipality"},"level":"law","status":"active","topics":["general"],"docNumber":"Republic Act No. 2022","issuingBody":"Congress of the Philippines","promulgatedDate":"1957-06-22","completenessNote":"全文，共 2 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1957/ra_2022_1957.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H1768-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"The Municipal District of Balabac, Province of Palawan, is converted into a regular municipality of said province, to be known as the Municipality of Balabac."}},{"id":"PH-H1768-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 22, 1957."}}],"pack":"ph-p25","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act Converting the Municipal District of Balabac, Province of Palawan, into a Regular Municipality","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H1769"] = {"id":"PH-H1769","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1957/ra_2023_1957.html","fetchedAt":"2026-10-06","articleCount":155,"structureMode":"ARTICLE","title":{"zh":"一般合作社基本法","en":"An Act to Provide the General Basic Cooperative Law and to Consolidate and Amend Existing Laws on Non-Agricultural Co-Operatives in the Philippines with Special Provisions for Given Types of Co-Operatives","orig":"An Act to Provide the General Basic Cooperative Law and to Consolidate and Amend Existing Laws on Non-Agricultural Co-Operatives in the Philippines with Special Provisions for Given Types of Co-Operatives"},"level":"law","status":"active","topics":["company","environment"],"docNumber":"Republic Act No. 2023","issuingBody":"Congress of the Philippines","promulgatedDate":"1957-06-22","completenessNote":"全文，共 155 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1957/ra_2023_1957.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H1769-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"Short title. This Act shall be known as the \"Philippine Non-Agricultural Co-operative Act.\""}},{"id":"PH-H1769-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"Declaration of policy and objectives. It is hereby declared to be the policy of Congress to assist the people to develop their enterprises on a co-operative basis to strengthen their economic independence within the framework of this Act by the promotion of organized methods of industrial production, marketing, distribution and credit, the improvement of processes and other activities and the removal of conditions which hamper the growth of a rising standard of living with a view to promote the general well-being of the people and to expand the national economy.\nIn furtherance of this policy, the Government shall encourage and assist in the establishment of a system of co-operative banks all over the country which shall provide banking facilities and reasonable credit for the non-agricultural co-operatives and encourage the distribution of consumer requirements through co-operatives by the establishment of a system of co-operative wholesale societies all over the country which shall provide steady and wholesale source of consumer requirements and act as a link between producers and consumers co-operatives by adopting a policy of gradual transfer of the business of procurement of consumer requirements from the National Marketing Corporation (NAMARCO) to the Philippine Co-operative Wholesale Society.\nTo achieve this policy, the Central Bank of the Philippines, the Department of Commerce and Industry and all other departments, agencies or instrumentalities of the Government shall, in cooperation with the Administrator, provide technical guidance, financial assistance and other facilities to develop a sound and stable co-operative movement in the Philippines."}},{"id":"PH-H1769-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"Definitions. As used in this Act and unless a different meaning is intended in the context\n(1) \"Co-operative\" means a non-profit organization of natural or juridical persons registered in accordance with this Act to achieve common benefits of an economic and social character on a co-operative basis; \"Co-operative\" refers to non-agricultural co-operatives.\n(2) \"Co-operative basis\" includes\n(a) open and voluntary membership;\n(b) democratic control one member one vote;\n(c) limited interest on capital not exceeding the limitations provided in this Act; and\n(d) distribution of savings to members in proportion to their participation in the business of the co-operative.\n(3) \"Federation of Co-operatives\" means a co-operative the primary object of which is to co-ordinate and facilitate the activities of its member co-operatives and to foster the growth of the co-operative movement;\n(4) \"Member\" includes both a person who subscribes to the articles of incorporation of a co-operative and a person, either natural or juridical, who agrees to join the co-operative and is admitted to membership after registration in accordance with the by-laws and the regulations promulgated under this Act;\n(5) \"Regulations\" means the regulations promulgated under this Act;\n(6) \"By-laws\" means the by-laws registered under this Act and includes a registered amendment of the by-laws;\n(7) \"Board\" means the board of directors to whom the management of the affairs of the co-operative is entrusted under Section 38 of this Act; and\n(8) \"Administrator\" means the administrator of the Co-operatives Administration Office."}},{"id":"PH-H1769-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"Scope. (1) Every co-operative under the jurisdiction of the Co-operatives Administration Office existing at the time of the approval of this Act which has been registered under existing co-operative laws (Commonwealth Act five hundred sixty-five, Act twenty-five hundred eight and Act thirty-four hundred twenty-five, all as amended) shall be deemed to be registered under this Act, and its by-laws shall, so far as they are not inconsistent with the provisions of this Act, continue in force and be deemed to be registered under this Act.\n(2) All executive and administrative orders, rules and regulations and notices issued, all transactions entered into and suits and proceedings instituted under the said Acts shall be deemed, so far as may be, to have been issued, entered into, or instituted under this Act."}},{"id":"PH-H1769-A5","no":5,"noLabel":{"en":"Section 5."},"text":{"en":"References. Upon the approval of this Act, all references to existing laws affecting non-agricultural co-operatives shall be construed as references to this Act, and no proceedings instituted and pending or anything done shall be deemed to have been invalid on the ground that such laws did not refer to this Act."}},{"id":"PH-H1769-A6","no":6,"noLabel":{"en":"Section 6."},"text":{"en":"Exemption of co-operatives from certain provisions of the Act. Upon recommendation of the Administrator, the Secretary of Commerce and Industry may, by regulation to be published in the Official Gazette, exempt any co-operative or type of co-operatives from any of the provisions of this Act, or may direct that such provisions shall apply to such co-operative or type of co-operatives with such modifications as may be specified in the regulation: Provided, however, That no regulation shall be issued without giving to such co-operative or type of co-operatives an opportunity to present its case."}},{"id":"PH-H1769-A7","no":7,"noLabel":{"en":"Section 7."},"text":{"en":"Corporation Law not applicable. The provisions of the Corporation Law shall not apply to co-operatives.\nAdministrator"}},{"id":"PH-H1769-A8","no":8,"noLabel":{"en":"Section 8."},"chapter":{"en":"CHAPTER II"},"text":{"en":"The Administrator. (1) The Administrator of the Co-operatives Administration Office under the Department of Commerce and Industry is hereby charged with the administration of this Act. There shall be one or more assistant administrator for each type of co-operative who shall be appointed by the President of the Philippines with the consent of the Commission on Appointments. Each assistant administrator shall receive an annual compensation which shall be fixed by the President at the time of his appointment.\n(2) No person shall be appointed Administrator or Assistant Administrator unless he possesses the following qualifications:\n(a) He must be a holder of at least a bachelor's degree from a university or college recognized by the Government, and\n(b) He must have at least five years experience in co-operatives, either as an officer of a co-operative or of a government agency engaged in the development of co-operatives.\nOrganization and Registration"}},{"id":"PH-H1769-A9","no":9,"noLabel":{"en":"Section 9."},"chapter":{"en":"CHAPTER III"},"text":{"en":"Purposes. A co-operative may be registered for the mutual benefit of the members thereof, who have for their common objective any lawful purpose or purposes, on a co-operative basis, more particularly those noted hereunder\n(1) To encourage thrift among the members;\n(2) To create funds and extend credit to the members for productive and provident purposes;\n(3) To encourage scientific production and marketing among the members;\n(4) To provide goods, services and other requirements to the members;\n(5) To build houses or to acquire lands for the members;\n(6) To insure against losses of the members;\n(7) To promote and advance the economic, social and educational condition of the members;\n(8) To undertake such other activities calculated to help the members to solve their problems on a co-operative basis; and\n(9) To co-ordinate and facilitate the activities of co-operatives."}},{"id":"PH-H1769-A10","no":10,"noLabel":{"en":"Section 10."},"chapter":{"en":"CHAPTER III"},"text":{"en":"Service motive. The object to every co-operative shall be to provide maximum service to its members, not to earn the most profit for its members nor to operate the business for charitable purposes."}},{"id":"PH-H1769-A11","no":11,"noLabel":{"en":"Section 11."},"chapter":{"en":"CHAPTER III"},"text":{"en":"Legality declared; not in restraint of trade. No co-operative or method or act thereof which complies with this Act shall be deemed a conspiracy or combination in restraint of trade or an illegal monopoly, or an attempt to lessen competition or fix prices arbitrarily in violation of any of the laws of the Philippines."}},{"id":"PH-H1769-A12","no":12,"noLabel":{"en":"Section 12."},"chapter":{"en":"CHAPTER III"},"text":{"en":"Who may organize. Fifteen or more persons, citizens of the Philippines who are either ultimate consumers or primary producers and residing in the proposed area of operation of a co-operative, may organize a co-operative under this Act: Provided, That two or more co-operatives may unite to organize a federation of co-operatives."}},{"id":"PH-H1769-A13","no":13,"noLabel":{"en":"Section 13."},"chapter":{"en":"CHAPTER III"},"text":{"en":"Survey and application. Every group of persons or co-operatives contemplating the organization of a co-operative under this Act, shall undertake a survey to draw up a program of activities, indicating the area of operation, the field of membership initial and potential and other data as may be required by the Administrator to enable him to determine the economic need and the advisability for registering the proposed co-operative. Such group of persons or cooperatives may thereupon apply to the Administrator for the registration of the co-operative."}},{"id":"PH-H1769-A14","no":14,"noLabel":{"en":"Section 14."},"chapter":{"en":"CHAPTER III"},"text":{"en":"Co-operatives which may be registered. Subject to the provisions of this Act and of regulations issued pursuant hereunder, a co-operative which has as its purposes one or more of those specified in section nine may be registered under this Act, with or without limited liability: Provided, That the liability of a co-operative which has a co-operative as a member shall be limited."}},{"id":"PH-H1769-A15","no":15,"noLabel":{"en":"Section 15."},"chapter":{"en":"CHAPTER III"},"text":{"en":"Administrator to decide certain questions. The Administrator shall decide all questions as to whether the articles of incorporation and the by-laws comply with the provisions of this Act and the regulations and whether the purposes of the proposed co-operatives are in accordance with section nine."}},{"id":"PH-H1769-A16","no":16,"noLabel":{"en":"Section 16."},"chapter":{"en":"CHAPTER III"},"text":{"en":"Articles of incorporation. (1) Articles of incorporation of a proposed co-operative shall be signed by each of the subscribers and acknowledged by them if natural persons, and by the presidents or secretaries if co-operatives, before a notary public or other officers authorized to take acknowledgments.\n(2) The articles of incorporation shall, within the limitations of this Act, set forth:\n(a) The name of the co-operative which shall include the word \"co-operative\"; the co-operative registered under this Act with unlimited liability shall also include at the end of its name the word \"unlimited\";\n(b) The purpose or purposes for which the co-operative is to be registered;\n(c) The term of existence of the co-operative which may be perpetual;\n(d) The area of operation and the postal address of its principal office;\n(e) The names, nationality and the postal addresses of the subscribers;\n(f) The field of membership;\n(g) The names and postal addresses of the directors who shall manage the co-operative for the first term;\n(h) A statement of whether the co-operative is to be registered with or without capital stock and the number of shares of stock or membership subscribed for;\n(i) If with capital stock, a statement of the amount of authorized capital, the number and types of shares and the par value thereof which may be placed at any figure, and the rights, preferences and restrictions of each type of shares; and the number and amount of capital stock subscribed for and the amount paid thereon by each member, indicating their names and postal addresses;\n(j) If without capital stock, a statement of whether the property rights of members shall be equal or unequal, and, if unequal, the general rule or rules by which the rights and interests of each member shall be determined and fixed;\n(k) The articles of incorporation may also contain any other provisions not inconsistent with this Act or any other law, for the conduct of the business affairs of the co-operative.\n(3) Four copies each of the articles of incorporation, proposed by-laws and the result of the survey required under section thirteen together with the bond of the accountable officers in such amount as may be prescribed in regulations, shall be submitted to the Administrator for registration.\n(4) The Administrator shall not register a co-operative unless the articles of incorporation is accompanied by a sworn statement of the treasurer elected by the subscribers showing:\n(a) In the case of a co-operative with capital stock, that at least twenty per centum of the number of authorized shares of capital stock has been subscribed and that at least twenty per centum of the subscription has been either paid to him in cash or that there has been transferred to him in trust and received by him property the fair valuation of which is equal to twenty per centum of the subscriptions; or\n(b) In the case of a co-operative without capital stock, the number of members and the amount of their capital contribution either paid to him in cash or that there has been transferred to him in trust and received by him property the fair valuation of which is equal to the capital contribution of the members; under both clauses (a) and (b) of this subsection, for the benefit and to the credit of the co-operative, and further, that the Administrator shall satisfy himself that the capital contribution of members under this subsection is sufficient for the initial operation of the co-operative."}},{"id":"PH-H1769-A17","no":17,"noLabel":{"en":"Section 17."},"chapter":{"en":"CHAPTER III"},"text":{"en":"Adoption of by-laws; contents. (1) Each co-operative to be registered under this Act shall adopt for its management a code of by-laws not inconsistent with the powers granted by this Act. The by-laws shall be filed with the Administrator at the time of filing the articles of incorporation and shall take effect upon registration and issuance of a certificate of registration by the Administrator.\n(2) The by-laws of each co-operative shall provide for\n(a) The qualifications for admission to membership and the payment to be made or interest to be acquired as a condition to the exercise of the right of membership;\n(b) The rights and liabilities of membership;\n(c) The circumstances under which the withdrawal and the expulsion of members shall be permitted;\n(d) The procedure to be followed in cases of withdrawal, ineligibility and/or death of members;\n(e) The conditions under which the transfer of a share or interest of the member shall be permitted;\n(f) The time, place and manner of calling and conducting assemblies and meetings and the right of voting;\n(g) The general conduct of the business of the co-operative, including the powers and duties of directors, officers and committee members;\n(h) The manner in which the capital may be raised and the purposes for which it can be utilized;\n(i) The mode of custody and of investment of surplus funds;\n(j) The manner of keeping accounts;\n(k) The method of distribution of net savings;\n(l) The manner of adopting, amending, repealing and abrogating by-laws;\n(m) In case of co-operatives loaning funds;\n(i) the conditions governing the granting of loans, the determination of the maximum and normal credit of members and the maximum loan which may be granted to a member, (ii) the rate of interest on loans, (iii) the purposes for which the loans may be granted, (iv) the security for payment of loans,\nv) the period of repayment of loans, and (vi) the extension of the period of payment and renewal of loans, and\n(n) Other matters incident to the purposes and activities of the co-operative."}},{"id":"PH-H1769-A18","no":18,"noLabel":{"en":"Section 18."},"chapter":{"en":"CHAPTER III"},"text":{"en":"Registration. (1) If the Administrator is satisfied that a co-operative has complied with the provisions of this Act and the regulations, and that its proposed articles of incorporation and by-laws are not contrary thereto, he may register the co-operative. The articles of incorporation and by-laws shall become operative only upon registration and issuance of a certificate to that effect by the Administrator.\n(2) If the Administrator refuses to register a co-operative, he shall record the reasons for his refusal. An appeal shall lie to the Secretary of Commerce and Industry from an order of the Administrator refusing to register a co-operative within two months from the date of the receipt of such order by the secretary of the proposed co-operative, and the decision of the Secretary of Commerce and Industry on the matter shall be final."}},{"id":"PH-H1769-A19","no":19,"noLabel":{"en":"Section 19."},"chapter":{"en":"CHAPTER III"},"text":{"en":"Evidence of registration. A certificate of registration signed by the Administrator under his official seal shall be conclusive evidence that the co-operative therein mentioned is duly registered unless it is proven that the registration of the co-operative has been cancelled."}},{"id":"PH-H1769-A20","no":20,"noLabel":{"en":"Section 20."},"chapter":{"en":"CHAPTER III"},"text":{"en":"Amendment of articles of incorporation and by-laws. (1) The articles of incorporation and by-laws made under this Act and the regulations may be amended, repealed or abrogated by general assemblies of members and shall take effect upon registration thereof and the issuance of the corresponding certificate by the Administrator.\n(2) If the Administrator refuses to register an amendment, repeal or abrogation under subsection (1), he shall record the reasons for his refusal. An appeal shall lie to the Secretary of Commerce and Industry from an order of the Administrator refusing to register the amendment, repeal or abrogation within two months from the date of the receipt of such order by the secretary of the co-operative and the decision of the Secretary of Commerce and Industry on the matter shall be final."}},{"id":"PH-H1769-A21","no":21,"noLabel":{"en":"Section 21."},"chapter":{"en":"CHAPTER III"},"text":{"en":"Change of liability. A co-operative may, subject to the provisions of this Act and to any regulations made in this behalf, change its liability by amending its articles of incorporation and by-laws, provided that:\n(1) The co-operative shall give notice, both by publication in a newspaper of general circulation and by posting in a conspicuous place in the locality where the co-operative has its principal office, of its intention to change its liability to all its members and creditors;\n(2) Any member or creditor shall, notwithstanding any by-laws or contract to the contrary, have the option of withdrawing his interest in the co-operative within three months of the service of such notice on him and the change shall not take effect until all such claims have been satisfied; and\n(3) Any member or creditor, who does not exercise his option within the period aforesaid, shall be deemed to have assented to the change: Provided, That the change shall take effect at once if all the members and creditors assent thereto."}},{"id":"PH-H1769-A22","no":22,"noLabel":{"en":"Section 22."},"chapter":{"en":"CHAPTER III"},"text":{"en":"Power of federation of co-operatives to direct amendment of by-laws. (1) Subject to the regulations, whenever it appears to a federation of co-operatives that an amendment of the by-laws of a co-operative which is a member and a debtor of such federation is necessary or desirable in the interest of such co-operative, it may in the prescribed manner, call upon the co-operative to make the amendment within such time as it may specify.\n(2) If the co-operative fails to make the amendment or repay the loan within the time specified, the federation may expel the co-operative from membership and take action to collect the loan."}},{"id":"PH-H1769-A23","no":23,"noLabel":{"en":"Section 23."},"chapter":{"en":"CHAPTER III"},"text":{"en":"Division of co-operatives. Any co-operative registered under this Act may, by a resolution approved by a vote of three-fourths of the members present and eligible to vote at a general assembly specifically convened for the purpose, resolve to divide itself into two or more co-operatives. The procedure for such division shall be prescribed in the regulations. The new co-operatives shall become legally established upon registration by the Administrator."}},{"id":"PH-H1769-A24","no":24,"noLabel":{"en":"Section 24."},"chapter":{"en":"CHAPTER III"},"text":{"en":"Transfer of assets and liabilities of co-operatives. (1) Any co-operative registered under this Act may, by a resolution approved by a vote of three-fourths of the members present and eligible to vote at a general assembly held for the purpose, resolve to transfer its assets and liabilities to any other co-operative which has expressed willingness to accept them by a resolution of its general assembly. The resolution shall become effective upon approval by the Administrator and cancellation of the registration of the co-operative transferring its assets and liabilities.\n(2) Any two or more co-operatives registered under this Act may, by a resolution approved by a vote of three-fourths of the members present and eligible to vote at a general assembly of each such co-operative held for the purpose, resolve to join together as a single co-operative. The resolution shall become effective upon the approval and registration of the new co-operative and the cancellation of the registration of the co-operatives which have ceased to exist.\n(3) The procedure to be followed under this section shall be prescribed in the regulations."}},{"id":"PH-H1769-A25","no":25,"noLabel":{"en":"Section 25."},"chapter":{"en":"CHAPTER III"},"text":{"en":"Federation of co-operatives. (1) A federation of co-operatives may be registered under this Act for any or all of the following purposes:\n(a) To carry on any co-operative enterprise authorized under section nine;\n(b) To carry on, encourage and assist educational and advisory work relating to co-operation;\n(c) To render service designed to insure efficiency and uniformity in the conduct of the business of its member co-operatives and to standardize their bookkeeping, accounting and other procedures;\n(d) To print, publish and circulate any newspaper or other publication in the interest of co-operative enterprises, principles or practices;\n(e) To co-ordinate and facilitate the activities of its member co-operative and do all other things incidental and conducive to the attainment of its objects; and\n(f) To discharge other duties prescribed by the regulations. A federation of co-operatives may be registered by carrying out the formalities provided under this Chapter for registration of a co-operative. No federation of co-operatives shall be registered without the previous approval of the Secretary of Commerce and Industry.\n(2) The Secretary of Commerce and Industry, upon recommendation of the Administrator, shall have the power to issue regulations regarding the organization, registration, administration, operation and supervision of federations of co-operatives, and in particular on the duties of federations of co-operatives; the procedure and conditions for the affiliation of co-operatives, the conditions under which natural persons may become members of federations of co-operatives, the representation of members and the composition of its board of directors and committees; and the manner of holding general assemblies, voting and other matters as may be prescribed.\n(3) Co-operatives registered under this Act within a province may unite to register as a provincial federation of co-operatives according to the type of business carried on. There shall not be more than one federation of co-operatives of a type within a province. A provincial federation of co-operatives may, with the approval of the Administrator and the central federation of co-operatives of which it is a member, extend its operation to neighboring provinces until such time as its operation can be taken over by a similar federation of co-operatives registered in each one of the provinces. Large cities shall, with the approval of the Administrator, be treated as a province in so far as the registration of provincial federations of co-operatives are concerned.\n(4) Each type of provincial federations of co-operatives may unite to register only one central federation of co-operatives at the national level, to which shall be affiliated all federations of co-operatives and co-operatives having common economic, social and administrative objectives.\n(5) There shall be registered only one national co-operative union at the national level to which all types of co-operatives, provincial and central federations of co-operatives, shall affiliate. The co-operative union shall have the following duties:\n(a) To represent all the co-operatives in the Philippines at home and abroad;\n(b) To acquire, analyze and disseminate economic, statistical and other information regarding co-operatives;\n(c) To conduct studies in the economic, legal, financial, social and other phases of co-operation, and publish the results thereof;\n(d) To promote the knowledge of co-operative principles and practices;\n(e) To develop the co-operative movement in the Philippines within the framework of the economic plan of the Government;\n(f) To supervise federations of co-operatives; and\n(g) To advise the appropriate authorities on all questions relating to co-operatives.\nMembership"}},{"id":"PH-H1769-A26","no":26,"noLabel":{"en":"Section 26."},"chapter":{"en":"CHAPTER IV"},"text":{"en":"Qualifications of members. (1) Any natural person, co-operative or any nonprofit group shall be eligible for membership in a co-operative if the applicant meets the qualifications prescribed in the regulations and the by-laws. An applicant for membership shall be deemed a member after approval of his membership by the board of directors and shall exercise the rights of a member after having made such payment to the co-operative in respect of membership or acquired interest in the co-operative as may be prescribed by the regulations and the by-laws.\n(2) Notwithstanding the provisions of any law or regulation, officers or employees of the Government shall be eligible for membership in any co-operative if he meets the qualifications therefor and he shall not be precluded from being elected to any elective position in the co-operative of which he is a member and to hold office therein, or from receiving compensation therefor: Provided, That elective officers of the Government shall be ineligible to become officers and directors of any co-operative. For this purpose, individual permission need not be obtained from the proper head of office: Provided, however, That this authority shall not be construed to permit the use of official time.\n(3) Membership in a co-operative shall be voluntary and open to all persons residing in the area of operation and falling within the field of membership, provided they meet the qualifications prescribed in the by-laws and are admitted as members by the board of directors: Provided, however, That no person shall be eligible to borrow from more than one co-operative. In case membership is refused or denied by the board of directors, an appeal may be made to the general assembly of the co-operative, the decision of which shall be final."}},{"id":"PH-H1769-A27","no":27,"noLabel":{"en":"Section 27."},"chapter":{"en":"CHAPTER IV"},"text":{"en":"Members to furnish information. A statement of assets and liabilities duly certified to be correct and true, in such form as may be prescribed, shall be furnished under oath:\n(a) By an applicant for membership of co-operative with unlimited liability at the time of his admission to membership, at the close of each fiscal year, and at any other time as may be required by the co-operative;\n(b) By a member of a co-operative with unlimited liability when required to do so by the Administrator or any person authorized by him;\n(c) By a member of any other co-operative at the time of any application for a loan or credit line or for acceptance as surety."}},{"id":"PH-H1769-A28","no":28,"noLabel":{"en":"Section 28."},"chapter":{"en":"CHAPTER IV"},"text":{"en":"Liability of member. (1) In the case of a co-operative with limited liability a member shall be liable for the debts of the co-operative to the extent of the unpaid amount of his subscription to the capital stock or to the membership capital.\n(2) In the case of a co-operative with unlimited liability a member shall, upon the liquidation of the co-operative, be jointly and severally liable for the debts of a co-operative."}},{"id":"PH-H1769-A29","no":29,"noLabel":{"en":"Section 29."},"chapter":{"en":"CHAPTER IV"},"text":{"en":"Liability of past member. The liability of a past member for the debts incurred by a co-operative as they existed at the date of his ceasing to be a member shall continue for a period of two years from the said date."}},{"id":"PH-H1769-A30","no":30,"noLabel":{"en":"Section 30."},"chapter":{"en":"CHAPTER IV"},"text":{"en":"Withdrawal and expulsion of members. (1) A member may withdraw from a co-operative effective at the end of any fiscal year by giving a minimum of sixty days notice, with the approval of the board of directors. A resolution of the board of directors disapproving the application for withdrawal may be appealed to the general assembly of the members.\n(2) The death, dissolution, insanity, interdiction or expulsion of a member shall be considered an automatic withdrawal from membership.\n(3) A member may be expelled by a vote of a majority of the members entitled to vote in a special or a regular general assembly of members for any of the following causes:\n(i) when a member has failed to patronize the business of the co-operative for an unreasonable period of time as may be specified in the by-laws,\n(ii) when a member has continually refused to comply with his obligations,\n(iii) when a member has acted in violation of the by-laws and the rules of the co-operative, and\n(iv) for any attempted, frustrated or consummated act injurious or prejudicial to the interest or the welfare of the co-operative, Provided, That the member against whom the charges are to be preferred shall be informed thereof in writing at least ten days in advance of the assembly and shall be given an opportunity to be heard in the said assembly."}},{"id":"PH-H1769-A31","no":31,"noLabel":{"en":"Section 31."},"chapter":{"en":"CHAPTER IV"},"text":{"en":"Nomination of beneficiary. A member of a co-operative may nominate a person in whose favor the co-operative shall dispose of the share or interest of such member on his death without prejudice to the rights of other persons as provided under existing laws affecting the estate of a deceased person. The nominated beneficiary of the deceased member may apply for membership and pay the required entrance fee, but the board of directors shall have the right to approve or reject the said application. If the application is rejected the co-operative shall return his entrance fee and repurchase his shares or interest, provided that the latter can be done without jeopardizing the solvency of the co-operative. In case the co-operative cannot do so upon request, the beneficiary shall have the right to dispose of the share or interest to any person who is acceptable as a member to the board of directors of the said co-operative."}},{"id":"PH-H1769-A32","no":32,"noLabel":{"en":"Section 32."},"chapter":{"en":"CHAPTER IV"},"text":{"en":"Disposal of sums due to a withdrawing member. All sums calculated in accordance with the regulations and by-laws to be due from a co-operative to a withdrawing member, shall be paid to him either by the co-operative or by the approved transferee, as the case may be, in accordance with this Act."}},{"id":"PH-H1769-A33","no":33,"noLabel":{"en":"Section 33."},"chapter":{"en":"CHAPTER IV"},"text":{"en":"Bar to claims. All payments and transfers made by a co-operative in accordance with this Act shall be valid and effectual against any demand made upon the co-operative by any other person.\nAdministration"}},{"id":"PH-H1769-A34","no":34,"noLabel":{"en":"Section 34."},"chapter":{"en":"CHAPTER V"},"text":{"en":"Final authority of a co-operative. Subject to the provisions of this Act and the regulations, the final authority in every co-operative shall be vested in the general assembly of the members or the delegates of such members elected in the prescribed manner and assembled in a general meeting."}},{"id":"PH-H1769-A35","no":35,"noLabel":{"en":"Section 35."},"chapter":{"en":"CHAPTER V"},"text":{"en":"Annual general assembly. The members' annual general assembly shall be composed of such members as are entitled to vote under the regulations and the by-laws, and when lawfully constituted, shall represent all the members. The annual general assembly shall be called by the board of directors and shall be held at least once each year within ninety days after the close of each fiscal year. The regulations shall prescribed the procedure and method of calling, holding, time, place and quorum requirement of, election and the business to be transacted in the annual general assemblies."}},{"id":"PH-H1769-A36","no":36,"noLabel":{"en":"Section 36."},"chapter":{"en":"CHAPTER V"},"text":{"en":"Special general assembly. A special general assembly may be called at any time by a majority of the board of directors and such an assembly shall be called by the board of directors within one month after receipt of a request in writing from at least ten per centum of the total members or the Administrator or his duly authorized agent, or the federation of co-operatives of which it is a member to transact specific business covered by the call. The regulations shall prescribe the procedure and the method of calling and holding and quorum requirement of special general assemblies."}},{"id":"PH-H1769-A37","no":37,"noLabel":{"en":"Section 37."},"chapter":{"en":"CHAPTER V"},"text":{"en":"Voting. (1) Each member of a co-operative shall have only one vote, except that where a co-operative includes in its membership co-operatives or any nonprofit groups the voting rights of such member co-operatives or groups may be as prescribed in the by-laws.\n(2) No voting agreement or other device to evade the one-member-one-vote provision except as provided under subsection (1) shall be enforceable.\n(3) No member shall be permitted to vote by proxy.\n(4) The by-laws may provide for voting by mail and by units of membership. If a co-operative has provided for voting by mail, the votes cast by the members shall be deemed to include the votes cast by mail.\n(5) If a co-operative has provided for voting by delegates, the votes cast by the members shall apply to votes cast by delegates: Provided, That no delegate shall vote by mail."}},{"id":"PH-H1769-A38","no":38,"noLabel":{"en":"Section 38."},"chapter":{"en":"CHAPTER V"},"text":{"en":"Board of directors. A co-operative shall be managed by a board of not less than five nor more than fifteen directors elected by the general assembly for a term fixed in the by-laws but not exceeding two years and shall hold office until their successors are elected and have qualified or until removed. The by-laws may provide for a method of allocating the number of directors among the units of membership into which the co-operative may be divided, and for the election of directors by the respective units to which they are allocated. The procedure for the election of directors, officers and committee members together with the method of calling and holding of the meetings may be prescribed in the regulations."}},{"id":"PH-H1769-A39","no":39,"noLabel":{"en":"Section 39."},"chapter":{"en":"CHAPTER V"},"text":{"en":"Qualifications of directors and committee members. (1) Any member of a co-operative who has acquired the right to vote and who does not possess any of the disqualifications provided in the regulations or the by-laws shall be eligible to be elected as director or committee member.\n(2) The by-laws may provide that one or more directors or committee members may be appointed by the Administrator to provide technical knowledge not available within its membership. Such directors or committee members shall not number more than one-third of the total number of directors or committee members. Such persons need not be members of the co-operative, but shall have the same powers and right as other directors and committee members."}},{"id":"PH-H1769-A40","no":40,"noLabel":{"en":"Section 40."},"chapter":{"en":"CHAPTER V"},"text":{"en":"Removal of directors, officers and committee members. An elective officer or committee member may be removed by a vote of the majority of the members entitled to vote at an annual or special general assembly. The person involved shall have an opportunity to be heard at said assembly."}},{"id":"PH-H1769-A41","no":41,"noLabel":{"en":"Section 41."},"chapter":{"en":"CHAPTER V"},"text":{"en":"Filling vacancy in board of directors. When a vacancy in the board of directors occurs other than by expiration of term, the remaining members of the board, by a majority vote, shall fill the vacancy, unless the by-laws provide for an election of directors by units of members. In such case, the board of directors shall immediately call a special general assembly of the members entitled to vote in that unit of membership to fill the vacancy."}},{"id":"PH-H1769-A42","no":42,"noLabel":{"en":"Section 42."},"chapter":{"en":"CHAPTER V"},"text":{"en":"Contract for profit prohibited. No director, officer, committee member or employee, during the term of his office, shall be a party to a contract for profit with the co-operative. However, contracts that may be entered into by the members with the co-operatives, may be entered into by the same director, officer or committee member or employee."}},{"id":"PH-H1769-A43","no":43,"noLabel":{"en":"Section 43."},"chapter":{"en":"CHAPTER V"},"text":{"en":"Election of officers. A co-operative shall have the following officers: a president, one or more vice-presidents, a secretary and a treasurer, or a secretary-treasurer. The officers shall be elected annually by the directors unless the by-laws otherwise provide. The president and at least one vice-president must be directors, but no other officer need necessarily be a director."}},{"id":"PH-H1769-A44","no":44,"noLabel":{"en":"Section 44."},"chapter":{"en":"CHAPTER V"},"text":{"en":"Duties of directors, officers and committee members. The duties and responsibilities of directors, officers and committee members shall be as prescribed in the regulations and the by-laws of a co-operative."}},{"id":"PH-H1769-A45","no":45,"noLabel":{"en":"Section 45."},"chapter":{"en":"CHAPTER V"},"text":{"en":"Liability of directors and committee members for unlawful acts. The directors and committee members shall, in the discharge of their respective duties, be personally responsible, jointly and severally, for any transaction, act or omission made in violation of law, the regulations, the by-laws, the resolution of the general assemblies or the rules of the co-operative except those who entered a protest at the time when such transaction, act or omission was acted upon."}},{"id":"PH-H1769-A46","no":46,"noLabel":{"en":"Section 46."},"chapter":{"en":"CHAPTER V"},"text":{"en":"Committees. (1) An executive committee of the board of directors may be created in such manner and with such powers and duties, subject to the general direction and control of the board, as the by-laws may prescribe.\n(2) The regulations and by-laws may also provide for the creation of other committees to exercise such powers and perform such duties as may be conferred or imposed by this Act, the regulations and the by-laws of a co-operative."}},{"id":"PH-H1769-A47","no":47,"noLabel":{"en":"Section 47."},"chapter":{"en":"CHAPTER V"},"text":{"en":"Compensation of directors and committee members. A co-operative may, subject to regulations, provide a fair remuneration for the time actually spent by its directors, committee members and officers in its service."}},{"id":"PH-H1769-A48","no":48,"noLabel":{"en":"Section 48."},"chapter":{"en":"CHAPTER V"},"text":{"en":"Certain administrative powers. Subject to the regulations, the Administrator shall, so far as is necessary to carry out the purposes of this Act, have the following administrative powers:\n(1) To direct in writing any co-operative to consider an amendment of its by-laws together with the reasons for the necessity of such an amendment proposed by the Administrator, in its next general assembly, annual or special, held after the receipt of such communication, when he considers said amendment necessary and desirable in the interest of the co-operative. Such directive shall be sent to the co-operative by registered mail. When the general assembly fails to decide on the amendment, either for or against, he may register such amendment and issue by registered post to the co-operative a certified copy which shall be conclusive evidence that the amendment has been duly registered and such amendment shall be binding on all the members of such co-operative;\n(2) To direct any co-operative which pursues a policy contrary to the principle of open and voluntary membership, to open its membership for all persons qualified to become members under its by-laws, except such persons as may have been disqualified by the board. The names of such disqualified persons together with reasons for their disqualifications shall be brought to the notice of the next general assembly of such co-operative for approval;\n(3) To order the removal of any officer, director or committee member of a co-operative and also disqualify him from holding any such position in all co-operatives registered under this Act for a period not exceeding three years, if the Administrator is satisfied that such person has acted or has been acting fraudulently or with gross negligence or in contravention of the by-laws of the co-operative or without the sanction of the board or committee when such sanction is necessary, or contrary to the resolution of the board or against the lawful written orders issued under this Act and regulations thereunder or in any way detrimental to the best interest of the co-operative, after affording an opportunity to the person and the board or committee to be heard, and the reason for the order of removal shall be recorded and communicated to the person concerned and the board or committee of the co-operative;\n(4) To prescribe, from time to time, in agreement with the Central Bank of the Philippines, the manner and standards of fluid resources to be maintained by co-operatives accepting time and demand deposits from individuals and institutions. The Secretary of Commerce and Industry may, however, empower the Administrator, by general or special order, to relax the standard of fluid resources prescribed for a particular co-operative or type of co-operatives for a specified period;\n(5) To order the suspension of the execution of any decision taken by the board or committee or the general assembly of any co-operative when the Administrator decides that such decision endangers the financial stability of the co-operative or contravenes the provisions of this Act, the regulations or the by-laws;\n(6) (i) Notwithstanding the provisions of this Act or the regulations made thereunder, where a compromise or arrangement is proposed between a co-operative and its creditor or any class of creditors, the Administrator, on his own motion or upon an application made in the prescribed manner by the co-operative or any creditor or by the liquidator of the co-operative appointed under Section ninety-six, may order a meeting of the creditors or the class of creditors, as the case may be, to be called, held, and conducted in such manner as may be prescribed by the regulations; (ii) Any compromise or arrangement approved by a majority of the members in number representing three-fourths in value of the creditors or the class of creditors, as the case may be, present, either in person or by proxy, at the meeting shall, if sanctioned by the Administrator and upon publication in the prescribed manner, be binding upon all creditors or the class of creditors, as the case may be, and also upon the co-operative or the liquidator of the co-operative and all persons who have been or may be required by the liquidator under Section ninety-seven to contribute to the assets of the co-operative; (iii) When two-thirds in value of the obligation or liability fixed in the compromise or arrangement is paid by the co-operative or the liquidator thereof, the compromise or arrangement may be revised at the instance of the parties concerned or the Administrator;\n(7) The Administrator, with the previous approval of the Secretary of Commerce and Industry and upon the application of a co-operative and under such conditions as may be prescribed, may deputize any official of the Co-operatives Administration Office or any official of other government agencies subject to the approval of the head of the department concerned.\nDuties, responsibilities and privileges of co-operatives"}},{"id":"PH-H1769-A49","no":49,"noLabel":{"en":"Section 49."},"chapter":{"en":"CHAPTER VI"},"text":{"en":"Address of co-operatives. Every co-operative shall have an official postal address registered with the Administrator in accordance with the regulations, to which all notices and communications shall be sent, and shall send to the Administrator notice of every change thereof."}},{"id":"PH-H1769-A50","no":50,"noLabel":{"en":"Section 50."},"chapter":{"en":"CHAPTER VI"},"text":{"en":"Copy of Act, regulations, etc., to be open for inspection. Every co-operative shall keep open to its members and representatives of the Co-operatives Administration Office for inspection free of charge at all reasonable times at its official address:\n(a) A copy of this Act;\n(b) A copy of the regulations;\n(c) A copy of the article of incorporation and by-laws of the co-operative;\n(d) A register of members;\n(e) The minute book of the meetings of board of directors and general assemblies; and\n(f) Such other documents as may be prescribed in the regulations."}},{"id":"PH-H1769-A51","no":51,"noLabel":{"en":"Section 51."},"chapter":{"en":"CHAPTER VI"},"text":{"en":"Maintenance of books, records, and accounts and their production. The president of a co-operative shall cause the up-to-date keeping of books, records and accounts in the manner prescribed by the regulations and shall be responsible for the production of the same at the time of audit, inspection and inquiry. All the books, records and accounts so kept shall not be removed outside of the headquarters of a co-operative, except upon orders of courts or of the Administrator."}},{"id":"PH-H1769-A52","no":52,"noLabel":{"en":"Section 52."},"chapter":{"en":"CHAPTER VI"},"text":{"en":"Duty to account and publish financial statements. Each co-operative shall maintain records and accounts in such a manner that the true and correct condition and the results of the operation of the business of the co-operative may be ascertained therefrom at any time, and the financial statements, audited according to regulations, shall be annually published in the prescribed manner."}},{"id":"PH-H1769-A53","no":53,"noLabel":{"en":"Section 53."},"chapter":{"en":"CHAPTER VI"},"text":{"en":"Annual Report. (1) Every co-operative shall annually make a report of its financial affairs as of December 31st of each year, which shall be filed with the Administrator or his duly authorized representative on or before the first day of February of each year or within the extension which may be granted by the Administrator in exceptional cases. The report shall in such form and manner and shall contain such matters as may be prescribed by the regulations and shall be certified by one of the officers of the co-operatives as true and correct in all respects, to the best of his knowledge and belief.\n(2) If any co-operative fails to make and file the report required herein, or fails to include therein any matter required by the regulations, the Administrator shall within fifteen days from the expiration of the prescribed period send such co-operative a registered notice directed to its official postal address stating the delinquency and its consequences. If the co-operative fails to file the report within thirty days from the receipt of such notice, any member of the co-operative may, or the provincial or city fiscal of the province or city where the principal office of the co-operative is located shall, upon request made in writing by the Administrator, petition the court for mandamus to compel the co-operative and its officers to file such report and require the co-operative or the officers at fault to pay all the expenses of the proceeding, including counsel fees when the filing is made by a member."}},{"id":"PH-H1769-A54","no":54,"noLabel":{"en":"Section 54."},"chapter":{"en":"CHAPTER VI"},"text":{"en":"Duty to furnish information and required reports. (1) Every officer, director, committee member, member and employee of a co-operative shall furnish such information in regard to the transactions or working of the co-operative as may be required of him by the Administrator or any person authorized by him.\n(2) Every co-operative shall submit the reports prescribed in this Act and the regulations and any other reports as may be required by the Administrator."}},{"id":"PH-H1769-A55","no":55,"noLabel":{"en":"Section 55."},"chapter":{"en":"CHAPTER VI"},"text":{"en":"Bonding of accountable officers. Every director, officer and employee handling funds, securities or property on behalf of any co-operative shall, subject to regulations, execute and deliver adequate bonds for the faithful performance of his duties and obligations."}},{"id":"PH-H1769-A56","no":56,"noLabel":{"en":"Section 56."},"chapter":{"en":"CHAPTER VI"},"text":{"en":"Restrictions on borrowing. A co-operative shall receive deposits and loans from members only to such extent and under such conditions as may be prescribed by the regulations and the by-laws."}},{"id":"PH-H1769-A57","no":57,"noLabel":{"en":"Section 57."},"chapter":{"en":"CHAPTER VI"},"text":{"en":"Restrictions on loan. Subject to the restrictions that may be imposed by the Administrator, a co-operative shall make loans only to its members and not in excess of either the maximum or of the normal credit determined by the co-operative for that member in accordance with the regulations whichever may be prescribed. Nonmembers may obtain loans on the deposits they hold in the co-operative."}},{"id":"PH-H1769-A58","no":58,"noLabel":{"en":"Section 58."},"chapter":{"en":"CHAPTER VI"},"text":{"en":"Restrictions on other transactions with nonmembers. Subject to the provision of Sections fifty-six and fifty-seven, a co-operative shall not transact business with nonmembers to exceed that done with members."}},{"id":"PH-H1769-A59","no":59,"noLabel":{"en":"Section 59."},"chapter":{"en":"CHAPTER VI"},"text":{"en":"Co-operatives to be bodies corporate. A co-operative after registration under this Act shall be a body corporate by the name under which it is registered till the registration is cancelled, with perpetual succession and a common seal and with power to hold property, to enter into contracts, to institute and defend suits and other legal proceedings and to do all things necessary for the purposes of its constitution."}},{"id":"PH-H1769-A60","no":60,"noLabel":{"en":"Section 60."},"chapter":{"en":"CHAPTER VI"},"text":{"en":"Co-operative's power to call for statement of claims. (1) When a member of a co-operative, which includes among its purposes granting of loans to its members, applies for a loan or when a person applies for membership in such a co-operative, the co-operative may in the prescribed manner serve a notice on any creditor named in the application or ascertained after subsequent inquiry, and may also publish a general notice on all creditors, requiring him or them to furnish a written statement of his or their claim, in the prescribed form and within the time specified in the notices, which shall not be less than ten days.\n(2) When a member of a co-operative, which includes among its purposes the granting of loans to its members, has already borrowed from the co-operative and intends to apply for a loan from any person other than the co-operative, such member shall send to the co-operative a notice in writing stating:\n(a) His intention to apply for such loan;\n(b) The amount of the loan for which he intends to apply;\n(c) The object of taking the loan; and\n(d) The name and address of the lender."}},{"id":"PH-H1769-A61","no":61,"noLabel":{"en":"Section 61."},"chapter":{"en":"CHAPTER VI"},"text":{"en":"Debts due to co-operatives shall be a first charge. (1) Notwithstanding the provisions of existing laws, rules and regulations, but subject to the prior claim of the Government in respect of any sum recoverable as a public demand or of Government financing institutions for whatever amount they have extended as loans in connection with production, storage, processing and marketing, or of a landlord in respect of share or rent or any sum recoverable as share or rent, any debt or outstanding demand owing to a co-operative from any member, past member or the estate of a deceased member shall be a first charge:\n(a) If the debt or demand is due in connection with the supply of, or any loan to provide the means of paying for, seed, fertilizer, labor, subsistence, irrigation facilities, fodder for cattle, or any other thing incidental to the conduct of agricultural operations upon the crops or other agricultural produce of such member or estate of such deceased member, at any time within two years from the date of such supply or loan;\n(b) If the debt or demand is due in connection with the supply of, or any loan for the purchase of cattle, agricultural implements or machinery or warehouses for the storage of agricultural produce in the manner and to the extent aforesaid upon the crops or agricultural produce of such member or estate of such deceased member and also upon the cattle, agricultural implements or machinery or warehouses thus supplied, purchased or constructed in whole or in part from any such loan;\n(c) If the debt or demand is due in connection with the supply of, or any loan for the purchase of raw materials, industrial implements and machinery, workshops, warehouses or business premises upon the raw materials or other things supplied or purchased by such member, or estate of such deceased member in whole or in part from any such loan and also upon any articles manufactured from raw materials or with implements and machinery, workshops, warehouses or business premises so supplied, purchased or constructed wholly or in part from any such loan;\n(d) If the debt or demand is due in connection with any loan for the purchase or redemption of land, upon the land purchased or redeemed by such member in whole or in part from any such loan;\n(e) If the debt or demand is due in connection with any loan for the purchase or construction of any house or building or any portion thereof or in respect of the supply of materials for such construction, upon the house or building so purchased or constructed by such member from any such loan or material; and\n(f) If the debt or demand is due in connection with the supply of, or any loan for the purchase of consumer goods, facilities or other things, upon the goods, facilities or property so supplied or purchased in whole or in part from any such loan.\n(2) No property or interest in property which is subject to a charge under subsection (1) shall be transferred in any manner except by way of lease for a term not exceeding ten years without the previous permission of the co-operative.\n(3) Notwithstanding the provisions of any law, any transfer made in contravention of the provisions of subsection (2) shall be void.\n(4) Notwithstanding the provisions of this Act or of any other law\n(a) Any member of a co-operative who applies for a loan from the co-operative shall, if he owns any land, make a declaration in the form prescribed in the regulations. Such declaration shall state that the applicant for a loan thereby creates a charge on the land owned by him and specified therein for the payment of the loan which the co-operative may make to the member in pursuance of the application and for all future advances, if any, required by him which the co-operative may grant him as such member subject to such maximum as may be determined by the co-operative together with interest on such loan and advances;\n(b) Any member of a co-operative who has obtained a loan from the co-operative before the enactment of this Act and who owns any land shall, as soon as possible, make a declaration in the form and to the effect referred to in clause (a), and no such member shall, unless and until he has made such declaration, be entitled to exercise any right as a member of the co-operative;\n(c) A declaration made under clauses (a) and (b) may be revised at any time by a member with the consent of the co-operative in whose favor such declaration is made;\n(d) No member shall alienate the whole or any part of the land specified in the aforementioned declaration until the whole amount borrowed by or advanced to the member together with interest thereon is paid in full: Provided, That any such land and the standing crops thereon may be alienated with previous written permission of the co-operative."}},{"id":"PH-H1769-A62","no":62,"noLabel":{"en":"Section 62."},"chapter":{"en":"CHAPTER VI"},"text":{"en":"Agreements with members for deductions from salary to meet claims of co-operative permitted. (1) A member of a co-operative may, notwithstanding the provisions of existing laws, execute an agreement in favor of the co-operative authorizing his employer to deduct from the salary or wages payable to him by the employer such amount as may be specified in the agreement and to pay the amount so deducted to the co-operative in satisfaction of any debt or other demand owing from the member to the co-operative.\n(2) Upon the execution of such agreement the employer shall, if so required by the co-operative by a request in writing and so long as such debt or other demand or any part of it remains unpaid, make the deduction in accordance with the agreement and remit forthwith the amount so deducted to the co-operative.\n(3) The term \"employer\" as used in this section includes the Government of the Philippines or of any local authority and any other person who has under his employ a member of a co-operative.\n(4) The provisions of this section shall also apply to all such agreements of the nature referred to in subsection (1) as were in force on the date of the approval of Commonwealth Act Numbered five hundred sixty-five."}},{"id":"PH-H1769-A63","no":63,"noLabel":{"en":"Section 63."},"chapter":{"en":"CHAPTER VI"},"text":{"en":"Lien and set off on members' interest. A co-operative shall have an absolute lien upon the capital, deposits or interest of a member or past member for any debt or demand due to a co-operative from such a member, either as a principal or as a surety, and may set off any sum credited or payable to a member or past member in or towards payment of any such debt or demand."}},{"id":"PH-H1769-A64","no":64,"noLabel":{"en":"Section 64."},"chapter":{"en":"CHAPTER VI"},"text":{"en":"Register of members. Any register or list of members or shares kept by any registered co-operative shall be prima facie evidence of the following particulars entered therein:\n(a) The date on which the name of any person was entered in such register or list as a member; and\n(b) The date on which any such person ceased to be a member."}},{"id":"PH-H1769-A65","no":65,"noLabel":{"en":"Section 65."},"chapter":{"en":"CHAPTER VI"},"text":{"en":"Admissibility of copy of entry as evidence. (1) A copy of any entry in any book, register or list regularly kept in the course of business in the possession of a co-operative shall, if duly certified in such manner as may be prescribed by the regulations, be admissible in evidence of the existence of the entry and shall be admitted as prima facie evidence of the matters and transactions therein recorded in every where, and to the same extent to which, the original entry would, if produced, have been admissible to prove such matters.\n(2) In the case of such co-operative as the Administrator may direct, no person or a co-operative in possession of the books of such co-operative shall in any legal proceedings to which the co-operative is not a party be compelled to produce any of the books of the co-operative, the contents of which can be proved under subsection (1) or to appear as a witness to prove the matters, transactions and accounts therein recorded, unless by order of a competent court or judge made for special cause."}},{"id":"PH-H1769-A66","no":66,"noLabel":{"en":"Section 66."},"chapter":{"en":"CHAPTER VI"},"text":{"en":"Exemptions. Co-operatives registered under this Act shall, notwithstanding the provisions of existing law to the contrary, enjoy the following exemptions:\n(1) Co-operatives with net assets of not more than five hundred thousand pesos shall be exempt from all taxes and government fees of whatever name and nature except those provided for under this Act: Provided, however, That co-operatives having net assets in excess of five hundred thousand pesos shall pay taxes as provided hereunder:\n(a) Income Tax they shall pay tax at the full rate as provided under existing laws on the amount allocated for interest on capital;\n(b) Sales Tax they shall pay fixed and percentage taxes at the full rate as provided under existing laws on gross sales to non-members; and\n(c) They shall pay all other taxes, unless otherwise provided herein at the full rate as provided under existing laws.\n(2) They shall be exempt from the payment of documentary stamp tax, residence taxes, tax on banks and insurance companies and municipal or city taxes.\n(3) Any justice of the peace, in his capacity as notary public ex officio, shall render service, free of charge, to any person or group of persons requiring either the administration of oath or the acknowledgment of articles of incorporation of a proposed co-operative and instruments of loan from a co-operative not exceeding two thousand pesos.\n(4) Any register of deeds shall accept for registration, free of charge, any instrument relative to a loan made under this Act which does not exceed two thousand pesos or the deeds of title to any property acquired by the co-operative or any paper or document drawn in connection with any action brought by the co-operative or with any court judgment rendered in its favor or any instrument relative to a bond of any accountable officer of a co-operative for the faithful performance of his duties and obligations.\n(5) They shall be exempt from the payment of all court and sheriff's fees payable to the Philippine Government for and in connection with all actions brought under this Act, or to enforce the payment of obligations contracted in favor of the co-operative, and where such an action is brought by the Administrator before the court, he shall, likewise, not be required to pay any such fees.\n(6) They shall be exempt from putting up a bond for bringing an appeal against the decision of an inferior court or for seeking to set aside any third party claim, provided, that a certification of the Administrator showing that the net assets of the co-operative are in excess of the amount of the bond required by the court in similar cases shall be accepted by the court as a sufficient bond.\n(7) Any security issued by co-operatives shall be exempt from the provisions of the Securities Act provided such security shall not be speculative."}},{"id":"PH-H1769-A67","no":67,"noLabel":{"en":"Section 67."},"chapter":{"en":"CHAPTER VI"},"text":{"en":"Other privileges. Co-operatives registered under this Act shall, notwithstanding the provisions of any law, be accorded also the following privileges:\n(1) The reports or returns prescribed under this Act shall be deemed to be sufficient returns for any purpose prescribed under any law.\n(2) Co-operatives shall enjoy the privilege of depositing their sealed cash boxes or containers, documents or any valuable papers in the safes of the municipal or city treasurers and other government offices free of charge, and the custodian of such articles shall issue a receipt acknowledging the articles received, witnessed by another person.\n(3) Co-operatives shall enjoy the privilege of depositing with the postal savings banks such funds as they may desire to deposit at the same rate of interest as that granted to individuals and without limitations as to the amount.\n(4) Co-operatives shall enjoy the privilege of being represented in courts by the provincial or city fiscal or the Solicitor General or his representatives, as the case may be, free of charge, in any case in which they are either plaintiffs or defendants, except when the Philippine Government is the plaintiff itself; and all suits brought by or on behalf of a co-operative shall be instituted in court by them at most within three months from the date of receipt of such suit.\nCapital, property and funds"}},{"id":"PH-H1769-A68","no":68,"noLabel":{"en":"Section 68."},"chapter":{"en":"CHAPTER VII"},"text":{"en":"Capital. The capitalization of co-operatives and the accounting therefor shall be governed by the provisions of this Act and the regulations issued hereunder."}},{"id":"PH-H1769-A69","no":69,"noLabel":{"en":"Section 69."},"chapter":{"en":"CHAPTER VII"},"text":{"en":"Source of funds. Co-operatives registered under this Act may, subject to the regulations derive funds from:\n(a) Members' capital contribution in the form of shares, with or without capital stock;\n(b) Loan capital, including deposits;\n(c) Retains authorized on a percentage or per unit basis;\n(d) Revolving capital by deferment of the payment of patronage refunds and/or by authorized retains; and\n(e) Fees, dues, subsidies, donations, and such other sources as may be authorized in the regulations."}},{"id":"PH-H1769-A70","no":70,"noLabel":{"en":"Section 70."},"chapter":{"en":"CHAPTER VII"},"text":{"en":"Limitation on individual share holdings. No member of a co-operative other than a co-operative or the Government of the Philippines or any of its subdivisions shall, unless expressly authorized in writing by the Administrator in special circumstances, own or hold more than five thousand pesos worth of shares or twenty per centum of the subscribed share capital of the co-operative as may be prescribed by the regulations."}},{"id":"PH-H1769-A71","no":71,"noLabel":{"en":"Section 71."},"chapter":{"en":"CHAPTER VII"},"text":{"en":"Limited return on capital. Interest on share capital shall not exceed eight per centum per annum upon the fully paid-up shares and such interest shall be non-commutative."}},{"id":"PH-H1769-A72","no":72,"noLabel":{"en":"Section 72."},"chapter":{"en":"CHAPTER VII"},"text":{"en":"Restriction on transferability of shares. Subject to the provisions of section seventy, a member shall not transfer any share held by him or his interest in the co-operative or any part thereof unless:\n(a) He has held such share or interest for not less than one year;\n(b) The transfer is made to the co-operative or to a member of the co-operative or to a person who falls within the field of membership of the co-operative and whose membership is acceptable to the co-operative; and\n(c) The board of directors has approved such transfer."}},{"id":"PH-H1769-A73","no":73,"noLabel":{"en":"Section 73."},"chapter":{"en":"CHAPTER VII"},"text":{"en":"Share capital. The term \"share\" refers to a unit of capital, the par value of which may be fixed at any figure of not less than one peso. The share capital of a co-operative with capital stock is the money paid or authorized or required to be paid for conducting its operations, whereas the share capital of a co-operative without capital stock is the money pair or required to be paid and is not limited by any authorized amount. The method of issuing and the contents of stock or membership certificates may be prescribed in the regulations."}},{"id":"PH-H1769-A74","no":74,"noLabel":{"en":"Section 74."},"chapter":{"en":"CHAPTER VII"},"text":{"en":"Interest or fine on unpaid capital contribution. The by-laws of a co-operative may prescribed interest or fine on unpaid capital contribution."}},{"id":"PH-H1769-A75","no":75,"noLabel":{"en":"Section 75."},"chapter":{"en":"CHAPTER VII"},"text":{"en":"Recall or purchase of shares. A co-operative may, by resolution of the members of a general assembly recall the holdings of any member in excess of the amount requisite for membership: Provided, That no purchase shall be made when the debts of the co-operative exceed fifty per centum of the assets thereof. All shares that shall be purchased under sections thirty-one, thirty-two, seventy-two and seventy five shall be reissued or cancelled."}},{"id":"PH-H1769-A76","no":76,"noLabel":{"en":"Section 76."},"chapter":{"en":"CHAPTER VII"},"text":{"en":"Investment of funds. (1) A co-operative shall invest or deposit its funds:\n(a) With the sanction of the Administrator, in the shares or debentures or the securities of any other co-operative with limited liability; or\n(b) In the Postal Savings Bank if no co-operative bank exists in the province where the co-operative is located.\n(c) In the securities issued or guaranteed by the Government; or\n(d) In any other manner prescribed in the regulations.\n(2) When the funds of a co-operative are in excess of operational requirements the Administrator shall instruct such co-operative to invest its funds in accordance with subsection (1) hereof."}},{"id":"PH-H1769-A77","no":77,"noLabel":{"en":"Section 77."},"chapter":{"en":"CHAPTER VII"},"text":{"en":"Government aid to co-operatives. (1) Notwithstanding the provisions of any law, the Government of the Philippines and its subdivisions may, subject to such regulations as may be prescribed on this matter, grant loans to, take shares in, or give financial assistance in any other form to any co-operative registered under this Act.\n(2) With the previous sanction of the Government of the Philippines and subject to limitations to be prescribed by the Government, any federation of co-operatives may issue debentures. The Government of the Philippines may guarantee the principal thereof and the interest thereon, subject to such maximum amount of principal or such rate of interest and to such other conditions as may be prescribed by the Government."}},{"id":"PH-H1769-A78","no":78,"noLabel":{"en":"Section 78."},"chapter":{"en":"CHAPTER VII"},"text":{"en":"Revolving capital. The general assembly of members of any co-operative may by a majority vote decide to raise a revolving capital to strengthen the capital structure of their co-operative by deferring the payment of patronage refunds or by the authorized deduction if a percentage from the proceeds of products sold or per unit of product handled. The board of directors shall issue revolving-fund certificates with serial number, name, and amount and shall distinctly set forth that the time of retirement of such certificates and the amounts to be returned are at the discretion of the directors. The rate of interest to be paid on capital raised by this method shall not exceed five per centum per annum.\nAllocation and distribution of savings"}},{"id":"PH-H1769-A79","no":79,"noLabel":{"en":"Section 79."},"chapter":{"en":"CHAPTER VIII"},"text":{"en":"Computation of savings. Notwithstanding the provisions of existing laws or other regulations, the computation of savings for co-operatives shall be as may be prescribed in the regulations. Every co-operative shall compute the savings at least once at the close of every business year and at such other time as may be prescribed by the Administrator."}},{"id":"PH-H1769-A80","no":80,"noLabel":{"en":"Section 80."},"chapter":{"en":"CHAPTER VIII"},"text":{"en":"Savings, not profit. The net savings shall not be construed as profit but shall be construed as excess payments made by patrons which shall be deemed to have been returned to them if the net savings are distributed as prescribed in section eighty-one, eighty-two, eighty-three, eighty-four and eighty-five."}},{"id":"PH-H1769-A81","no":81,"noLabel":{"en":"Section 81."},"chapter":{"en":"CHAPTER VIII"},"text":{"en":"Reserve fund. (1) Every co-operative shall create and maintain in the following manner a reserve fund for the stability of the co-operative and to meet losses in its business:\n(a) At the close of each business year, twenty per centum of the net savings, as reflected in its audited financial statements and computed as prescribed in the regulations, shall be transferred to the reserve fund. The members may at a general assembly increase, or, if such fund equals the subscribed capital, may decrease the proportion of the net savings to be thus set aside. Whenever the reserve fund does not equal the subscribed capital, it shall be replenished by regular appropriations in such amounts or in such percentages required to equal the subscribed capital;\n(b) The by-laws may provide that certain given fees or fines, or a portion thereof, shall be set aside for the reserve fund; and\n(c) Any sums recovered on items previously charged to the reserve fund shall be credited to such fund.\n(2) The reserve fund shall not be utilized as working capital or for investment other than those mentioned in section seventy-six except with the written sanction of the Administrator under conditions to be prescribed. Such sums of the reserve fund set apart in excess of the amount equal to the subscribed capital may, with the written approval of the Administrator, be appropriated at any time by resolution of the members for the purposes specified under subsection (4).\n(3) Any loss sustained by a co-operative may be charged to its reserve fund with the approval of the general assembly.\n(4) On the dissolution of the co-operative, the reserve fund shall not be divisible among the members. The members' general assembly may resolve:\n(a) To contribute the reserve fund to any federation of co-operatives operating in the area of the co-operative for the improvement of the Co-operative Movement, and/or\n(b) To donate, contribute or otherwise dispose of the amount for any purpose which would improve the economic and social condition of the community in the area of the co-operative. If the members do not meet or cannot decide upon the disposal of the reserve fund, the Administrator shall dispose of it in accordance with the purpose of this subsection."}},{"id":"PH-H1769-A82","no":82,"noLabel":{"en":"Section 82."},"chapter":{"en":"CHAPTER VIII"},"text":{"en":"Educational fund. (1) Every co-operative shall create and maintain in the following manner an educational fund for co-operative educational and other purposes as may be prescribed:\n(a) At the close of each business year, ten per centum of the net savings of each year shall be set aside for such fund;\n(b) The by-laws may provide that certain given fees or fines, or a portion thereof, shall be credited to such fund; and\n(c) Such amounts as may be transferred under subsection eighty-five and from sources shall thus be set aside.\n(2) Half of the amounts transferred to the educational fund annually under subsection (1) may be spent by the co-operative for educational and other co-operative purposes; while the other half shall be credited to a Central Co-operative Educational Fund which, together with the Central Co-operative Audit Fund provided under Section eighty-six, shall be administered and utilized by a Central Co-operative Educational Board of seven (7) members to be composed of representatives of co-operatives, the Administrator as chairman and such members as may be nominated by him as prescribed in the regulations. The Central Co-operative Educational Fund and the Central Co-operative Audit Fund shall be paid in the manner and at the time prescribed by the regulations to the Central Co-operative Educational Board.\n(3) On the dissolution of a co-operative, the unexpended balance of the educational fund appertaining to the Co-operative may be utilized for the purposes specified under section eighty-one (4) or contributed to the Central Co-operative Educational Fund provided under subsection (2)."}},{"id":"PH-H1769-A83","no":83,"noLabel":{"en":"Section 83."},"chapter":{"en":"CHAPTER VIII"},"text":{"en":"Other funds. The general assembly of the members of a co-operative may set aside a land and building fund, community development fund and any other necessary fund the total of which may not exceed ten per centum of the net savings of each year."}},{"id":"PH-H1769-A84","no":84,"noLabel":{"en":"Section 84."},"chapter":{"en":"CHAPTER VIII"},"text":{"en":"Interest on capital and patronage refund.\n(1) The remaining net savings shall be divided into two equal halves: one half of it shall be available for the declaration of interest on capital as provided in section seventy-one and the other half for patronage refunds. Sums that are in excess of the statutory limitation of interest on capital may be declared for patronage refund or may be credited to an interest equalization fund.\n(2) Co-operatives with unlimited liability shall not declare interest on capital or patronage refund without the written permission of the Administrator."}},{"id":"PH-H1769-A85","no":85,"noLabel":{"en":"Section 85."},"chapter":{"en":"CHAPTER VIII"},"text":{"en":"Patronage refunds. The sums allocated for patronage refunds shall be distributed at the same rate to all patrons of the co-operative in proportion to their individual patronage: Provided, That:\n(a) In the case of a member patron, his proportionate amount of patronage refund shall be paid to him unless he agrees that the co-operative should credit the amount to his account toward the purchase of an additional share or shares or other capital;\n(b) In the case of subscriber patron, his proportionate a mount of patronage refund shall be credited to his account until his capital contribution has been fully paid;\n(c) In the case of a non-member patron, his proportionate amount of patronage refund shall be set aside in a general fund for such patrons and shall be allocated to individual non-member patrons only upon request and presentation of evidence of the amount of his patronage. The amount so allocated shall be credited to such patron toward payment of the minimum amount of capital contribution for membership. When a sum equal to this amount has accumulated at any time within a period of time specified in the by-laws, such patron shall be deemed and become a member of the co-operative if he so agrees or requests and complies with the provisions of the by-laws for admission to membership; and\n(d) If within any period of time specified in the by-laws (a) any subscriber has not accumulated and paid in the amount of capital subscribed for; or (b) any non-member patron has not accumulated in his individual account the sum necessary for membership; or (c) any non-member patron has accumulated the sum necessary for membership but neither requests nor agrees to become a member or fails to comply with the provisions of the by-laws for admission to membership, then the amounts so accumulated or paid in and any part of the general fund for non-member patrons which has not been allocated to individual non-member patrons, shall go to the education fund and thereafter no member or other patron shall have any right in said paid-in capital or accumulated patronage refund as such: Provided, further, That nothing in this section shall prevent a co-operative from deferring payment of patronage refund for a fixed period of years as prescribed in their by-laws or create a revolving capital under section seventy-eight, nor from adopting a system whereby the payment of patronage refunds shall be made in cash, in kind or in shares.\nAudit, inquiry and inspection"}},{"id":"PH-H1769-A86","no":86,"noLabel":{"en":"Section 86."},"chapter":{"en":"CHAPTER IX"},"text":{"en":"Audit. (1) The Administrator shall audit or cause to be audited by some person, hereinafter referred to as the auditor, authorized by him in writing the accounts of every co-operative registered under this Act as least once a year.\n(2) Every director, committee member, officer, employee or member of the co-operative shall furnish such information in regard to the transactions and working of the co-operative as the administrator or the auditor may require.\n(3) Co-operatives shall pay the cost of audit as determined by the Administrator in accordance with the scale to be prescribed in the regulations. The Administrator shall have power to collect and credit the amount to the Central Co-operative Audit Fund to be administered by the Central Co-operative Educational Board and also all have power to appoint auditors from out of a list of persons recommended by the said board, when the personnel of the Co-operatives Administration Office is inadequate to audit all the co-operatives and to meet the remuneration of the auditors from out of the Central Co-operative Audit Fund in the scale to be determined by the Central Co-operative Educational Board. At the close of each fiscal year, fifty per centum or higher proportion of the unexpended balance of the Central Co-operative Audit Fund shall be transferred to the Central Co-operative Educational Fund created under Section eighty-two."}},{"id":"PH-H1769-A87","no":87,"noLabel":{"en":"Section 87."},"chapter":{"en":"CHAPTER IX"},"text":{"en":"Power of Administrator to have accounts written up. If at the time of audit the accounts of a co-operative are not complete, the Administrator or his duly authorized representative may cause the accounts to be written up at the expense of the co-operative or the employees, as he deems fit."}},{"id":"PH-H1769-A88","no":88,"noLabel":{"en":"Section 88."},"chapter":{"en":"CHAPTER IX"},"text":{"en":"Nature of audit. (1) The audit under Section eighty-six shall include:\n(a) A verification of the cash balances and securities;\n(b) A verification of the balance to the credit of depositors and creditors and of the amounts due from the debtors of the co-operative;\n(c) An examination of overdue debts, if any;\n(d) A valuation of the assets and liabilities of the co-operative;\n(e) An examination of the transactions of the co-operative within such limits as may be prescribed;\n(f) An examination of the financial statements prepared in the prescribed form and manner by the board of directors;\n(g) A certification of the business done with members and non-members; and\n(h) Such other matters as may be prescribed.\n(2) The financial statements thus audited, together with the modifications, if any, made therein by the Administrator shall be final and binding on the co-operative."}},{"id":"PH-H1769-A89","no":89,"noLabel":{"en":"Section 89."},"chapter":{"en":"CHAPTER IX"},"text":{"en":"Audit report. The auditor shall, on such date as may be prescribed, submit to the co-operative and to the Administrator an audit report in the prescribed form and manner, including a statement of:\n(a) Every transaction which appears to him to be contrary to law, to the regulations or the by-laws;\n(b) Every sum which ought to have been, but has not been, brought into account;\n(c) The amount of any deficiency or loss which appears to have resulted from any negligence or misconduct or which requires further investigation;\n(d) Any money or property which ought to have been in the custody of the co-operative which appears to have been misappropriated or fraudulently retained by any person; and\n(e) Such other matters as may be prescribed."}},{"id":"PH-H1769-A90","no":90,"noLabel":{"en":"Section 90."},"chapter":{"en":"CHAPTER IX"},"text":{"en":"Inquiry. (1) The Administrator may, on his own initiative, at any time conduct an inquiry or direct some person authorized by him in writing in this behalf, to conduct an inquiry into the constitution, working and financial condition of a co-operative.\n(2) The Administrator or the person authorized by him shall conduct such inquiry on the application of:\n(a) A majority of the members of the board of directors of the co-operative;\n(b) Ten per centum of the members of the co-operative;\n(c) A federation of co-operatives of which the co-operative is a member; and\n(d) Creditors representing not less than one-half of the borrowed capital of the co-operative.\n(3) All directors, committee members, officers, employees and members of the co-operative whose affairs are investigated shall furnish such information in their possession in regard to the affairs of the co-operatives as the Administrator of the person authorized by him may require.\n(4) The Administrator shall communicate the result of any inquiry under this section to those who applied for inquiry under subsection (2)."}},{"id":"PH-H1769-A91","no":91,"noLabel":{"en":"Section 91."},"chapter":{"en":"CHAPTER IX"},"text":{"en":"Inspection. (1) The Administrator may, on his own initiative or on the application of a creditor of a co-operative, inspect or direct any person authorized by him in this behalf in writing to inspect the co-operative.\n(2) No inspection shall be made or directed under subsection (1) on the application of a creditor unless:\n(a) The creditor satisfies the Administrator that the debt is a sum then due, that he has demanded payment thereof and he has not received satisfaction within a reasonable time; and\n(b) The creditor deposits with the Administrator such sum a security for the cost of the proposed inspection as the Administrator may fix.\n(3) A federation of co-operatives shall have the right to inspect at any time any co-operative which is indebted to it. The inspection may be made either by an officer of the federation of co-operatives or by a member of its paid staff certified by the Administrator as competent to conduct such an inspection.\n(4) The results of an inspection under this section shall be communicated to the creditor, to the co-operative and to the federation of co-operatives to which the co-operative is indebted; and when the inspection is made by a federation of co-operatives, to the Administrator and the co-operative."}},{"id":"PH-H1769-A92","no":92,"noLabel":{"en":"Section 92."},"chapter":{"en":"CHAPTER IX"},"text":{"en":"Cost of inquiry and inspection. (1) The Administrator may prescribe the cost of inquiry under Section ninety and inspection under Section ninety-one and may, after giving the parties an opportunity to be heard, apportion the cost or such part of the cost as he may think right between the co-operative, the members or creditor demanding an inquiry or inspection, the officers or former officers and the members or past members of the co-operative. The grounds on which the Administrator has apportioned the cost shall be specified in writing.\n(2) Any sum awarded by way of cost under subsection (1) if not paid within the time specified may be recovered under Section one hundred forty-four."}},{"id":"PH-H1769-A93","no":93,"noLabel":{"en":"Section 93."},"chapter":{"en":"CHAPTER IX"},"text":{"en":"Rectification of defects pointed out in audit, inquiry or inspection. If the result of audit under Section eighty-six or an inquiry under Section ninety or an inspection under Section ninety-one discloses any defects or irregularities in the working of a co-operative, the Administrator shall bring such defects or irregularities to the notice of the co-operative, and if the co-operative is a member of a federation of co-operatives to the notice of it, and shall afford them an opportunity of explaining such defects or irregularities pointed out in audit, inquiry or inspection, and thereafter if the co-operative or its proper officers or the federation of co-operatives fail to remedy such defects or irregularities, then the Administrator may proceed to take action as provided under Section ninety-four.\nSupersession"}},{"id":"PH-H1769-A94","no":94,"noLabel":{"en":"Section 94."},"chapter":{"en":"CHAPTER X"},"text":{"en":"Supersession. (1) If the Administrator, after an audit under Section eighty-six or an inquiry under Section ninety or an inspection under Section ninety-one is satisfied that the board of directors or any committee responsible to the members of a co-operative is not functioning properly or have neglected to perform their duties, he may, after giving an opportunity to the board of directors or the committee to explain its reason for such circumstances and to state its objections, if any, and after considering the reasons and objections raised, call a general assembly of members to dissolve and reconstitute the board of directors or the committee. He may order that all or any of the directors or committee members shall be disqualified from being reelected to the board of directors or to any of the committees of the co-operative for a period to be specified in the order not exceeding three years: Provided, That the Administrator may from time to time extend the period specified in such order for further periods not exceeding one year at a time, but not exceeding in the aggregate of two years.\n(2) Every order issued under subsections (1) and (3) shall state the reasons for which it is made and shall be communicated by registered post to the co-operative concerned.\n(3) If the members fail to elect a board of directors or a committee which, in the opinion of the Administrator, is likely to function satisfactorily or to perform their duties diligently, and the Administrator is satisfied that, under the circumstances of the case, it is undesirable to order the cancellation of the registration of the co-operative, he may, by order in writing setting forth the reasons therefor, dissolve the board of directors or the committee, the members of which shall forthwith vacate their offices, and thereafter he shall appoint a suitable person or persons to manage the affairs of the co-operative on such conditions as may be prescribed for a specified period not exceeding two years or until a new board or committee is elected earlier than the termination of the period of appointment at the discretion of the Administrator.\n(4) The person of persons so appointed under subsection (3) shall, subject to the control of the Administrator and to such instructions as he may from time to time give, have power to exercise all or any of the functions of the board of directors or the committee or of any officer of the co-operative, as the case may be, and take all such action as may be required in the interest of the co-operative.\n(5) The Administrator may fix the remuneration of the person or persons so appointed under subsection (3). The amount of such remuneration and other costs, if any, incurred in the management of the co-operative shall be payable from its funds.\n(6) The person or persons so appointed under subsection (3) shall, at the expiration of the period of his or their appointment or earlier as the Administrator may direct, arrange for the election of new board of directors or committees in accordance with the by-laws of the co-operative.\n(7) Before taking any action under subsections (1) and (3) in respect of any co-operative, the Administrator shall, if the co-operative is indebted to a federation of co-operatives, consult such federation regarding such action and the provision to be made for the management of the affairs of the co-operative.\n(8) Any member of the co-operative may, within one month from the date of any order made by the Administrator under subsections (1) and (3), appeal from such order to the Secretary of Commerce and Industry.\n(9) Nothing in this section shall be deemed to affect the power of the Administrator to order the winding up of the affairs of a co-operative under Section ninety-five.\nLiquidation and arbitration"}},{"id":"PH-H1769-A95","no":95,"noLabel":{"en":"Section 95."},"chapter":{"en":"CHAPTER XI"},"text":{"en":"Winding up. (1) The Administrator may, subject to the regulations prescribed, by an order in writing, direct that a co-operative shall be liquidated if:\n(a) After an audit under Section eighty-six or an inquiry under Section ninety or an inspection under Section ninety-one; or\n(b) On an application made upon a resolution passed by three-fourths of the members of the co-operative present and qualified to vote at a special general assembly called for the purpose; or\n(c) On the expiration of its term of existence; or\n(d) The co-operative:\n(i) has not commenced its business within one year from the date of registration; or (ii) has ceased working for one year; or (iii) has paid in capital below that prescribed in this Act or the regulations; or (iv) has membership below the requirements provided under Section twelve; or\nv) has failed to account to its members for business done or to send to the Administrator the annual report required under Section fifty-three within one year after the close of its fiscal year; or (vi) has been doing business liable to cause injury to the public; or (vii) has persistently neglected orders duly issued under the provisions of this Act, the regulations or the by-laws; or (viii) has not been able to be traced and no member, depositor, creditor and others with interest in it fail to show cause within one year after due notice has been given in the prescribed manner; or\n(e) For any other causes as may be prescribed by the regulations, he is of the opinion that the affairs of the co-operative ought to be wound up.\n(2) A copy of such order shall be communicated, in the prescribed manner, to the co-operative and to the federation of co-operatives, if any, of which the co-operative is a member.\n(3) Any member, depositor or creditor of the co-operative, or any person whose interest could be affected by such order may, within one month from the date of publication of such order as prescribed in the regulations, appeal to the Secretary of Commerce and Industry from such order.\n(4) The order shall take effect on the expiration of the time allowed for preferring an appeal under subsection (3) where no appeal is preferred; or where an appeal is preferred, upon rejection of the appeal by the Secretary of Commerce and Industry."}},{"id":"PH-H1769-A96","no":96,"noLabel":{"en":"Section 96."},"chapter":{"en":"CHAPTER XI"},"text":{"en":"Appointment of a liquidator and necessary assistance. When an order is issued under Section ninety-five for the winding up of the affairs of a co-operative, the Administrator shall, the provisions of the Rules of Court or of any law to the contrary notwithstanding, appoint a competent person or persons to be liquidator of the co-operative and such other assistance and may retain such of the officers or employees of the co-operative as he deems necessary and fix their remuneration to be paid out of the funds of the co-operative. He may remove any such person and appoint another in his place."}},{"id":"PH-H1769-A97","no":97,"noLabel":{"en":"Section 97."},"chapter":{"en":"CHAPTER XI"},"text":{"en":"Powers of liquidator. (1) Notwithstanding the provisions of subsections (3) and (4) of Section ninety-five, a liquidator appointed under Section ninety-six shall have the power, from the date of his appointment, to take immediate possession and control of the business, property, assets, claims, books, records, and other documents of every description of the co-operative, and he shall investigate the existing financial condition of the co-operative at the time of his appointment and make an inventory of the property, and shall draw up a balance sheet, all of which shall be forwarded to the Administrator for approval. The Administrator may, if he thinks necessary, consult the general assembly of members before such approval.\n(2) Upon the issuance of the order of liquidation of the co-operative the liquidator shall, subject to the regulations and under the control and supervision of the Administrator, have power, as far as is necessary for the beneficial winding up of the affairs of the co-operative, on behalf of the co-operative, in the name of his Office, to carry on the business thereof to do all acts and execute all documents necessary to such winding up, and in particular shall exercise the following powers:\n(a) To institute and defend suits and other legal proceedings;\n(b) To enter into any compromise or arrangement with any person between whom and the co-operative there exists any dispute and to refer such dispute to arbitration;\n(c) To determine from time to time the contribution to be made or remaining to be made by the members or past members or by estates or nominees, or heirs or legal representatives of deceased members or by any present or former officers, board of directors, committee members to the assets of the co-operative, such contribution including debts due from such members or persons, and to revise from time to time any order of contribution to realize such contributions, until the winding up its completed;\n(d) To investigate all claims against the co-operative and, subject to the provisions of this Act, to decide questions of priority arising out of such claims and to pay in full or ratably, as the assets of the co-operative permit; and to apply the surplus, if any, remaining after payment of the claims in full, in the payment of interest from the date of the order of winding up at a rate to be fixed by him but not exceeding the contract rate;\n(e) To pay any class or classes of creditors in full;\n(f) To calculate the costs of liquidation and to determine by what persons and in what proportions they shall be borne;\n(g) To give such directions in regards to the collection and distribution of the assets of the co-operative for winding up of the affairs of the co-operative;\n(h) To fix the time within which creditors shall prove their debts and claims or be included for the benefit of any distribution made before those debts or claims are provided; and\n(i) To dispose of, by consulting the members' general assembly, the surplus, if any, remaining after paying the claims against the co-operative in accordance with the purposes of subsection (4) of Section eighty-one and subsection (3) of Section eighty-two:\nProvided, That the liquidator shall not determine the contribution, debt or dues to be recorded from any person unless an opportunity has been given to such person to answer the claim.\n(3) The liquidator shall not distribute the property of the co-operative to its members until the payment of all debts has been made or secured by deposit for payment and the approval of the Administrator is obtained.\n(4) When the work of the liquidator is completed he must without delay draw up and submit a final report to the Administrator and on his approval place the report before the general assembly for its sanction.\n(5) When the final report of liquidation has been sanctioned by the general assembly, the liquidator shall deposit the records of the co-operative in such place as the Administrator may direct.\n(6) Any person aggrieved by any order of the liquidator, may, in the prescribed manner, appeal to the Administrator against such order within a month from the date of the issue of the order."}},{"id":"PH-H1769-A98","no":98,"noLabel":{"en":"Section 98."},"chapter":{"en":"CHAPTER XI"},"text":{"en":"Bar of suit during liquidation and cancellation of registration. Save in so far as is expressly provided in this Act no court shall take cognizance of any civil matter connected with the liquidation or dissolution of a co-operative under this Act and when a liquidation order has been made no suit or other legal proceeding shall lie or be proceeded with against the co-operative except by leave of the Administrator and subject to such terms as he may impose."}},{"id":"PH-H1769-A99","no":99,"noLabel":{"en":"Section 99."},"chapter":{"en":"CHAPTER XI"},"text":{"en":"Effect of liquidation of co-operative on past members or on estate of deceased member. Notwithstanding the provisions of section twenty-nine, when a co-operative is directed to be liquidated under Section ninety-five, the liability of a past member and the estate of a deceased member of the co-operative, as it existed on the date of the winding up order, shall continue until all the liabilities of the co-operative are settled."}},{"id":"PH-H1769-A100","no":100,"noLabel":{"en":"Section 100."},"chapter":{"en":"CHAPTER XI"},"text":{"en":"Cancellation of liquidation or registration.\n(1) The Administrator may, when the members or the federation of co-operatives of which the co-operative is a member have satisfied him that they can operate the co-operative, cancel the order for the liquidation of the co-operative.\n(2) In any other case, the Administrator shall, after considering the report of the liquidator and the sanction of the general assembly, if any, order the registration of the co-operative to be cancelled and the co-operative shall cease to exist as a corporate body from date of such order."}},{"id":"PH-H1769-A101","no":101,"noLabel":{"en":"Section 101."},"chapter":{"en":"CHAPTER XI"},"text":{"en":"Arbitration. (1) All civil controversies touching the constitution or business of a co-operative arising between members or past members of the co-operative or persons claiming through a member or past member or between members or past members or persons so claiming and any officer, director, committee member, agent or employee of the co-operative past or present, or between co-operative or its board, committee and any officer, director, committee member, agent, member or employee of the co-operative past or present, shall be referred to the Administrator for decision by himself or his nominee or, if either of the parties involved in the controversy so desires, to arbitration of three persons one of whom shall be the Administrator of his nominee and the two to be nominated by each of the parties concerned.\nA controversy shall include claims by a co-operative for debts or demands due from persons noted under this subsection whether such debts or demands be admitted or not.\nProvide, That if the controversy between parties is one involving complicated questions of law and fact, the Administrator may, if he thinks fit, suspend the proceedings and advise the parties to file a regular suit in a court having jurisdiction. If no proceedings are instituted by either of the parties within six months from the date of such advice, the Administrator shall decide the controversy himself.\n(2) Where controversies are referred to arbitrators under subsection (1) the procedure and provisions of Republic Act Numbered Eight hundred seventy-six (The Arbitration Law) shall be applicable, as far as they are not inconsistent with the provisions of this Act and the regulations, and the Administrator shall exercise the authority vested in Courts of First Instance under said Act.\n(3) The awards made by the or nominees of the Administrator shall be appealable to the Administrator and the award made by the Administrator shall be appealable to the Secretary of Commerce and Industry.\n(4) Any award made under this section shall not be called in question by courts except on matters of law and shall be deemed to be a decree of the court to which it is sent for execution."}},{"id":"PH-H1769-A102","no":102,"noLabel":{"en":"Section 102."},"chapter":{"en":"CHAPTER XI"},"text":{"en":"Power to direct payment of dues. Notwithstanding the provisions on arbitration, the Administrator may, on his own initiative or on the written request of his assistants appointed under Section eight hereof, or of a co-operative or of a federation of co-operatives for the recovery of any loan or amount due by a defaulting member, after due inquiry, make an award directing payment by such member of the amount found to be due."}},{"id":"PH-H1769-A103","no":103,"noLabel":{"en":"Section 103."},"chapter":{"en":"CHAPTER XI"},"text":{"en":"Powers of Administrator and others. The Administrator, subject to any restrictions prescribed in the regulations, the auditor under section eighty-six, the liquidator under section ninety-six the arbitrator under section one hundred one, the person appointed under section ninety-four or any person conducting an inquiry under section ninety, or an inspection under section ninety-one, shall at all reasonable times have free access to the books, accounts, vouchers, documents, securities, cash and other properties belonging to or in the custody of a co-operative and shall, in so far as is necessary for carrying out of any of the purposes of this Act, have power to summon and enforce attendance of witnesses and parties concerned who, he has reason to believe, can give valuable information in regard to any transaction of the co-operative or the management of its affairs and to compel them to give evidence upon oath and to compel the production of any books, accounts, vouchers, documents, securities, cash and other properties relating to the affairs of the co-operative at any place at the headquarters of the co-operative or at the office of the Administrator, by the same means and, as far as possible, in the same manner as that provided for the courts in civil cases.\nSurcharge and attachment of property"}},{"id":"PH-H1769-A104","no":104,"noLabel":{"en":"Section 104."},"chapter":{"en":"CHAPTER XII"},"text":{"en":"Surcharge. When in the course of an audit under section eighty-six, or an inquiry under section ninety or an inspection under section ninety-one, or the liquidation of a co-operative, it appears that any person who has taken part in the organization or management of the co-operative or any past or present officer, director or committee member of the co-operative has at any time after the effectivity of this Act and within a period of four years prior to the date of such audit, inquiry, inspection or winding up, as the case may be, or within two years of the date on which it comes to the notice of the Administrator, whichever is earlier:\n(a) Intentionally made or authorized any payment which is contrary to the provisions of this Act or the regulations or the by-laws of the co-operative, or is against the written direction or instructions of the federation of co-operatives to which the co-operative is indebted; or\n(b) By reason of his culpable negligence or misconduct in respect of any prescribed matter, involved the co-operative or the federation of co-operatives to which the co-operative is indebted, in any loss or deficiency; or\n(c) Failed to bring into account any sum which ought to have been brought into account; or the Administrator may, on his own initiative or on the application of the person conducting the audit, inquiry, inspection or winding up or of any creditor or contributor, inquire into the conduct of such person, officer, director or committee member and after giving him an opportunity to be heard and in the cases falling under clause (a) of this section, after affording him an opportunity to recover the amount of such payment from the payee and credit it to the funds of the co-operative, or the federation of co-operatives, as the case may be, subject to the regulations, make an order in writing requiring such person, officer, director or committee member to pay such sum to the assets of the co-operative or the federation of co-operatives, as the case may be, by way of compensation in respect of such payment or loss or deficiency or sum or to restore such property or any part thereof together with interest at such rate as the Administrator thinks just, and to pay such sum as the Administrator may fix to meet the cost of the proceeding under this section.\n(2) Any person aggrieved by an order of the Administrator made under subsection (1) may, within sixty days from the date of the communication of the order to him, appeal to the Secretary of Commerce and Industry, otherwise, the order of the Administrator shall be final and conclusive and shall not questioned in any court.\n(3) Any order made under subsections (1) and (2) shall, upon the application of the Administrator, be enforced as provided in sections one hundred forty-four and one hundred forty-five.\n(4) This section shall apply notwithstanding any criminal liability which may be incurred by such person, officer, director or committee member."}},{"id":"PH-H1769-A105","no":105,"noLabel":{"en":"Section 105."},"chapter":{"en":"CHAPTER XII"},"text":{"en":"Attachment of property. Whenever it shall appear to the Administrator that any person or co-operative with intent to defeat or delay the execution of any order that may be issued under Chapters XI, XII or XIV\n(a) Is disposing or is about to dispose of the whole or any part of his or its property; or\n(b) Is removing or his about to remove the whole or any part of his or its property from the jurisdiction of the Administrator; he may, unless sufficient security is furnished as he may require, proceed against such person in accordance with Rule 59 of the Rules of Court and other pertinent laws.\nRegulations"}},{"id":"PH-H1769-A106","no":106,"noLabel":{"en":"Section 106."},"chapter":{"en":"CHAPTER XIII"},"text":{"en":"Regulations. The Administrator, subject to the previous approval of the Secretary of Commerce and Industry, shall prescribe the necessary regulations to carry out the provisions of this Act. Such regulations shall be published in the Official Gazette before they become effective.\nOffenses and penalties"}},{"id":"PH-H1769-A107","no":107,"noLabel":{"en":"Section 107."},"chapter":{"en":"CHAPTER XIV"},"text":{"en":"Prohibition of the use of the word \"Co-operative\". (1) No person or group of persons other than a co-operative registered under this Act, except as authorized under other co-operative laws, shall carry on business under any name or title of which the word \"co-operative\" or its equivalent in vernacular forms part without the sanction of the Secretary of Commerce and Industry: Provided, That any person or group of persons or their successors in interest using the word co-operative or its equivalent in the vernacular in any name or title under which they carried on business before the enactment of existing co-operative laws and this Act may continue to use the word co-operated or is equivalent in vernacular.\n(2) Whoever violates the provisions of subsection (1) shall be punished by a fine of not exceeding two hundred pesos at the discretion of the court, and in the case of continuing offense, by a further fine of twenty pesos for each day such offense is continued."}},{"id":"PH-H1769-A108","no":108,"noLabel":{"en":"Section 108."},"chapter":{"en":"CHAPTER XIV"},"text":{"en":"Offenses. (1) Any officer, director or committee member of a co-operative:\n(a) With a paid-up capital of five thousand pesos or more, who fails without reasonable excuse to give any notice, send any return or document, do or allow to be done anything which the co-operative, officer, director, committee member or member is by this Act required to give, send, do or allow to be done; or\n(b) Who neglects or refuses to do any act or to furnish information required for the purposes of this Act by the Administrator or other person duly authorized by him in writing in this behalf; or\n(c) Who makes a false return or furnishes false information; or\n(d) Who recommends or sanctions for his own personal use or benefit a loan in the name of any other person in spite of the concurrence of such other person; or\n(e) Who grants loans to non-members except on the security of their deposits or to members on the pledge of their shares or for the return of shares of certain members or all the members without resolution of the board or the general assembly, as the case may be, with a view to depriving the creditors of the co-operative or to circumvent the provisions of Chapter XI and XII; shall, upon conviction be punished by fine of not less than fifty pesos nor more than five hundred pesos, in the discretion of the court, without prejudice to other legal remedies.\n(2) Any officer, director, committee member or member of a co-operative guilty of an offense for which no specific penalty has been provided in this Act shall be liable to a fine of not less than twenty-five pesos nor more than one hundred pesos, in the discretion of the court, without prejudice to other legal remedies."}},{"id":"PH-H1769-A109","no":109,"noLabel":{"en":"Section 109."},"chapter":{"en":"CHAPTER XIV"},"text":{"en":"Penalty for nonperformance of obligations. Notwithstanding the provisions of this Act, where a co-operative or a person required to take action under this Act, under the regulations or the by-laws and such action is not taken\n(a) Within the time provided in this Act, the regulations or the by-laws; or\n(b) Where no time is provided, within such reasonable time as the Administrator may specify by a notice in writing, the Administrator may apply to the court for an order which shall call upon any person whom the Administrator considers to be responsible for the carrying out of his directions and after giving such person an opportunity to be heard, requiring him to pay to the assets of the co-operative such sum not exceeding twenty pesos at the discretion of the court for each day until the directions of the Administrator are carried out."}},{"id":"PH-H1769-A110","no":110,"noLabel":{"en":"Section 110."},"chapter":{"en":"CHAPTER XIV"},"text":{"en":"Penalty for certain acts. Where it appears to the Administrator, that any person has contravened the provisions of this Act, the regulations or the by-laws\n(a) By sitting or voting as a member of board or committee or voting in the affairs of a federation of co-operatives as a representative of another co-operative which is a member of such federation, or exercising the rights of a member of a co-operative, when such person was not entitled to sit or vote or exercise such rights, as the case may be; or\n(b) By applying a loan for a purpose different from that for which it was granted; the Administrator may apply to the court for an order, which shall after affording such person an opportunity to be heard, directing such person to pay to the assets of the co-operative by way of penalty such sum as the court deems fit in respect of every such contravention."}},{"id":"PH-H1769-A111","no":111,"noLabel":{"en":"Section 111."},"chapter":{"en":"CHAPTER XIV"},"text":{"en":"Penalty for disposing of property in contravention of Section 61. Any member or past member, or the heir or legal representative of a deceased member who, in violation of the provisions or section sixty-one, fraudulently disposes of any property over which a co-operative has charge under that section or doing any other act and to the prejudice of such charge, shall, in addition to other legal remedies, be punished by a fine of not exceeding five hundred pesos in the discretion of the court after hearing the party concerned."}},{"id":"PH-H1769-A112","no":112,"noLabel":{"en":"Section 112."},"chapter":{"en":"CHAPTER XIV"},"text":{"en":"Prosecution of offenses. No prosecution for offenses under sections one hundred seven, one hundred eight, one hundred nine, one hundred ten and one hundred eleven of this Act shall be lodged without the previous written sanction of the Administrator, who shall not give sanction until after hearing the party concerned: Provided, That if the offenses constitute criminal acts punishable under the Revised Penal Code, the same may be prosecuted even without the previous sanction of the Administrator.\nSpecial Provisions relating to co-operative banks"}},{"id":"PH-H1769-A113","no":113,"noLabel":{"en":"Section 113."},"chapter":{"en":"CHAPTER XV"},"text":{"en":"Applicability of provisions. The special provisions under this Chapter are applicable only to co-operative banks registered under this Act and the other provisions of this Act will apply to them only in so far as they are not against the express provisions contained in this Chapter."}},{"id":"PH-H1769-A114","no":114,"noLabel":{"en":"Section 114."},"chapter":{"en":"CHAPTER XV"},"text":{"en":"Definitions. As used in this Act, unless a different meaning is intended in the context\n(1) \"Affiliated co-operative or member co-operative\" means a co-operative or a federation of co-operatives registered under this Act which has been admitted to membership in the Philippine National Co-operative Bank or the Provincial Co-operative Bank as the case may be; and\n(2) \"Individual member\" means any person other than a body corporate who is a shareholder and has been admitted to membership of the Philippine National Co-operative Bank or the Provincial Co-operative Bank as the case may be."}},{"id":"PH-H1769-A115","no":115,"noLabel":{"en":"Section 115."},"chapter":{"en":"CHAPTER XV"},"text":{"en":"Objects. (1) The objects of the co-operative banks are to facilitate the operation of non-agricultural co-operatives by furnishing credit for the Co-operative Movement, and the Philippine National Co-operative Bank may\n(a) Carry on banking and credit business for the affiliated co-operatives;\n(b) Receive financial aid from the Government and the Central Bank of the Philippines for and on behalf of the provincial co-operative banks and primary co-operatives and supervise the lending and collection of such loans;\n(c) Mobilize the savings from urban areas for the benefit of the Co-operative Movement;\n(d) Act as a balancing medium for the surplus funds of co-operatives and federations of co-operatives;\n(e) Discount bills and promissory notes issued and drawn by affiliated co-operatives;\n(f) Issue drafts on demand to facilitate the activities of affiliated co-operatives;\n(g) Issue debentures with the approval of and under conditions and guarantees to be prescribed by the Government;\n(h) Borrow money from other banks within the limit to be prescribed by the Government;\n(i) Supervise the lending and collection of funds by the provincial co-operative banks;\n(j) Provide for the training of its employees and the employees of the affiliated co-operatives and other; and\n(k) Carry on all other objects as may be prescribed in the regulations.\n(2) The provincial co-operative banks may in addition to objects noted in clauses (a), (c), (d) and ( f ) of subsection (1) of this section may\n(a) Act as agents of the Philippine National Co-operative Bank;\n(b) Supervise the lending and collection of funds borrowed by primary co-operatives;\n(c) Receive financial aid from the Government and Central Bank of the Philippines through the Philippine National Co-operative Bank;\n(d) Provide for the training of its employees and the employees of the affiliated co-operatives and others: and\n(e) Carry on all other objects as may be prescribed in the regulations."}},{"id":"PH-H1769-A116","no":116,"noLabel":{"en":"Section 116."},"chapter":{"en":"CHAPTER XV"},"text":{"en":"Registration. No co-operative bank shall be registered by the Administrator unless the articles of incorporation and the by-laws of such bank have been approved by the Secretary of Commerce and Industry and the Central Bank of the Philippines and the co-operative bank satisfies all the provisions for registration of federations of co-operatives. There may be registered one co-operative bank at the national level to serve as the chief bank for non-agricultural and other types of co-operatives together with their federations, and one Provincial Co-operative Bank in each province."}},{"id":"PH-H1769-A117","no":117,"noLabel":{"en":"Section 117."},"chapter":{"en":"CHAPTER XV"},"text":{"en":"Name and jurisdiction. The co-operative bank at the national level may be known as \"The Philippine National Co-operative Bank.\" The co-operative banks at the provincial level may be known as \"The Provincial Co-operative Bank\" and shall include in their names the name of the province for which they are registered. The jurisdiction of the Philippine National Co-operative Bank may extend to the entire country with its headquarters at Manila while the jurisdiction of the provincial co-operative banks may extend to the province for which each one is registered unless necessary sanction is obtained under subsection (3) of section twenty-five of this Act and their headquarters shall be in the capital or any city of the province concerned as determined by the Administrator."}},{"id":"PH-H1769-A118","no":118,"noLabel":{"en":"Section 118."},"chapter":{"en":"CHAPTER XV"},"text":{"en":"Membership. Membership of co-operative banks may include co-operatives, federations of co-operatives and individual members who join in the articles of incorporation of the co-operative bank and co-operatives, federations of co-operatives and individual members admitted to membership by the board of directors of such bank after registration. Affiliated co-operatives shall be known as class \"A\" members and individual members shall be known as class \"B\" members."}},{"id":"PH-H1769-A119","no":119,"noLabel":{"en":"Section 119."},"chapter":{"en":"CHAPTER XV"},"text":{"en":"Board of Directors. The general assembly of every co-operative bank shall elect a board of directors, whose number and proportionate representation between class \"A\" and class \"B\" members shall be determined from time to time by the Secretary of Commerce and Industry in the regulations or by special order in writing, but in no case shall the directors representing the class \"B\" members be more than one third of the entire board of directors. Each class of members shall exercise their right to elect their share of representatives in the board of directors. The President, Secretary, Treasurer and Manager of every co-operative bank shall be appointed, their salaries determined and paid by the Secretary of Commerce and Industry in consultation with the board of directors of the co-operative bank concerned and the Administrator, until such time as, but not earlier than five years after registration of, the co-operative bank concerned, through a resolution of its general assembly, expresses to the Secretary of Commerce and Industry that it can elect or appoint, as the case may be, all or any of the said persons and pay their or his salary out of its fund without jeopardizing the co-operative bank's financial stability and thereafter the Secretary of Commerce and Industry shall withdraw all or any of the persons appointed by him and requested to be withdrawn by the co-operative bank and allow the co-operative bank to fill in the post according to its by-laws. The persons appointed by the Secretary of Commerce and Industry and the Administrator or his representative shall be ex officio directors of the board and ex officio members of the executive committee, if any, created. The president shall be the chairman of the general assembly, board and the executive committee."}},{"id":"PH-H1769-A120","no":120,"noLabel":{"en":"Section 120."},"chapter":{"en":"CHAPTER XV"},"text":{"en":"Budget control. The board of directors shall not recommend a budget to the general assembly nor shall the general assembly approve a budget which shall involve an expenditure exceeding such percentage of the gross earnings of the previous year or the anticipated realizable gross earnings of the next year whichever is lower as shall be determined by the Administrator and the Central Bank of the Philippines."}},{"id":"PH-H1769-A121","no":121,"noLabel":{"en":"Section 121."},"chapter":{"en":"CHAPTER XV"},"text":{"en":"Loans. All loans which shall be granted by the co-operative banks to the affiliated co-operatives shall be for short and intermediate terms, the former not to exceed a maximum period of fifteen months and the latter not to exceed a maximum period of three years and shall be brought to the notice of the Administrator, except loans on investments held or deposited by the affiliated co-operatives in the co-operative banks. Loans which are declared to be risky by the Administrator shall not be granted by the board of directors of the co-operative banks. Class \"B\" members shall not be eligible for loans except on deposits they hold in the co-operative banks and other securities that may be approved by the board of directors."}},{"id":"PH-H1769-A122","no":122,"noLabel":{"en":"Section 122."},"chapter":{"en":"CHAPTER XV"},"text":{"en":"Administrative control. The co-operative banks registered under this Act shall submit to the supervision of the Administrator so far as the provisions of this Act are concerned and the Monetary Board of the Philippines on banking transactions so far as the supervision of the Monetary Board of the Philippines is not inconsistent with the provisions of this Act."}},{"id":"PH-H1769-A123","no":123,"noLabel":{"en":"Section 123."},"chapter":{"en":"CHAPTER XV"},"text":{"en":"Capital. (1) The Philippine National Co-operative Bank shall have an authorized capital of ten million pesos (P10,000,000) divided into shares of one hundred pesos par value each. The shares shall be divided into two groups marked series \"A\" and series \"B\".\n(a) Series \"A\" shall comprise of five million pesos (P5,000,000) to be subscribed for by the Government of the Philippines. On registration of the Philippine National Co-operative Bank, the Philippine Government shall pay towards subscription of the said amount, one million pesos (P1,000,000) and the balance shall be paid in each year on a fund-matching basis with the owned capital of the Philippine National Co-operative Bank. The owned capital shall include share capital under clause (b) of this section, reserve fund and other funds set apart in accordance with this Act and excludes payments received from the Philippine Government under this clause. The shares held by the Philippine Government shall not be entitled to any interest or votes.\n(b) Series \"B\" shall comprise of five million pesos (P5,000,000) to be subscribed for by the affiliated co-operatives and individual members.\n(c) If the Philippine National Co-operative Bank does not have sufficient owned capital to receive further payments towards capital by the Philippine Government on fund-matching basis under clause (a) of this section, the Government of the Philippines may authorize the said bank to issue debentures under subsection (2) of section seventy-seven of this Act.\n(2) Each provincial co-operative bank shall have an initial authorized capital of one million pesos (P1,000,000) divided into shares of one hundred pesos par value each. The shares shall be divided into two groups marked series \"A\" and series \"B\".\n(a) Series \"A\" shall comprise of five hundred thousand pesos (P500,000) to be subscribed for by the Government of the Philippines. On registration of each provincial co-operative bank, the Government shall pay towards subscription of the said amount one hundred thousand pesos (P100,00) and the balance shall be paid in each year on the fund-matching basis with the owned capital of the provincial co-operative bank. The owned capital shall be as mentioned in clause (a) of subsection (1). The government may provide its share of capital contribution under this clause by directing the Central Bank of the Philippines to extend the same benefits as are extended to the rural banks under the Rural Bank Act, without contravening the co-operative basis or the provisions of this Act. The shares held by the Government shall not be entitled to any interest or votes while contribution towards shares if paid in under the Rural Bank Act shall be entitled only to interest as provided under the Rural Bank Act.\n(b) Series \"B\" shall comprise of five hundred thousand pesos (P500,00) to be subscribed for by the affiliated co-operatives and individual members.\n(3) The by-laws of every co-operative bank shall specify a percentage of each loan borrowed by affiliated co-operatives to be invested as share capital in the lending co-operative bank."}},{"id":"PH-H1769-A124","no":124,"noLabel":{"en":"Section 124."},"chapter":{"en":"CHAPTER XV"},"text":{"en":"Audit. Subject to the provisions of Section eighty-six the general assembly of every co-operative bank shall also make separate arrangement for audit of their accounts and shall appoint an auditor to audit the accounts of the bank and to submit report to the board of directors and the general assembly as often as is required by them."}},{"id":"PH-H1769-A125","no":125,"noLabel":{"en":"Section 125."},"chapter":{"en":"CHAPTER XV"},"text":{"en":"Distribution of savings. The provisions under Chapter VIII Allocation and Distribution of savings of this Act shall apply to the distribution of savings of co-operative banks except that the Reserve Fund to be set apart shall at least be twenty-five per cent of the net saving and the general assembly shall decide whether to allow patronage refund or not; and if to be allowed, the amount to be utilized for patronage refund."}},{"id":"PH-H1769-A126","no":126,"noLabel":{"en":"Section 126."},"chapter":{"en":"CHAPTER XV"},"text":{"en":"Privileges. In addition to the privileges granted in Chapter VI, the co-operative banks shall be granted the following privileges:\n(a) The Government of the Philippines shall provide free transfer of funds between the co-operative banks and its affiliated co-operatives; and\n(b) The co-operative banks registered under this Act shall be given the same privileges as are granted to the rural banks under the Rural Bank Act of the Philippines without affecting in any way the provisions of this Act.\nSpecial provisions relating to co-operative wholesale societies"}},{"id":"PH-H1769-A127","no":127,"noLabel":{"en":"Section 127."},"chapter":{"en":"CHAPTER XVI"},"text":{"en":"Applicability of provisions. The special provisions under this Chapter are applicable only to co-operative wholesale societies registered under this Act and the other provisions of this Act will apply to them only in so far as they are not against the express provisions contained in this Chapter."}},{"id":"PH-H1769-A128","no":128,"noLabel":{"en":"Section 128."},"chapter":{"en":"CHAPTER XVI"},"text":{"en":"Objectives. (1) The objects of co-operative wholesale societies are to facilitate the operation of consumers and producers co-operatives in particular and retailers in general by being a source of steady supply and disposal of domestic requirements of their members, and The Philippine Co-operative Wholesale Society may\n(a) Purchase, produce and supply in wholesale quantities through the provincial co-operative wholesale societies, if in existence, to the affiliated co-operatives with goods which they require for domestic purposes of their members and to retailers and their associations or corporations who have become members;\n(b) Enter into retail trade as far as it is necessary;\n(c) Import goods from other countries and as far as possible through the Co-operative Movement of other countries;\n(d) Establish branches in each province where no provincial co-operative wholesale society exists, with a view to convert such branches into provincial co-operative wholesale societies;\n(e) Undertake to distribute essential commodities to the people in case of emergencies, under the control of the Government;\n(f) Stand guarantee for the affiliated co-operatives;\n(g) Market the products manufactured including articles of handicrafts and small industry by the affiliated co-operatives, either by the outright purchase or on commission basis;\n(h) Provide training of its employees and the employees of the affiliated co-operatives and spread knowledge as to why and how the consumers should organize themselves;\n(i) Protect the interest of the consumers and producers co-operatives in the sphere of legislation; and\n(j) Carry on all other objects as may be prescribed in the regulations.\n(2) The provincial co-operative wholesale societies may, in addition to the objects noted in clauses (b), (e), ( f ), (g) and (h) of subsection (1) of this section, may\n(a) Act as agent of The Philippine Co-operative Wholesale Society; and\n(b) Carry on all other objects as may be prescribed in the regulations."}},{"id":"PH-H1769-A129","no":129,"noLabel":{"en":"Section 129."},"chapter":{"en":"CHAPTER XVI"},"text":{"en":"Registration. No co-operative wholesale society shall be registered by the Administrator, unless the articles of incorporation and the by-laws of such co-operative wholesale society have been approved by the Secretary of Commerce and Industry and the co-operative wholesale society satisfies all the provisions for registration of federations of co-operatives. There may be registered one co-operative wholesale society at the national level to serve as the chief source of supply and marketing of goods required and produced by the affiliated co-operatives and one provincial co-operative wholesale society in each province."}},{"id":"PH-H1769-A130","no":130,"noLabel":{"en":"Section 130."},"chapter":{"en":"CHAPTER XVI"},"text":{"en":"Name and jurisdiction. The co-operative wholesale society at the National level may be known as \"The Philippine Co-operative Wholesale Society\" with its jurisdiction all over the country and headquarters at Manila. The co-operative wholesale societies at the provincial level may be known as \"The Provincial Co-operative Wholesale Society\" and shall include in their names the name of the province for which they are registered. The jurisdiction of the provincial co-operative wholesale societies shall extend to the province for which each one is registered unless necessary sanction is obtained under subsection (3) of Section twenty five of this Act and their headquarters shall be in the capital or any city of the province concerned as determined by the Administrator."}},{"id":"PH-H1769-A131","no":131,"noLabel":{"en":"Section 131."},"chapter":{"en":"CHAPTER XVI"},"text":{"en":"Membership. Membership of co-operative wholesale societies may consist of consumers and producers co-operatives together with their federations and retailers or their associations or corporations and shall include all those of the above description who join in the articles of incorporation of any co-operative wholesale society and all those of the above description admitted to membership by the board of directors of such co-operative wholesale society after registration. Affiliated co-operatives shall be known as class \"A\" members and retailers and their associations or corporations shall be known as class \"B\" members."}},{"id":"PH-H1769-A132","no":132,"noLabel":{"en":"Section 132."},"chapter":{"en":"CHAPTER XVI"},"text":{"en":"Voting. Each member attending the general assembly shall have one vote as a member and shall have as many votes in addition according to the scale to be prescribed in the by-laws, giving weight for the business done with the co-operative wholesale society concerned."}},{"id":"PH-H1769-A133","no":133,"noLabel":{"en":"Section 133."},"chapter":{"en":"CHAPTER XVI"},"text":{"en":"Board of directors. The general assembly of every co-operative wholesale society shall elect a board of directors, whose number and proportionate representation between class \"A\" and class \"B\" members shall be determined from time to time by the Secretary of Commerce and Industry in the regulations or by special order in writing. Each class of members shall exercise their right to elect their share of representatives in the board of directors. The President, Secretary, Treasurer and Manager of every co-operative wholesale society shall be appointed, their salaries determined and paid by the Philippine Government in consultation with the board of directors of the co-operative wholesale society concerned and the Administrator, until such time as, but not earlier than five years after registration of, the co-operative wholesale society concerned through a resolution of its general assembly, express to the Secretary of Commerce and Industry that it can elect or appoint, as the case may be, all or any of the said persons and pay their or his salary out of its fund without jeopardizing its financial stability and thereafter the Secretary of Commerce and Industry shall withdraw all or any of the persons appointed by him and requested to be withdrawn by the co-operative wholesale society and allow the co-operative wholesale society to fill in the post according to its by-laws. The persons appointed by the Secretary of Commerce and Industry, the Administrator or his representative and the General Manager of the National Marketing Corporation or his representative so long as the National Marketing Corporation exists, shall be ex officio directors of the board and ex officio members of the Executive committee, if any, created. The President shall be the chairman of the general assembly, board and the executive committee."}},{"id":"PH-H1769-A134","no":134,"noLabel":{"en":"Section 134."},"chapter":{"en":"CHAPTER XVI"},"text":{"en":"Manager. The Manager of the co-operative wholesale society shall be responsible for the day-to-day management of the business in accordance with the decisions of the board and the executive committee. The duties of the manager shall be specified in the by-laws of every co-operative wholesale society."}},{"id":"PH-H1769-A135","no":135,"noLabel":{"en":"Section 135."},"chapter":{"en":"CHAPTER XVI"},"text":{"en":"Budget control. The board of directors shall not recommend a budget to the general assembly nor shall the general assembly approve a budget which shall involve an expenditure exceeding such percentage of the gross earnings of the previous year or the anticipated realizable gross earnings of the next year whichever is lower as shall be determined by the Administrator."}},{"id":"PH-H1769-A136","no":136,"noLabel":{"en":"Section 136."},"chapter":{"en":"CHAPTER XVI"},"text":{"en":"Borrowing. Subject to the regulations, the general assembly shall fix a maximum limit of borrowings for each year. As far as possible, all the banking transactions shall be done with the co-operative banks."}},{"id":"PH-H1769-A137","no":137,"noLabel":{"en":"Section 137."},"chapter":{"en":"CHAPTER XVI"},"text":{"en":"Terms of business. All sales to members shall be on cash basis: Provided, however, That the members may order supplies on indent basis with a deposit of a percentage of the value as determined by the board of directors at the time of order and payment of the balance on delivery: Provided, further, That when a member refuses to receive and pay for the supplies after order, the said deposit may be forfeited in whole or in part at the discretion of the board."}},{"id":"PH-H1769-A138","no":138,"noLabel":{"en":"Section 138."},"chapter":{"en":"CHAPTER XVI"},"text":{"en":"Capital. (1) The Philippine Co-operative Wholesale Society shall have an authorized capital of ten million pesos (P10,000,000) divided into shares of one hundred pesos par value each. The shares shall be divided into two groups marked series \"A\" and series \"B\".\n(a) Series \"A\" shall comprise of five million pesos (P5,000,000) to be subscribed for by the Government of the Philippines. On registration of the Philippine Co-operative Wholesale Society the Government shall pay towards subscription of the said amount one million pesos (P1,000,000) and the balance shall be paid in each year on a fund-matching basis with the owned capital of the Philippine Co-operative Wholesale Society. The owned capital shall include paid-up share capital under clause (b) of this section, reserve fund and other funds set apart under this Act and excludes payments received from the Government under this clause. The shares held by the Government shall not be entitled to any interest or votes.\n(b) Series \"B\" shall comprise of five million pesos (P5,000,000) to be subscribed for by the members of the co-operative wholesale society.\n(2) Each provincial co-operative wholesale society shall have an initial authorized capital of one million pesos (P1,000,000) divided into two groups marked series \"A\" and series \"B\".\n(a) Series \"A\" shall comprise of five hundred thousand pesos (P500,000) to be subscribed for by the Government of the Philippines. On registration of each provincial co-operative wholesale society, the Government shall pay towards subscription of the said amount one hundred thousand pesos (P100,000) and the balance shall be paid in each year on a fund-matching basis with the owned capital of the provincial co-operative wholesale society. The owned capital shall be as mentioned in clause (a) of subsection (1). The shares held by the Government shall not be entitled to any interest or votes.\n(b) Series \"B\" shall comprise of five hundred thousand pesos (P500,000) to be subscribed for by class \"A\" and class \"B\" members.\n(3) The proportion of shares to be purchased by members in relation to their membership, paid-in capital and the business done with the co-operative wholesale society, as the case may be, shall be specified in the by-laws."}},{"id":"PH-H1769-A139","no":139,"noLabel":{"en":"Section 139."},"chapter":{"en":"CHAPTER XVI"},"text":{"en":"Warehouse financing. The Government of the Philippines through any of its agencies may provide long term loans to any or all co-operative wholesale societies or authorize them issue debentures to finance the building of warehouses, provided that such co-operative wholesale societies finance at least twenty per centum of the cost of the warehouse. The security for the loans or the debentures shall be the warehouse built."}},{"id":"PH-H1769-A140","no":140,"noLabel":{"en":"Section 140."},"chapter":{"en":"CHAPTER XVI"},"text":{"en":"Audit. Subject to the provisions of Section eighty six the general assembly of every co-operative wholesale society shall also make separate arrangement for audit of their accounts and shall appoint an auditor to audit the accounts of the co-operative wholesale society and to submit report to the board of directors and the general assembly as often as in required by them."}},{"id":"PH-H1769-A141","no":141,"noLabel":{"en":"Section 141."},"chapter":{"en":"CHAPTER XVI"},"text":{"en":"Distribution of savings. The provisions under Chapter VIII Allocation and Distribution of Savings of this Act shall apply to the distribution of savings of co-operative wholesale societies except that the Reserve Fund to be set aside shall at least be twenty-five per cent of the net savings."}},{"id":"PH-H1769-A142","no":142,"noLabel":{"en":"Section 142."},"chapter":{"en":"CHAPTER XVI"},"text":{"en":"Liquidation. Subject to the provisions of Chapter XI, every co-operative wholesale society shall seek liquidation when one half of its paid-capital has been lost. The Philippine Government shall have first charge on the assets of the co-operative wholesale society under liquidation."}},{"id":"PH-H1769-A143","no":143,"noLabel":{"en":"Section 143."},"chapter":{"en":"CHAPTER XVI"},"text":{"en":"Privileges. In addition to the privileges granted in Chapter VI, the co-operative wholesale societies shall be granted the following privileges:\n(a) The Government of the Philippines may provide sufficient facilities for import and export of goods and the necessary exchange of currency for the business operation;\n(b) The National Marketing Corporation shall at progressive stages transfer its trade to the co-operative wholesale societies and in the meanwhile treat the co-operative wholesale societies as its agents and extend better concessions to them than shown to individuals, retailers or their associations or corporations; and\n(c) The Government of the Philippines may give preference in procuring its requirement through or from the co-operative wholesale societies as far the terms of supply of co-operative wholesale societies are equal to that of any individual or corporations.\nMiscellaneous"}},{"id":"PH-H1769-A144","no":144,"noLabel":{"en":"Section 144."},"chapter":{"en":"CHAPTER XVII"},"text":{"en":"Money how recovered. Every order issued for the recovery of any sum granted or transferred under this Act in respect of which no specific mode of recovery is provided, shall, if not carried out, on a certificate signed by the Administrator or liquidator which shall be deemed as a decree of court, be executed by any court having jurisdiction in the same manner as a decree of such court, or on a certificate signed by the Administrator and forwarded to the Collector of Internal Revenue who shall proceed to recover the amount in the same manner as if it were an arrears of internal revenue and the collection handed over to the Administrator for disposal to the proper authority, provided that all sums due from a co-operative to the Government or otherwise recoverable from a co-operative may be recovered firstly, from the property of the co-operative; secondly, in the case of a co-operative with limited liability from the members, past members, estates of deceased members or their sureties subject to the limit of their liability and thirdly, in the case of other co-operatives from the members, past members or estates of deceased members or their sureties to such extent or in such proportion as may be determined by the Administrator."}},{"id":"PH-H1769-A145","no":145,"noLabel":{"en":"Section 145."},"chapter":{"en":"CHAPTER XVII"},"text":{"en":"Enforcement of orders. Every order issued under Chapters IX, XI and XII, in addition to any other method of enforcement under this Act, shall be submitted to a court of competent jurisdiction for approval and enforcement as in any ordinary case."}},{"id":"PH-H1769-A146","no":146,"noLabel":{"en":"Section 146."},"chapter":{"en":"CHAPTER XVII"},"text":{"en":"Register of co-operatives. The Administrator shall maintain a register wherein he shall chronologically note every co-operative registered or cancelled under this Act together with information required under Section sixteen and any other information considered useful by him. He shall publish every year a list of co-operatives in existence, under dissolution and whose registration is cancelled during the year together with such information on each of them as may be prescribed in the regulations."}},{"id":"PH-H1769-A147","no":147,"noLabel":{"en":"Section 147."},"chapter":{"en":"CHAPTER XVII"},"text":{"en":"Acts of co-operative, etc., not to be invalidated by certain defects. (1) No act of a co-operative or board or committee or of any officer or liquidator done in good faith in the course of the business of the co-operative shall be deemed to be invalid by reason only of some defect subsequently discovered in the registration of the co-operatives or in the formation of the general assembly or in the constitution of board or committee or in the appointment or election of directors, committee members, liquidator or officer or on the ground that such person was disqualified for his appointment.\n(2) No act done in good faith by any person appointed under this Act shall be invalid by reason only of the fact that his appointment has been cancelled by or in consequence of any order subsequently passed under this Act.\n(3) The Administrator shall decide whether any act done was in good faith under this section."}},{"id":"PH-H1769-A148","no":148,"noLabel":{"en":"Section 148."},"chapter":{"en":"CHAPTER XVII"},"text":{"en":"Notice to Administrator in suits against co-operatives necessary. No suit shall be instituted against a co-operative or persons representing it in respect of any act touching the business of the co-operative until the expiration of two months after notice in writing has been delivered to the Administrator, stating the cause of action, the name and postal address of the person giving notice and the relief he claims, together with a statement that such notice has been delivered."}},{"id":"PH-H1769-A149","no":149,"noLabel":{"en":"Section 149."},"chapter":{"en":"CHAPTER XVII"},"text":{"en":"Private transfer of property made after issue of certificate void against co-operative. Any private transfer or delivery of, or encumbrance or charge in, property made or created after the issue of the certificate of the Administrator or liquidator, as the case may be, under section one hundred forty-four shall be null and void as against the co-operative on whose application the said certificate was issued."}},{"id":"PH-H1769-A150","no":150,"noLabel":{"en":"Section 150."},"chapter":{"en":"CHAPTER XVII"},"text":{"en":"Board of directors of National Co-operative Union. The composition of the board of directors of the National Co-operative Union shall be such as to consist of all interest representing the Co-operative Movement and the Government of the Philippines."}},{"id":"PH-H1769-A151","no":151,"noLabel":{"en":"Section 151."},"chapter":{"en":"CHAPTER XVII"},"text":{"en":"Review and revision. (1) Within thirty days from notice of an order issued by the Administrator in a proceeding under this Act, any person aggrieved thereby may obtain a review of such order by the Secretary of Commerce and Industry. Upon such petition for review or motu propio, the Secretary of Commerce and Industry shall have the power to affirm, modify, or set aside, in whole or in part, any order of the Administrator.\n(2) The Administrator may at any time\n(a) Revise any order issued by himself; or\n(b) Call for and examine the record any inquiry or inspection held or made under this Act or the proceedings of any person acting on his authority, and if it appears to him that any decision, order or award or any proceedings so called for should for any reason be modified, annulled or reversed, he may issue such orders thereon as he thinks fit:\nProvided, That, before any order is made under subsections (1) and (2) the Secretary of Commerce and Industry or the Administrator, as the case may be, shall afford to any person, likely to be affected adversely by such order, an opportunity to be heard.\n(3) The Administrator shall submit, through the Secretary of Commerce and Industry, at the end of each calendar year a review of the activities of the Co-operatives Administration Office during the year and its plans and programs for the following year for the consideration and approval of the National Economic Council in line with the economic development program: Provided, That in the first year of its operation after the approval of this Act, attention shall be given to the promotion of one co-operative wholesale society and one-co-operative bank at the national level, and consumers co-operatives; in the second year, attention shall be given to the promotion of industrial co-operatives in urban and rural communities; and in the third year, attention shall be given to the strengthening of credit co-operative societies: Provided, further, That the organization of such co-operatives shall be done gradually, starting with localities where conditions are most suitable for their successful operation."}},{"id":"PH-H1769-A152","no":152,"noLabel":{"en":"Section 152."},"chapter":{"en":"CHAPTER XVII"},"text":{"en":"Repeals. All acts, executive orders, rules and regulations or parts thereof in conflict with the provisions of this Act, are repealed. If any provision of this Act shall be held invalid the remainder shall not be affected thereby."}},{"id":"PH-H1769-A153","no":153,"noLabel":{"en":"Section 153."},"chapter":{"en":"CHAPTER XVII"},"text":{"en":"Appropriation: nonagricultural co-operative fund. To carry out the provisions of this Act, there is hereby authorized to be appropriated, out of any funds in the National Treasury not otherwise appropriated, the sum fifty million pesos (P50,000,000.00), which shall be known as the Non-Agricultural Co-operative Fund: Provided, however, That of the said sum, two million two hundred fifty thousand pesos (P2,250,00) shall be made immediately available from the proceeds of the bonds authorized to be issued under Republic Act Numbered One Thousand for the following purposes:\n(a) Two million pesos (P2,000,000.00) for the initial capital investments required under Chapters XV and XVI, and\n(b) Two hundred fifty thousand pesos (P250,000.00) for certain costs of administration provided for in Sections one hundred nineteen and one hundred thirty-three hereof."}},{"id":"PH-H1769-A154","no":154,"noLabel":{"en":"Section 154."},"chapter":{"en":"CHAPTER XVII"},"text":{"en":"Report to Congress. The Administrator, through the Secretary of Commerce and Industry, shall submit to Congress copy of the rules and regulations promulgated by him in accordance with the provisions of this Act, as well as an annual report of the nonagricultural co-operatives program established under this Act."}},{"id":"PH-H1769-A155","no":155,"noLabel":{"en":"Section 155."},"chapter":{"en":"CHAPTER XVII"},"text":{"en":"Effectivity. This Act shall take effect upon its approval.\nApproved: June 22, 1957."}}],"pack":"ph-p25"};
  FT["PH-H1770"] = {"id":"PH-H1770","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1957/ra_2031_1957.html","fetchedAt":"2026-10-06","articleCount":2,"structureMode":"ARTICLE","title":{"zh":"修订第146号联邦法第14条（c）项（经修正），将拖船与驳船从公共服务委员会的管辖、监督与控制中排除的法案","en":"An Act Amending Subsection (c), Section Fourteen, of Commonwealth Act Numbered One Hundred and Forty-Six, as Amended, by Removing from the Jurisdiction, Supervision and Control of the Public Service Commission Tugboats and Lighters","orig":"An Act Amending Subsection (c), Section Fourteen, of Commonwealth Act Numbered One Hundred and Forty-Six, as Amended, by Removing from the Jurisdiction, Supervision and Control of the Public Service Commission Tugboats and Lighters"},"level":"law","status":"active","topics":["administrative"],"docNumber":"Republic Act No. 2031","issuingBody":"Congress of the Philippines","promulgatedDate":"1957-06-23","completenessNote":"全文，共 2 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1957/ra_2031_1957.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H1770-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"Subsection (c), section fourteen, of Commonwealth Act Numbered One hundred and forty-six, as amended by Commonwealth Act Numbered Four hundred and fifty-four, is further amended to read as follows:\n\"(c) Vehicles drawn by animals and bancas moved by oar or sail, and tugboats and lighters.\""}},{"id":"PH-H1770-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"This Act shall take effect on its approval.\nEnacted, without executive approval, June 23, 1957."}}],"pack":"ph-p25","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act Amending Subsection (c), Section Fourteen, of Commonwealth Act Numbered One Hundred and Forty-Six, as Amended, by Removing from the Jurisdiction, Supervision and Control of the Public Service Commission Tugboats and Lighters","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H1771"] = {"id":"PH-H1771","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1957/ra_2032_1957.html","fetchedAt":"2026-10-06","articleCount":2,"structureMode":"ARTICLE","title":{"zh":"1932年重组法","en":"The Reorganization Law of Nineteen Hundred and Thirty-Two","orig":"An Act to Amend Section Ten of Act Numbered Four Thousand and Seven, Known as “The Reorganization Law of Nineteen Hundred and Thirty-Two”"},"level":"law","status":"active","topics":["general"],"docNumber":"Republic Act No. 2032","issuingBody":"Congress of the Philippines","promulgatedDate":"1957-06-23","completenessNote":"全文，共 2 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1957/ra_2032_1957.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H1771-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"Section ten of Act Numbered Four thousand and seven, known as \"The Reorganization Law of Nineteen hundred and thirty-two\", is hereby amended to read as follows:\n\"Sec. 10. The Commissioner of Civil Service shall be Executive Officer of all the Boards of Examiners hereinafter named and shall conduct the examinations given by said Boards according to the rules and regulations promulgated by him and approved by the President. Subject to the approval of the President the Commissioner shall designate a ranking officer of his bureau to act as Secretary of all the Boards of Examiners and who shall receive a compensation of six thousand pesos per annum. The bureau shall, under the direct custody of the Secretary keep all the records of the Boards of Examiners, including examination papers, minutes of deliberations, and records of administrative proceedings and investigations of all the Boards. Examination and registration fees shall be paid to the disbursing officer for the Bureau of Civil Service and such officer shall pay from the receipts thereof all the authorized expenses of the different Boards, including the compensation provided for herein.\"\n\"The Board of Accountancy, the Board of Examiners for Marine Officers, the Board of Examiners for Marine Engineers, the Board of Medical Examiners, the Board of Dental Examiners, the Board of Pharmaceutical Examiners, the Board of Optical Examiners, the Board of Examiners for Nurses, the Veterinary Examining Board, the Board of Examiners for Surveyors, the Board of Examiners for Civil Engineers, the Board of Mechanical Engineering Examiners, the Board of Mining Engineering, the Board of Examiners for Chemical Engineers, the Board of Examiners for Architects, shall each be composed of a chairman and two members, who shall be appointed by the President of the Philippines, upon the recommendation of the Commissioner of Civil Service, from among such persons of recognized standing in their professions as may be certified as having practiced at least ten years, except the Board of Examiners for Marine Officers, which practice should be fifteen years including that acquired from third mate to master and harbor or coast pilot, academically and morally qualified by their respective bona fide professional organizations, who shall serve for a period of three years, and who shall receive compensation not to exceed ten pesos per capita of the candidates examined, or registered without examination: Provided, That members of the first boards to be appointed after the approval of this Act shall hold office for the following terms: Chairman for three years, one member for two years, and one member for one year: Provided, further, That the President of the Philippines shall designate any chairman of any of the sixteen boards as executive chairman as official spokesman of all the examiners without extra compensation, to see that the office of the Boards of Examiners performs its function efficiently and other duties necessary to insure the efficient performance of the duties of each Board in conducting examination, raising the ethical and educational standards of the different professions and shall be given a transportation monthly allowance of one hundred and fifty pesos.\n\"Subject to the approval of the President and with the advice of the Commissioner of Civil Service, the Boards aforementioned shall promulgate necessary rules and regulations, set professional standards for the practice of their respective professions and prescribe collegiate courses for same. The Boards shall report within one hundred twenty days after each examination the results therefor to the Commissioner of Civil Service, who shall in turn and with his recommendation, submit such results to the President for approval. After approval thereof the Board concerned shall issue the registration certificate attested by the Secretary entitling the candidate to whom it is issued to practice the profession for which he has taken the examination. The same procedure shall be followed with respect to registration certificates without examination.\n\"Except as modified by this Act, all laws governing examinations given by the above-mentioned boards shall continue in force."}},{"id":"PH-H1771-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 23, 1957."}}],"pack":"ph-p25","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"The Reorganization Law of Nineteen Hundred and Thirty-Two","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H1772"] = {"id":"PH-H1772","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1957/ra_2033_1957.html","fetchedAt":"2026-10-06","articleCount":2,"structureMode":"ARTICLE","title":{"zh":"规定保和省图比贡市镇现称Panaytayon小学的学校今后名称为Jose Boja小学的法案","en":"An Act Providing that the School in the Municipality of Tubigon, Province of Bohol, at Present Known as Panaytayon Primary School, Shall Hereafter be Known as Jose Boja Primary School","orig":"An Act Providing that the School in the Municipality of Tubigon, Province of Bohol, at Present Known as Panaytayon Primary School, Shall Hereafter be Known as Jose Boja Primary School"},"level":"law","status":"active","topics":["education"],"docNumber":"Republic Act No. 2033","issuingBody":"Congress of the Philippines","promulgatedDate":"1957-06-23","completenessNote":"全文，共 2 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1957/ra_2033_1957.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H1772-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"The school in the Municipality of Tubigon, Province of Bohol, at present known as Panaytayon Primary School, shall hereafter be known as Jose Boja Primary School."}},{"id":"PH-H1772-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 23, 1957."}}],"pack":"ph-p25","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act Providing that the School in the Municipality of Tubigon, Province of Bohol, at Present Known as Panaytayon Primary School, Shall Hereafter be Known as Jose Boja Primary School","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H1773"] = {"id":"PH-H1773","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1957/ra_2034_1957.html","fetchedAt":"2026-10-06","articleCount":2,"structureMode":"ARTICLE","title":{"zh":"废止莱特省纳瓦尔市镇的希加坦甘岛希加坦甘村，并在该市镇另行设立利伯塔德村与马比尼村的法案","en":"An Act Abolishing the Barrio of Higatangan, Higatangan Island, Municipality of Naval, Province of Leyte, and Creating Instead the Barrios of Libertad and Mabini in the Same Municipality","orig":"An Act Abolishing the Barrio of Higatangan, Higatangan Island, Municipality of Naval, Province of Leyte, and Creating Instead the Barrios of Libertad and Mabini in the Same Municipality"},"level":"law","status":"active","topics":["general"],"docNumber":"Republic Act No. 2034","issuingBody":"Congress of the Philippines","promulgatedDate":"1957-06-23","completenessNote":"全文，共 2 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1957/ra_2034_1957.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H1773-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"The barrio of Higatangan, Higatangan Island, Municipality of Naval, Province of Leyte, is abolished and instead its sitios of Libertad and Mabini are converted into barrios of the same municipality, to be known as the barrios of Libertad and Mabini, respectively."}},{"id":"PH-H1773-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 23, 1957."}}],"pack":"ph-p25","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act Abolishing the Barrio of Higatangan, Higatangan Island, Municipality of Naval, Province of Leyte, and Creating Instead the Barrios of Libertad and Mabini in the Same Municipality","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H1774"] = {"id":"PH-H1774","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1957/ra_2035_1957.html","fetchedAt":"2026-10-06","articleCount":11,"structureMode":"ARTICLE","title":{"zh":"授予 Zoilo E. Masculino 在菲律宾境内建设、维护和运营私人船岸与陆上移动无线电台的临时许可的法案","en":"An Act Granting Zoilo E. Masculino a Temporary Permit to Construct, Maintain and Operate Private Boat-to-Shore and Land Mobile Radio Stations for the Reception and Transmission of Radio Communications Within the Philippines","orig":"An Act Granting Zoilo E. Masculino a Temporary Permit to Construct, Maintain and Operate Private Boat-to-Shore and Land Mobile Radio Stations for the Reception and Transmission of Radio Communications Within the Philippines"},"level":"law","status":"active","topics":["general"],"docNumber":"Republic Act No. 2035","issuingBody":"Congress of the Philippines","promulgatedDate":"1957-06-23","completenessNote":"全文，共 11 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1957/ra_2035_1957.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H1774-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"There is hereby granted to Zoilo E. Masculino, his successors or assigns, a temporary permit to construct, maintain and operate in the Philippines, at such places as the said grantee may select, subject to the approval of the Secretary of Public Works and Communications, private boat-to-shore and land mobile radio stations for the reception and transmission of wireless messages on radiotelegraphy or radiotelephony, each station to be provided with a radio transmitting apparatus and a radio receiving apparatus."}},{"id":"PH-H1774-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"This temporary permit shall continue to be in force during the time that the Government has not established similar service at the places selected by the grantee, and is granted upon the express condition that the same shall be void unless the grantee shall start the operation thereof within one and one-half years from the date of approval of this Act."}},{"id":"PH-H1774-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"The grantee, his successors or assigns, shall not engage in domestic business of telecommunications in the Philippines without further special assent of the Congress of the Philippines, it being understood that the purpose of this temporary permit is to secure to the grantee the right to construct, install, maintain and operate private boat-to-shore and land mobile radio stations in such places within the Philippines as the interest of the grantee and of his trade and business may justify."}},{"id":"PH-H1774-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"Fees shall not be charged by the grantee as the radio stations that may be established by virtue of this Act shall engage in communication regarding the grantee’s business only."}},{"id":"PH-H1774-A5","no":5,"noLabel":{"en":"Section 5."},"text":{"en":"The grantee, his successors or assigns, shall so construct and operate his radio stations as not to interfere with the operation of other radio stations maintained and operated in the Philippines."}},{"id":"PH-H1774-A6","no":6,"noLabel":{"en":"Section 6."},"text":{"en":"The grantee, his successors or assigns, shall hold the national, provincial, city, and municipal governments of the Philippines harmless from all claims, accounts, demands, or actions arising out of accidents or injuries, whether to property or to persons, caused by the construction or operation of its radio stations."}},{"id":"PH-H1774-A7","no":7,"noLabel":{"en":"Section 7."},"text":{"en":"The grantee, his successors or assigns, shall be subject to the corporation laws of the Philippines now existing or which may hereafter be enacted."}},{"id":"PH-H1774-A8","no":8,"noLabel":{"en":"Section 8."},"text":{"en":"The grantee, his successors or assigns, is authorized to operate his private boat-to-shore and land mobile radio station in the medium frequency, high frequency and very high frequency that may be assigned to him by the Secretary of Public Works and Communications."}},{"id":"PH-H1774-A9","no":9,"noLabel":{"en":"Section 9."},"text":{"en":"A special right is hereby reserved to the President of the Philippines, in time of war, insurrection, public peril, calamity or disaster, to cause the closing of the grantee’s radio stations or to authorize the temporary use or possession thereof by any department of the Government, upon payment of just compensation."}},{"id":"PH-H1774-A10","no":10,"noLabel":{"en":"Section 10."},"text":{"en":"This temporary permit shall be subject to amendment, alteration, or repeal by the Congress of the Philippines when the public interest so requires, and shall not be interpreted as an exclusive grant of the privileges herein provided for."}},{"id":"PH-H1774-A11","no":11,"noLabel":{"en":"Section 11."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 23, 1957."}}],"pack":"ph-p25","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act Granting Zoilo E. Masculino a Temporary Permit to Construct, Maintain and Operate Private Boat-to-Shore and Land Mobile Radio Stations for the Reception and Transmission of Radio Communications Within the Philippines","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H1775"] = {"id":"PH-H1775","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1957/ra_2036_1957.html","fetchedAt":"2026-10-06","articleCount":16,"structureMode":"ARTICLE","title":{"zh":"授予菲律宾无线电通信公司设立国内电信无线电台的特许经营权法案","en":"An Act Granting the Radio Communications of the Philippines a Franchise to Establish Radio Stations for Domestic Telecommunications","orig":"An Act Granting the Radio Communications of the Philippines a Franchise to Establish Radio Stations for Domestic Telecommunications"},"level":"law","status":"active","topics":["investment","data"],"docNumber":"Republic Act No. 2036","issuingBody":"Congress of the Philippines","promulgatedDate":"1957-06-23","completenessNote":"全文，共 16 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1957/ra_2036_1957.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H1775-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"Subject to the provisions of the Constitution, and to the provisions, not inconsistent herewith, of Act Numbered Three thousand eight hundred and forty-six, entitled \"An Act providing for the regulation of radio stations and radio communications in the Philippines Islands, and for other purposes;\" Commonwealth Act Numbered One hundred forty-six, known as the Public Service Act, and their amendments, and other applicable laws, there is hereby granted to the Radio Communications of the Philippines, its successors or assigns, the right and privilege of constructing, installing, establishing and operating in the Philippines, at such places as the said corporation may select and the Secretary of Public Works and Communications may approve, radio stations for the reception and transmission of wireless message on radiotelegraphy and/or radiotelephony, including both coastal and marine telecommunications, each station to consist of two radio apparatus comprising of receiving and sending radio apparatus."}},{"id":"PH-H1775-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"The President of the Philippines shall have the power and authority to permit the construction of said stations or any of them on any land of the public domain upon such terms and conditions as he may prescribe."}},{"id":"PH-H1775-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"This franchise shall continue for a period of fifty years from the date the first of said stations shall be place in operation, and is granted upon the express condition that the same shall be void unless the construction of said stations be begun within two years from the date of the approval of this Act and be completed within four years from said date."}},{"id":"PH-H1775-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"(a) This franchise shall not take effect nor shall any powers thereunder be exercised by the grantee until the Secretary of Public Works and Communications shall have allotted to the grantee the frequencies and wave lengths to be used, and issued to the grantee a license for such use.\n(b) The Secretary of Public Works and Communications, on reasonable notice to the grantee, may at any time change, or cancel, or modify, in whole or in part, any or all of the allotments of frequencies or wave lengths to be used. He may take such actions (1) whenever in his judgment such frequencies and wave lengths have been used, or there is danger that they will be used by the grantee to impair electrical communication, or stifle competition, to obtain a monopoly in electrical communication, or to secure unreasonable rates for such communication, or to violate otherwise the laws or public policy of the Philippine Republic; (2) whenever in his judgment the public interests of the Republic of the Philippines require that such frequencies or wave lengths should be used for other purposes than those of the grantee, either by the Government of the Philippines or by other individuals or corporations licensed by it; and (3) whenever in his judgment, for any reason, the public interests of the Philippines so require."}},{"id":"PH-H1775-A5","no":5,"noLabel":{"en":"Section 5."},"text":{"en":"The stations of the grantee shall be so constructed and operated and the wave lengths so selected as to avoid interference with existing stations and to permit the expansion of the grantee's services."}},{"id":"PH-H1775-A6","no":6,"noLabel":{"en":"Section 6."},"text":{"en":"A special right is reserved to the President of the Philippines in time of war, rebellion, public peril, calamity, disaster or disturbance of peace or order to cause the closing of the said stations or to authorize the temporary use and operation thereof by any department of the Government upon payment of just compensation to the grantee for the use of said stations during the period when they shall be so operated."}},{"id":"PH-H1775-A7","no":7,"noLabel":{"en":"Section 7."},"text":{"en":"The grantee shall hold the national, provincial, and municipal governments of the Philippines harmless from all claims, accounts, demands, or actions arising out of accidents or injuries, whether to property or to persons, caused by the construction or operation of the stations of the grantee."}},{"id":"PH-H1775-A8","no":8,"noLabel":{"en":"Section 8."},"text":{"en":"No private property shall be taken for any purpose by the grantee without proper condemnation proceedings and just compensation paid or tendered therefor, and any authority to take and occupy land contained herein shall not apply to the taking, use, or occupation of any land except such as is required for the actual necessary purposes for which this franchise is granted."}},{"id":"PH-H1775-A9","no":9,"noLabel":{"en":"Section 9."},"text":{"en":"The grantee shall keep an account of the gross receipts of its business and shall furnish to the Auditor General and the Treasurer of the Philippines a copy of such account not later than the thirty-first day of January of each year for the preceding year. All the books and accounts of the grantee pertaining to its business shall be subject to the official inspection of the Auditor General or his authorized representatives, and the audit and approval of such accounts shall be final and conclusive evidence as to the amount of said gross receipts, except that the grantee shall have the right to appeal to the courts of the Philippines, under the terms and conditions provided in the laws of the Philippines."}},{"id":"PH-H1775-A10","no":10,"noLabel":{"en":"Section 10."},"text":{"en":"The grantee, its successors or assigns, shall be subject to the corporation laws of the Philippines now existing or hereafter enacted."}},{"id":"PH-H1775-A11","no":11,"noLabel":{"en":"Section 11."},"text":{"en":"The grantee, shall file a bond in the amount of fifty thousand pesos to guaranty for the full compliance and fulfillment of the conditions under which this franchise is granted. If, after four years from the date of the approval of this Act, the grantee shall have fulfilled said conditions, or as soon thereafter as the grantee shall have fulfilled the same, the bond aforesaid shall be cancelled by the Government."}},{"id":"PH-H1775-A12","no":12,"noLabel":{"en":"Section 12."},"text":{"en":"The grantee shall not lease, transfer, grant the usufruct of, sell or assign this franchise, nor the rights or privileges acquired thereunder to any person, firm, company, corporation or other commercial or legal entity, nor merge with any other person, company, or corporation organized for the same purpose, without the approval of the Congress of the Philippines first had. Any corporation to which this franchise may be sold, transferred, or assigned, shall be subject to the corporation laws of the Philippines now existing or hereafter enacted, and any person, firm, company, corporation or other commercial or legal entity to which this franchise is sold, transferred, or assigned shall be subject to all conditions, terms, restrictions and limitations of this franchise as fully and completely and to the same extent as if the franchise had been originally granted to the said person, firm, company, corporation or other commercial or legal entity."}},{"id":"PH-H1775-A13","no":13,"noLabel":{"en":"Section 13."},"text":{"en":"In the event of any legal competing individual, partnership or corporation receiving from the Congress a similar franchise in which there shall be any term or terms more favorable than those herein granted or tending to place the herein grantee at any disadvantage, then such term or terms shall, ipso facto, become a part of the terms hereof and shall operate equally in favor of the grantee as in the case of said competing individual, partnership or corporation."}},{"id":"PH-H1775-A14","no":14,"noLabel":{"en":"Section 14."},"text":{"en":"(a) The grantee shall be liable to pay the same taxes on its real estate, buildings, and personal property, exclusive of the franchise, as other persons or corporations are now or hereafter may be required by law to pay.\n(b) The grantee shall further pay to the Treasurer of the Philippines each year, within ten days the audit and approval of the accounts as prescribed in this Act one and one-half per centum of all gross receipts from the business transacted under this franchise by the said grantee."}},{"id":"PH-H1775-A15","no":15,"noLabel":{"en":"Section 15."},"text":{"en":"This franchise shall not be interpreted to mean an exclusive grant of the privileges herein provided for."}},{"id":"PH-H1775-A16","no":16,"noLabel":{"en":"Section 16."},"text":{"en":"This Act shall take effect upon its approval.\nEnacted, without Executive approval, June 23, 1957."}}],"pack":"ph-p25","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act Granting the Radio Communications of the Philippines a Franchise to Establish Radio Stations for Domestic Telecommunications","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H1776"] = {"id":"PH-H1776","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1957/ra_2037_1957.html","fetchedAt":"2026-10-06","articleCount":14,"structureMode":"ARTICLE","title":{"zh":"授予 Ricardo P. Ocampo 先生在菲律宾建设、安装、设立和运营公共无线电话与无线电报海岸站及相关中继站、陆上移动站的临时许可的法案","en":"An Act Granting Mr. Ricardo P. Ocampo, Residing at Number One Hundred Forty C. Francisco, Makati, Rizal, Philippines, a Temporary Permit to Construct, Install, Establish and Operate Public Radiotelephone and Radiotelegraph Coastal Stations, with the Corresponding Relay Stations, and Public Fixed and Public Base and Land Mobile Stations for the Reception and Transmission of Radiotelephone and Radiotelegraph Communications Within the Philippines not at Present Served by Public Radiotelegraph and/or Radiotelephone Systems Such as in Lumber and Mining Concessions, Farms, Deep-Sea Fishing and Isolated Municipalities","orig":"An Act Granting Mr. Ricardo P. Ocampo, Residing at Number One Hundred Forty C. Francisco, Makati, Rizal, Philippines, a Temporary Permit to Construct, Install, Establish and Operate Public Radiotelephone and Radiotelegraph Coastal Stations, with the Corresponding Relay Stations, and Public Fixed and Public Base and Land Mobile Stations for the Reception and Transmission of Radiotelephone and Radiotelegraph Communications Within the Philippines not at Present Served by Public Radiotelegraph and/or Radiotelephone Systems Such as in Lumber and Mining Concessions, Farms, Deep-Sea Fishing and Isolated Municipalities"},"level":"law","status":"active","topics":["environment"],"docNumber":"Republic Act No. 2037","issuingBody":"Congress of the Philippines","promulgatedDate":"1957-06-23","completenessNote":"全文，共 14 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1957/ra_2037_1957.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H1776-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"There is hereby granted and conceded to Mr. Ricardo P. Ocampo, residing at 140 C. Francisco, Makati, Rizal, Philippines, his successors or assigns, the temporary right and privilege of constructing, installing, establishing and operating in the Philippines and at such places as the grantee may select, subject to the approval of the Department Secretary under whose jurisdiction the Radio Control Division is functioning, or any competent authority who is or shall be authorized now or in the future to give said approval, public coastal road stations with the corresponding relay stations, and public fixed and public base and land mobile stations for the reception and transmission of wireless messages on radiotelephony (voice) and/or radiotelegraphy, or both, within the Philippines and with vessels at sea and aircrafts over the air, irrespective of whether such vessels and aircrafts are within or without the Philippines: Provided, However , That Mr. Ricardo P. Ocampo shall only establish and operate such public fixed and public base and land mobile stations in lumber and mining concessions, farms, municipalities and other places not at present served by public radiotelegraph and/or radiotelephone systems."}},{"id":"PH-H1776-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"The President of the Philippines shall have the power and authority to permit the location on the public domain upon such terms as he may prescribed any or all of the land radio stations that may be established under this grant."}},{"id":"PH-H1776-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"This temporary permit shall continue to be in force during the time that the Government has not established similar service at the places selected by the grantee, and is made upon the express condition that the same shall be void unless the construction of said stations be begun within three years from the date of approval of this Act and be completed within five years from said date."}},{"id":"PH-H1776-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"A special right is hereby reserved to the President of the Philippines in time of war, insurrection, public peril, calamity or disaster to cause the closing of the stations or to authorize the temporary use or possession thereof by any department of the Government, upon payment of just compensation."}},{"id":"PH-H1776-A5","no":5,"noLabel":{"en":"Section 5."},"text":{"en":"The grantee, his successors or assigns, shall hold the national, provincial and municipal governments of the Philippines harmless from all claims, accounts, demands, or actions arising out of accidents or injuries, whether to property or to persons caused by the construction, or operation of the stations for reception and transmission of wireless messages by the grantee, his successors or assigns."}},{"id":"PH-H1776-A6","no":6,"noLabel":{"en":"Section 6."},"text":{"en":"The grantee, his successors or assign, shall so construct and operate his radio stations as not to interfere with the operation of other radio stations maintained and operated in the Philippines."}},{"id":"PH-H1776-A7","no":7,"noLabel":{"en":"Section 7."},"text":{"en":"No private property shall be taken for any purpose by the grantee of this temporary permit, his successors or assigns, without proper condemnation proceedings and just compensation paid or tendered therein, and any authority to take and occupy land contained herein shall not authorize the taking, use, or occupation of any land except such as is required for the actual necessary purposes for which the temporary permit is granted. All lands or rights of use and occupation of lands granted to the grantee, his successors or assigns, shall, upon the termination of this temporary permit or upon its revocation or repeal, revert to the national, provincial or municipal government to which such land or right to use and occupy belonged at the time of the grant thereof or the right to use and occupy the same was conceded to the grantee herein, his successors or assigns."}},{"id":"PH-H1776-A8","no":8,"noLabel":{"en":"Section 8."},"text":{"en":"The right is hereby reserved to the Government of the Philippines, through the Public Service Commission, or such other government agency as may hereafter be duly authorized, to fix the maximum rates or charges to be charged by the grantee."}},{"id":"PH-H1776-A9","no":9,"noLabel":{"en":"Section 9."},"text":{"en":"The grantee shall keep a separate account of the gross receipts of the business transacted by him in the Philippines, and shall furnish the Auditor General and the Treasurer of the Philippines a copy of such account not later than the thirty-first day of January of each year for the preceding year. For the purpose of auditing the accounts so rendered to the Auditor General and the National Treasurer, all the books and accounts of the grantee, or duplicates thereof, so far as they relate to the business transacted in the Philippines shall be kept in the Philippines, and shall be subject to the official inspection of the Auditor General or his authorized representatives, and the audit and approval of such accounts shall be final and conclusive evidence as to the amount of said gross receipts, except that the grantee shall have the right to appeal to the courts of the Philippines, under the terms and conditions provided in the laws of the Philippines."}},{"id":"PH-H1776-A10","no":10,"noLabel":{"en":"Section 10."},"text":{"en":"As a condition of the granting of this temporary permit the grantee shall execute a bond in favor of the Government of the Philippines in the sum of fifty thousand pesos, in form and with sureties satisfactory to the Secretary of Public Works and Communications, conditioned upon the faithful performance of the grantee’s obligations hereunder during the first three years of the life of this temporary permit. If, after three years from the date of the acceptance of this temporary permit, the grantee shall have fulfilled the same, the bond aforesaid shall be cancelled by the Secretary of Public Works and Communications."}},{"id":"PH-H1776-A11","no":11,"noLabel":{"en":"Section 11."},"text":{"en":"Acceptance of this temporary permit shall be given in writing within six months after approval of this Act. When so accepted by the grantee and upon the approval of the bond aforesaid by the Secretary of Public Works and Communications the grantee shall be empowered to exercise the privilege granted thereby."}},{"id":"PH-H1776-A12","no":12,"noLabel":{"en":"Section 12."},"text":{"en":"The grantee shall not lease, transfer, grant the usufruct of, sell or assign this temporary permit, nor the rights or privileges acquired thereunder to any person, firm, company, corporation or other commercial or legal entity, nor merge with any other person, company or corporation organized for the same purpose, without the approval of the Congress of the Philippines first had. Any corporation to which this temporary permit may be sold, transferred, or assigned, shall be subject to the corporation laws of the Philippines now existing or hereafter enacted, and any person, firm, company, corporation or other commercial or legal entity to which this temporary permit is sold, transferred, or assigned shall be subject to all conditions, terms, restrictions and limitations of this temporary permit as fully and completely and to the same extent as if the temporary permit had been originally granted to the said person, firm, company, corporation or other commercial or legal entity."}},{"id":"PH-H1776-A13","no":13,"noLabel":{"en":"Section 13."},"text":{"en":"This temporary permit shall be subject to amendment, alteration, or repeal by the Congress of the Philippines when the public interest so requires and shall not be interpreted as an exclusive grant of the privilege herein provided for."}},{"id":"PH-H1776-A14","no":14,"noLabel":{"en":"Section 14."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 23, 1957."}}],"pack":"ph-p25","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act Granting Mr. Ricardo P. Ocampo, Residing at Number One Hundred Forty C. Francisco, Makati, Rizal, Philippines, a Temporary Permit to Construct, Install, Establish and Operate Public Radiotelephone and Radiotelegraph Coastal Stations, with the Corresponding Relay Stations, and Public Fixed and Public Base and Land Mobile Stations for the Reception and Transmission of Radiotelephone and Radiotelegraph Communications Within the Philippines not at Present Served by Public Radiotelegraph and/or Radiotelephone Systems Such as in Lumber and Mining Concessions, Farms, Deep-Sea Fishing and Isolated Municipalities","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H1777"] = {"id":"PH-H1777","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1957/ra_2038_1957.html","fetchedAt":"2026-10-06","articleCount":6,"structureMode":"ARTICLE","title":{"zh":"将达沃省 Compostela 市镇划分为两个市镇，其一沿用原名，另一名为 Nabunturan 市镇的法案","en":"An Act Dividing the Municipality of Compostela, Province of Davao, into Two Municipalities, One to Retain the Name “Compostela,” and the Other to be Known as the Municipality of Nabunturan","orig":"An Act Dividing the Municipality of Compostela, Province of Davao, into Two Municipalities, One to Retain the Name “Compostela,” and the Other to be Known as the Municipality of Nabunturan"},"level":"law","status":"active","topics":["general"],"docNumber":"Republic Act No. 2038","issuingBody":"Congress of the Philippines","promulgatedDate":"1957-06-23","completenessNote":"全文，共 6 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1957/ra_2038_1957.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H1777-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"The Municipality of Compostela, Province of Davao, is hereby divided into two municipalities, one to retain the name \"Compostela,\" and the other to be known as the Municipality of Nabunturan, with the seat of government at the present barrio of Nabunturan."}},{"id":"PH-H1777-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"The boundary line between the two municipalities shall run straight northwesterly from the Municipal Boundary Monument No. 15, located on the boundary between the present Municipality of Compostela and the Municipality of Pantukan, to Barrio Boundary Monument No. 4, located near the barrio of Siocon, and there to Municipal Boundary Monument No. 7, located on the boundary between the present Municipality of Compostela and the Municipality of Monkayo."}},{"id":"PH-H1777-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"The Municipality of Nabunturan, as herein organized, shall contain the barrios of Linoan, Pangotosan, Magading, Cabidianan, Manat, Kaw, Mainit, Andili, Nuevo Iloco, Sao-sao, Libasan, and Nabunturan, and the sitios of Matilo, Anislagan, New Leyte, Guisok, Tabontabon, Sasa and Linda."}},{"id":"PH-H1777-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"The Municipality of Compostela shall have its present territory minus the portion thereof included in the Municipality of Nabunturan. It shall transfer its seat of government, now temporarily at the barrio of Nabunturan, to Compostela proper, but it shall not hereafter construct or establish any public building, plaza, or playground within Compostela proper, which is situated in a patented area owned by a single individual."}},{"id":"PH-H1777-A5","no":5,"noLabel":{"en":"Section 5."},"text":{"en":"The present mayor, vice-mayor and councilors of Compostela who are now in the barrio of Nabunturan shall, until the expiration of their term of office, act respectively as mayor, vice-mayor and councilors of the new Municipality of Nabunturan, and their substitutes in the Municipality of Compostela shall be appointed by the President of the Philippines, to hold office until their successors shall have been elected in the next regular election of provincial and municipal officials, and shall have qualified."}},{"id":"PH-H1777-A6","no":6,"noLabel":{"en":"Section 6."},"text":{"en":"This Act shall take effect thirty days after its approval.\nApproved: June 23, 1957."}}],"pack":"ph-p25","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act Dividing the Municipality of Compostela, Province of Davao, into Two Municipalities, One to Retain the Name “Compostela,” and the Other to be Known as the Municipality of Nabunturan","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H1778"] = {"id":"PH-H1778","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1957/ra_2039_1957.html","fetchedAt":"2026-10-06","articleCount":2,"structureMode":"ARTICLE","title":{"zh":"将高山省 Kayan 市镇的政府所在地从其现址迁至同一市镇 Tadian 村所在地的法案","en":"An Act Transferring the Seat of Government of the Municipality of Kayan, Mountain Province, from its Present Site to the Site of the Barrio of Tadian in the Same Municipality","orig":"An Act Transferring the Seat of Government of the Municipality of Kayan, Mountain Province, from its Present Site to the Site of the Barrio of Tadian in the Same Municipality"},"level":"law","status":"active","topics":["general"],"docNumber":"Republic Act No. 2039","issuingBody":"Congress of the Philippines","promulgatedDate":"1957-06-23","completenessNote":"全文，共 2 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1957/ra_2039_1957.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H1778-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"The seat of government of the Municipality of Kayan, Mountain Province, is transferred to the site of the barrio of Tadian in the same municipality."}},{"id":"PH-H1778-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 23, 1957."}}],"pack":"ph-p25","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act Transferring the Seat of Government of the Municipality of Kayan, Mountain Province, from its Present Site to the Site of the Barrio of Tadian in the Same Municipality","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H1779"] = {"id":"PH-H1779","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1957/ra_2040_1957.html","fetchedAt":"2026-10-06","articleCount":4,"structureMode":"ARTICLE","title":{"zh":"关于延长碧瑶乡村俱乐部公司法人存续期的法案","en":"An Act to Extend the Corporate Existence of the Baguio Country Club Corporation","orig":"An Act to Extend the Corporate Existence of the Baguio Country Club Corporation"},"level":"law","status":"active","topics":["company"],"docNumber":"Republic Act No. 2040","issuingBody":"Congress of the Philippines","promulgatedDate":"1957-06-23","completenessNote":"全文，共 4 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1957/ra_2040_1957.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H1779-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"The corporate existence of the Baguio Country Club Corporation is hereby extended for fifty years counting from the nineteenth day of February, nineteen hundred and fifty-seven, subject to the filing by said corporation with the Securities and Exchange Commission of a copy of its amended articles of incorporation, duly certified to be correct by the president and the secretary of the corporation and a majority of the board of directors, setting out that its corporate existence is to expire fifty years from the nineteenth day of February, nineteenth hundred and fifty-seven."}},{"id":"PH-H1779-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"The Securities and Exchange Commission shall be entitled to collect and receive for the filing of the amended article of incorporation, referred to in section one, the same fees that it may be entitled to collect and receive for the filing of articles of incorporation as now provided by law."}},{"id":"PH-H1779-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"All Acts or parts of Acts inconsistent or in conflict with this Act are hereby repealed."}},{"id":"PH-H1779-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 23, 1957."}}],"pack":"ph-p25","titleTranslation":{"engine":"manual-llm","reviewed":false,"source":"An Act to Extend the Corporate Existence of the Baguio Country Club Corporation","note":"人工逐条翻译（模型产出，未经人工复核）；公司名、地名、机构名保留原文。"}};
  FT["PH-H1780"] = {"id":"PH-H1780","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1957/ra_2041_1957.html","fetchedAt":"2026-10-06","articleCount":6,"structureMode":"ARTICLE","title":{"zh":"授予 Metropolitan Express 公司经营信使与快递服务的特许权法案","en":"An Act to Grant to the Metropolitan Express Company, Incorporated, a Franchise to Conduct a Messenger and Delivery Express Service","orig":"An Act to Grant to the Metropolitan Express Company, Incorporated, a Franchise to Conduct a Messenger and Delivery Express Service"},"level":"law","status":"active","topics":["investment","company"],"docNumber":"Republic Act No. 2041","issuingBody":"Congress of the Philippines","promulgatedDate":"1957-06-23","completenessNote":"全文，共 6 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1957/ra_2041_1957.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H1780-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"Any provision of law to the contrary notwithstanding, the Metropolitan Express Company, Incorporated, a Philippines corporation duly registered with the Securities and Exchange Commission, is hereby granted a franchise to conduct a messenger and delivery express service of packages and of oral or written messages, at regular intervals and/or in specific or rush emergency cases through all hours of the day, for a period of fifty years from the approval of this Act."}},{"id":"PH-H1780-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"The grantee is hereby empowered to fix its service charges subject to the approval of the Public Service Commission."}},{"id":"PH-H1780-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"The Metropolitan Express Company, Incorporated, in addition to the taxes imposed by the Internal Revenue Code, shall also pay an additional annual tax at the rate of one per cent on its net profit, the proceeds of which shall accrue to the National Government."}},{"id":"PH-H1780-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"This franchise is granted subject to the condition that it shall be subject to the amendment, alteration, or repeal when the public interest so requires and shall not be understood as exclusive in character."}},{"id":"PH-H1780-A5","no":5,"noLabel":{"en":"Section 5."},"text":{"en":"The grantee shall file a bond in the amount of ten thousand pesos to answer for any loss or damages that any customer or customers may sustain."}},{"id":"PH-H1780-A6","no":6,"noLabel":{"en":"Section 6."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 23, 1957."}}],"pack":"ph-p25","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act to Grant to the Metropolitan Express Company, Incorporated, a Franchise to Conduct a Messenger and Delivery Express Service","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H1781"] = {"id":"PH-H1781","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1957/ra_2042_1957.html","fetchedAt":"2026-10-06","articleCount":2,"structureMode":"ARTICLE","title":{"zh":"经费拨款法","en":"An Act Appropriating the Sum of Three Million Twenty-Eight Thousand Pesos for the Salary Adjustments of High School Teachers in Provinces and Cities and of Intermediate School Teachers in Cities in Pursuance of Republic Act Numbered Eight Hundred and Forty-Two","orig":"An Act Appropriating the Sum of Three Million Twenty-Eight Thousand Pesos for the Salary Adjustments of High School Teachers in Provinces and Cities and of Intermediate School Teachers in Cities in Pursuance of Republic Act Numbered Eight Hundred and Forty-Two"},"level":"law","status":"active","topics":["education"],"docNumber":"Republic Act No. 2042","issuingBody":"Congress of the Philippines","promulgatedDate":"1957-06-23","completenessNote":"全文，共 2 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1957/ra_2042_1957.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H1781-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"The sum of three million twenty-eight thousand pesos, or so much thereof as may be necessary, is hereby appropriated, out of any funds in the National Treasury not otherwise appropriated, as an aid to provincial, municipal and/or city governments to effect the salary adjustments and/or increases for teachers and other personnel in the public high schools being maintained and operated by such governments, as well as of teachers and other personnel in the public intermediate schools being maintained and operated by city governments, in pursuance of the provisions of Republic Act Numbered Eight hundred forty-two, otherwise known as the Public Schools Salary Act of Nineteen hundred fifty-three."}},{"id":"PH-H1781-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"This Act shall take effect upon its approval.\nEnacted, without Executive Approval, June 23, 1957."}}],"pack":"ph-p25"};
  FT["PH-H1782"] = {"id":"PH-H1782","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1957/ra_2043_1957.html","fetchedAt":"2026-10-06","articleCount":2,"structureMode":"ARTICLE","title":{"zh":"将安蒂克省达奥市镇塔吉姆蒂姆村更名为帕西恩西亚的法案","en":"An Act Changing the Name of the Barrio of Taguimtim, Municipality of Dao, Province of Antique, to Paciencia","orig":"An Act Changing the Name of the Barrio of Taguimtim, Municipality of Dao, Province of Antique, to Paciencia"},"level":"law","status":"active","topics":["general"],"docNumber":"Republic Act No. 2043","issuingBody":"Congress of the Philippines","promulgatedDate":"1957-06-23","completenessNote":"全文，共 2 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1957/ra_2043_1957.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H1782-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"The name of the barrio of Taguimtim, Municipality of Dao, Province of Antique, is hereby changed to Paciencia."}},{"id":"PH-H1782-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 23, 1957."}}],"pack":"ph-p25","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act Changing the Name of the Barrio of Taguimtim, Municipality of Dao, Province of Antique, to Paciencia","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H1783"] = {"id":"PH-H1783","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1957/ra_2044_1957.html","fetchedAt":"2026-10-06","articleCount":14,"structureMode":"ARTICLE","title":{"zh":"授予 Joseph De Castro 在马尼拉、Legaspi、Tacloban、Davao 等地建设、安装、维护和运营无线电报及无线电话站的特许经营权法案","en":"An Act Granting Joseph De Castro a Franchise to Construct, Install, Maintain and Operate Radiotelegraph and/or Radiotelephone Stations in Manila, Legaspi, Tacloban, Davao, Zamboanga and Cagayan De Oro","orig":"An Act Granting Joseph De Castro a Franchise to Construct, Install, Maintain and Operate Radiotelegraph and/or Radiotelephone Stations in Manila, Legaspi, Tacloban, Davao, Zamboanga and Cagayan De Oro"},"level":"law","status":"active","topics":["investment"],"docNumber":"Republic Act No. 2044","issuingBody":"Congress of the Philippines","promulgatedDate":"1957-06-23","completenessNote":"全文，共 14 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1957/ra_2044_1957.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H1783-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"There is hereby granted Joseph de Castro, Filipino, of legal age, with residence and postal address at 21 Spencer Street, Cubao, Quezon City, his successors and assigns, and hereunder referred to as the \"grantee,\" a franchise to construct, install, maintain and operate radiotelegraph and/or radiotelephone stations in Manila, Legaspi, Tacloban, Davao, Zamboanga and Cagayan de Oro, in the domestic point-to-point and coastal maritime service with the corresponding relay stations for the reception and transmission of wireless messages on radiotelephony and/or radiotelegraphy, or both, with vessels at sea and aircrafts in the air within or without the Philippines."}},{"id":"PH-H1783-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"This grant shall continue for a period of fifty years from the date said stations shall be put in operation: Provided, However , That at least three such stations shall be established and ready for operation within the period of six months after the approval of this Act."}},{"id":"PH-H1783-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"The President of the Philippines shall have the power and authority to permit the location on the public domain, upon such terms as he may prescribe, any or all of the land radio stations that may be established under this grant."}},{"id":"PH-H1783-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"A special right is reserved to the President of the Philippines in time of war, insurrection, public peril, calamity or disaster to cause the closing of the station or to authorize the temporary use or possession thereof by any department of the Government, upon payment of just compensation."}},{"id":"PH-H1783-A5","no":5,"noLabel":{"en":"Section 5."},"text":{"en":"The grantee, his successors or assigns, shall hold the national, provincial and municipal governments of the Philippines harmless from all claims, accounts, demands, or actions arising out of accidents or injuries, whether to property or to persons, caused by the construction, or operation of the stations for reception and transmission of wireless messages by the grantee, his successors or assigns."}},{"id":"PH-H1783-A6","no":6,"noLabel":{"en":"Section 6."},"text":{"en":"The grantee, his successors or assigns, shall so construct and operate his radio stations as not to interfere with the operation of other radio stations maintained and operated in the Philippines."}},{"id":"PH-H1783-A7","no":7,"noLabel":{"en":"Section 7."},"text":{"en":"No private property shall be taken of any purpose by the grantee of this franchise, his successors or assigns, without proper condemnation proceedings and just compensation tendered therein, and authority to take and occupy land contained herein shall not authorize the taking, use, or occupation of any land except such as is required for the actual necessary purposes for which the franchise is granted. All lands or rights of use and occupation of lands granted to the grantee, his successors or assigns, shall, upon the termination of this franchise or upon its revocation or repeal, revert to the national, provincial or municipal government to which such land or right to use and occupy belonged at the time of the grant thereof or the right to use and occupy the same was conceded to the grantee herein, his successors or assigns."}},{"id":"PH-H1783-A8","no":8,"noLabel":{"en":"Section 8."},"text":{"en":"The right to fix the maximum rates or charges to be charged by the grantee is reversed to the Government of the Philippines through the Public Service Commission or such other government agency as may hereafter be duly authorized."}},{"id":"PH-H1783-A9","no":9,"noLabel":{"en":"Section 9."},"text":{"en":"The grantee shall keep a separate account of the gross receipts of business transacted by it in the Philippines and shall furnish the Auditor General and the Treasurer of the Philippines a copy of such account not later than the thirty-first day of January of each year for the preceding year. For the purpose of auditing the accounts surrendered to the Auditor General and National Treasurer, all the books and accounts of the grantee, or duplicates thereof, so far as they relate to the business transacted in the Philippines shall be kept in the Philippines and shall be subject to the official inspection of the Auditor General or his authorized representatives, and the audit or approval of such accounts shall be final and conclusive evidence as to the amount of said gross receipts, except that the grantee shall have the right to appeal to the courts of the Philippines, under the terms and conditions provided in the laws of the Philippines."}},{"id":"PH-H1783-A10","no":10,"noLabel":{"en":"Section 10."},"text":{"en":"As a condition of the granting of this franchise the grantee shall execute a bond in favor of the Government of the Philippines in the sum of fifty thousand pesos, in a form and with sureties satisfactory to the Secretary of Public Works and Communications, conditioned upon the faithful performance of the grantee’s obligations hereunder during the first three years of the life of this franchise. If, after three years from the date of the acceptance of this franchise, the grantee shall have fulfilled the same, the bond aforesaid shall be cancelled by the Secretary of Public Works and Communications."}},{"id":"PH-H1783-A11","no":11,"noLabel":{"en":"Section 11."},"text":{"en":"Acceptance of this franchise shall be given in writing within three months after approval of this Act. When so accepted by the grantee and upon the approval of the bond aforesaid by the Secretary of Public Works and Communications the grantee shall be empowered to exercise the privileges granted hereby."}},{"id":"PH-H1783-A12","no":12,"noLabel":{"en":"Section 12."},"text":{"en":"The grantee shall not lease, transfer, grant the usufruct of, sell or assign this franchise, nor the rights or privileges acquired thereunder to any person, firm, company, corporation or other commercial or legal entity, nor merge with any other person, company or corporation organized for the same purpose, without the approval of the Congress of the Philippines first had. Any corporation to which this franchise may be sold, transferred, or assigned, shall be subject to the corporation laws of the Philippines now existing or hereafter enacted, and any person, firm, company, corporation or other commercial or legal entity to which this franchise is sold, transferred, or assigned shall be subject to all conditions, terms, restrictions and limitations of this franchise as fully and completely and to the same extent as if the franchise had been originally granted to the said person, firm, company, corporation or other commercial or legal entity."}},{"id":"PH-H1783-A13","no":13,"noLabel":{"en":"Section 13."},"text":{"en":"This franchise shall be subject to amendment, alteration, or repeal by the Congress of the Philippines when the public interest so requires, and shall not be interpreted as an exclusive grant of the privileges herein provided for."}},{"id":"PH-H1783-A14","no":14,"noLabel":{"en":"Section 14."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 23, 1957."}}],"pack":"ph-p25","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act Granting Joseph De Castro a Franchise to Construct, Install, Maintain and Operate Radiotelegraph and/or Radiotelephone Stations in Manila, Legaspi, Tacloban, Davao, Zamboanga and Cagayan De Oro","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H1784"] = {"id":"PH-H1784","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1957/ra_2045_1957.html","fetchedAt":"2026-10-06","articleCount":12,"structureMode":"ARTICLE","title":{"zh":"授予黎刹省 San Mateo 市镇电灯、供热与动力系统特许权的法案","en":"An Act Granting the Municipality of San Mateo, Province of Rizal, a Franchise for an Electric Light, Heat and Power System","orig":"An Act Granting the Municipality of San Mateo, Province of Rizal, a Franchise for an Electric Light, Heat and Power System"},"level":"law","status":"active","topics":["investment"],"docNumber":"Republic Act No. 2045","issuingBody":"Congress of the Philippines","promulgatedDate":"1957-06-23","completenessNote":"全文，共 12 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1957/ra_2045_1957.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。 源文条号不连续（自第 1 条起，止于第 13 条，缺 3）：经逐条比对原始页面，该处原文没有对应的 “Section N.” 抬头行，系来源页自身的编号跳跃或条文以“续段”形式并入前条，非抽取遗漏，故未擅自补号。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H1784-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"Subject to the terms and conditions established in Act Numbered Thirty-six hundred thirty-six, as amended by Commonwealth Act Numbered One hundred thirty-two, and to the provisions of the Constitution, there is granted to the Municipality of San Mateo, Province of Rizal, for a period of fifty years from the approval of this Act, the right, privilege, and authority to construct, maintain, and operate an electric light, heat and power system for the purpose of generating and distributing electric light, heat, and/or power for sale within the Municipality of San Mateo, Province of Rizal."}},{"id":"PH-H1784-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"Rates for electricity— Limit of net profit. -The rates for electricity shall be fixed so that the grantee obtains a profit of not more than six per centum per annum of the rate base as defined herein: Provided, That no grantee shall start operation unless the original rate shall have been previously approved by the Public Service Commission: Provided, further, That the grantee which shall have reported profits in excess of six per centum per annum for the first year of its operation shall effect immediate reduction in its existing rates by a percentage which the reported profits in excess of six per centum per annum bear to the reported revenue in that year: Provided, further, That during each succeeding years, the grantee reporting profits still in excess of six per centum per annum, notwithstanding the rate reduction of the immediately preceding years, shall effect reduction in rates by a percentage which the reported profits in excess of six per centum per annum during the preceding year bear to the reported revenue of the same year, such reduction to be made not later than April first of each year retroactive to January first of the same year: Provided, further, That where the applicable reduction to customers will mean less than one per centum reduction in the prevailing rates or will include such a fraction, no reduction in rates shall be made to the extent of such fraction but such amount shall be placed in a special fund of the grantee available only for the improvement and expansion of the system; Provided, further, That the reduction to be effected by the grantee in accordance with the next preceding proviso shall not be conclusive but may be further increased at such rates as shall be found justifiable in the verification that shall be undertaken by the Public Service Commission, with the cooperation of the General Auditing Office and such other agencies of the Government as the President may designate, of the rate base of the revenue, and of the operating expenses: Provided, further, That any violation of any provision of this section, including inflation of the rate base, padding of operating expenses, and understatement of revenues, shall be penalized with dismissal from the service, and by imprisonment for not less than one year and not more than five years, of the public officers and employees responsible for the violation, without prejudice to the civil liability of the grantee concerned to the consumers in double the amount of the over charge plus attorneys fees and costs of litigation, which liability may be enforced independently of the criminal action arising from the same act.\nThe net profit obtained by the grantee shall not be used for any purpose other than the improvement and expansion of the system.\nSection 3 . Records of assets, liabilities, capital, income etc. -The grantee shall make and keep complete records of its assets, liabilities, capital, revenues, expenses, income, and operations in accordance with a detailed system of accounts which shall embody the cost principle as defined in section seven hereof, and which shall be prescribed by the Public Service Commission or its legal successor, and such accounting system shall conform to the system approved by the Auditor General. The grantee shall account for retirements or replacements of, or additions to, its property according to a classified list of units of property which the Public Service Commission or its legal successor shall prescribe. Until the Public Service Commission or its legal successor prescribes the aforementioned list of units of property, the grantee may adopt its own list of property which it shall submit to the Public Service Commission or its legal successor for approval."}},{"id":"PH-H1784-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"Record of amount of depreciation of depreciable property. -The grantee shall record in its accounts at the end of each month the estimated amount of depreciation of every depreciable property for that month computed according to the straight-line method, as defined in section seven hereof. In estimating such accrued depreciation the grantee shall use its own judgment as to the estimated service lives and depreciation rates of its depreciable property which it shall submit to the Public Service Commission or its legal successor for approval, until such time as the Public Service Commission or its legal successor fixes the service lives and depreciation rates which the grantee shall be required to use thereafter."}},{"id":"PH-H1784-A5","no":5,"noLabel":{"en":"Section 5."},"text":{"en":"Definition of terms. -For purposes of this Act, the following terms are defined as follows:\n\"Cost\" means the amount of money actually paid for property or services or their cash value at the time of the transaction.\n\"Units of property\" means those items of property which when retired, with or without replacement, are accounted for by crediting the book cost thereof to the property account in which included.\n\"Straight-line method\" of depreciation means the spreading of depreciation of depreciable property in equal amounts monthly over its estimated service life.\n\"Rate base\" means the money honestly and prudently invested in the used and useful property and equipment less accrued depreciation plus one-twelfth of the annual cash operating expenses as working capital."}},{"id":"PH-H1784-A6","no":6,"noLabel":{"en":"Section 6."},"text":{"en":"Limit of operating expenses, quality of service. -The grantee shall abide by the limit or operating expenses that the Public Service Commission or its legal successor may impose and shall comply with the safety rules and render the quality of service which said Commission may provide."}},{"id":"PH-H1784-A7","no":7,"noLabel":{"en":"Section 7."},"text":{"en":"Power to borrow from government banking institutions. -In order to finance its projects, the grantee is empowered to borrow from any financial institution or incur indebtedness in excess of its borrowing capacity, notwithstanding any provision of law to the contrary."}},{"id":"PH-H1784-A8","no":8,"noLabel":{"en":"Section 8."},"text":{"en":"Administration of franchise on non-partisan basis. -The franchise granted herein shall be administered entirely on a non-partisan basis, and in the appointment of officials, selection of employees and promotion of any such officials or employees, no political test or qualification shall be permitted or given consideration, but all such appointments and promotions shall be given and made on the basis of merit and efficiency. The benefits of this franchise shall be made available without discrimination to any person, group or association, irrespective of color, race, creed, religion or political party."}},{"id":"PH-H1784-A9","no":9,"noLabel":{"en":"Section 9."},"text":{"en":"Right of National Government to acquire grantee’s property. -It is expressly provided that, in the event the National Government should desire to maintain and operate for itself the system and enterprise herein authorized, the grantee shall surrender its franchise and turn over to the National Government all serviceable equipment therein, and the National Government shall pay the grantee its original investment and/or assume all the obligations of the grantee to finance the system."}},{"id":"PH-H1784-A10","no":10,"noLabel":{"en":"Section 10."},"text":{"en":"Penal Provisions. -Any public officer or employee found directly or indirectly responsible for the use of the net profit of the grantee for any purpose other than the improvement and expansion of the system shall be punished by a fine of not more than five thousand pesos or imprisonment for not more than two years, or both.\nAny public officer or employee found directly or indirectly responsible for the violation of this section or any such officer or employee who, having known such violation, fails to report the same to the justice of the peace, shall be punished with dismissal from the service and by imprisonment for not less than one year and not more than five years.\nNothing in this section shall be construed to relieve or exempt the grantee from complying with the provisions of other laws relative to franchises."}},{"id":"PH-H1784-A11","no":11,"noLabel":{"en":"Section 11."},"text":{"en":"Repeal or modification of other laws, executive orders, etc. -All laws or parts of laws and all executive orders, rules and regulations or parts thereof inconsistent with the provisions of this Act are repealed or modified accordingly."}},{"id":"PH-H1784-A12","no":12,"noLabel":{"en":"Section 12."},"text":{"en":"Separability clause. -If any provision of this Act or the application of such provision to any person or circumstance is declared invalid, the remainder of the Act or the application of such provision to other persons or circumstances shall not be affected by such declaration."}},{"id":"PH-H1784-A13","no":13,"noLabel":{"en":"Section 13."},"text":{"en":"Effectivity clause. -This Act shall take effect upon its approval.\nApproved: June 23, 1957."}}],"pack":"ph-p25","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act Granting the Municipality of San Mateo, Province of Rizal, a Franchise for an Electric Light, Heat and Power System","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H1785"] = {"id":"PH-H1785","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1957/ra_2046_1957.html","fetchedAt":"2026-10-06","articleCount":12,"structureMode":"ARTICLE","title":{"zh":"关于设立名为甲米地配电管理局的公营公司的法案","en":"An Act Creating a Public Corporation to be Known as the Cavite Electricity Distributing Authority","orig":"An Act Creating a Public Corporation to be Known as the Cavite Electricity Distributing Authority"},"level":"law","status":"active","topics":["energy"],"docNumber":"Republic Act No. 2046","issuingBody":"Congress of the Philippines","promulgatedDate":"1957-06-23","completenessNote":"全文，共 12 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1957/ra_2046_1957.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H1785-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"Creation of the Cavite Electricity Distributing Authority; its general purposes; zone and extent of jurisdiction; domicile and place of business of the corporation. -For the purpose of consolidating and centralizing the generation and distribution of electric light, heat and/or power in the Province of Cavite, under one control direction, management and supervision, there is hereby created a public corporation to be known as the Cavite Electricity Distributing Authority, which shall be organized immediately after the approval of this Act.\nThe Cavite Electricity Distributing Authority shall own and/or have jurisdiction and supervision over all electric systems within the boundaries of cities and municipalities in Cavite.\nThe domicile and place of business of the Authority shall be determined by the Board of Directors."}},{"id":"PH-H1785-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"Powers and General Functions of the Authority. -The powers, functions and activities of the Cavite Electricity Distributing Authority shall be the following:\n(a) To have the continuous succession under its corporate name until otherwise provided by law;\n(b) To prescribe its by-laws;\n(c) To adopt and use a seal and alter it at pleasure;\n(d) To sue and be sued in court;\n(e) To construct, maintain, and operate distribution lines for the purpose of supplying electric light, heat and/or power to the inhabitants of its zone, both for domestic and other purposes; regulate the control and use, and prevent the wastage and pilferage of electricity; to fix electric rates and provide for the collection of fees therefor;\n(f) To acquire, purchase, hold, transfer, sell, lease, rent, mortgage, encumber, and otherwise dispose of real and personal property, including rights and franchises, within its jurisdiction, as authorized by the purposes for which the Authority was created and reasonably and necessarily required for the transaction of the lawful business of the same, unless otherwise provided in this Act;\n(g) To underwrite, purchase, own, sell, mortgage or otherwise dispose of stocks, bonds, debentures, securities and other evidences of indebtedness issued for and in connection with its functions;\n(h) To construct works across, or otherwise, any stream, watercourse, canal, ditch, flume, street, avenue, highway, or railway, as the location of said works may require: Provided, That such works be constructed in such manner as to afford security for life and property: And, Provided, further, That the stream, watercourse, canal, ditch, flume, street, avenue, highway, or railway so crossed or intersected be restored to their former state as near as may be, or in a manner not to impair unnecessarily their usefulness. Every person or entity whose right of way is crossed or intersected by said works shall not obstruct the forming of such crossing or intersection and shall grant the Authority the proper authority, upon payment of just compensation, for the execution of such work. The Authority is hereby given the right of way to locate, construct and maintain such works over and through any of the lands which are now or may be the property of the Government of the Republic of the Philippines or any of its branches and political subdivisions;\n(i) To exercise the right of eminent domain for the purpose for which the Authority was created, in the manner provided by law for condemnation proceedings by the national, provincial, and municipal government;\n(j) When essential to the proper administration of its corporate affairs or when necessary for the proper transaction of its business or for carrying out the purposes for which it was organized, to contract indebtedness and issue bonds, subject to the approval of the Provincial Governor of Cavite and the Secretary of Finance. The bonded indebtedness of the Authority, of all classes, shall not at any time exceed ten million pesos, and the issue thereof shall be subject to the conditions set forth in section five of this Act;\n(k) To issue such regulations as may be necessary for the proper distribution of electric light, heat and/or power, and for the protection of its distribution systems, as soon as established, any violation of which shall be punished by a fine of not more than five hundred pesos or by imprisonment for not more than six months, or both such fine and imprisonment in the discretion of the court; and\n(l) To transact the business for which it was organized and do such things as may be reasonably necessary to carry out the purposes for which it was established."}},{"id":"PH-H1785-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"Exercise of corporate power; conduct of affairs and current business; officers and employees of the Authority, their appointment and qualifications, their salaries and functions. -Unless otherwise provided by law, all corporate powers of the Cavite Electricity Distributing Authority shall be exercised, its business managed, and its properties kept and preserved, by a Board of Directors to be composed of five members, a chairman and four other members.\nThe affairs and current business of the Cavite Electricity Distributing Authority shall be conducted under the direction of the Board, by a general manager, a chief engineer, a treasurer, an auditor, and such additional officers and employees as the Board may provide.\nThe duties and powers as well as the compensation of said officers and employees shall be such as may be defined and prescribed or fixed by the Board which shall not be inconsistent with the provisions of this Act and other existing laws.\n(a) Chairman-General Manager. -The Chairman shall be appointed by the Provincial Governor of Cavite, with the consent of the Public Utilities Commission, and may be removed for cause by the Provincial Governor of Cavite. He shall, as ex officio General Manager of the Authority, represent the Authority in all its business matters; shall submit to the Board an annual report and such partial reports as may be required by it or he may see fit to render from time to time, regarding the condition of the business, or of any part of the business of the Cavite Electricity Distributing Authority; and shall perform such other executive duties as may be prescribed by law or may be required of him by resolution of the Board.\n(b) Board Member-Chief Engineer. — One member of the Board shall at least be an electrical engineer, who shall be appointed by the Provincial Governor of Cavite with the consent of the Board of Directors of National Power Corporation, and may be removed for cause by the Provincial Governor of Cavite. He shall, as ex officio Chief Engineer of the Authority, perform such duties as may be required of him by the Board or by the General Manager. He shall act as general manager in case of the temporary disability or absence of the general manager.\n(c) Board Member-Treasurer. -One member of the Board shall possess knowledge of business management and finance, who shall be appointed by the Provincial Governor of Cavite, with the consent of the Board of Directors of the Rehabilitation Finance Corporation, and may be removed for cause by the Provincial Governor of Cavite. He shall, as ex officio treasurer of the Authority, perform such duties as may be required of him by the Board or by the General Manager.\n(d) The two other members of the Board, who shall represent the consumers, shall be appointed by the Provincial Governor of Cavite, upon election by the city and municipal mayors of Cavite in meeting assembled, and shall hold office for two years unless otherwise removed for cause by the Provincial Governor of Cavite: Provided, That at any time existing conditions may warrant, the Board may change the purpose and procedure of selecting the board members mentioned in this paragraph.\n(e) Auditor. -The Provincial Auditor of Cavite, who is hereby designated as ex officio Auditor of the Cavite Electricity Distributing Authority, shall be the representative of the Auditor General. He shall be the chief of its auditing and accounting department. He shall audit, examine and settle all accounts of the Cavite Electricity Distributing Authority according to existing law and regulations, and shall perform such other duties as the Auditor General or the Board may require of him from time to time.(f) Other officers and employees of the Authority. — All other officers and employees of the Authority shall be appointed by the Chairman-General Manager with the approval of the Board, subject to the Civil Service Law and Rules.\nThe employees of the Auditor’s office shall be appointed by the Auditor General, who, with the approval of the Board, shall fix the number and salaries of said employees.\nNo appointment under paragraph (f) shall be considered permanent until after one year from the date of appointment.\nThe Chairman-General Manager, Board Member-Chief Engineer and Board Member-Treasurer of the Cavite Electricity Distributing Authority shall each receive an annual salary which shall be fixed by the Board with the approval of the Provincial Governor of Cavite and the Secretary of Finance. The two Board Members representing the consumers and the Auditor shall be entitled to collect per diem and transportation expenses incurred in connection with their functions with the Authority."}},{"id":"PH-H1785-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"First meeting of the Board; quorum; votes necessary, in general, for adoption of resolutions; Secretary of the Board and his salary; annual reports. -The Chairman of the Board shall, immediately after the formation thereof, fix a time and place for the first meeting, at which the Board shall adopt rules of procedure and fix a time and place for holding regular meetings.\nNot less three members of the Board shall constitute a quorum for the transaction of business, and three affirmative votes shall be necessary for the adoption of any resolution or motion, except as herein otherwise provided.\nThe Board shall appoint its secretary and fix his salary.\nThe Board shall render annual reports of the Provincial Governor of Cavite, the Public Utilities Commission, the National Power Corporation and the Rehabilitation Finance Corporation."}},{"id":"PH-H1785-A5","no":5,"noLabel":{"en":"Section 5."},"text":{"en":"Resolution to issue bonds, debentures, securities and collaterals and incur other obligations. -Whenever the Board may deem it necessary for the Authority to incur indebtedness or issue bonds, debentures, securities and collaterals, it shall by resolution so declare and state the purpose for which the proposed debt is to be incurred and the condition of the bonds, debentures, securities and collaterals; which resolution, however, shall be subject to the approval of the Provincial Governor and the Secretary of Finance. These bonds and other obligations shall be redeemable at the pleasure of the Board after ten years from date of issue; payable forty years after date of issue, and shall bear such interest as may be fixed by the Secretary of Finance; and shall be in registered form and transferable at the Office of the National Treasurer. The said bonds are hereby declared exempt from taxation by the Government of the Republic of the Philippines, or by any authority, branch, division or political subdivision thereof, which fact shall be stated upon the face of said bonds. The bonds shall be receivable as security in any transaction with the Government of the Republic of the Philippines in which such security is required.\nA sinking fund shall be created for the payment of the bonds issued under the provisions of this Act in such manner that the total amount thereof on each annual due date of the bonds issued shall be equal to the total of annuity of such a sum for each million pesos of the bonds outstanding that, together with interest at a rate to be determined by the Secretary of Finance, shall be sufficient to retire the bonds at maturity. The sinking fund shall be under the custody of the Central Bank of the Philippines, which shall invest the same in such manner as the Monetary Board and the Secretary of Finance may approve in accordance with Act Numbered Three thousand fourteen, and shall credit to the same the interest on investment and other incomes accruing to it.\nThe Government of the Republic of the Philippines hereby guarantees the payment by the Cavite Electricity Distributing Authority of both the principal and the interest of the bonds issued by said Authority by virtue of this Act, and shall pay such principal and interest in case the said Authority fails to do so; and there are hereby authorized to be appropriated, out of any fund in the National Treasury not otherwise appropriated, the sums necessary to make the payments guaranteed by this Act: Provided, That the sums so paid by the Government of the Republic of the Philippines shall be refunded by the Cavite Electricity Distributing Authority, and if said Authority fails to refund the same within thirty days after such payment has been made by the Government of the Republic of the Philippines, the National Treasurer is hereby authorized and directed to retain out of the revenues of the provinces, cities and municipalities included in the Authority, that may come into his possession as belonging to said provinces, cities and municipalities, the sum necessary to refund the payments made by the Government of the Republic of the Philippines in any proportion which the Auditor General may approve and which will insure their collection."}},{"id":"PH-H1785-A6","no":6,"noLabel":{"en":"Section 6."},"text":{"en":"Acquisition by the Cavite Electricity Distributing Authority of franchises and serviceable equipment of electric operators. -Upon resolution of the Board of Directors and approval by the Provincial Governor of Cavite, the Cavite Electricity Distributing Authority may acquire by purchase all serviceable equipment and franchises of electric operators within the zone of jurisdiction of the Authority."}},{"id":"PH-H1785-A7","no":7,"noLabel":{"en":"Section 7."},"text":{"en":"Fixing, charging and collection of rates. -The Cavite Electricity Distributing Authority is hereby authorized to fix, charge and collect rates for all services rendered in each sector, city, municipality, or group of consumers, whether to any person, corporation, firm, government body, municipal entity or religious or charitable institutions, subject to review by the Public Utilities Commission.\nThe Authority shall exist as an independent agency of the Government under the Office of the Provincial Governor of Cavite for administrative purposes."}},{"id":"PH-H1785-A8","no":8,"noLabel":{"en":"Section 8."},"text":{"en":"Tenure of Authorization. -The duration of authorization granted to the Cavite Electricity Distributing Authority granted under this Act shall be for a period of fifty years computed from the date of approval of this Act."}},{"id":"PH-H1785-A9","no":9,"noLabel":{"en":"Section 9."},"text":{"en":"Exemption from payment of all taxes. -The Cavite Electricity Distributing Authority shall be exempt from all taxes incidental to its operation except as herein provided for."}},{"id":"PH-H1785-A10","no":10,"noLabel":{"en":"Section 10."},"text":{"en":"Letting of contracts for public works of the Authority. -All construction and repair works authorized by the Authority involving an estimated cost of ten thousand pesos or more shall be let by the General Manager with the approval of the Board of Directors to contract under the usual bidding procedure of the Government, except in the case of construction or repair of distribution systems, and such other projects which, in the discretion of the Board, due to its urgent nature, shall be undertaken by the Authority by administration."}},{"id":"PH-H1785-A11","no":11,"noLabel":{"en":"Section 11."},"text":{"en":"Repeal or modification. -The public interest so requiring, all acts, executive orders, administrative orders, proclamations and municipal ordinances or parts thereof inconsistent with any of the provisions of this Act are hereby repealed or modified accordingly."}},{"id":"PH-H1785-A12","no":12,"noLabel":{"en":"Section 12."},"text":{"en":"Effective date of this Act. -This Act shall take effect upon its approval.\nApproved: June 23, 1957."}}],"pack":"ph-p25","titleTranslation":{"engine":"manual-llm","reviewed":false,"source":"An Act Creating a Public Corporation to be Known as the Cavite Electricity Distributing Authority","note":"人工逐条翻译（模型产出，未经人工复核）；公司名、地名、机构名保留原文。"}};
  FT["PH-H1786"] = {"id":"PH-H1786","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1957/ra_2047_1957.html","fetchedAt":"2026-10-06","articleCount":2,"structureMode":"ARTICLE","title":{"zh":"修订设立为Lanao省Tangcal市镇区的第1537号共和国法第1条的法案","en":"An Act Amending Section One of Republic Act Numbered One Thousand Five Hundred Thirty-Seven, Creating the Municipal District of Tangcal in the Province of Lanao","orig":"An Act Amending Section One of Republic Act Numbered One Thousand Five Hundred Thirty-Seven, Creating the Municipal District of Tangcal in the Province of Lanao"},"level":"law","status":"active","topics":["general"],"docNumber":"Republic Act No. 2047","issuingBody":"Congress of the Philippines","promulgatedDate":"1957-06-23","completenessNote":"全文，共 2 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1957/ra_2047_1957.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H1786-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"Section one of Republic Act Numbered One thousand five hundred thirty seven, creating the Municipal District of Tangcal in the Province of Lanao, is hereby amended to read as follows:\n\"Sec. 1. The barrios of Tangcal, Berowar, Pangao, Tawinian, Lumbac, Lawigadato, Somyorang, Bayabao, Pilingkingan, Ramain, Bagigicon, Lamaosa, Meladoc Big and Meladoc Small and Rarab, now comprised within the Municipality of Kolambugan, Province of Lanao, are hereby separated from said municipality and constituted into a distinct and independent municipal district to be known as the Municipal District of Tangcal. The sitios of Palao, Mintering, Inoma, Lindungan, and Banisilin, shall be included within the barrios of Meladoc Small, Meladoc Big, Lamosa, Pilingkingan and Berowar, respectively, in the said municipal district.\""}},{"id":"PH-H1786-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 23, 1957."}}],"pack":"ph-p25","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act Amending Section One of Republic Act Numbered One Thousand Five Hundred Thirty-Seven, Creating the Municipal District of Tangcal in the Province of Lanao","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H1787"] = {"id":"PH-H1787","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1957/ra_2048_1957.html","fetchedAt":"2026-10-06","articleCount":3,"structureMode":"ARTICLE","title":{"zh":"设立Callang市","en":"An Act Creating the Municipality of Callang, Province of Isabela","orig":"An Act Creating the Municipality of Callang, Province of Isabela"},"level":"law","status":"active","topics":["general"],"docNumber":"Republic Act No. 2048","issuingBody":"Congress of the Philippines","promulgatedDate":"1957-06-23","completenessNote":"全文，共 3 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1957/ra_2048_1957.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H1787-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"The barrios of Callang, Eden, Babanuang, Cabaritan, Sta. Cruz, Malalinta, Mararigue, Calaocan, and Caraniogan, Municipality of Roxas, Province of Isabela, are separated from said municipality and are constituted into a new municipality, to be known as the Municipality of Callang, Province of Isabela, with the seat of government at the site of the present barrio of Callang."}},{"id":"PH-H1787-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"The first mayor, vice-mayor, and councilors of the new municipality shall be appointed by the President of the Philippines with the concurrence of the Commission on Appointments and shall hold office until their successors shall have been elected in the next general election for provincial and municipal officials and shall have duly qualified."}},{"id":"PH-H1787-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 23, 1957."}}],"pack":"ph-p25"};
  FT["PH-H1788"] = {"id":"PH-H1788","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1957/ra_2049_1957.html","fetchedAt":"2026-10-06","articleCount":2,"structureMode":"ARTICLE","title":{"zh":"修订第821号共和国法第1条第1款的法案","en":"An Act to Amend the First Paragraph of Section One of Republic Act Numbered Eight Hundred Twenty-One","orig":"An Act to Amend the First Paragraph of Section One of Republic Act Numbered Eight Hundred Twenty-One"},"level":"law","status":"active","topics":["general"],"docNumber":"Republic Act No. 2049","issuingBody":"Congress of the Philippines","promulgatedDate":"1957-06-23","completenessNote":"全文，共 2 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1957/ra_2049_1957.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H1788-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"The first paragraph of section one of Republic Act Numbered Eight hundred twenty-one is hereby amended to read as follows:\n\"Sec. 1. It is hereby declared to be the policy of Congress to assist small farmers in securing liberal credit and to promote the effective groupings of farmers into cooperative associations to enable them to market efficiently their agricultural commodities, so as to place agriculture (including livestock, poultry and fishing including deep-sea fishing) on a basis of economic equality with other industries, and to improve the standard of living of our people engaged in agriculture.\""}},{"id":"PH-H1788-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 23, 1957."}}],"pack":"ph-p25","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act to Amend the First Paragraph of Section One of Republic Act Numbered Eight Hundred Twenty-One","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H1789"] = {"id":"PH-H1789","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1958/ra_2050_1958.html","fetchedAt":"2026-10-06","articleCount":2,"structureMode":"ARTICLE","title":{"zh":"经费拨款法","en":"An Act Appropriating the Sum of One Hundred Fifty Thousand Pesos to Help Defray the Expenses of the Training, Preparation and Participation of a Filipino Athletic Delegation to the Third Asian Games to be Held in Tokyo, Japan, from May Twenty-Four, Nineteen Hundred Fifty-Eight to June First, Nineteen Hundred Fifty-Eight","orig":"An Act Appropriating the Sum of One Hundred Fifty Thousand Pesos to Help Defray the Expenses of the Training, Preparation and Participation of a Filipino Athletic Delegation to the Third Asian Games to be Held in Tokyo, Japan, from May Twenty-Four, Nineteen Hundred Fifty-Eight to June First, Nineteen Hundred Fifty-Eight"},"level":"law","status":"active","topics":["general"],"docNumber":"Republic Act No. 2050","issuingBody":"Congress of the Philippines","promulgatedDate":"1958-05-20","completenessNote":"全文，共 2 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1958/ra_2050_1958.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H1789-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"The sum of one hundred fifty thousand pesos is appropriated, out of any funds in the National Treasury not otherwise appropriated, as an aid to the Philippine Amateur Athletic Federation to defray the expenses of the selection, assembling, equipping, preparation and sending of a competent athletic delegation to represent the Philippines at the Third Asian Games to be held in Tokyo, Japan, from May twenty-four to June first, nineteen hundred fifty-eight."}},{"id":"PH-H1789-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: May 20, 1958."}}],"pack":"ph-p25"};
  FT["PH-H1790"] = {"id":"PH-H1790","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1958/ra_2051_1958.html","fetchedAt":"2026-10-06","articleCount":2,"structureMode":"ARTICLE","title":{"zh":"修订《菲律宾关税与海关法典》第830条的法案","en":"An Act to Amend Section Eight Hundred Thirty of the Tariff and Customs Code of the Philippines","orig":"An Act to Amend Section Eight Hundred Thirty of the Tariff and Customs Code of the Philippines"},"level":"law","status":"active","topics":["tax"],"docNumber":"Republic Act No. 2051","issuingBody":"Congress of the Philippines","promulgatedDate":"1958-05-21","completenessNote":"全文，共 2 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1958/ra_2051_1958.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H1790-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"Section eight hundred thirty of Republic Act Numbered Nineteen hundred thirty-seven, otherwise known as the Tariff and Customs Code of the Philippines, is amended by adding at the end thereof the following paragraph:\n\"(1) Every vessel of Philippine registry of not less than ten gross tons nor more than one hundred fifty gross tons, which is operated exclusively for catching and transporting fish in the territorial waters of the Philippines, shall be required to carry only one licensed navigator regardless of grade or rank and one licensed engineer regardless of grade or rank to man such fishing vessel.\""}},{"id":"PH-H1790-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: May 21, 1958."}}],"pack":"ph-p25","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act to Amend Section Eight Hundred Thirty of the Tariff and Customs Code of the Philippines","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H1791"] = {"id":"PH-H1791","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1958/ra_2052_1958.html","fetchedAt":"2026-10-06","articleCount":5,"structureMode":"ARTICLE","title":{"zh":"授权菲律宾总统增加菲律宾共和国在国际货币基金组织与国际复兴开发银行的份额，并规定满足其资金需求的程序","en":"An Act Authorizing the President of the Philippines to Increase the Participation of the Republic of the Philippines in the International Monetary Fund and the International Bank for Reconstruction and Development, and Providing for the Procedure to Meet the Financial Requirements Therefor","orig":"An Act Authorizing the President of the Philippines to Increase the Participation of the Republic of the Philippines in the International Monetary Fund and the International Bank for Reconstruction and Development, and Providing for the Procedure to Meet the Financial Requirements Therefor"},"level":"law","status":"active","topics":["tax"],"docNumber":"Republic Act No. 2052","issuingBody":"Congress of the Philippines","promulgatedDate":"1958-05-21","completenessNote":"全文，共 5 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1958/ra_2052_1958.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H1791-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"The President of the Philippines is hereby authorized to negotiate for the increase in the subscription of the Republic of the Philippines to the capital stock of the International Bank for Reconstruction and Development and its quota in the International Monetary Fund, in such amounts as may be required by the Articles of Agreement of the Fund and the rules that may be promulgated thereunder."}},{"id":"PH-H1791-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"(a) To cover the initial payments on the increase in quota in the Fund and the subscription to the capital stock of the Bank as required under the Articles of Agreements of the International Monetary Fund and the International Bank for Reconstruction and Development, the Secretary of Finance is authorized to secure, for and in behalf of the Republic of the Philippines, advances from the Central Bank of the Philippines, the necessary funds against which he shall issue five-year non-interest bearing and non-negotiable promissory notes of the Republic of the Philippines: Provided, However , That said promissory notes may be renewed for another period of five years.\n(b) For the balance of the increase in quota and subscription payable to the Fund and the Bank, the Secretary of Finance is likewise authorized to issue special notes of the Republic of the Philippines at par which shall be non-interest bearing, and non-negotiable and shall be payable on demand by the Fund and Bank. In the event such demand is made by the Fund or the Bank, including any call for payment on the remaining eighty per cent of the subscription to the Bank, the Central Bank of the Philippines shall advance the necessary amount, under the same arrangements provided for in paragraph (a) of this section."}},{"id":"PH-H1791-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"There is hereby appropriated, out of any funds in the National Treasury not otherwise appropriated, such sums as may be needed to reimburse the Central Bank of the Philippines for all advances that may have been made by it pursuant to Section 2 of this Act."}},{"id":"PH-H1791-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"All Acts or parts of Acts inconsistent herewith are hereby amended accordingly."}},{"id":"PH-H1791-A5","no":5,"noLabel":{"en":"Section 5."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: May 21, 1958."}}],"pack":"ph-p25","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act Authorizing the President of the Philippines to Increase the Participation of the Republic of the Philippines in the International Monetary Fund and the International Bank for Reconstruction and Development, and Providing for the Procedure to Meet the Financial Requirements Therefor","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H1792"] = {"id":"PH-H1792","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1958/ra_2053_1958.html","fetchedAt":"2026-10-06","articleCount":2,"structureMode":"ARTICLE","title":{"zh":"授权菲律宾慈善彩票办公室每年举办彩票以惠及血库的法案","en":"An Act to Authorize the Philippine Charity Sweepstakes Office to Hold Annually a Lottery for the Benefit of the Blood Bank","orig":"An Act to Authorize the Philippine Charity Sweepstakes Office to Hold Annually a Lottery for the Benefit of the Blood Bank"},"level":"law","status":"active","topics":["tax"],"docNumber":"Republic Act No. 2053","issuingBody":"Congress of the Philippines","promulgatedDate":"1958-06-04","completenessNote":"全文，共 2 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1958/ra_2053_1958.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H1792-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"The Philippine Charity Sweepstakes Office is authorized to hold annually a lottery, the whole proceeds of which shall after deducting the prices and expenses as provided for in Republic Act Numbered Eleven Hundred sixty-nine, as amended, be turned over to the Blood Bank for its support and maintenance: Provided, That the proceeds from the first lottery under this Act shall the used exclusively for the construction of a blood bank building and the purchase of equipment and medicines."}},{"id":"PH-H1792-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 4, 1958."}}],"pack":"ph-p25","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act to Authorize the Philippine Charity Sweepstakes Office to Hold Annually a Lottery for the Benefit of the Blood Bank","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H1793"] = {"id":"PH-H1793","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1958/ra_2054_1958.html","fetchedAt":"2026-10-06","articleCount":2,"structureMode":"ARTICLE","title":{"zh":"修订《修订行政法典》第56章（经第1836号共和国法修正）的法案","en":"An Act to Further Amend Chapter Fifty-Six of the Revised Administrative Code as Amended by Republic Act Numbered Eighteen Hundred Thirty-Six","orig":"An Act to Further Amend Chapter Fifty-Six of the Revised Administrative Code as Amended by Republic Act Numbered Eighteen Hundred Thirty-Six"},"level":"law","status":"active","topics":["administrative"],"docNumber":"Republic Act No. 2054","issuingBody":"Congress of the Philippines","promulgatedDate":"1958-06-13","completenessNote":"全文，共 2 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1958/ra_2054_1958.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H1793-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"Section two thousand sixty-seven B of the Revised Administrative Code, as amended by Republic Act Numbered Eighteen hundred thirty-six, is amended to read as follows:\n\"Sec. 2067-B. Salaries of provincial officials. -The annual salaries of provincial governors, provincial treasurers, highway district engineers, provincial fiscals, provincial auditors, provincial health officers, provincial assessors, assistant provincial treasurers, assistant provincial auditors, assistant provincial health officers and assistant provincial assessors shall be as herein below fixed:\n\"In first-class provinces: For provincial governors, twelve thousand pesos; for provincial treasurers, highway district engineers, provincial fiscals, provincial auditors and provincial health officers, seven thousand eight hundred pesos; for provincial assessors, seven thousand two hundred pesos; for assistant provincial treasurers, assistant provincial auditors and assistant provincial health officers, five thousand one hundred pesos; and for assistant provincial assessors, four thousand five hundred pesos;\n\"In second-class provinces: For provincial governors, ten thousand pesos; for provincial treasurers, highway district engineers, provincial fiscals, provincial auditors, and provincial health officers seven thousand five hundred pesos; for provincial assessors, six thousand nine hundred pesos; for assistant provincial health officers, five thousand one hundred pesos; and for assistant provincial assessors, four thousand five hundred pesos;\n\"In third-class provinces: For provincial governors, nine thousand six hundred pesos; for provincial treasurers, highway district engineers, provincial fiscals, provincial auditors, and provincial health officers, seven thousand two hundred pesos; for provincial assessors, six thousand six hundred pesos; for assistant provincial treasurers, assistant provincial auditors and assistant provincial health officers, four thousand eight hundred pesos; and for assistant provincial assessors, four thousand two hundred pesos;\n\"In fourth-class provinces: For provincial governors, eight thousand four hundred pesos; for provincial treasurers, highway district engineers, provincial fiscals, provincial auditors, and provincial health officers, six thousand nine hundred pesos; for provincial assessors, six thousand three hundred pesos; for assistant provincial treasurers, assistant provincial auditors and assistant provincial health officers, four thousand five hundred sixty pesos; and for assistant provincial assessors, four thousand one hundred twenty pesos;\n\"In fifth-class provinces: For provincial governors, seven thousand two hundred pesos; for provincial treasurers, highway district engineers, provincial fiscals, provincial auditors, and provincial health officers, six thousand six hundred pesos; for provincial assessors, six thousand pesos; for assistant provincial treasurers, assistant provincial auditors and assistant provincial health officers, four thousand one hundred twenty pesos; and for assistant provincial assessors, four thousand eighty pesos;\n\"In sixth-class provinces: For provincial governors, six thousand six hundred pesos; for provincial treasurers, highway district engineers, provincial fiscals, provincial auditors and provincial health officers, six thousand pesos; for provincial assessors, five thousand four hundred pesos; for assistant provincial treasurers, assistant provincial auditors and assistant provincial health officers, four thousand eighty pesos; and for assistant provincial assessors, three thousand nine hundred pesos;\n\"In seventh-class provinces: For provincial governors, six thousand pesos; for provincial treasurers, highway district engineers, provincial fiscals, provincial auditors, and provincial health officers, five thousand four hundred pesos; for provincial assessors, four thousand eight hundred pesos; for assistant provincial treasurers, assistant provincial auditors and assistant provincial health officers, three thousand nine hundred pesos; and for assistant provincial assessors, three thousand six hundred pesos: Provided, That if after the classification of provinces as provided for in section five of this Act, the salaries of the present incumbents of the positions of provincial governor, provincial treasurer, highway district engineers, provincial fiscal, provincial auditor, provincial health officer, provincial assessor, assistant provincial treasurer, assistant provincial auditor, assistant provincial health officer and assistant provincial assessor shall be reduced on account of the application of the schedule provided for in this section, the said incumbents shall continue to receive their present salaries until their successors are appointed: And Provided, further, That if after the salary of a provincial governor, provincial treasurer, highway district engineer, provincial fiscal, provincial auditor, provincial health officer, provincial assessor, assistant provincial treasurer, assistant provincial auditor, assistant provincial health officer and assistant provincial assessor has been increased by virtue of the provisions hereof, the province concerned incurs an overdraft in its general fund or the operating expenses thereof exceed the revenue collections, the President of the Philippines, upon recommendation of the Secretary of Finance, shall reduce the salary of said officials to the maximum rates fixed for them in the next lower class of province.\n\"The salary of the highway district engineer shall be paid out of national funds. One-half of the salary of the provincial auditor, of the provincial health officer, of the assistant provincial auditor and of the assistant provincial health officer shall be paid out of the national funds and the other half shall be paid out of the funds of the province concerned: Provided, However , That the increase in the salary of the provincial auditor, provincial health officer, assistant provincial auditor and assistant provincial health officer shall be borne by the province until the share thereof of the National Government shall have been provided for in the General Appropriations Act.\""}},{"id":"PH-H1793-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"This Act shall take effect on July first, nineteen hundred and fifty-seven.\nApproved: June 13, 1958."}}],"pack":"ph-p25","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act to Further Amend Chapter Fifty-Six of the Revised Administrative Code as Amended by Republic Act Numbered Eighteen Hundred Thirty-Six","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H1794"] = {"id":"PH-H1794","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1958/ra_2055_1958.html","fetchedAt":"2026-10-06","articleCount":3,"structureMode":"ARTICLE","title":{"zh":"修订第357号共和国法（经第813号共和国法修正）第1条与第5条，将国家电力公司可借入的国际金融机构贷款额增至1亿美元","en":"An Act to Amend Section One and Five of Republic Act Numbered Three Hundred and Fifty-Seven as Amended by Republic Act Numbered Eight Hundred Thirteen by Increasing to One Hundred Million Dollars the Amount of Loans Which the National Power Corporation May Contract from the International Bank for Reconstruction and Development, the Export-Import Bank of Washington D.C., U.S.A., or Any Other International Financial Institution","orig":"An Act to Amend Section One and Five of Republic Act Numbered Three Hundred and Fifty-Seven as Amended by Republic Act Numbered Eight Hundred Thirteen by Increasing to One Hundred Million Dollars the Amount of Loans Which the National Power Corporation May Contract from the International Bank for Reconstruction and Development, the Export-Import Bank of Washington D.C., U.S.A., or Any Other International Financial Institution"},"level":"law","status":"active","topics":["trade","tax"],"docNumber":"Republic Act No. 2055","issuingBody":"Congress of the Philippines","promulgatedDate":"1958-06-13","completenessNote":"全文，共 3 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1958/ra_2055_1958.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H1794-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"Section one of Republic Act Numbered Three hundred fifty-seven as amended by Republic Act Numbered Eight hundred thirteen is amended to read as follows:\n\"Sec. 1. The National Power Corporation is hereby authorized to contract loans from time to time from the International Bank for Reconstruction and Development, the Export-Import Bank of Washington D.C. or any other international financial institution or fund sources the total amount of which exclusive of interest, shall not exceed one hundred million United States dollars or the equivalent thereof in other currencies on such terms and conditions as it shall deem appropriate for the accomplishment of its purposes and to enter into and execute agreements and other documents specifying such terms and conditions.\""}},{"id":"PH-H1794-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"Section five of Republic Act Numbered Three hundred fifty-seven is amended to read as follows:\n\"Sec. 5. The total principal amount of loans contracted or guaranteed by the Republic of the Philippines pursuant to the provisions of this Act shall not exceed the sum of one hundred million dollars in currency of the United States of America, or its equivalent in other currencies.\""}},{"id":"PH-H1794-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 13, 1958."}}],"pack":"ph-p25","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act to Amend Section One and Five of Republic Act Numbered Three Hundred and Fifty-Seven as Amended by Republic Act Numbered Eight Hundred Thirteen by Increasing to One Hundred Million Dollars the Amount of Loans Which the National Power Corporation May Contract from the International Bank for Reconstruction and Development, the Export-Import Bank of Washington D.C., U.S.A., or Any Other International Financial Institution","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H1795"] = {"id":"PH-H1795","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1958/ra_2056_1958.html","fetchedAt":"2026-10-06","articleCount":5,"structureMode":"ARTICLE","title":{"zh":"禁止、拆除和/或捣毁在公共通航水域或水道及公共渔场修建的堤坝、围堤或其他工程，规范上述水域、水道及公共渔场内的工程，并规定违反本法的处罚，及其他目的","en":"An Act to Prohibit, Remove and/or Demolish the Construction of Dams, Dikes or Any Other Works in Public Navigable Waters or Waterways and in Communal Fishing Grounds, to Regulate Works in Such Waters or Waterways and in Communal Fishing Grounds, and to Provide Penalties for its Violation, and for Other Purposes","orig":"An Act to Prohibit, Remove and/or Demolish the Construction of Dams, Dikes or Any Other Works in Public Navigable Waters or Waterways and in Communal Fishing Grounds, to Regulate Works in Such Waters or Waterways and in Communal Fishing Grounds, and to Provide Penalties for its Violation, and for Other Purposes"},"level":"law","status":"active","topics":["criminal"],"docNumber":"Republic Act No. 2056","issuingBody":"Congress of the Philippines","promulgatedDate":"1958-06-13","completenessNote":"全文，共 5 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1958/ra_2056_1958.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H1795-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"Any provision or provisions of law of the contrary notwithstanding, the construction or building of dams, dikes or any other works which encroaches into any public navigable river, stream, coastal, waters and any other navigable public waters or waterways as well as the construction or building of dams, dikes or any other works in areas declared as communal fishing grounds, shall be ordered removed as public nuisances or as prohibited construction as herein provided: Provided, however, That the Secretary of Public Works and Communications may authorize the construction of any such works when public interests or safety so requires, or when it is absolutely necessary for the protection of private property."}},{"id":"PH-H1795-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"When it is found by the Secretary of Public Works and Communications, after due notice and hearing, that any dam, dike or any other works now existing or may hereinafter be constructed encroaches into any public navigable river, stream, coastal waters and any other public navigable waters, or waterways, or that they are constructed in areas declared as communal fishing grounds, he shall have the authority to order the removal of any such works and shall give the party concerned a period not to exceed thirty days for the removal of the same: Provided, That fishpond constructions or works on communal fishing grounds introduced in good faith before the areas were proclaimed as fishing grounds shall be exempted from the provisions of this Act, provided such constructions or works do not obstruct or impede the free passage of any navigable river, stream, or would not cause inundations of agricultural areas: Provided, further, That should the party concerned fail to comply with the order of the Secretary of Public Works and Communications within the period so stated in the order, such removal shall be effected by the Secretary of Public Works and Communications at the expense of the said party within ten days following the expiration of the period given the party concerned: Provided, furthermore, That the investigation and hearing to be conducted by the Secretary of Public Works and Communication under this section shall be terminated and decided by him within a period which shall both exceed ninety days from the time he shall have been notified in writing or a written complaint shall have been filed with him by any interested party apprising him of the existence of a dam, dike or any other works that encroaches into any public navigable river, stream, coastal waters or any other public navigable waters or waterways, and in areas declared as communal fishing grounds: Provided, still furthermore, That the failure on the part of the Secretary of Public Works and Communications without justifiable or valid reason to terminate and decide a case or effect the removal; of any such works, as provided for in this section, shall constitute an offense punishable under section three of this Act: And provided, finally, That the removal of any of such works shall not impair fishponds completed or about to be completed which do not encroach or obstruct any public navigable river or stream and/or which would not cause inundations of agricultural areas and which have been constructed in good faith before the area was declared communal fishing grounds."}},{"id":"PH-H1795-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"Any person who shall violate the provisions of this Act or who shall fail to comply with a lawful order of the Secretary of Public Works and Communications within the period given him in the said order for the removal of any works, shall be punished by imprisonment of not less than six months or more than six years and a fine of not less than five hundred pesos or more than six thousand pesos. In the case of any Secretary of Public Works and Communications, in addition to the fine and imprisonment herein provided, he shall suffer the penalty of perpetual absolute disqualification to hold any public office."}},{"id":"PH-H1795-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"All Acts or parts of Acts, Executive Orders, rules and regulations which are inconsistent with the provisions of this Act are hereby repealed."}},{"id":"PH-H1795-A5","no":5,"noLabel":{"en":"Section 5."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 13, 1958"}}],"pack":"ph-p25","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act to Prohibit, Remove and/or Demolish the Construction of Dams, Dikes or Any Other Works in Public Navigable Waters or Waterways and in Communal Fishing Grounds, to Regulate Works in Such Waters or Waterways and in Communal Fishing Grounds, and to Provide Penalties for its Violation, and for Other Purposes","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H1796"] = {"id":"PH-H1796","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1958/ra_2057_1958.html","fetchedAt":"2026-10-06","articleCount":9,"structureMode":"ARTICLE","title":{"zh":"更新海岸与大地测量局委任人员制度并为其他目的法案","en":"An Act to Up-Date the Commissioned Service of the Bureau of Coast and Geodetic Survey and for Other Purposes","orig":"An Act to Up-Date the Commissioned Service of the Bureau of Coast and Geodetic Survey and for Other Purposes"},"level":"law","status":"active","topics":["general"],"docNumber":"Republic Act No. 2057","issuingBody":"Congress of the Philippines","promulgatedDate":"1958-06-13","completenessNote":"全文，共 9 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1958/ra_2057_1958.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H1796-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"Commissioned service of the Bureau of Coast and Geodetic Survey.— (a) The commissioned service in the Bureau of Coast and Geodetic Survey, Department of National Defense, established by Executive Order Numbered Ninety-four, series of nineteen hundred forty-seven, shall continue to be distributed in the grades of captain, commander, lieutenant-commander, lieutenant, lieutenant (junior grade), and ensign: Provided, That the number of officers in each grade shall not exceed the following percentages of the total authorized number of commissioned officers on the active list: eight per centum (8%) in the grade of captain, fourteen per centum (14%) in the grade of commander, nineteen per centum (19%) in the grade of lieutenant-commander, twenty-three per centum (23%) in the grade of lieutenant, eighteen per centum (18%) in the grade of lieutenant (junior grade), and eighteen per centum (18%) in the grade of ensign: Provided, further, That the number authorized in each grade may be increased by the number of vacancies existing in the higher grades.\n(b) Whenever a final fraction of one-half or greater occurs in computing the authorized number of offices of any grade, the next higher whole number shall be regarded as the authorized number: Provided, That no officer shall be reduced in grade or pay or separated from the active list as the result of any computations made to determine the authorized number of officers in the various grades.\n(c) Officers of the corps shall be natural-born male citizens of the Philippines and shall rank with and after officers of corresponding grades in the Armed Forces with the same length of service in grade, as follows: captain with colonel, commander with lieutenant-colonel, lieutenant-commander with major lieutenant with captain, lieutenant (junior grade) with first lieutenant, and ensign with second lieutenant."}},{"id":"PH-H1796-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"Appointment of commissioned officers. -(a) The President shall appoint the commissioned officers of the Bureau of Coast and Geodetic Survey: Provided, That, except as provided in paragraph (b) of this section, all original appointments shall be in the grade of ensign from among cadets who have qualifies in accordance with section 3 hereof; And Provided, further, That all appointments and promotions to the rank of captain shall be made with the consent of the Commission on Appointments of the Congress.\n(b) The Director of the Coast and Geodetic Survey shall have at least the rank of Captain. The Assistant Director shall have at least the rank of Commander. Both shall be appointed by the President, with the consent of the Commission on Appointments of the Congress, from the list of commissioned officers of the Coast and Geodetic Survey not below the rank of lieutenant commander and lieutenant, respectively.\n(c) Any commissioned officer who received his commission under Executive Order No. 94, series of 1947, shall continue to hold his commission with all the rights and privileges due his grade as any other officer who receives his commission under Sections 2 (a) or 2 (b) of this Act."}},{"id":"PH-H1796-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"Appointment of Cadets. -(a) Cadets shall be appointed by the Secretary of National Defense, upon recommendation of the Director of Coast and Geodetic Survey, from a list of eligibles established under the regulations prescribed by the Secretary of National Defense. The authorized number of cadets may be increased by the number of vacancies in the higher grades. Persons to be eligible for appointment as cadets shall be natural-born male citizens of the Philippines and shall have at least a bachelor of science degree in any of the following fields: geodetic, civil, mechanical, electrical, mining, or chemical engineering, or graduates of a naval or military academy recognized by the government with at least a bachelor of science degree.\n(b) Cadets shall be appointed ensigns under the regulations prescribed by the Secretary of National Defense as vacancies occur in the commissioned force, after not less than six months of continuous and satisfactory service as cadets."}},{"id":"PH-H1796-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"Promotion of commissioned officers. -(a) Commissioned officers of the Bureau of Coast and Geodetic Survey shall be promoted whenever vacancies occur within the limitations imposed under Section 1 hereof in accordance with a set of regulations prescribed by the Secretary of National Defense, and shall receive the same base pay, longevity pay and other allowances as are now or may hereafter be authorized for officers of corresponding grades in the Armed Forces: Provided, That for purposes of this Act, officers commissioned on July 1, 1947 shall be construed to have a length of service equivalent to all the service they have completed with the coast and geodetic survey: Provided, further, That service as an officer in the Armed Forces shall also be included in the computation of length of service.\n(b) Commissioned officers in the PI C&GS shall be entitled to time-in-grade promotion after selection on the basis of seniority, fitness, and efficient service by the Personnel Board constituted by the Secretary of National Defense for the purpose.\n(c) Irrespective of the existence of any vacancy, individual commissioned officers of the PI C&GS shall be considered by the Personnel Board for promotion to the next higher grade sufficiently in advance of the date on which they complete the corresponding number of years of active commissioned service required hereunder in order that such officers as are recommended by the Personnel Board may be promoted to and appointed in such higher grade on the date on which they correspondingly complete such requisite length of service:\n(1) Ensign to lieutenant (junior grade) after three (3) years as ensign;\n(2) Lieutenant (junior grade) to full lieutenant after five (5) years as lieutenant (junior grade);\n(3) Lieutenant to lieutenant-commander after seven (7) years as lieutenant: Provided, That the total number of lieutenant-commanders shall not exceed nineteen per centum (19%) of the total authorized number of commissioned officers in the active list;\n(4) Lieutenant-commander to commander after seven (7) years as lieutenant-commander: Provided, That the total number of commanders shall not exceed fourteen per centum (14%) of the total authorized number of commissioned officers on the active list;\n(5) Commander to captain after six (6) years as commander: Provided, That the total number of captains shall not exceed eight per centum (8%) of the total authorized number of commissioned officers on the active list.\n(d) Any provisions of existing law, executive orders, rules and regulations to the contrary notwithstanding, savings in the appropriations authorized for any fiscal year for the Bureau of Coast and Geodetic Survey for salaries and wages, for sundry expenses, and/or for special purpose may, with the approval of the President of the Philippines, be used to cover the amount necessary to effectuate the time-in-grade promotions herein provided.\n(e) Promotions to all grades shall be made by the President: Provided, That no person shall be appointed ensign or shall be promoted from ensign to lieutenant (junior grade), and from lieutenant (junior grade) to lieutenant without passing a satisfactory mental and physical examination conducted in accordance with regulations prescribed by the Secretary of National Defense."}},{"id":"PH-H1796-A5","no":5,"noLabel":{"en":"Section 5."},"text":{"en":"Retirement. -(a) The provisions of Republic Act Numbered Six hundred sixty as amended shall continue to be made applicable to the commissioned officers of the Philippine Coast and Geodetic Survey.\n(b) For purposes of this section, the periods of service of a commissioned officer of the Philippine Coast and Geodetic Survey shall be credited as follows:\n(1) Services of a commissioned officer shall include his total services in the Philippine Government and shall be deemed continuous through the period of enemy occupation during World War II. Service in the United States Coast and Geodetic Survey up to and including June 30, 1950, shall in any case be included in determining whether he has completed the minimum or maximum length of service for retirement: Provided, That the last ten (10) years of service shall be as commissioned officer in the Bureau of Coast and Geodetic Survey.\n(2) Any period of service amounting to six months or more shall be counted as a complete year."}},{"id":"PH-H1796-A6","no":6,"noLabel":{"en":"Section 6."},"text":{"en":"Saving Clause. -Nothing in this Act shall operate to reduce the grade, pay, and allowances of officers who are commissioned in the service of the Philippine Coast and Geodetic Survey at the time of the approval of this Act."}},{"id":"PH-H1796-A7","no":7,"noLabel":{"en":"Section 7."},"text":{"en":"All the provisions of Executive Order No. 94, series of 1947, not inconsistent with the provisions of this Act shall continue to remain in full force and effect."}},{"id":"PH-H1796-A8","no":8,"noLabel":{"en":"Section 8."},"text":{"en":"Repeal of Laws. -All laws and regulations or provisions thereof inconsistent with the provisions of this Act are hereby repealed or modified accordingly."}},{"id":"PH-H1796-A9","no":9,"noLabel":{"en":"Section 9."},"text":{"en":"Date of Effectivity. -This Act shall take effect upon its approval.\nApproved: June 13, 1958."}}],"pack":"ph-p25","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act to Up-Date the Commissioned Service of the Bureau of Coast and Geodetic Survey and for Other Purposes","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H1797"] = {"id":"PH-H1797","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1958/ra_2058_1958.html","fetchedAt":"2026-10-06","articleCount":3,"structureMode":"ARTICLE","title":{"zh":"修订第120号联邦法第1条，规定国家电力公司存续期间的法案","en":"An Act to Amend Section One of Commonwealth Act Numbered One Hundred Twenty Fixing the Period of Existence of the National Power Corporation","orig":"An Act to Amend Section One of Commonwealth Act Numbered One Hundred Twenty Fixing the Period of Existence of the National Power Corporation"},"level":"law","status":"active","topics":["general"],"docNumber":"Republic Act No. 2058","issuingBody":"Congress of the Philippines","promulgatedDate":"1958-06-13","completenessNote":"全文，共 3 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1958/ra_2058_1958.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H1797-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"Section one of Commonwealth Act Numbered One hundred twenty is amended so as to read as follows:\n\"Sec. 1. For the purpose of undertaking the development of water for hydroelectric power and the production of power from other sources and for other purposes specified in this Act, there is hereby created a public Corporation which shall be known as the ‘National Power Corporation’, and which shall exist until December thirty-one, twenty hundred. Unless its corporate life is extended anew, the corporation shall continue thereafter as a corporate body for such time as may be necessary for the purpose of liquidation. The words ‘Corporation’ and ‘Board’ appearing in this Act shall respectively refer to the National Power Corporation and the National Board, hereinafter created.\""}},{"id":"PH-H1797-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"All laws or provisions of laws and executive orders contrary to this Act are hereby repealed."}},{"id":"PH-H1797-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 13, 1958."}}],"pack":"ph-p25","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act to Amend Section One of Commonwealth Act Numbered One Hundred Twenty Fixing the Period of Existence of the National Power Corporation","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H1798"] = {"id":"PH-H1798","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1958/ra_2059_1958.html","fetchedAt":"2026-10-06","articleCount":2,"structureMode":"ARTICLE","title":{"zh":"授权菲律宾慈善彩票办公室举办一次特别彩票赛，以 Welfareville 机构为受益人的法案","en":"An Act to Authorize the Philippine Charity Sweepstakes Office to Hold One Special Sweepstakes Race for the Welfareville Institutions as Beneficiary","orig":"An Act to Authorize the Philippine Charity Sweepstakes Office to Hold One Special Sweepstakes Race for the Welfareville Institutions as Beneficiary"},"level":"law","status":"active","topics":["general"],"docNumber":"Republic Act No. 2059","issuingBody":"Congress of the Philippines","promulgatedDate":"1958-06-13","completenessNote":"全文，共 2 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1958/ra_2059_1958.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H1798-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"Provisions of existing laws to the contrary notwithstanding, the Philippine Charity Sweepstakes Office shall hold in the year nineteen hundred and fifty-nine, one special sweepstake horse race the net proceeds of which shall, after deducting the payment of the prizes and expenses, as provided in Act Numbered Forty-one hundred and thirty, as amended by Commonwealth Act Numbered Five hundred and forty-six, be turned over to the Social Welfare Administration for the construction of new buildings in the Welfareville Institutions. The plans for the construction of such buildings shall be approved by the Bureau of Public Works and all expenses therefor shall be subject to budgeting and auditing regulations. In the said special sweepstake horse race, the prizes for the three winning horses shall be in direct proportion, respectively, to the three main prizes for winning tickets and shall be ten per cent thereof, but in no case shall the total amount of the prizes for winning hoses exceed fifty thousand pesos."}},{"id":"PH-H1798-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 13, 1958."}}],"pack":"ph-p25","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act to Authorize the Philippine Charity Sweepstakes Office to Hold One Special Sweepstakes Race for the Welfareville Institutions as Beneficiary","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H1799"] = {"id":"PH-H1799","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1958/ra_2060_1958.html","fetchedAt":"2026-10-06","articleCount":2,"structureMode":"ARTICLE","title":{"zh":"修订《修订刑法典》第190条以将大麻及类似药物列入违禁药物之列的法案","en":"An Act Amending Article One Hundred and Ninety of the Revised Penal Code, so as to Include Marihuana and Similar Drugs Among the Prohibited Drugs","orig":"An Act Amending Article One Hundred and Ninety of the Revised Penal Code, so as to Include Marihuana and Similar Drugs Among the Prohibited Drugs"},"level":"law","status":"active","topics":["criminal","health"],"docNumber":"Republic Act No. 2060","issuingBody":"Congress of the Philippines","promulgatedDate":"1958-06-13","completenessNote":"全文，共 2 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1958/ra_2060_1958.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H1799-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"Article One hundred and ninety of the Revised Penal Code, is amended to read as follows:\n\"Art. 190. Possession, preparation and use of prohibited drugs, and maintenance of opium dens. -The penalty of arresto mayor in its medium period to prision correccional in its minimum period and a fine ranging from three hundred to ten thousand pesos shall be imposed upon:\n\"1. Anyone who, unless lawfully authorized shall possess, prepare, administer or otherwise use any prohibited drug.\n\"‘Prohibited drug’ as used herein includes opium, cocaine, alpha and beta eucaine, Indian hemp, their derivatives and all preparations made from them or any of them, and such other drugs, whether natural or synthetic, having physiological action as a narcotic drug.\n\"‘Opium’ embraces every kind, class, and character of opium, whether crude or prepared; the ashes or refuse of the same; narcotic preparations thereof or therefrom; morphine or any alkaloid of opium; preparations in which opium, morphine or any alkaloid of opium, enter as an ingredient, and also opium leaves or wrappings of opium leaves, whether prepared or not for their use.\n\"‘Indian hemp’ otherwise known as marihuana, cannabis Americana, hashish, bhang, guaza, churrus, and ganjah, embraces every kind, class and character of Indian hemp, whether dried or fresh flowering or fruiting tops of the pistillate plant cannabis satival, from which the resin has not been extracted, including all other geographic varieties whether used as reefers, resin, extract, tincture or in any other form whatsoever.\n\"By narcotic drug is meant a drug that produces a condition of insensibility and melancholy dullness of mind with delusions and may be habit forming.\n\"2. Anyone who shall maintain a dive or resort where any prohibited drug is used in any form, in violation of the law.\""}},{"id":"PH-H1799-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 13, 1958."}}],"pack":"ph-p25","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act Amending Article One Hundred and Ninety of the Revised Penal Code, so as to Include Marihuana and Similar Drugs Among the Prohibited Drugs","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H1800"] = {"id":"PH-H1800","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1958/ra_2061_1958.html","fetchedAt":"2026-10-06","articleCount":4,"structureMode":"ARTICLE","title":{"zh":"为免费专利申请、不完善或不完整产权的司法确认以及被宣布为公共土地之若干土地的司法程序重启规定新的期限的法案","en":"An Act Setting a New Time Limit for the Filing of Applications for Free Patents, for the Judicial Confirmation of Imperfect or Incomplete Titles, and for the Reopening of Judicial Proceedings on Certain Lands Which Were Declared Public Lands","orig":"An Act Setting a New Time Limit for the Filing of Applications for Free Patents, for the Judicial Confirmation of Imperfect or Incomplete Titles, and for the Reopening of Judicial Proceedings on Certain Lands Which Were Declared Public Lands"},"level":"law","status":"active","topics":["ip","judiciary"],"docNumber":"Republic Act No. 2061","issuingBody":"Congress of the Philippines","promulgatedDate":"1958-06-13","completenessNote":"全文，共 4 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1958/ra_2061_1958.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H1800-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"Sections forty-five and forty-seven of Commonwealth Act Numbered One hundred forty-one, otherwise known as the Public Land Act, as amended by Republic Act Numbered One hundred seven, are further amended to read as follows:\n\"Sec. 45. The President, upon recommendation by the Secretary of Agriculture and Natural Resources, shall from time to time fix by proclamation the period within which applications for free patents may be filed in the district, chartered city, province, municipality, or region specified in such proclamation, and upon the expiration of the period so designated, unless the same be extended by the President, all the land comprised within such district, chartered city, province, municipality, or region subject thereto under the provisions of this chapter may be disposed of as agricultural public land without prejudice to the prior right of the occupant and cultivator to acquire such land under this Act by means other than free patent. The time to be fixed in the entire Archipelago for the filing of applications under this chapter shall not extend beyond December thirty-one, nineteen hundred and sixty-eight, except in the provinces of Agusan, Cotabato, Bukidnon, Lanao, Davao, Sulu, and Mountain Province, where the President of the Philippines shall determine or fix the time beyond which the filing of applications under this chapter shall not extend. The period fixed for any district, chartered city, province, or municipality shall begin to run thirty days after the publication of the proclamation in the Official Gazette. A certified copy of said proclamation shall be furnished to the Director of Lands and to the provincial board and the municipal board or city council affected, and copies thereof shall be posted on the bulletin board of the Bureau of Land at Manila and at conspicuous places in the provincial building and the municipal building. It shall, moreover, be announced by crier in each of the barrios of the municipality.\"\n\"Sec. 47. The persons specified in the next following section are hereby granted time, not to extend beyond December thirty-one, nineteen hundred and sixty-eight within which to take advantage of the benefit of this chapter: Provided, That the several periods of time designated by the President in accordance with section forty-five of this Act shall apply also to the lands comprised in the provisions of this chapter, but this section shall not be construed as prohibiting any of said persons from acting under this chapter at any time prior to the period fixed by the President.\""}},{"id":"PH-H1800-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"The new time limit established in this Act for the filing of applications for free patents and for the judicial confirmation of imperfect or incomplete titles shall also apply to the reopening of judicial proceedings on parcels of land declared public land pursuant to the provisions of Republic Act Numbered Nine hundred thirty-one."}},{"id":"PH-H1800-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"The requisite of previous payment of real estate taxes shall not be a condition precedent to the filing of the applications or petitions for reopening provided for herein."}},{"id":"PH-H1800-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 13, 1958"}}],"pack":"ph-p25","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act Setting a New Time Limit for the Filing of Applications for Free Patents, for the Judicial Confirmation of Imperfect or Incomplete Titles, and for the Reopening of Judicial Proceedings on Certain Lands Which Were Declared Public Lands","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H1801"] = {"id":"PH-H1801","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1958/ra_2062_1958.html","fetchedAt":"2026-10-06","articleCount":2,"structureMode":"ARTICLE","title":{"zh":"豁免 Ramon Magsaysay 奖基金会所颁奖项的所得税、赠与税及所有其他税款的法案","en":"An Act to Exempt Awards Given by the Ramon Magsaysay Award Foundation from the Payment of Income, Gift and All Other Taxes","orig":"An Act to Exempt Awards Given by the Ramon Magsaysay Award Foundation from the Payment of Income, Gift and All Other Taxes"},"level":"law","status":"active","topics":["general"],"docNumber":"Republic Act No. 2062","issuingBody":"Congress of the Philippines","promulgatedDate":"1958-06-13","completenessNote":"全文，共 2 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1958/ra_2062_1958.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H1801-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"The provisions of any existing law to the contrary notwithstanding, all awards given by the Ramon Magsaysay Award Foundation shall be exempted from the payment of income, gift and all other taxes."}},{"id":"PH-H1801-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 13, 1958."}}],"pack":"ph-p25","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act to Exempt Awards Given by the Ramon Magsaysay Award Foundation from the Payment of Income, Gift and All Other Taxes","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H1802"] = {"id":"PH-H1802","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1958/ra_2063_1958.html","fetchedAt":"2026-10-06","articleCount":2,"structureMode":"ARTICLE","title":{"zh":"经费拨款法","en":"An Act Appropriating the Sum of Five Million Six Hundred Ninety-Four Thousand Eight Hundred Fifty-Four Pesos for the Implementation of Republic Act Numbered One Thousand Eight Hundred Thirty-One","orig":"An Act Appropriating the Sum of Five Million Six Hundred Ninety-Four Thousand Eight Hundred Fifty-Four Pesos for the Implementation of Republic Act Numbered One Thousand Eight Hundred Thirty-One"},"level":"law","status":"active","topics":["general"],"docNumber":"Republic Act No. 2063","issuingBody":"Congress of the Philippines","promulgatedDate":"1958-06-13","completenessNote":"全文，共 2 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1958/ra_2063_1958.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H1802-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"The sum of five million six hundred ninety-four thousand eight hundred fifty-four pesos is hereby appropriated, out of any funds in the National Treasury not otherwise appropriated, to implement the provisions of Republic Act Numbered One thousand eight hundred thirty-one from the date of its effectivity."}},{"id":"PH-H1802-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 13, 1958."}}],"pack":"ph-p25"};
  FT["PH-H1803"] = {"id":"PH-H1803","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1958/ra_2064_1958.html","fetchedAt":"2026-10-06","articleCount":2,"structureMode":"ARTICLE","title":{"zh":"规定每年举办彩票以惠及菲律宾心理健康协会，并为此修订第1169号共和国法（经修正）的法案","en":"An Act Providing for the Holding of a Lottery Annually for the Benefit of the Philippine Mental Health Association, Amending for the Purpose Republic Act Numbered Eleven Hundred Sixty-Nine, as Amended","orig":"An Act Providing for the Holding of a Lottery Annually for the Benefit of the Philippine Mental Health Association, Amending for the Purpose Republic Act Numbered Eleven Hundred Sixty-Nine, as Amended"},"level":"law","status":"active","topics":["health"],"docNumber":"Republic Act No. 2064","issuingBody":"Congress of the Philippines","promulgatedDate":"1958-06-13","completenessNote":"全文，共 2 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1958/ra_2064_1958.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H1803-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"Section nine of Republic Act Numbered Eleven hundred sixty-nine, as amended by Republic Act Numbered Fifteen hundred two, is further amended to read as follows:\n\"Sec. 9. Once a month, the Philippine Charity Sweepstakes Office is authorized to hold one regular sweepstakes draw and races and to hold every year six lotteries during days when there are no sweepstakes draw and ordinary races: Provided, However , That the net proceeds of the lotteries held in June and December every year shall be for the benefit of and shall accrue to the funds of the Quezon Institute: Provided, further, That the net proceeds of the lottery held in August every year shall be for the benefit of and shall accrue to the funds of the Philippine Mental Health Association: Provided, further, That except as hereinabove otherwise provided the net proceeds of one of the lotteries shall be for the benefit each of the National Federation of Women’s Clubs for the support of its charitable community improvement program, the athletic program of the public schools, leprosaria and orphanages in the Philippines, Juan Luna Centennial Commission, the Philippine Band of Mercy, the Manila Children’s Hospital, the Society for the Prevention of Cruelty to Animals, and the National Mental Hospital; said net proceeds to accrue only once to each of the said beneficiaries: Provided, further, That all disbursements from this fund shall be subject to the established rules and regulations governing disbursements of public funds: Provided, still further, That orphanages maintained by the Government shall be given priority apportionment: And provide, finally, That the allocations granted to the Federation of Women’s Clubs and other private associations shall exclusively be used for charitable purposes.\""}},{"id":"PH-H1803-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 13, 1958."}}],"pack":"ph-p25","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act Providing for the Holding of a Lottery Annually for the Benefit of the Philippine Mental Health Association, Amending for the Purpose Republic Act Numbered Eleven Hundred Sixty-Nine, as Amended","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H1804"] = {"id":"PH-H1804","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1958/ra_2065_1958.html","fetchedAt":"2026-10-06","articleCount":2,"structureMode":"ARTICLE","title":{"zh":"修订《菲律宾关税与海关法典》第827条的法案","en":"An Act Amending Section Eight Hundred Twenty-Seven of the Tariff and Customs Code of the Philippines","orig":"An Act Amending Section Eight Hundred Twenty-Seven of the Tariff and Customs Code of the Philippines"},"level":"law","status":"active","topics":["tax"],"docNumber":"Republic Act No. 2065","issuingBody":"Congress of the Philippines","promulgatedDate":"1958-06-13","completenessNote":"全文，共 2 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1958/ra_2065_1958.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H1804-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"Section eight hundred twenty-seven of the Tariff and Customs Code of the Philippines is hereby amended to read as follows:\n\"Sec. 827. Marine Investigation and Suspension or Revocation of Marine Certificate. -There shall be maintained in the Bureau of Customs at Manila a Board of Marine Inquiry to consist of five members, to wit: the Port Operations Officer as chairman ex-officio, two master marines and two chief engineers of the Philippine merchant marine, who shall be appointed by the department head. The members of the board shall receive a per diem of twenty pesos for each day of not less than seven hours of service rendered in connection with marine investigations. Three members present shall constitute a quorum for the transaction of business. In case of inability or absence of the Port Operations Officer, a temporary chairman may be chosen by the members from among themselves. such board shall have the power to investigate marine accidents and professional conduct of marine officers, giving the party affected an opportunity to be heard in his defense. The decision of the Commissioner based reprimanding a licensed marine officer or suspending or revoking any marine certificate on account of professional misconduct, intemperate habits, negligence or incapacity shall be final, unless, within thirty days after its promulgation, an appeal is perfected and filed with the department head who may confirm, revoke or modify said decision.\n\"Rules and regulations governing the procedure of marine investigations shall be promulgated by the department head.\n\"The Commissioner may, with the approval of the department head, authorize the collectors to appoint boards for the purpose of investigating marine accidents or charges preferred against the marine officers in their respective districts. The proceedings of such investigations, together with findings and recommendations of said board shall be submitted, through the Commissioner, to the Board of Marine Inquiry, Manila, for final review and recommendation.\n\"In order to safeguard lives and properties at sea, a Collector may withhold clearance of any Philippine vessel whenever he has reasonable cause to fear that the mental condition or capacity, whether permanent or otherwise, of her master, mate or engineer under investigation, pending the final decision thereon so warrants.\""}},{"id":"PH-H1804-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 13, 1958."}}],"pack":"ph-p25","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act Amending Section Eight Hundred Twenty-Seven of the Tariff and Customs Code of the Philippines","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H1805"] = {"id":"PH-H1805","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1958/ra_2066_1958.html","fetchedAt":"2026-10-06","articleCount":4,"structureMode":"ARTICLE","title":{"zh":"授权邮政局将其邮票年度销售的一部分用于改善邮政系统的法案","en":"An Act to Authorize the Bureau of Posts to Use a Portion of its Annual Sales of Postage Stamps for the Purpose of Improving the Postal System","orig":"An Act to Authorize the Bureau of Posts to Use a Portion of its Annual Sales of Postage Stamps for the Purpose of Improving the Postal System"},"level":"law","status":"active","topics":["general"],"docNumber":"Republic Act No. 2066","issuingBody":"Congress of the Philippines","promulgatedDate":"1958-06-13","completenessNote":"全文，共 4 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1958/ra_2066_1958.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H1805-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"The Director of Posts is hereby authorized, subject to the approval of the Secretary of Public Works and Communications, to use not more than twenty per centum of the amount of sales of postage stamps of the Bureau of Posts in each fiscal year for five fiscal years for the purposes hereinafter provided in the following order of priorities:\n(1) To employ regular postmasters and/or postal clerks in municipalities still without post offices;\n(2) To employ regular postmasters and/or postal clerks in municipalities where there are no regular postmasters; and\n(3) To employ additional postal clerks, mail carriers, money order and postal savings bank tellers, stamp tellers, and other personnel needed in the different post offices:\nProvided, That all appointments made under this Act shall be subject to civil service law, rules and regulations: Provide, further, That the Director of Posts shall also open post-offices and purchase out of said amount such postal supplies, furniture and/or equipment as may be needed in various offices: Provided, finally, That the Director of Posts before the end of each fiscal year shall submit to the President of the Senate and the Speaker of the House of Representatives a complete report of the manner the amount herein authorized has been used or spent."}},{"id":"PH-H1805-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"The additional positions in the Bureau of Posts created in accordance with section one hereof shall be continued and provided for in subsequent annual General Appropriations Act."}},{"id":"PH-H1805-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"The authority herein granted shall expire at the end of the fiscal year nineteen hundred sixty-three."}},{"id":"PH-H1805-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"This Act shall take effect on July first, nineteen hundred and fifty-eight.\nApproved: June 13, 1958."}}],"pack":"ph-p25","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act to Authorize the Bureau of Posts to Use a Portion of its Annual Sales of Postage Stamps for the Purpose of Improving the Postal System","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H1806"] = {"id":"PH-H1806","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1958/ra_2067_1958.html","fetchedAt":"2026-10-06","articleCount":33,"structureMode":"ARTICLE","title":{"zh":"整合、协调并加强科学技术研究与开发，促进发明，为此提供资金并为其他目的法案","en":"An Act to Integrate, Coordinate, and Intensify Scientific and Technological Research and Development and to Foster Invention; to Provide Funds Therefor; and for Other Purposes","orig":"An Act to Integrate, Coordinate, and Intensify Scientific and Technological Research and Development and to Foster Invention; to Provide Funds Therefor; and for Other Purposes"},"level":"law","status":"active","topics":["general"],"docNumber":"Republic Act No. 2067","issuingBody":"Congress of the Philippines","promulgatedDate":"1958-06-13","completenessNote":"全文，共 32 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1958/ra_2067_1958.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。 源文条号不连续（自第 1 条起，止于第 33 条，缺 10）：经逐条比对原始页面，该处原文没有对应的 “Section N.” 抬头行，系来源页自身的编号跳跃或条文以“续段”形式并入前条，非抽取遗漏，故未擅自补号。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H1806-A1","no":1,"noLabel":{"en":"Section 1."},"heading":{"en":"This Act shall be known as the \"Science Act of 1958.\""},"text":{"en":"Section 1. This Act shall be known as the \"Science Act of 1958.\""}},{"id":"PH-H1806-A2","no":2,"noLabel":{"en":"Section 2."},"heading":{"en":"In consonance with the provisions of section four, Article XIV of the Constitution, it is hereby declared to be the poli"},"text":{"en":"Section 2. In consonance with the provisions of section four, Article XIV of the Constitution, it is hereby declared to be the policy of the state to promote scientific and technological research and development, foster invention, and utilize scientific knowledge as an effective instrument for the promotion of national progress."}},{"id":"PH-H1806-A3","no":3,"noLabel":{"en":"Section 3."},"heading":{"en":"In the implementation of the foregoing policy, the Government shall, in accordance with the provisions of this Act:"},"text":{"en":"Section 3. In the implementation of the foregoing policy, the Government shall, in accordance with the provisions of this Act:\n(1) Stimulate and guide scientific, engineering and technological efforts towards filling the basic and immediate needs of the people;\n(2) Survey the scientific, engineering and technological resources of the country and formulate a comprehensive program for the development and maximum utilization of such resources in the solution of the country's problems;\n(3) Strengthen the educational system of the country so that the same will provide a steady source of competent scientific and technological manpower;\n(4) Furnish incentives to private and individual initiative in scientific work, as a fundamental basis for the advancement of science;\n(5) Promote and encourage the dissemination of the results of scientific and technological research and the general application thereof;\n(6) Encourage and facilitate the active participation of domestic and foreign sectors in furnishing financial, technical and other forms of assistance for scientific and technological activities;\n(7) Promote coordination and cooperation in research in order to secure concentration of effort, minimize duplication and thereby achieve maximum progress;\n(8) Initiate and bring about the establishment of standards, quality control measures and documentation facilities; and\n(9) Encourage studies in the pure and fundamental sciences."}},{"id":"PH-H1806-A4","no":4,"noLabel":{"en":"Section 4."},"heading":{"en":"To carry out the provisions of the preceding section, there is hereby created a National Science Development Board, here"},"text":{"en":"Section 4. To carry out the provisions of the preceding section, there is hereby created a National Science Development Board, hereinafter referred to as the Board, with the following functions, powers and duties:\n(1) To coordinate and promote cooperation in the scientific research and development activities of government agencies and private enterprises;\n(2) With the approval of the President of the Philippines, to formulate consistent and specific national scientific policies and prepare comprehensive scientific and technological programs which shall be observed and implemented by the Government and all its subdivisions, agencies and instrumentalities;\n(3) To establish a system of priorities for scientific and technological projects;\n(4) To review and analyze scientific and technological projects, schedules of activities, programs and project proposals, including the progress of project being undertaken, and to take such measures as may be necessary to accomplish the objectives and policies involved in these activities;\n(5) To develop a program for the effective training and utilization of scientific and technological manpower;\n(6) To initiate and facilitate arrangements for scientific and technological aid from domestic private sectors and foreign sources and for the exchange of information among local and foreign institutions and scientific investigators;\n(7) To offer to, and accept from, public and private sectors, specific project proposals of scientific and/or technological research and development in accordance with section ten hereof, and to provide appropriate financial, technical and other support thereto;\n(8) To establish and/or provide incentives, including financial and technological support, for the establishment of scientific and technological centers;\n(9) To disseminate the results of scientific and technological research and to encourage their practical application;\n(10) To grant scholarship in mathematics, science, technology and science teaching to deserving citizens;\n(11) To grant financial or other awards, bonuses and/or prized to deserving scientific, engineering and technological researchers and inventors;\n(12) To pay additional compensation to scientific, engineering and technological researchers and inventors employed in the Government or its subdivisions and instrumentalities under such terms and conditions as may be most conducive towards the attainment of maximum efficiency in scientific research and studies;\n(13) To extend travel grants for scientific and/or technological purposes; to send delegates and/or observers to scientific and technological conferences or conventions; and to promote and assist scientific and technological conferences and conventions in the Philippines;\n(14) With the approval of the President of the Philippines, to appoint not more than five science attaches with the proper scientific background and, whenever necessary, to send scientific and technological missions abroad;\n(15) To undertake, in collaboration with the Department of Education, a thorough survey of the educational system and to determine, as well as to recommend to the corresponding authorities, the measures which may be necessary to make it an effective instrument for scientific advancement;\n(16) To initiate and formulate measures designed to promote scientific effort and science consciousness;\n(17) To submit to the President of the Philippines and to both Houses of Congress, not later than the opening of the regular session each year, an annual report on the status of the national science effort, embodying such recommendations as it may deem proper to make; and\n(18) Generally, to do such other things and take such action as may be directly or indirectly incidental or conducive to the attainment of the objectives of this Act."}},{"id":"PH-H1806-A5","no":5,"noLabel":{"en":"Section 5."},"heading":{"en":"The Board shall be composed of a Chairman; a Vice-Chairman, who shall concurrently be the Executive Director of the Boar"},"text":{"en":"Section 5. The Board shall be composed of a Chairman; a Vice-Chairman, who shall concurrently be the Executive Director of the Board; and the following members: the Chairman of the National Research Council of the Philippines, the Commissioner of the National Institute of Science and Technology, the Commissioner of the Philippine Atomic Energy Commission, the Director of the Office of National Planning of the National Economic Council, a representative from the University of the Philippines to be designated by the President of the University, one member representing industry, one member representing scientific and/or technological associations or societies, one member representing agriculture, and one member representing education.\nThe members representing industry, scientific and/or technological associations or societies, agriculture and education shall be appointed by the President of the Philippines from among those who shall be recommended by representative groups, subject to the confirmation of the Commission on Appointments, and shall hold office each for a period of three years."}},{"id":"PH-H1806-A6","no":6,"noLabel":{"en":"Section 6."},"heading":{"en":"The Chairman of the Board, who shall have cabinet rank, shall be appointed by the President of the Philippines, subject"},"text":{"en":"Section 6. The Chairman of the Board, who shall have cabinet rank, shall be appointed by the President of the Philippines, subject to the confirmation of the Commission on Appointments. He shall be a citizen of the Philippines with proven executive ability who shall have distinguished himself in science, technology and/or his chosen profession or field of activity. He shall hold office for six years and shall not be removed therefrom except for cause. He shall receive an annual compensation of twenty-four thousand pesos.\nThe Vice-Chairman shall be appointed by the President of the Philippines, subject to the confirmation of the Commission on Appointments. He shall be a citizen of the Philippines with proven executive ability who shall have achieved distinction in science and/or technology. He shall receive an annual compensation of eighteen thousand pesos.\nBoth the Chairman and the Vice-Chairman shall pass the necessary security clearance."}},{"id":"PH-H1806-A7","no":7,"noLabel":{"en":"Section 7."},"heading":{"en":"The member of the Board, except the Commissioner of the National Institute of Science and Technology and the Commissione"},"text":{"en":"Section 7. The member of the Board, except the Commissioner of the National Institute of Science and Technology and the Commissioner of the Philippine Atomic Energy Commission who shall serve as ex officio members without extra compensation, shall receive a per diem of fifty pesos each per session of the Board: Provided, That the monthly total of such per diems for each member shall not exceed two hundred pesos."}},{"id":"PH-H1806-A8","no":8,"noLabel":{"en":"Section 8."},"heading":{"en":"The Board shall have the following divisions: the Division of Programming and Evaluation, the Division of Development an"},"text":{"en":"Section 8. The Board shall have the following divisions: the Division of Programming and Evaluation, the Division of Development and Assistance, the Administrative Division, the Legal Division and such other divisions which the Board may deem necessary to create."}},{"id":"PH-H1806-A9","no":9,"noLabel":{"en":"Section 9."},"heading":{"en":"The Board shall have, for all legal purposes, all the duties, powers and prerogatives of a Board of Directors and shall"},"text":{"en":"Section 9. The Board shall have, for all legal purposes, all the duties, powers and prerogatives of a Board of Directors and shall function as such, unless otherwise provided for in this Act. The Board shall promulgate such rules and regulations as may be necessary for the conduct and exercise of its functions, duties, and powers under this Act: Provided, That the concurrence of at least six members is required for the approval of any resolution: And provided, further, That only the members of the Board who have passed the necessary security clearance shall deliberate and act on classified matters relating to atomic energy and/or nuclear science.\nThe Board shall exercise its powers in such manner as to insure the continuity of research and development activities in the fields specified in this Act by the Government and private enterprise and to assist in increasing theoretical and practical knowledge in such fields."}},{"id":"PH-H1806-A10","no":10,"noLabel":{"en":"Section 10."},"heading":{"en":"Notwithstanding the provisions of Commonwealth Act Numbered One hundred and thirty-eight and the requirements of public"},"text":{"en":"Section 10 Notwithstanding the provisions of Commonwealth Act Numbered One hundred and thirty-eight and the requirements of public bidding, the Chairman shall, subject to the approval of the Board enter into contracts, or otherwise make arrangements, for the conduct of the following activities and their development:\n(a) Industrial research\n(b) Agricultural research\n(c) Medical and pharmaceutical research\n(d) Biological research\n(e) Atomic energy research\n(f) Food and nutrition research\n(g) Engineering research\n(h) Research on social science and the humanities, and\n(i) Pure and fundamental science studies.\nIn implementation of such contracts or arrangements the Chairman may, subject to the approval of the Board, make partial or advance payments and make available such equipment and facilities of the Board and its agencies as he may deem necessary.\nThe Chairman shall, with the approval of the Board, appoint such technical and administrative personnel as may be necessary to carry out the assigned functions of the Board."}},{"id":"PH-H1806-A11","no":11,"noLabel":{"en":"Section 11."},"heading":{"en":"The Vice-Chairman and Executive Director shall exercise immediate control and supervision over the divisions and offices"},"text":{"en":"Section 11. The Vice-Chairman and Executive Director shall exercise immediate control and supervision over the divisions and offices of the Board."}},{"id":"PH-H1806-A12","no":12,"noLabel":{"en":"Section 12."},"heading":{"en":"There is hereby created the National Institute of Science and Technology, hereinafter referred to as the Institute, whic"},"text":{"en":"Section 12. There is hereby created the National Institute of Science and Technology, hereinafter referred to as the Institute, which shall be under the supervision of the National Science Development Board, with the following functions, powers, and duties:\n(1) To implement and conduct programs of scientific and technological research and development as may be directed by the Board;\n(2) To cooperate with private enterprise in research activities relating to scientific and technological problems of industry, agriculture, medicine, engineering, mathematics and the natural, biological and social sciences;\n(3) To conduct studies through its research centers on industrial, agricultural, medical, biological and related field, and to cooperate with other government agencies along these lines;\n(4) To perform analyses and tests for the purpose of establishing suitable standards of products, to calibrate weights and measures, to determine the quality and composition of materials, and to issue certification in relation thereto;\n(5) To provide government entities and local industrial organizations with data of scientific and/or technological nature, subject to established laws and regulations on national security;\n(6) To establish, expand, maintain and operate pilot plants, research centers, test and standard laboratories, experimental stations and documentation facilities;\n(7) To study and evaluate project proposals for research and development in the industrial, agricultural, medical, biological and related fields from public and private sectors, and to recommend necessary financial, technical and other appropriate assistance thereto;\n(8) To receive assignments or patents, grant exclusive rights to their use, charges and collect reasonable fees or charges for their use in accordance with the policies of the institute;\n(9) To keep posted on research projects and activities finance or assisted under this Act;\n(10) To recommend deserving citizens for training, government and private grants and scholarships in the Philippines and abroad in science, other than nuclear science, technology, mathematics and science teaching; and\n(11) To render annual reports and such special reports as may be requested by the Board."}},{"id":"PH-H1806-A13","no":13,"noLabel":{"en":"Section 13."},"heading":{"en":"The Institute shall be under a Commissioner and a Deputy Commissioner, both of whom shall be appointed by the President"},"text":{"en":"Section 13. The Institute shall be under a Commissioner and a Deputy Commissioner, both of whom shall be appointed by the President of the Philippines upon the recommendation of the Chairman of the Board, subject to the confirmation of the Commission on Appointments. Both officials shall be citizens of the Philippines with distinguished accomplishments in scientific and/or technological research and with broad administrative experience. The Commissioner shall receive an annual compensation of eighteen thousand pesos, and the Deputy Commissioner an annual compensation of fifteen thousand pesos."}},{"id":"PH-H1806-A14","no":14,"noLabel":{"en":"Section 14."},"heading":{"en":"The Institute shall have the following divisions: the Administrative Division, the Division of Documentation, the Legal"},"text":{"en":"Section 14. The Institute shall have the following divisions: the Administrative Division, the Division of Documentation, the Legal Division, and such other divisions as the Board may, upon the recommendation of the Commissioner of the Institute, deem necessary to create.\nThere shall also be under the control and supervision of the Institute the following centers: the Industrial Research Center, the Agricultural Research Center, the Medical Research Center, the Biological Research Center, and such other centers as may be created by the Board. Each research center shall be headed by a research director.\nThe President of the Philippines is hereby authorized to transfer to and place under the jurisdiction of the Institute, upon recommendation of the Board, such existing government research agencies and instrumentalities as may constitute the nucleus of the respective centers herein provided. The President may likewise, upon recommendation of the Board, reorganize and strengthen said government agencies and instrumentalities so that they may adequately function as research centers under the provisions of this Act.\nThe existing Institute of Nutrition under the Department of Health, together with its personnel, appropriation, supplies and equipment with all its functions and powers, is hereby transferred to the National Institute of Science and Technology, under which it shall become one of its research centers and shall function as presently organized, Reorganization Plan No. 14-A under Republic Act Numbered Nine hundred ninety-seven, as amended, notwithstanding, without prejudice to its reorganization by the President as above provided. The said Institute of Nutrition is hereby renamed Food and Nutrition Research Center."}},{"id":"PH-H1806-A15","no":15,"noLabel":{"en":"Section 15."},"heading":{"en":"Such technical and administrative personnel as may be necessary to carry out the functions of the Institute shall be app"},"text":{"en":"Section 15. Such technical and administrative personnel as may be necessary to carry out the functions of the Institute shall be appointed by the Chairman of the Board, upon recommendation of the Commissioner of the Institute and subject to the approval of the Board."}},{"id":"PH-H1806-A16","no":16,"noLabel":{"en":"Section 16."},"heading":{"en":"There is hereby created the Philippine Atomic Energy Commission, hereinafter referred to as the Commission, which shall"},"text":{"en":"Section 16. There is hereby created the Philippine Atomic Energy Commission, hereinafter referred to as the Commission, which shall be under the supervision of the Board, with the following functions, powers, and duties:\n(1) To establish or cause the establishment of laboratories for nuclear research and training;\n(2) To conduct or cause the performance of research and development relating to:\n(a) Nuclear processes and techniques;\n(b) The theory of atomic energy;\n(c) Processes, materials, and devices used in the production of atomic energy;\n(d) The utilization of special nuclear material and radioactive material for commercial, industrial, medical, biological, agricultural, or other peaceful purposes;\n(3) To issue rules and regulations for the protection of its personnel and the general public and undertake their enforcement;\n(4) To approved and facilitate the procurement of radioactive material and instruments for use in nuclear laboratories;\n(5) To issue licenses for the use of radioactive material;\n(6) To study and evaluate project proposals on nuclear research from public and private sectors, and to recommend necessary technical, financial and other appropriate assistance thereto;\n(7) To coordinate the work of research entities and government agencies and instrumentalities on nuclear science;\n(8) To keep posted on nuclear research project and activities financed or assisted under this Act;\n(9) To represent the Philippines in conferences related to atomic energy and its application;\n(10) To recommend deserving citizens for training, government and private grants and scholarships in the Philippines and abroad in nuclear science; and\n(11) To render annual reports and such special reports as may be requested by the Board."}},{"id":"PH-H1806-A17","no":17,"noLabel":{"en":"Section 17."},"heading":{"en":"The Commission shall be under a Commissioner and a Deputy Commissioner, both of whom shall be appointed by the President"},"text":{"en":"Section 17. The Commission shall be under a Commissioner and a Deputy Commissioner, both of whom shall be appointed by the President of the Philippines upon recommendation of the Chairman of the Board, subject to the confirmation of the Commission on Appointments. Both officials shall be citizens of the Philippines with adequate administrative experience who shall have won distinction in science and/or technology and who posses sufficient background in nuclear science. Both shall pass the necessary security clearance.\nThe Commissioner shall receive an annual compensation of eighteen thousand pesos, and the Deputy Commissioner fifteen thousand pesos."}},{"id":"PH-H1806-A18","no":18,"noLabel":{"en":"Section 18."},"heading":{"en":"The Commission shall have the following divisions: the Administrative Division, the Division of Training, Plans and Poli"},"text":{"en":"Section 18. The Commission shall have the following divisions: the Administrative Division, the Division of Training, Plans and Policies, the Research and Development Division, the Legal Division and such other divisions as the Board may, upon recommendation of the Commissioner, deem necessary to create.\nThe Commission shall exercise control and supervision over the activities of the Atomic Energy Research Center which is hereby created, and such other centers as may be created by the Board, upon recommendation of the Commissioner."}},{"id":"PH-H1806-A19","no":19,"noLabel":{"en":"Section 19."},"heading":{"en":"Such technical and administrative personnel as may be necessary to carry out the functions of the Commission shall be ap"},"text":{"en":"Section 19. Such technical and administrative personnel as may be necessary to carry out the functions of the Commission shall be appointed of the Commissioner and subject to the approval of the Board."}},{"id":"PH-H1806-A20","no":20,"noLabel":{"en":"Section 20."},"heading":{"en":"The National Research Council of the Philippines shall act as the official adviser on scientific matters to the Governme"},"text":{"en":"Section 20. The National Research Council of the Philippines shall act as the official adviser on scientific matters to the Government of the Philippines.\nThe Science Foundation of the Philippines shall act as the official adviser on scientific matters to the Board."}},{"id":"PH-H1806-A21","no":21,"noLabel":{"en":"Section 21."},"heading":{"en":"The Board and its agencies are hereby authorized to call upon other government agencies and instrumentalities for assist"},"text":{"en":"Section 21. The Board and its agencies are hereby authorized to call upon other government agencies and instrumentalities for assistance and cooperation in the formulation and implementation of its policies, plans and programs."}},{"id":"PH-H1806-A22","no":22,"noLabel":{"en":"Section 22."},"heading":{"en":"The Chairman and Vice-Chairman of the Board, the Commissioners and Deputy Commissioners of both the National Institute o"},"text":{"en":"Section 22. The Chairman and Vice-Chairman of the Board, the Commissioners and Deputy Commissioners of both the National Institute of Science and Technology and the Philippine Atomic Energy Commission shall not, during their continuance in office, engage in the practice of any profession, or intervene, directly or indirectly, in the management or control of any private enterprise which in any way may be affected by the functions of their office, nor shall they directly or indirectly be financially interested in any contract with the Government or any subdivision or instrumentality thereof."}},{"id":"PH-H1806-A23","no":23,"noLabel":{"en":"Section 23."},"heading":{"en":"The Board and its agencies, as well as the University of the Philippines, are hereby authorized and empowered to receive"},"text":{"en":"Section 23. The Board and its agencies, as well as the University of the Philippines, are hereby authorized and empowered to receive grants, bequests and donations, made or given for the purpose of aiding scientific and technological investigations or establishing scholarships in the fields of science, engineering and technology. Such grants, bequests and donations shall be tax-exempt and upon certification of the Board or the University that said grants, bequests and donations are dedicated to the purposes above-mentioned."}},{"id":"PH-H1806-A24","no":24,"noLabel":{"en":"Section 24."},"heading":{"en":"The Board shall promote and, in its discretion assist in the establishment of private foundations for scientific advance"},"text":{"en":"Section 24. The Board shall promote and, in its discretion assist in the establishment of private foundations for scientific advancement as well as specific research and development projects by private individuals, firms and institutions. All funds contributed to the support and maintenance of such foundations and their projects as well as specific research and development projects undertaken by private individuals and educational institutions, shall be tax-exempt and deductible from the donor's income tax returns, upon certification by the Board that such foundations and funds are dedicated to scientific pursuits."}},{"id":"PH-H1806-A25","no":25,"noLabel":{"en":"Section 25."},"heading":{"en":"Any person who evades or defeats or attempts to evade or defeat, in any manner, any tax imposed by law by availing himse"},"text":{"en":"Section 25. Any person who evades or defeats or attempts to evade or defeat, in any manner, any tax imposed by law by availing himself of the provisions of section twenty-three or twenty-four hereof through fraud or misrepresentation shall be punished by a fine of not more than four thousand pesos or imprisonment for not more than one year, or both, in the discretion of the Court.\nIn case the violator is a corporation or association the penalty shall be fine of not more than ten thousand pesos, without prejudice to the criminal responsibility of the member, officer of employee thereof committing such violation."}},{"id":"PH-H1806-A26","no":26,"noLabel":{"en":"Section 26."},"heading":{"en":"Provisions of law to the contrary notwithstanding, all officials and employees appointed under this Act, classification,"},"text":{"en":"Section 26. Provisions of law to the contrary notwithstanding, all officials and employees appointed under this Act, classification, shall be exempt from the provisions of laws, except those who belong to the clerical and janitorial rules and regulations on wage and position classification."}},{"id":"PH-H1806-A27","no":27,"noLabel":{"en":"Section 27."},"heading":{"en":"There are hereby authorized to be appropriated such sums as may be necessary to carry out the provisions and purposes of"},"text":{"en":"Section 27. There are hereby authorized to be appropriated such sums as may be necessary to carry out the provisions and purposes of this Act.\nAll sums heretofore appropriated or to be appropriated under section three of Republic Act Numbered One thousand six hundred and six, including the special fund known as the Scientific, Engineering and Technological Research Fund, as well as other appropriations for the National Science Board, the National Scientific and Industrial Research Institute (the former Institute of Science and Technology), the Philippine Nuclear Energy Commission, the Institute of Nutrition and such other government agencies and instrumentalities as may be transferred to the Board pursuant to section fourteen hereof, and all appropriations for the foregoing agencies and instrumentalities under the Appropriation Act for the fiscal year 1959 are hereby re-appropriated as funds of the Board to be used in such manner as shall best insure the implementation of the objectives of this Act, subject to the provisions of section twenty-five hereof.\nThe sum of six hundred thousand pesos is hereby appropriated from any available funds of the National Treasury not otherwise appropriated as additional outlay for the activities of the Board for the fiscal year nineteen hundred fifty-nine."}},{"id":"PH-H1806-A28","no":28,"noLabel":{"en":"Section 28."},"heading":{"en":"Funds appropriated for the Board and its agencies shall, if obligated by contract during the fiscal year for which appro"},"text":{"en":"Section 28. Funds appropriated for the Board and its agencies shall, if obligated by contract during the fiscal year for which appropriated, remain available for expenditure for four years following the expiration of the fiscal year for which appropriated or for the duration of the contract under which obligated."}},{"id":"PH-H1806-A29","no":29,"noLabel":{"en":"Section 29."},"heading":{"en":"All files, records, supplies, equipment, buildings, personnel, funds and unexpended balance of appropriations of the Nat"},"text":{"en":"Section 29. All files, records, supplies, equipment, buildings, personnel, funds and unexpended balance of appropriations of the National Science Board, the National Scientific and Industrial Research Institute (the former Institute of Science and Technology), and the Philippine Nuclear Energy Commission, are hereby transferred respectively to each of the corresponding agencies under this Act, subject to the provisions of sections ten, fifteen and nineteen hereof."}},{"id":"PH-H1806-A30","no":30,"noLabel":{"en":"Section 30."},"heading":{"en":"Projects already initiated under the National Science Board shall be continued under the National Science Development Bo"},"text":{"en":"Section 30. Projects already initiated under the National Science Board shall be continued under the National Science Development Board.\nThe projects enumerated under Republic Act Numbered One thousand six hundred and six, which have not yet been initiated shall be reviewed and, if necessary, revised by the National Science Development Board which shall provide for their continuance until the end of the fiscal year nineteen hundred sixty-one."}},{"id":"PH-H1806-A31","no":31,"noLabel":{"en":"Section 31."},"heading":{"en":"If any provision of this Act or the application of such provision to any person or circumstances is held invalid, the re"},"text":{"en":"Section 31. If any provision of this Act or the application of such provision to any person or circumstances is held invalid, the remainder of this Act or the application of such provision to other persons or circumstances shall not be affected thereby."}},{"id":"PH-H1806-A32","no":32,"noLabel":{"en":"Section 32."},"heading":{"en":"This Act repeals Republic Act Numbered One thousand six hundred and six, except section three thereof which shall contin"},"text":{"en":"Section 32. This Act repeals Republic Act Numbered One thousand six hundred and six, except section three thereof which shall continue in force as amended by section twenty-six hereof, Republic Act Numbered One thousand eight hundred and fifteen, except section ten thereof which shall continue in force as amended by section twenty-six hereof, and such other Acts or parts of Acts which are inconsistent herewith."}},{"id":"PH-H1806-A33","no":33,"noLabel":{"en":"Section 33."},"heading":{"en":"This Act shall take effect upon the constitution of the Board but not later than thirty days after the approval hereof."},"text":{"en":"Section 33. This Act shall take effect upon the constitution of the Board but not later than thirty days after the approval hereof.\nApproved: June 13, 1958"}}],"pack":"ph-p25","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act to Integrate, Coordinate, and Intensify Scientific and Technological Research and Development and to Foster Invention; to Provide Funds Therefor; and for Other Purposes","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"},"recrawled":"2026-10-24 从 https://lawphil.net/statutes/repacts/ra1958/ra_2067_1958.html 重抓，33 → 33 条"};
  FT["PH-H1807"] = {"id":"PH-H1807","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1958/ra_2068_1958.html","fetchedAt":"2026-10-06","articleCount":3,"structureMode":"ARTICLE","title":{"zh":"增加总检察长办公室某些官员的人数与薪金，为此修订《行政法典》（经第945号共和国法修正）第1659条","en":"An Act Increasing the Number and the Salaries of Certain Officials of the Office of the Solicitor General, Amending for This Purpose Section Sixteen Hundred Fifty-Nine of the Administrative Code, as Amended by Republic Act Numbered Nine Hundred Forty-Five","orig":"An Act Increasing the Number and the Salaries of Certain Officials of the Office of the Solicitor General, Amending for This Purpose Section Sixteen Hundred Fifty-Nine of the Administrative Code, as Amended by Republic Act Numbered Nine Hundred Forty-Five"},"level":"law","status":"active","topics":["administrative"],"docNumber":"Republic Act No. 2068","issuingBody":"Congress of the Philippines","promulgatedDate":"1958-06-13","completenessNote":"全文，共 3 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1958/ra_2068_1958.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H1807-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"Section sixteen hundred fifty-nine of the Administrative Code, as amended by Republic Act Numbered Nine hundred forth-five, is further amended to read as follows:\n\"Sec. 1659. Chief Officials of Office of the Solicitor General. -The Office of the Solicitor General shall have one chief to be known as the Solicitor General whose salary shall be twelve thousand pesos per annum and shall have the rank of an Undersecretary of a Department. He shall be assisted by one First Assistant Solicitor General whose salary shall be eleven thousand pesos per annum. When the Solicitor General is unable to perform his duties or in case of a vacancy in the office, the First Assistant Solicitor General shall temporarily perform the functions of said officer, or in his absence, the next Assistant Solicitor General who is senior in the service. There shall also be five Assistant Solicitors General each of whom shall receive a salary of ten thousand pesos per annum, and thirty-six Solicitors whose salaries shall be as follows:\n\"(a) Six Solicitors, nine thousand pesos per annum each;\n\"(b) Six Solicitors, eight thousand four hundred pesos per annum each;\n\"(c) Six Solicitors, seven thousand eight hundred pesos per annum each;\n\"(d) Six Solicitors, seven thousand two hundred pesos per annum each;\n\"(e) Six Solicitors, six thousand six hundred pesos per annum each;\n\"(f) Six Solicitors, six thousand pesos per annum each;\n\"The qualifications for appointment to the position of Solicitor General, the First Assistant Solicitor General and the Assistant Solicitor General shall be the same as those prescribed for Judges of Courts of First Instance, and those of Solicitors shall be the same as those prescribed for provincial fiscals, except those for Solicitors mentioned in paragraphs (e), and (f) of this section which must be actual practice of law for at least three years or having occupied a position requiring a lawyer’s diploma for the same period.\""}},{"id":"PH-H1807-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"To carry out the provisions of this Act, and in addition to such sums as may have been provided in the current Appropriation Act, there is hereby appropriated out of any funds in the National Treasury not otherwise appropriated, such sums as are necessary to carry out the provisions of this Act."}},{"id":"PH-H1807-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 13, 1958."}}],"pack":"ph-p25","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act Increasing the Number and the Salaries of Certain Officials of the Office of the Solicitor General, Amending for This Purpose Section Sixteen Hundred Fifty-Nine of the Administrative Code, as Amended by Republic Act Numbered Nine Hundred Forty-Five","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H1808"] = {"id":"PH-H1808","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1958/ra_2069_1958.html","fetchedAt":"2026-10-06","articleCount":4,"structureMode":"ARTICLE","title":{"zh":"修订第1434号共和国法（即《萨马理工学院宪章》）若干条款的法案","en":"An Act to Amend Certain Sections of Republic Act Numbered One Thousand Four Hundred Thirty-Four, Otherwise Known as the Charter of the Samar Institute of Technology","orig":"An Act to Amend Certain Sections of Republic Act Numbered One Thousand Four Hundred Thirty-Four, Otherwise Known as the Charter of the Samar Institute of Technology"},"level":"law","status":"active","topics":["general"],"docNumber":"Republic Act No. 2069","issuingBody":"Congress of the Philippines","promulgatedDate":"1958-06-13","completenessNote":"全文，共 4 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1958/ra_2069_1958.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H1808-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"The first paragraph of section three of Republic Act Numbered One thousand four hundred thirty-four, otherwise known as the Charter of the Samar Institute of Technology, is hereby amended to read as follows:\n\"Sec. 3. The Samar Institute of Technology shall have the general powers set out in section thirteen of the Corporation Law, as amended, and the government and administration of said Institute and the exercise of its corporate powers are hereby vested exclusively in the Board of Trustees, and the President of the Institute insofar as authorized by said Board. The governing body of the Institute shall be the Board of Trustees of the Samar Institute of Technology. The said Board of Trustees shall be composed of the Secretary of Education, who shall be ex-officio chairman, the Chairman of the Committee on Education of the House of Representatives, the Director of Public Schools, the President of the Institute, the President of the Alumni Association, and a prominent citizen of Samar to be designated by the President of the Philippines. When the Secretary of Education is unable to perform his duties as ex-officio Chairman of the Board, owing to illness, absence, or other causes, or in case of a vacancy in the office, the Undersecretary of Education shall temporarily perform the functions of ex-officio Chairman of said Board. When both the Secretary and the Undersecretary of Education are unable to exercise the powers of the Chairman of the Board of Trustees, or when these two positions are vacant, the members of the Board may elect from among themselves a temporary chairman who shall act as Chairman of the Board of Trustees.\""}},{"id":"PH-H1808-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"The first paragraph of section four of the same Act is amended to read as follows:\n\"Sec. 4. The Board of Trustees shall have the following powers and duties, in addition to its general powers of administration and the exercise of all the powers of a corporation as provided in section thirteen of the Corporation Law, as amended:\""}},{"id":"PH-H1808-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"Between sections ten and eleven of the same Act, the following two new sections are inserted:\n\"Sec. 10-A. The Treasurer of the Philippines shall be ex-officio Treasurer of the Institute, and all account and expenses thereof shall be audited by the Auditor General or his duly authorized representatives, and all disbursements shall be made in accordance with rules and regulations prescribed by him.\"\n\"Sec. 10-B. Heads of bureaus or offices of the National Government are hereby authorized to loan or transfer, upon request of the President of the Institute, such apparatus or supplies as may be needed by the Institute, and to detail employees for duty therein, when in the judgment of the head of the Bureau or office such services, apparatus or supplies and employees can be spared without serious detriment to the public service. Employees so detailed shall perform such duties as may be required by the President of the Institute, and the time so employed shall count as part of their regular official service.\""}},{"id":"PH-H1808-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 13, 1958."}}],"pack":"ph-p25","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act to Amend Certain Sections of Republic Act Numbered One Thousand Four Hundred Thirty-Four, Otherwise Known as the Charter of the Samar Institute of Technology","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H1809"] = {"id":"PH-H1809","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1958/ra_2070_1958.html","fetchedAt":"2026-10-06","articleCount":11,"structureMode":"ARTICLE","title":{"zh":"规定全国税务普查的法案","en":"An Act to Provide for National Tax Census","orig":"An Act to Provide for National Tax Census"},"level":"law","status":"active","topics":["tax"],"docNumber":"Republic Act No. 2070","issuingBody":"Congress of the Philippines","promulgatedDate":"1958-06-13","completenessNote":"全文，共 11 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1958/ra_2070_1958.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H1809-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"Every resident of the Philippines over eighteen years of age, every guardian of minors and executor or administrator of estates and every corporation, joint stock company, partnership, joint account or association, whether domestic or resident foreign, shall within one hundred days from the effective date of this Act, and during the month of January of each succeeding year, file with the city or municipal treasurer in such form as the Commissioner of Internal Revenue, with the approval of the Secretary of Finance shall prescribe, without charge to such resident, corporation, joint stock company, partnership, joint account or association, a statement under oath showing: in the case of a corporation, joint stock company, partnership, joint account or association: (1) the name of the business or businesses engaged in, (2) form of organization, (3) name and nationality of President, (4) name and nationality of manager thereof and (5) list of stockholders, partners or members of associations with their respective holdings; in the case of individuals: (1) name, (2) age, (3) sex, (4) nationality (if alien, the number of the Alien Registration Certificate), and aliases used, or authorized to be used, if any, (5) address, (6) occupation, (7) place of business, (8) wife's or husband's name, age, sex, occupation and place of business, and (9) the members of his family, age and sex; and in both cases: (1) real property owned, stating the nature thereof, location and assessed value thereof, and. the annual gross income therefrom during the preceding year, (2) property held under lease stating also the nature, location and assessed value thereof and the annual income during the preceding year, (3) businesses subject to tax giving the nature and location thereof and the annual gross receipts or earnings during the preceding year, (4) stocks in corporation or shares in partnerships or associations, (5) professions or occupations, stating the kind and location thereof and the annual salaries or gross receipts or earnings during the preceding year, and (6) such other information as may be necessary to determine his or its tax liability. This statement shall be prepared in quadruplicate. One copy shall be retained by the city or municipal treasurer who shall transmit the original and two copies to the Regional Director concerned, who shall send the original to the Commissioner of Internal Revenue and a copy to the Director of the Census and Statistics.\nThe Commissioner of Internal Revenue may, in meritorious cases, grant a reasonable extension of thirty days for filing the statement required in this Act."}},{"id":"PH-H1809-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"Each city or municipal treasurer and Regional Director shall keep and maintain, an appropriate national tax register of the persons residing in his jurisdiction based upon the data and information given in the statement required in section one hereof. The register should also show at any time the taxes due and taxes paid by the taxpayer concerned. The national tax register shall be revised and kept up to date as verification, investigation or additional information may disclose or require. It shall be available for use by any internal revenue or other tax collecting officer as aid in the collection of taxes."}},{"id":"PH-H1809-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"The Regional Directors are hereby authorized to require the assistance of city and municipal treasurers, public school officials, teachers and other employees assigned in the cities and municipalities within their jurisdiction and it shall be the duty of said treasurers, public school officials, teachers and other employees to render assistance to the Regional Directors in the preparation and periodic revision of the national tax registers. For the preparation or revision of the national tax registers, they shall receive additional compensation at the rate of five centavos per register form accomplished. They shall also be entitled to the payment of ordinary traveling expenses upon the proper presentation of reimbursement receipts."}},{"id":"PH-H1809-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"The statements furnished the Commissioner of Internal Revenue shall be consolidated by the Bureau of Internal Revenue into a tax census, copies of which shall be transmitted to the Secretary of Finance for statistical purposes, with the end in view of formulating tax policies and recommending reforms in the tax system and in revenue administration to achieve efficiency and honesty in the collection of taxes. The Secretary of Finance shall submit to Congress within thirty days from the opening of each regular session a report on said tax census and the extent to which such census has been compiled, tabulated and analyzed in relation to actual revenue collections."}},{"id":"PH-H1809-A5","no":5,"noLabel":{"en":"Section 5."},"text":{"en":"Any person who fails to file the statement required in this Act, or who intentionally gives false or fraudulent information therein, shall, upon conviction, be punished by a fine of not more than five hundred pesos or by imprisonment for not more than six months, or both, in the discretion of the court. Any responsible officer of any corporation, joint stock company, partnership, joint account or association, required by this Act to make and file such statement, who refuses or neglects to make or file such statement within the time prescribed in this Act or who makes any false or fraudulent statement, shall be punished by a fine of not exceeding four thousand pesos or by imprisonment for not exceeding six months, or both, in the discretion of the court. In case the offender is an alien, said offender, upon conviction, shall be deported immediately without the necessity of further proceedings in the Deportation Board."}},{"id":"PH-H1809-A6","no":6,"noLabel":{"en":"Section 6."},"text":{"en":"No information secured from the statement required in section one hereof shall be published, except in the form of tabulations or summaries having no reference to individuals: Provided, That any court of record by order or subpoena duces tecum may require the presentation of documents or information herein provided for when such documents or information are necessary for the adjudication of the case at issue. Any such officer or employee who shall divulge to any unauthorized person information regarding the business, income, or inheritance of any taxpayer, the secrets, operation, style of work, or apparatus of any manufacturer or producer, or confidential information, knowledge of which was acquired by him in the discharge of his official duties under the provisions of this Act, shall be fined in a sum not exceeding two thousand pesos or imprisoned for a term of not less than six months nor more than five years, or both, in the discretion of the Court, except in such instances where the information regarding the business, income, or inheritance of any tax-payer, the secrets, operation, style of work, or apparatus of any manufacturer or producer, or confidential information, constitutes prima facie evidence of the commission of a crime, or constitutes in itself a crime, in which case the obligation to reveal same to any duly constituted investigating body shall exempt the officer or employee from any liability. Nothing contained in this section shall be construed to prevent courts of justice or the Congress or legislative committee to require the production of any statement referred to herein when relevant to the issues or matters, subject of judicial or legislative investigation."}},{"id":"PH-H1809-A7","no":7,"noLabel":{"en":"Section 7."},"text":{"en":"The Commissioner of Internal Revenue, with the approval of the Secretary of Finance, shall promulgate rules and regulations to carry out the provisions of this Act."}},{"id":"PH-H1809-A8","no":8,"noLabel":{"en":"Section 8."},"text":{"en":"There is hereby created a new Division in the Bureau of Internal Revenue to be known as the Tax Census Division, hereinafter referred to as the Division."}},{"id":"PH-H1809-A9","no":9,"noLabel":{"en":"Section 9."},"text":{"en":"The Division shall have the following personnel who shall receive the compensation hereinbelow indicated:\nOne Chief of Division ₱6,000.00 One Assistant Chief of Division 5,400,00 Ten Supervisors at ₱3,600 each.\n36,000.00 Four stenographers at ₱2,400 each 9,600.00 Ten typists at ₱1,800 each 18,000.00 One hundred twenty census takers at ₱1,800 each 216,000.00 Ten Senior clerks at ₱2,400 each 24,000.00 Ten clerks at ₱l,800 each 18,000.00 One messenger 1,440.00"}},{"id":"PH-H1809-A10","no":10,"noLabel":{"en":"Section 10."},"text":{"en":"The sum of six hundred thousand pesos or so much thereof as may be necessary to carry out the provisions of this Act is hereby appropriated, out of any funds in the National Treasury not otherwise appropriated, for the salaries and the purchase of supplies and equipment necessary to carry out the provisions of this Act. Thereafter, the funds necessary shall be included in the regular Appropriation Act."}},{"id":"PH-H1809-A11","no":11,"noLabel":{"en":"Section 11."},"text":{"en":"This Act shall take effect upon its approval.\nApproved, June 13, 1958."}}],"pack":"ph-p25","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act to Provide for National Tax Census","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H1810"] = {"id":"PH-H1810","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1958/ra_2071_1958.html","fetchedAt":"2026-10-06","articleCount":3,"structureMode":"ARTICLE","title":{"zh":"修订第481号共和国法（题为“为菲律宾武装部队人员提供更高效牙科医疗”，经第1128号共和国法修正）若干条款","en":"An Act to Amend Certain Section of Republic Act Numbered Four Hundred Eighty-One, Entitled “An Act to Provide More Efficient Dental Care for the Personnel of the Armed Forces of the Philippines,” as Amended by Republic Act Numbered Eleven Hundred Twenty-Eight","orig":"An Act to Amend Certain Section of Republic Act Numbered Four Hundred Eighty-One, Entitled “An Act to Provide More Efficient Dental Care for the Personnel of the Armed Forces of the Philippines,” as Amended by Republic Act Numbered Eleven Hundred Twenty-Eight"},"level":"law","status":"active","topics":["defence"],"docNumber":"Republic Act No. 2071","issuingBody":"Congress of the Philippines","promulgatedDate":"1958-06-13","completenessNote":"全文，共 3 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1958/ra_2071_1958.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H1810-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"Section three of Republic Act Numbered Four hundred eighty-one is amended to read as follows:\n\"Sec. 3. The Dental Service shall (1) establish professional standards and policies for the conduct of the Dental Service; (2) issue instructions and conduct inspections and surveys for the maintenance of such standards; (3) initiate and direct all actions relating to the dental service and pertaining to facilities, equipment, supplies, research, tables of organization, planning and personnel, including the appointment, training, classification, assignment, transfer, promotion and decoration of personnel; and (4) submit estimated of the amount of funds needed to maintain the Dental Service.\""}},{"id":"PH-H1810-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"Section five of Republic Act Numbered Four hundred eighty-one, as amended, is further amended to read as follows:\n\"Sec. 5. The number of officers of the Dental Service shall not be less than two officers for every thousand of the total strength of the AFP authorized from time to time. A separate roster for officers of the Dental Service shall be kept separate from the Medical Service. Hereafter the Dental Service shall consist of commissioned officers of the same grades and proportionately distributed among such grades as are now or may hereafter be provided for the Medical Corps, and who shall have the rank, pay and allowances of officers of corresponding grades in the medical corps.\""}},{"id":"PH-H1810-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 13, 1958."}}],"pack":"ph-p25","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act to Amend Certain Section of Republic Act Numbered Four Hundred Eighty-One, Entitled “An Act to Provide More Efficient Dental Care for the Personnel of the Armed Forces of the Philippines,” as Amended by Republic Act Numbered Eleven Hundred Twenty-Eight","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H1811"] = {"id":"PH-H1811","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1958/ra_2072_1958.html","fetchedAt":"2026-10-06","articleCount":2,"structureMode":"ARTICLE","title":{"zh":"修订《国家国内税收法典》第191条第1款（经修正）的法案","en":"An Act to Amend the First Paragraph of Section One Hundred Ninety-One of the National Internal Revenue Code, as Amended","orig":"An Act to Amend the First Paragraph of Section One Hundred Ninety-One of the National Internal Revenue Code, as Amended"},"level":"law","status":"active","topics":["tax"],"docNumber":"Republic Act No. 2072","issuingBody":"Congress of the Philippines","promulgatedDate":"1958-06-13","completenessNote":"全文，共 2 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1958/ra_2072_1958.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H1811-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"The first paragraph of section one hundred ninety-one of the National Internal Revenue Code, as amended, is further amended to read as follows:\n\"Sec. 191. Percentage tax on road, building, irrigation, artesian well, waterworks, and other construction work contractors, proprietors or operators of dockyards, and others. Roads, buildings, irrigation, artesian well, waterworks, and other construction work contractors; filling contractors; demolition and salvage work contractors; arrastre contractors; persons engaged in the installation of gas or electric light, heat, or power; persons selling water, light, heat or power, except those paying a franchise tax; proprietors or operators of dockyards, mine drilling apparatus, smelting plants, engraving plants, plating establishments, plastic lamination establishments, vulcanizing and recapping establishments; establishments for washing and/or greasing of motor vehicles, battery charging, planing or surfacing and recutting of lumber; sawmills under contract to saw and/or cut logs belonging to others; dry-cleaning or dyeing establishments, steam laundries using washing machines; photographic studios, telephone or telegraph lines or exchanges, broadcasting or wireless stations, funeral parlors; shops for the construction or repair of bicycles or vehicles of any kind, mechanical devices, instruments, apparatus, or furniture of any kind, shoe repairing by machine or any mechanical contrivance, and tailor shops, beauty parlors, dressmakers, milliners, hatters, keepers of hotels, lodging houses, stevedores, warehousemen; plumbers, smiths; house or sign painters; lithographers, publishers, except those engaged in the publication or printing and publication of any newspaper, magazine, review or bulletin which appears at regular intervals, with fixed prices for subscription and sale, and which is not devoted principally to the publication of advertisements; printers and bookbinders, business agents and other independent contractors except persons, associations and corporations under contract for embroidery and apparel for export as well as their agents and contractors, shall pay a tax equivalent to three per centum of their gross receipt.\""}},{"id":"PH-H1811-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 13, 1958"}}],"pack":"ph-p25","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act to Amend the First Paragraph of Section One Hundred Ninety-One of the National Internal Revenue Code, as Amended","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H1812"] = {"id":"PH-H1812","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1958/ra_2073_1958.html","fetchedAt":"2026-10-06","articleCount":3,"structureMode":"ARTICLE","title":{"zh":"对《关税海关法典》的修改","en":"An Act to Amend Paragraphs 73.11 and 73.21 of Chapter 73, Schedule XV, of Republic Act Numbered Nineteen Hundred Thirty-Seven, Otherwise Known as Tariff and Customs Code of the Philippines, and for Other Purposes","orig":"An Act to Amend Paragraphs 73.11 and 73.21 of Chapter 73, Schedule XV, of Republic Act Numbered Nineteen Hundred Thirty-Seven, Otherwise Known as Tariff and Customs Code of the Philippines, and for Other Purposes"},"level":"law","status":"active","topics":["tax"],"docNumber":"Republic Act No. 2073","issuingBody":"Congress of the Philippines","promulgatedDate":"1958-06-13","completenessNote":"全文，共 3 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1958/ra_2073_1958.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H1812-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"Paragraph 73.11 of Chapter 73, Schedule XV, of Republic Act Numbered Nineteen hundred thirty-seven is hereby amended to read as follows:\n\"73.11 Angles, shapes, sections and sheet piling, of iron or steel, hot-rolled, forged or cold-finished, whether or not drilled or punched, but not assembled:\nA.\nAngles of which the maximum cross-sectional dimension does not exceed eighty-eight millimeters and channels of which the maximum cross-section dimension does not exceed seventy-five millimeters ad val. 25% B.\nRiveted, welded, punched, or drilled ad val. 80% C.\nOther ad val. 15%.\""}},{"id":"PH-H1812-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"Paragraph 73.21 of Chapter 73, Schedule XV, of Republic Act Numbered Nineteen hundred thirty-seven, is hereby amended to read as follows:\n\"73.21 Assembled sheet pilling of cast iron, iron or steel; girders, beams, joists and pillars made from assembled elements; structures and finished parts for assembly into structures (e.g., bridge sections, roofing frameworks, shutters, pylons, balconies, balustrades, verandas, window and frames) of cast iron, iron or steel ad val. 80%.\""}},{"id":"PH-H1812-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 13, 1958"}}],"pack":"ph-p25"};
  FT["PH-H1813"] = {"id":"PH-H1813","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1958/ra_2074_1958.html","fetchedAt":"2026-10-06","articleCount":2,"structureMode":"ARTICLE","title":{"zh":"经费拨款法","en":"An Act Appropriating Additional Funds for the Operation and Maintenance of the Bureau of Prisons During the Period from July First, Nineteen Hundred and Fifty-Seven to June Thirtieth, Nineteen Hundred and Fifty-Eight, and for Other Purposes","orig":"An Act Appropriating Additional Funds for the Operation and Maintenance of the Bureau of Prisons During the Period from July First, Nineteen Hundred and Fifty-Seven to June Thirtieth, Nineteen Hundred and Fifty-Eight, and for Other Purposes"},"level":"law","status":"active","topics":["general"],"docNumber":"Republic Act No. 2074","issuingBody":"Congress of the Philippines","promulgatedDate":"1958-06-13","completenessNote":"全文，共 2 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1958/ra_2074_1958.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H1813-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"The sum of five hundred thirty-five thousand two hundred sixteen pesos is hereby appropriated, out of any funds in the National Treasury not otherwise appropriated, for additional expenses for the operation and maintenance of the Bureau of Prisons during the period from July first, nineteen hundred and fifty-seven to June thirtieth, nineteen hundred and fifty-eight: Provided, That not less than twenty per centum shall be used for the building program of the Bureau of Prisons: And Provided, further, That any balance thereof remaining unexpended at the end of said fiscal year shall be available for expenditure during the next fiscal year."}},{"id":"PH-H1813-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 13, 1958."}}],"pack":"ph-p25"};
  FT["PH-H1814"] = {"id":"PH-H1814","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1958/ra_2075_1958.html","fetchedAt":"2026-10-06","articleCount":2,"structureMode":"ARTICLE","title":{"zh":"经费拨款法","en":"An Act Appropriating the Sum of Eight Hundred Thousand Pesos for Handling, Hauling and Distributing the Relief Goods Which Have Been Donated to the Philippines by the National Relief or Welfare Organizations in the United States of America and Other Countries in the Free World","orig":"An Act Appropriating the Sum of Eight Hundred Thousand Pesos for Handling, Hauling and Distributing the Relief Goods Which Have Been Donated to the Philippines by the National Relief or Welfare Organizations in the United States of America and Other Countries in the Free World"},"level":"law","status":"active","topics":["general"],"docNumber":"Republic Act No. 2075","issuingBody":"Congress of the Philippines","promulgatedDate":"1958-06-13","completenessNote":"全文，共 2 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1958/ra_2075_1958.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H1814-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"The sum of eight hundred thousand pesos is appropriated, out of any funds in the National Treasury not otherwise appropriated, for handling, hauling and distributing the relief goods which have been donated to the Philippines during the fiscal year nineteen hundred fifty-seven-nineteen hundred fifty-eight, by the national relief or welfare organizations in the United States of America and other countries in the Free World."}},{"id":"PH-H1814-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 13, 1958."}}],"pack":"ph-p25"};
  FT["PH-H1815"] = {"id":"PH-H1815","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1958/ra_2076_1958.html","fetchedAt":"2026-10-06","articleCount":12,"structureMode":"ARTICLE","title":{"zh":"修订第 1609 号共和国法（即以合理价格向农民供应化肥促进农业生产）若干条款的法案","en":"An Act Amending Certain Sections of Republic Act Numbered Sixteen Hundred Nine, Entitled “An Act to Encourage Agricultural Production by Making Fertilizers Available to Farmers at Reasonable Prices”","orig":"An Act Amending Certain Sections of Republic Act Numbered Sixteen Hundred Nine, Entitled “An Act to Encourage Agricultural Production by Making Fertilizers Available to Farmers at Reasonable Prices”"},"level":"law","status":"active","topics":["environment"],"docNumber":"Republic Act No. 2076","issuingBody":"Congress of the Philippines","promulgatedDate":"1958-06-13","completenessNote":"全文，共 12 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1958/ra_2076_1958.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。 源文存在同号重出的条款（第 3 条）：该处官方页面确有两段均标同一 Section 号，本库照录其 `no` 值（不改动官方编号），条文 `id` 以 `_2`「_3」后缀保证唯一。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H1815-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"Section two of Republic Act Numbered Sixteen hundred and nine is amended to read as follows:\n\"Section 2. The government shall purchase fertilizers and soil conditioners in the manner hereinafter provided, and shall sell the same to farmers in the manner herein provided, according to the following schedule of prices:\nSulphate or ammonia (synthetic crystalline) ₱70 per ton Phosphate of ammonia 90 per ton Superphosphate 60 per ton Sulphate of potash 80 per ton Muriate of potash 80 per ton Organic fertilizer and soil conditioner Not less than 50 per ton Provided, That mixed fertilizers shall be priced according to the cost herein provided for the various components of the mixture plus a reasonable charge for manufacturing: And provided, further, That the prices hereinabove provided shall be for fertilizers and soil conditioners in standard six-ply paper bags, asphalt laminated, ex-warehouse Manila basis, the necessary transportation and handling expenses shall be added to the price for points outside Manila.\""}},{"id":"PH-H1815-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"Section three of the same Act is hereby amended to read as follows:\n\""}},{"id":"PH-H1815-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"Only bona fide farmers shall be eligible to purchase fertilizers and soil conditioners under this Act and they shall be allowed to purchase only those types and in the quantities which the field agents of the Bureau of Agricultural Extension shall certify jointly with the municipal agriculturist to be actually necessary for their own planting operations.\n\"In making the certification provided in the first paragraph hereof, the officials concerned shall be guided by a national program for the allocation and distribution of fertilizers and soil conditioners formulated by the Secretary of Agriculture and Natural Resources or by any council or committee designated by him for the purpose.\n\"In no case shall the fertilizers and soil conditioners acquired under this Act be resold or disposed of without previous approval from the Bureau of Agricultural Extension.\""}},{"id":"PH-H1815-A3-d2","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"Section four of the same Act is amended to read as follows:\n\"Section 4. The ACCFA is hereby designated and directed to administer the distribution of fertilizers and soil conditioners through the facilities of farmers' cooperative marketing associations and their federations or other farmers' cooperative associations or bona fide private farmers' organizations duly registered with the Department of Labor that are or may be organized in every town, and in towns where there are no farmers' cooperative marketing associations operating or doing business therein, other farmers' cooperative associations or bona fide private farmers' organizations through the Bureau of Agricultural Extension proportionately to the acreage devoted for agricultural production by province in accordance with the latest statistics of the Department of Agriculture and Natural Resources: Provided, That the fertilizer and soil conditioner shall be used for the purpose it is intended and shall not be channeled to the black market; and that the distributing agency of fertilizers and soil conditioners shall take all steps to prevent the waste and black marketing of the same, and shall provide the greatest publicity concerning their distribution, giving such information to the barrio councils or to any other civic organizations requesting such information: Provided, further, That in the distribution of fertilizers and soil conditioners preference be given to small farmers with landholdings not exceeding five hectares, except in the case of small farmers with landholdings of not exceeding two hectares who may be allowed to buy the fertilizers and soil conditioners on credit: Provided, further, That fertilizers and soil conditioners not exceeding one bag per farmer may be distributed free to indigent farmers who suffer losses due to crop failure because of calamitous events certified, to by the Director of the Bureau of Agricultural Extension, with the approval of the Secretary of Agriculture and Natural Resources: Provided, furthermore, That in the handling, warehousing, transporting, and trucking of said fertilizers and soil conditioners, only personnel and facilities of the farmers' cooperative marketing associations and their federations or bona fide private farmers' organizations or other farmers' cooperative associations shall be utilized: Provided, finally, That the ACCFA shall be responsible for delivering the fertilizers and soil conditioners to the farmers at the fertilizing period appropriate for the various crops of farmers throughout the Philippines.\""},"dupIndex":2},{"id":"PH-H1815-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"Section five of the same Act is amended to read as follows:\n\"Section 5. The ACCFA shall determine before the beginning of each crop year, in consultation with the Bureau of Agricultural Extension, the various commodity corporations, the various chambers of agriculture, the cooperative associations, and bona fide private farmers' organizations the aggregate fertilizer and soil conditioner requirements for the year, the actual needs and/or requirements per hectare of land according to the kind of crop or crops produced thereon, and the monthly schedule of procurement and delivery. The quantity of fertilizer and soil conditioner to be allotted to the farmer-applicants shall be on the basis of the actual needs and/or requirements of each kind of crop or crops per hectare as determined in the manner hereinabove described: Provided, however, That delivery and/or distribution of the fertilizers and soil conditioners shall be made by the ACCFA directly to the farmers concerned or, if such farmer or farmers is or are members of a cooperative association which is affiliated with the ACCFA, to said cooperative association: Provided, further, That in the event the funds made available.to the ACCFA be less than what is appropriated, delivery and/or distribution shall be made proportionately on the basis of the actual needs or requirements of each kind of crop or crops.\""}},{"id":"PH-H1815-A5","no":5,"noLabel":{"en":"Section 5."},"text":{"en":"Section, six of the same Act is amended to read as follows:\n\"Section 6. The ACCFA shall procure the fertilizers and soil conditioners in the quantities and types which are required at the lowest possible prices first from locally produced supplies and the balance from imports through public bidding to be conducted by a committee composed of the Secretary of Finance or his representative, as chairman, the Secretary of Agriculture and Natural Resources or his representative and a representative of the ACCFA, as members: Provided, That the Central Bank of the Philippines shall allocate the necessary dollars for the importation of said fertilizers and soil conditioners: And provided, further, That in order to assure the procurement and delivery of the aggregate fertilizer and soil conditioner requirements, the funds appropriated in section nine hereof shall be utilized solely for the purpose of paying the difference between the total price of purchases made and the selling price of the different kinds of fertilizer and soil conditioner as provided in section two hereof.\""}},{"id":"PH-H1815-A6","no":6,"noLabel":{"en":"Section 6."},"text":{"en":"Between section six and section seven of the same Act, the following new section is inserted:\n\"Section 6-A. Local purchases and/or importations made by the ACCFA of the aggregate fertilizer and soil conditioner requirements in compliance with the above sections shall be exempt from the payment of sale tax, all percentage taxes of whatever nature and description, including the special import tax.\""}},{"id":"PH-H1815-A7","no":7,"noLabel":{"en":"Section 7."},"text":{"en":"Section seven of the same Act is amended to read as follows:\n“Section 7. The representatives of farmers' cooperative marketing associations and their federations may demand at any time that a bidding be called by the committee herein created, for the purpose of assuring procurement and delivery of their respective fertilizer and soil conditioner requirements on time.\""}},{"id":"PH-H1815-A8","no":8,"noLabel":{"en":"Section 8."},"text":{"en":"Section eight of the same Act is amended to read as follows:\n\"Section 8. Any official or employee of the ACCFA, or any official or employee of any farmers' cooperative association and their federation or bona fide private farmers' organization who shall discriminate in favor of or against any person or persons in violation of section three hereof, or who shall aid, abet, facilitate, or channel fertilizers and soil conditioners provided for in this Act to persons other than those embraced in section three hereof or who shall violate any provision of this Act shall be punished by a fine of not less than two thousand pesos or not more than five thousand pesos and imprisonment of not less than six months and not more than two years.\n\"Any farmer receiving fertilizers or soil conditioners under this Act who shall dispose of the same in any manner other than their application to his farm without previous approval from the Bureau of Agricultural Extension shall forfeit all rights to receive fertilizers or soil conditioners under this Act and shall, in addition, be punished by a fine of two thousand pesos or imprisonment of one year, or both.\n\"Any person who knowingly buys or receives from any farmer receiving fertilizers or soil conditioners under this Act without previous approval from the Bureau of Agricultural Extension, or any person or the president or manager of any juridical person who shall possess, deal in, sell, store, or export fertilizers or soil conditioners provided for in this Act, shall be punished with the same penalties prescribed in the preceding paragraph of this section.\""}},{"id":"PH-H1815-A9","no":9,"noLabel":{"en":"Section 9."},"text":{"en":"Section nine of the same Act is amended to read as follows:\n\"Section 9. There is hereby appropriated for the purpose of this Act an amount of twenty million pesos to be drawn every year and for a period of six years out of any funds in the National Treasury.\""}},{"id":"PH-H1815-A10","no":10,"noLabel":{"en":"Section 10."},"text":{"en":"Section ten of the same Act is amended to read as follows:\n\"Section 10. This Act shall take effect upon its approval and for a period of six years from the date of its approval.\""}},{"id":"PH-H1815-A11","no":11,"noLabel":{"en":"Section 11."},"text":{"en":"This Act shall take effect upon its approval.\nApproved, June 13, 1958."}}],"pack":"ph-p25","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act Amending Certain Sections of Republic Act Numbered Sixteen Hundred Nine, Entitled “An Act to Encourage Agricultural Production by Making Fertilizers Available to Farmers at Reasonable Prices”","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H1816"] = {"id":"PH-H1816","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1958/ra_2077_1958.html","fetchedAt":"2026-10-06","articleCount":6,"structureMode":"ARTICLE","title":{"zh":"修订第 1828 号共和国法第 2、3、5、6 与 8 条的法案","en":"An Act to Amend Sections Two, Three, Five, Six and Eight of Republic Act Numbered One Thousand Eight Hundred Twenty-Eight","orig":"An Act to Amend Sections Two, Three, Five, Six and Eight of Republic Act Numbered One Thousand Eight Hundred Twenty-Eight"},"level":"law","status":"active","topics":["general"],"docNumber":"Republic Act No. 2077","issuingBody":"Congress of the Philippines","promulgatedDate":"1958-06-13","completenessNote":"全文，共 6 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1958/ra_2077_1958.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H1816-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"Section two of Republic Act Numbered One thousand eight hundred twenty-eight is hereby amended to read as follows:\n\"Sec. 2. There is hereby created the Surigao Mineral Reservation Board, hereinafter referred to as the Board, composed of the Chairman of the National Economic Council, as chairman, the Secretary of Agriculture and Natural Resources, the Secretary of Finance, the Secretary of Justice, and the Governor of the Central Bank, as members, who shall carry out and implement the provisions of this Act. It shall have the power and authority to represent the Government in the operations and to insure compliance with the terms and conditions of the operating contract or contracts.\n\"The Board is hereby authorized to organize an office and appoint the necessary staff, whose salaries and emoluments shall be fixed by the Board, and to secure the assistance of the personnel of the National Economic Council and other government offices.\n\"In order to carry out the policy declared in section one hereof, the President of the Philippines is hereby authorized to determine, upon previous advice and recommendation of the Board, whether the development, exploitation and utilization of the said mineral deposit and the processing and disposition of the minerals that may be produced therefrom:\n\"(1) shall be undertaken by the Government itself, in which case he is authorized to contract loans and/or float bonds in such amounts as he may deem necessary and adequate to carry out effectively the undertakings contemplated in this Act, but not exceeding two hundred million pesos, after consultation with the Monetary Board of the Central Bank and upon recommendation of the National Council; or \"(2) shall be undertaken by the Government jointly with private enterprise, in which case he is also authorized to contract loans and/or float bonds in the amount and in the manner stipulated in the preceding subparagraph (1): Provided, however, That the Government shall, at any one time, own not less than fifty-one per centum of the capital stock of such enterprise; or \"(3) shall have the operation undertaken as hereinabove provided through an independent contractor or contractors who are qualified pursuant to the provisions hereunder, for the entire operation or any part or phase thereof.\n\"Unless there are clear advantages in favor of the third mode, either of the first two modes shall be preferred: Provided, That, in any case, the Board shall implement the policy herein declared.\n\"Should the President of the Philippines decide to have the operation undertaken through an independent contractor or contractors, as hereinabove provided, the Board may engaged and utilize the services of persons or corporations, as independent contractor or contractors, with the approval of the President, by calling for bids to undertake or perform for the Government any phase or phases of all the operations authorized in this Act covering any particular area or areas within the Surigao Mineral Reservation, and the processing of the minerals produced therefrom, negotiating and entering for such purpose into a contract or contracts of service with any party or parties, domestic or foreign, fully qualified as to organization, finances, resources, experience and technical competence, and which may offer such terms and conditions as determined by the Board, subject to the approval of the President of the Philippines, to be most advantageous to the Government: Provided, That should there be no bid submitted, or the bid or bids submitted are unacceptable, the Board, with the approval of the President, is hereby authorized to negotiate with such party or parties, domestic or foreign, as may be fully qualified as to organization, finances, resources, experience and technical competence, for the operation of the whole or part of the Surigao Mineral Reservation under the provisions of this Act.\n\"For the purpose of this Act, a contract of service shall mean an operating contract in which the Operator is an independent contractor of service, entitled as such to compensation for services rendered: Provided, That any contractor or contractors of service shall not, by virtue of the contract, acquire any title or interest in the area or areas affected, nor, except as hereinafter provided in section five hereof, in any of the minerals from the Surigao Mineral Reservation produced or processed by it. The Operator shall furnish all materials, labor, equipment, plants and other installations that may be acquired for carrying on the operations herein authorized, or necessary or incident to those herein authorized, and all such operations, processes, work or acts shall be carried out at Operator's own cost and expenses, without prejudice to the Government and Operator agreeing on other terms regarding materials, equipment, plants and other installations.\""}},{"id":"PH-H1816-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"Section three of the same Act is hereby amended to read as follows:\n\"Sec. 3. The President may grant to the Government entity which may operate the Reservation under paragraph one or two of section two, or to the operator under paragraph three of the same section, as the case may be, the following rights and privileges:\n\"(1) Necessary rights over an area or areas for investigation within the Surigao Mineral Reservation;\n\"(2) Exemption from laws and regulations relating to: (a) importation of machinery, equipment, accessories, spare parts, and/or supplies and materials necessary for or in connection with said operation or processing of minerals; (b) construction, installation and operation of power plants, including importation of machinery and equipment, accessories, spare parts and/or operating supplies and materials, should the National Power Corporation fail to supply within a reasonable period and at reasonable cost the power needed in the operation; (c) exportation of such machinery and equipment which were imported solely for construction and installation purposes in connection with the aforesaid operation and processing, and which are no longer needed in the operation;\n\"(3) Exportation of mineral products produced by the operations: Provided, That all domestic requirements for same shall have first been satisfied;\n\"(4) Importation of highly technical and specialized personnel and executive staff, who may exercise without examination or certification their profession solely for this undertaking subject to such regulations as may be prescribed by the office or agency to be created and designated, and who may receive not more than fifty per centum of their annual compensation in foreign exchange: And provided, That if the alien technicians lose their employment, the applicable laws and regulations on immigrants shall apply to such alien technicians and their immediate families; and \"(5) Gratuitous use of timber and water for mining and processing purposes from the Surigao Mineral Reservation.\""}},{"id":"PH-H1816-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"Section five of the same Act is hereby amended to read as follows:\n\"Sec. 5. The following provisions shall guide the relationship between the Government and the private enterprise holding the minority capital stock and/or its approved contractor as provided for in section two hereof:\n\"(1) Any minority stockholder and/or contractor may be authorized to repatriate not more than eighty per centum of the duly authorized and recognized foreign capital investments, plus interest, within five years or longer, in the discretion of the Board, from the first year of actual commercial production, depending upon operation circumstances, and to remit to non-resident investors abroad profits or dividends, out of current and annual profits or dividends: Provided, That the total repatriation of foreign investments herein authorized plus the total remission of profits or dividends for any year shall not exceed fifty per centum of the percentage contribution to the total capital investment: And provided, further, That the repatriation of the remaining duly authorized and recognized foreign capital investment shall be subject to the existing Central Bank regulations at the time: And provided, finally, That repatriations and remissions as herein provided may, at any time during the terms of the contract, be done under the provisions of this paragraph or under such regulations as may from time to time be promulgated by the Central Bank on the matter, at the election of the minority stockholder or operator;\n\"(2) The final area or areas in compact block or blocks, irrespective of water separation of portions, shall be selected sufficient to meet his reasonable needs of the operation as to ore reserves, plant sites, timber and water resources, to assure commercial operations, but in no case to exceed a total land area of twenty-five thousand hectares;\n\"(3) The rights and obligations of the Government and the minority stockholders shall be governed by the shares held by each;\n\"(4) Philippine citizens shall be given preference in all types of employment within the country insofar as such citizens are qualified to perform the corresponding work with reasonable efficiency and without hazard to the safety of the operations; and effective programs of training and advancement commensurate with the demonstrated abilities of such citizens to perform satisfactorily the various types of work involved in the operation shall be maintained.\""}},{"id":"PH-H1816-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"Section six of the same Act is hereby amended to read as follows:\n\"Sec. 6. Should the President of the Philippines decide to have the operations or any part thereof authorized in this Act done through the services of an independent contractor or contractors, the same shall be, among others, under the following terms and conditions:\n\"(1) The Operator shall be paid for services rendered and expenditures incurred beginning with the end of the first year after the effective date of the contract the sum of one peso (P1.00) per year, and the Operator shall receive, by way of additional compensation, an amount equivalent to a portion of the net profit or of the gross annual receipts from all minerals, mineral and metal products, and by-products resulting from the operation, processing, and disposition thereof computed such that the Government shall retain not less than thirty-five per centum of the annual net profit, realized from such operation, processing and disposition, or not less than three and one-half per centum of the gross annual receipts, f. o. b. point of export, whichever is higher: Provided, That the Operator may be exempt from all taxes, duties, fees and charges, both national and local, directly payable by it, until recovery of seventy-five per centum of the capital invested: Provided, however, That the Operator shall put the area or areas covered by the contract into actual production within five years from the effective date of the contract. Thereafter, penalties may be applied against the Operator for failure to effect such production, and/or reach certain levels of production within specific time period, as may be agreed upon: And provided, further, That exemption from taxes shall not extend to taxes due from contractor's personnel in their personal capacities;\n\"(2) The Operator shall file a bond to guarantee full and faithful compliance with all its obligations;\n\"(3) The Operator may be authorized to repatriate within five years or longer, in the discretion of the Board, from the first year of actual commercial production, depending upon operational circumstances, not more than eighty per centum of the duly authorized and recognized foreign capital investment, plus interest, and to remit to non-resident investors abroad profits or dividends, out of current and annual profits or dividends: Provided, That the repatriation of the remaining duly authorized and recognized foreign capital investment shall be subject to the existing Central Bank regulations at the time: And provided, further, That repatriations and remissions as herein provided may, at any time during the terms of the contract, be done under the provisions of this paragraph or under such regulations as may from time to time be promulgated by the Central Bank on the matter, at the election of the Operator: And provided, finally, That the total repatriation of foreign investments herein authorized plus the total remission of profits or dividends for any year shall not exceed fifty per centum of the total gross receipts for that particular year;\n\"(4) Within one year from the first date of commercial production, the Operator shall select a final area or areas in compact block or blocks, irrespective of water separation of portions to be retained by him sufficient to meet his reasonable needs as to ore reserves, plant sites, timber and water resources to ensure commercial operation, but in no case to exceed a total land area of twenty-five thousand hectares;\n\"(5) The Operator shall give preference to Philippine citizens in all types of employment within the country insofar as such citizens are qualified to perform the corresponding work with reasonable efficiency and without hazard to the safety of the operations; and shall maintain effective programs of training and advancement commensurate with the demonstrated abilities of such citizens to perform satisfactorily the various types of work involved in the operation. The Operator, however, shall not be hindered from using officials of its own selection for executive or technical work and for all other work which, in its judgment, and with the approval of the Board, requires highly specialized training and/or long experience;\n\"(6) The Operator and/or its personnel shall be subject to the jurisdiction of the Philippine Courts;\n\"(7) If and when the Government shall decide to have the renounced area operated by an independent contractor, the preferential right of the operator of the parcel already being operated to operate the same shall be recognized under such terms and conditions as may be fixed by the Government at the time: Provided, That said Operator shall be qualified and shall have been diligent in the prosecution of its operation and in the compliance with its obligations.\n\"In case said operator shall fail to qualify or to exercise its preferential right, then said renounced area shall be open to operation in the manner provided by existing law at the time.\"\n\"(8) If and when the Government shall decide to have the other parcel or parcels of the Surigao Mineral Reservation operated by independent contractor or contractors in accordance with section two numbered (3) hereof, the preferential right of the Operator of the parcel already being operated to operate the same shall be recognized under such terms and conditions as may be fixed by the Government at that time: Provided, That said Operator shall be qualified and shall have been diligent in the prosecution of its operation and in the compliance with its obligations.\n\"In case said operator shall fail to qualify or to exercise its preferential right, then said parcel or parcels shall be open to operation in the manner provided by existing law at the time.\""}},{"id":"PH-H1816-A5","no":5,"noLabel":{"en":"Section 5."},"text":{"en":"The whole provision of section eight of the Act is hereby deleted and in lieu thereof the following new provision is inserted:\n\"Sec. 8. For the purpose of carrying out the provisions of this Act, the amount equivalent to three per centum of whatever the Government shall receive from the operation of the Surigao Mineral Reservation is hereby set aside to cover the expenses, including salaries, wages, and per diems of the members of the Board and its staff and personnel.\""}},{"id":"PH-H1816-A6","no":6,"noLabel":{"en":"Section 6."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 13, 1958"}}],"pack":"ph-p25","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act to Amend Sections Two, Three, Five, Six and Eight of Republic Act Numbered One Thousand Eight Hundred Twenty-Eight","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H1817"] = {"id":"PH-H1817","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1958/ra_2078_1958.html","fetchedAt":"2026-10-06","articleCount":2,"structureMode":"ARTICLE","title":{"zh":"经费拨款法","en":"An Act Appropriating the Amount of Two Million Four Hundred Forty-Eight Thousand Three Hundred Forty-Four Pesos as Additional Funds for the Operation of the Bureau of Prisons During the Period from July First, Nineteen Hundred and Fifty-Eight to June Thirtieth, Nineteen Hundred and Fifty-Nine","orig":"An Act Appropriating the Amount of Two Million Four Hundred Forty-Eight Thousand Three Hundred Forty-Four Pesos as Additional Funds for the Operation of the Bureau of Prisons During the Period from July First, Nineteen Hundred and Fifty-Eight to June Thirtieth, Nineteen Hundred and Fifty-Nine"},"level":"law","status":"active","topics":["general"],"docNumber":"Republic Act No. 2078","issuingBody":"Congress of the Philippines","promulgatedDate":"1958-06-13","completenessNote":"全文，共 2 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1958/ra_2078_1958.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H1817-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"The following sums are hereby appropriated out of any funds in the National Treasury not otherwise appropriated as additional appropriation for the operation of the Bureau of Prisons during the period from July 1, 1958 to June 30, 1959:\nGENERAL FUND\nI. - PERSONAL SERVICES 1 One hundred fifty guards at ₱1,716 ₱257.400.00 2 Two medical officers at ₱4,632 9,264.00 3 Three penal psychiatrists at ₱4,632 13,896.00 4 Five guidance-counselors at ₱3,108 15,540.00 5 One radiologist :\n4,632.00 6 Six nurses at ₱2.304 13,824.00 7 Five penal institutions teachers at ₱2,196 10,980.00 8 Seven clerks I at ₱1,800 12,600.00 9 Six nursing attendants at ₱1,548 9,288.00 Total for personal services ₱347,424.00 =========== II.- MAINTENANCE AND OTHER OPERATING EXPENSES 1 Supplies and materials ₱2,000,920.00 2 Sundry expenses 68,000.00 Total for maintenance and other operating expenses ₱2,068,920.00 =========== III.- FURNITURE AND EQUIPMENT 1 Equipment outlay ₱32.000.00 Total for furniture and equipment ₱32,000.00 ========= IV.- SUMMARY Total for personal services ₱347,424.00 Total for maintenance and other operating expenses 2,068,920.00 Total for furniture and equipment 32,000.00 Total additional appropriation for current operating expenditures for the Bureau of Prisons ₱2,448,344.00 ==========="}},{"id":"PH-H1817-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"This Act shall take effect upon its approval.\nApproved, June 13, 1958."}}],"pack":"ph-p25"};
  FT["PH-H1818"] = {"id":"PH-H1818","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1958/ra_2079_1958.html","fetchedAt":"2026-10-06","articleCount":2,"structureMode":"ARTICLE","title":{"zh":"经费拨款法","en":"An Act Appropriating the Sum of Three Million Pesos to Cover Deficiencies in the Appropriation of the Bureau of Hospitals for the Operation and Maintenance of General Hospitals Under It","orig":"An Act Appropriating the Sum of Three Million Pesos to Cover Deficiencies in the Appropriation of the Bureau of Hospitals for the Operation and Maintenance of General Hospitals Under It"},"level":"law","status":"active","topics":["health"],"docNumber":"Republic Act No. 2079","issuingBody":"Congress of the Philippines","promulgatedDate":"1958-06-13","completenessNote":"全文，共 2 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1958/ra_2079_1958.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H1818-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"The sum of three million pesos is hereby appropriated, out of any funds in the National Treasury not otherwise appropriated, to cover deficiencies in the appropriation of the Bureau of Hospitals for the operation and maintenance of general hospitals under said Bureau."}},{"id":"PH-H1818-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 13, 1958."}}],"pack":"ph-p25"};
  FT["PH-H1819"] = {"id":"PH-H1819","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1958/ra_2080_1958.html","fetchedAt":"2026-10-06","articleCount":35,"structureMode":"ARTICLE","title":{"zh":"政府运营经费拨款法","en":"An Act Appropriating Funds for the Operation of the Government of the Republic of the Philippines During the Period from July First, Nineteen Hundred and Fifty-Eight to June Thirtieth, Nineteen Hundred and Fifty-Nine, and for Other Purposes","orig":"An Act Appropriating Funds for the Operation of the Government of the Republic of the Philippines During the Period from July First, Nineteen Hundred and Fifty-Eight to June Thirtieth, Nineteen Hundred and Fifty-Nine, and for Other Purposes"},"level":"law","status":"active","topics":["general"],"docNumber":"Republic Act No. 2080","issuingBody":"Congress of the Philippines","promulgatedDate":"1958-06-14","completenessNote":"全文，共 35 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1958/ra_2080_1958.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H1819-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"Appropriation of funds. —The following sums, or so much thereof as may be necessary, are appropriated out of any funds in the Philippine Treasury not otherwise appropriated for the operation of the Government of the Republic of the Philippines during the period from July first, nineteen hundred and fifty-eight to June thirtieth, nineteen hundred and fifty-nine, except where otherwise specifically provided:\n[Itemized portion omitted] GENERAL PROVISIONS"}},{"id":"PH-H1819-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"Authority to pay salaries not in conformity with the prescribed grades or rates of compensation. —Payment to incumbent employees of salaries the rates of which are not in conformity with the schedule of grades or rates of compensation provided in section three of Commonwealth Act Numbered Four hundred and two, as amended, is hereby authorized; PROVIDED, That new appointments, whether original or promotion, to positions not carrying the salary rates prescribed in Commonwealth Act Numbered Four hundred and two, as amended, shall be made only at the rates authorized in the said Act."}},{"id":"PH-H1819-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"Personnel in the classified Civil Service not to be effected by the adoption of the Performance Budget. —The adoption of the budgetary system based on functions, activities and projects in terms of expected results shall neither result in any manner in the laying off of personnel in the classified Civil Service except for cause as provided by law nor in the reduction of actual salaries of incumbents or demotion in rank or change of status."}},{"id":"PH-H1819-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"Authority to use savings in appropriations to cover deficits. —Except as otherwise provided in this Act, any savings in the regular appropriations authorized in this Act for any Executive Department for \"personal services,\" for \"maintenance and other operating expenses,” and for \"furniture and equipment\" of the bureaus and offices under the same Department may, with the approval of the President, be used to cover a deficit in any other item of the regular appropriations except for personal services, under the same Department: PROVIDED, That whenever authorized positions are transferred from one program to another within the same Department the corresponding amounts appropriated for personal services are also deemed transferred, without increasing the total outlay for personal services of the Department concerned. In no case, however, shall any item of appropriations be augmented, pursuant to the authority granted in this section, by more than thirty per centum of the original appropriation provided in this Act for such item."}},{"id":"PH-H1819-A5","no":5,"noLabel":{"en":"Section 5."},"text":{"en":"Quarterly report to Congress on transfers of appropriations and accomplishments of bureaus and offices. —The Auditor General and the Commissioner of the Budget shall submit separately to the Congress a quarterly report of any transfer of appropriation made to cover a deficit, the report to specify the items and the amounts involved and shall furnish copies to each member of Congress in his office. The heads of bureaus or offices whose appropriations are based on the Performance Budget shall likewise submit separately to each member of the Congress a quarterly report of their accomplishments."}},{"id":"PH-H1819-A6","no":6,"noLabel":{"en":"Section 6."},"text":{"en":"Authority to use savings for other purposes. — The President of the Philippines is authorized to use any savings in the appropriations provided in this Act for the Executive Departments for the settlement of the following obligations incurred during the current fiscal year and/or previous fiscal years, the limitation in section 7-1(27) of Commonwealth Act Numbered Two hundred forty-six, as amended, notwithstanding: (1) claims under section 699 of the Revised Administrative Code and the Workmen's Compensation Act, whichever is applicable, of officers, employees and laborers who died or were injured in line of duty; (2) commutation of the money value of the additional leave, extended leave and accrued leave earned by American and deceased Filipino officers and employees, or by Filipino officers and employees separated from the service except for cause, for service rendered prior to November twenty-ninth, nineteen hundred and thirty-six (3) purchase of furniture and equipment to replace those that may be lost through accident, fire or other calamity, or may have been damaged through tne same cause, the disposal of which is deemed reasonable and necessary, if it would be more expensive to have them repaired, and purchase, with the approval of the President, of furniture and equipment to replace unserviceable ones condemned by the Auditor General; (4) payment of salaries of suspended employees who have subsequently been exonerated; (5) payment of the share of the National Government in the salaries of national officials in newly created cities and provinces where no appropriation has been provided therefor; (6) three per cent contribution of the Government to the Government Service Insurance System for the employees' insurance premiums corresponding to the period from December thirty-first, nineteen hundred and forty-one to February twenty-eight, nineteen hundred and forty-five, pursuant to section four of Republic Act Numbered One hundred thirty-two, the provisions of section 7(c) of Commonwealth Act Numbered One hundred eighty-six, as amended, to the contrary notwithstanding: (7) commutation of vacation and sick leave of employees who may be retired under existing laws; (8) additional compensation to government nurses assigned to public health nursing at P50 a month in lieu of quarters, subsistence and laundry allowances as provided under section three of Republic Act Numbered Six hundred forty-nine; (9) purchase or rental of accounting machines to carry out the plan of mechanizing the accounting system, of the Government; (10) obligation of the National Government under the provisions of subsection (a) of section 2553 of the Revised Administrative Code; (11) cash commutation of the accumulated vacation and sick leave of employees who voluntarily resign or are separated from the service thru no fault of their own, in accordance with the provisions of Republic Act Numbered Six hundred eleven, as amended by Republic Act Numbered One thousand eighty-one; (12) printing of briefs in cases appealed by the Government; (13) improvement of food rations in government hospitals and leprosaria; (14) rural improvement; (15) payment of premiums for the insurance of government properties; (16) payment of gratuities of employees who are laid off as a result of the elimination of their positions in this Act and the government reorganization under Republic Act No. 997, as amended, at a rate equivalent to one monthly salary for every year of continuous satisfactory service rendered but not exceeding twelve months, on the basis of the last salary received: PROVIDED, That if said employees are entitled to gratuity or pension under any retirement law, they shall select either such gratuity or pension or the gratuity herein provided; (17) unpaid claims for commutation of maternity leave of absence due women employees under the provisions of Republic Act No. 1564; (18) opening of additional primary classes; (19) adjustment of salaries of national officials and employees resulting from the reclassification of provinces and municipalities; (20) payment of duly registered and recognized pre-war obligations of the different offices of the government in favor of private individuals and/or entities; and (21) adjustment of salaries of employees resulting from reorganization pursuant to Republic Act No. 1890."}},{"id":"PH-H1819-A7","no":7,"noLabel":{"en":"Section 7."},"text":{"en":"Suspension of expenditures of appropriations. —Except as otherwise provided in this Act and whenever in his judgment the public interest so requires, the President is authorized to suspend or otherwise stop the expenditure of any amount herein appropriated in any item or items for the Executive Departments for any purpose, except amounts for salaries of positions with incumbents, and thereupon the funds affected by such action shall become available for any other expenditures authorized in this Act for the Executive Departments as the President may determine, except for personal services; PROVIDED, That whenever authorized positions are transferred from one program to another, the corresponding amounts appropriated for personal services are also deemed transferred, without increasing the total outlay for personal services of the office concerned. In no case, however, shall any item of appropriation be augmented, Pursuant to the authority granted in this section, by more than thirty per centum of the original appropriation provided in this Act for such item. The Auditor General the Commissioner of the Budget shall report separately to the Congress within a period of thirty days any suspension or transfer of funds made by the President during the previous quarter and shall furnish copies to each member of Congress in his office."}},{"id":"PH-H1819-A8","no":8,"noLabel":{"en":"Section 8."},"text":{"en":"Failure on the part of the Auditor General and the Commissioner of the Budget to make report. —Failure on the part of the Auditor General and the Commissioner of the Budget to make the report herein required within the period specified therein shall automatically cause the suspension of the payment of their salaries until they shall have complied therewith."}},{"id":"PH-H1819-A9","no":9,"noLabel":{"en":"Section 9."},"text":{"en":"Provision for \"excess of actual salary.\" —Appropriations provided in this Act may be used for payment of excess of actual salaries to the incumbent of a position to which said \"excess\" pertains who is actually receiving the same \"excess\" as part of the salary granted to him upon his appointment to the said position before the reduction of the basic pay thereof to the amount provided : PROVIDED, HOWEVER, That if the position be vacated and the successor to its previous incumbent shall have previously received an equal salary plus the \"excess of actual salary\" in the same or any other branch of the government service, such excess shall be allowable to him."}},{"id":"PH-H1819-A10","no":10,"noLabel":{"en":"Section 10."},"text":{"en":"Purchase of locally manufactured furniture, equipment, parts, accessories, supplies, and materials. —All appropriations for the purchase of furniture, equipment, supplies and materials authorized in this Act shall be available only for locally manufactured furniture, equipment, parts, accessories, supplies and materials except when none is available in the market, or when the prices of the locally manufactured article exceed those determined by the Flag Law by ten per cent."}},{"id":"PH-H1819-A11","no":11,"noLabel":{"en":"Section 11."},"text":{"en":"Renting of automobiles, jitneys or trucks for a continuous period exceeding fifteen days prohibited. —No appropriation provided in this Act for the Executive Departments shall be used for renting automobiles, jitneys or trucks on the monthly basis nor on the daily basis for a continuous period exceeding fifteen days."}},{"id":"PH-H1819-A12","no":12,"noLabel":{"en":"Section 12."},"text":{"en":"Authority to purchase motor vehicles. —No appropriation authorized in this Act shall be used for the purchase of automobiles, jitneys, jeeps, station wagons, motorcycles and other motor vehicles unless otherwise specifically provided in this Act."}},{"id":"PH-H1819-A13","no":13,"noLabel":{"en":"Section 13."},"text":{"en":"Officials entitled to government motor transportation. —The following officials are entitled to use government motor transportation chargeable against the appropriations authorized in this Act:\n1. The President of the Philippines,\n2. The Vice-President of the Philippines,\n3. The President of the Senate,\n4. The Speaker of the House of Representatives,\n5. The President Pro-Tempore of the Senate,\n6. The Majority Floor Leader of the Senate,\n7. The Chairman, Committee on Finance of the Senate,\n8. The Chairman, Committee on Accounts of the Senate,\n9. The Chairman, Committee on Foreign Relations of the Senate,\n10. The Chairman, Committee on Public Works of the Senate,\n11. The Minority Floor Leader of the Senate,\n12. The Secretary of the Senate,\n13. The Speaker Pro-Tempore of the House of Representatives,\n14. The Majority Floor Leader and the Assistant Majority Floor Leader of the House of Representatives,\n15. The Chairman, Committee on Appropriations of the House of Representatives,\n16. The Chairman, Committee on Accounts of the House of Representatives\n17. The Chairman, Committee on Ways and Means of the House of Representatives,\n18. The Chairman, Committee on Foreign Affairs of the House of Representatives,\n19. The Chairman, Committee on Public Works of the House of Representatives,\n20. The Minority Floor Leader of the House of Representatives,\n21. The Secretary of the House of Representatives,\n22. The Chief Justice of the Supreme Court,\n23. The Presiding Justice of the Court of Appeals,\n24. The Auditor General,\n25. The Ambassadors, Ministers Plenipotentiary and Consuls in charge of consulates while in their respective stations abroad, and\n26. The Chief of Staff and the Vice-Chief of Staff and the Commanding Officers of the other Major Services of the Armed Forces of the Philippines."}},{"id":"PH-H1819-A14","no":14,"noLabel":{"en":"Section 14."},"text":{"en":"Officials entitled to transportation allowance. —The Department Heads, including the Administrator of Economic Coordination, the Commissioner of the Budget, the Press Secretary, the Chairman of the Presidential Complaints and Action Committee, the Technical Assistant on Local Governments and Civil Affairs, the Chairman, National Economic Council, the Chairman of the Commission on Elections, the Social Welfare Administrator, and the Chairman of the House Electoral Tribunal, are hereby granted a commutable transportation allowance of two hundred fifty pesos each per month; the Undersecretaries of Departments and officials with the same rank, the Executive Judge of the Court of Agrarian Relations, the Legislative Secretary, the Legislative Liaison Officer, the Presiding Judge of the Court of Industrial Relations, the Presiding Judge of the Court of Tax Appeals, the Commissioner, Land Registration Commission, the Public Service Commissioner, the Presiding Judge of the Juvenile and Domestic Relations Court, the Chairman of Land Tenure Administration, the Judicial Superintendent and the Chief Prosecuting Attorney, Office of the Secretary of Justice, the Commissioner of Immigration, the Administrator of Social Security System, the Director of Labor Standards, as ex-officio Chairman of the Labor Standards Commission, the Director of Workmen's Compensation, as ex-officio Chairman of the Workmen's Compensation Commission, the Tariff Commissioner, the Agricultural Tenancy Commissioner, the Director of Classification and Compensation, the Chief, Budget Operations Service, and the Chief, Motor Vehicles Office, two hundred pesos each per month; and the following officials, directors or chiefs of bureaus and offices, and the Sergeant-at-Arms of the House of Representatives, one hundred pesos each per month, chargeable against the appropriations authorized in this Act for their respective offices:\n1. The Director of Printing,\n2. The Director, National Media Production Center,\n3. The Assistant Tariff Commissioner,\n4. The Commissioner of Civil Service,\n5. The Civil Defense Administrator,\n6. The Manager, UNICEF child Feeding Program,\n7. The Commissioner of Customs,\n8. The Commissioner of Internal Revenue,\n9. The Treasurer of the Philippines,\n10. The Purchasing Agent, Bureau of Supply,\n11. The Insurance Commissioner,\n12. The two Associate Commissioners, Public Service Commission,\n13. The Members, Land Tenure Administration,\n14. The two Associate Judges, Court of Tax Appeals,\n15. The four Associate Judges of the Court of Industrial Relations,\n16. The Director, National Bureau of Investigation,\n17. The Director of Prisons,\n18. The Chairman, Code Commission,\n19. The Director of Plant Industry,\n20. The Director of Animal Industry,\n21. The Director of Forestry,\n22. The Director of Lands,\n23. The Director of Mines,\n24. The Director of Fisheries,\n25. The Director of Soils,\n26. The Director of Agricultural Extension,\n27. The Director of Parks and Wildlife,\n28. The Manager, Fiber Inspection Service,\n29. The Director of Public Works,\n30. The Postmaster General,\n31. The Director of Telecommunications,\n32. The Commissioner of Public Highways,\n33. The Director of Public Schools,\n34. The Director of Public Libraries,\n35. The Director, Institute of National Language,\n36. The Director of National Museum,\n37. The Director of Private Schools,\n38. The Director of Labor Relations,\n39. The two Associate Commissioners, Workmen's Compensation Commission,\n40. The two Associate Commissioners, Labor Standards Commission,\n41. The Assistant to the Secretary and Administrative Officer, Department of Labor,\n42. The Director of Field Operations, Department of Labor,\n43. The Director of Coast and Geodetic Survey,\n44. The Chairman, Philippine Veterans Board,\n45. The Chairman, Board on Pensions for Veterans,\n46. The Director, Veterans Memorial Hospital,\n47. The Director of Quarantine,\n48. The Director of Hospitals,\n49. The Director of Health,\n50. The Director of Public Health Research Laboratories,\n51. The Director of Nutrition,\n52. The Director of Commerce,\n53. The Administrator, Sugar Quota Administration,\n54. The Director, Philippines Patent Office,\n55. The Commissioner, Securities and Exchange Commission,\n56. The Administrator, Civil Aeronautics Administration,\n57. The Director, Weather Bureau,\n58. The Director of the Census and Statistics,\n59. The Administrator, Cooperatives Administration Office,\n60. The administrator, No-dollar Import Office,\n61. The Director, Institute of Science and Technology,\n62. The Director, Philippine General Hospital,\n63. The Ministers who are assigned in the Home Office and the Counselors who are assigned as heads of offices in the Department of Foreign Affairs,\n64. The Chief, Irrigation Service Unit,\n65. The Clerk of Court of the House Electoral Tribunal,\n66. The Director of Forest Products Research Institute,\n67. The Finance and Kate Regulation Officer, the Chief Hearing Officer, the Chief Utilities Regulation Engineer, and the Transportation Regulation Chief of the Public Service Commission, and\n68. The Chief, Management Service, Budget Commission."}},{"id":"PH-H1819-A15","no":15,"noLabel":{"en":"Section 15."},"text":{"en":"Bureaus and offices entitled to use, operate and maintain government motor vehicles and launches.—No bureau or office shall use, operate or maintain from the appropriations authorized in this Act government service cars, jeeps, station wagons, vans, service trucks, pickup trucks, launches, speedboats, motorcycles, etc., except the following:\n1. The House of Representatives, for general service purposes;\n2. The Senate, for general service purposes;\n3. Malacañang, for general service purposes;\n4. The National Intelligence Coordinating Agency, in the coordination of the national intelligence activities and in carrying out its functions in the interest of national security;\n5. The Civil Defense Administration, for general service purposes in connection with the establishment and administration of the national civil defense program;\n6. The Philippine Broadcasting Service for covering special events for delayed broadcasts, servicing of sponsored programs, contacting artists, fetching ''sign on\" personnel and conducting home those, \"signing off\";\n7. The National Media Production Center, for delivery of different media of mass communications, such as press releases, handbills, pamphlets, posters, motion pictures, film-strips, etc., and for motion picture and photoessay coverage of different projects of the government;\n8. The UNICEF Programmes of the Philippines, for use in connection with the supervision and inspection of feeding agencies in the cities and rural areas;\n9. The Social Welfare Administration, for ministering relief, during military actions against dissidents, to evacuees, the injured and incapacitated and to the victims of typhoons, earthquakes, fires, floods, tidal waves and volcanic eruptions; and for conducting the inmates of Welfareville to and from the Courts, hospitals and other offices, procuring materials and food supplies for their subsistence, and delivering food to the various units within the Welfareville compound, including collection and disposal of garbage;\n10. The Budget Commission, for gathering from the various government offices and instrumentalities of such data and information as are essentially material or pertinent to the exercise of authority over budget operations and control, for the performance of duties connected with the preparation of the National Budget, and for wage and position classification survey;\n11. The Department of Foreign Affairs, for carrying out protocol duties, including those connected with the arrival or visit in the Philippines of high dignitaries and officials or accredited representatives of foreign governments, and for general service purposes particularly in relation to the delivery of diplomatic pouches to and from points of embarkation or shipment;\n12. The Bureau of Customs, for use as the Collector of Customs may recommend and the Commissioner of Customs may approve;\n13. The Bureau of Internal Revenue, including its Regional Offices, for strict enforcement of the internal revenue laws and regulations and detection of violations thereof;\n14. The Bureau of the Treasury, for transportation of cash from the Central Bank of the Philippines to the Bureau of the Treasury, and vice versa;\n15. The Office of the Insurance Commissioner, for examination of the financial condition and methods of doing business of insurance companies and for the inspection of buildings in the different blocks of Manila and its neighboring cities and municipalities and other risks in connection with the supervision of said office over the fixing of premium rates on non-life insurance;\n16. The National Bureau of Investigation, for detection and investigation of crimes and criminals and other law violations;\n17. The Bureau of Immigration, for the enforcement of immigration laws;\n18. The Court of Tax Appeals, for transportation of its personnel whenever the Court hold its hearing outside of the City of Manila pursuant to Section 6 of Republic Act No. 1125;\n19. The Land Tenure Administration and the Court of Agrarian Relations, for transportation of their personnel whenever they go out to hear cases or take evidence in places other than their headquarters, or make settlement pursuant to the decisions of the court;\n20. The Bureau of Prisons, for conducting prisoners to and from the Bureau of Prisons, inspection of prison institutions and stations, procuring food supplies and materials, and delivering products and/or manufactures of the Prison Industries in Muntinlupa and in the penal colonies;\n21. The Juvenile and Domestic Relations Court, for conducting to and from the court, dependent or neglected children or juvenile delinquents committed to the care of persons or institutions and for inspection and supervision thereof;\n22. The Office of the Secretary of Agriculture and Natural Resources, for gathering agricultural statistics for researches and analysis in agriculture, for distribution of agricultural information materials for guidance of farmers in improving their farming methods, and for conducting inspection trips to coordinate agricultural programs;\n23. The Agricultural Tenancy Commission, for the administration and implementation of Republic Act No. 1199, particularly mediation and legal aid activities, distribution of information materials, conducting rallies, researches, and farm management investigations in the different regions of the country;\n24. The Bureau of Plant Industry, for the control of abaca mosaic and other plant pests and diseases, and for supervision of agricultural experiment stations and seed farms;\n25. The Bureau of Animal Industry, for the distribution of animal products and transportation of animals and feeds, including insemination work;\n26. The Bureau of Forestry, for forest protection reforestation, land classification, research and general administration, including transportation of cinchona barks, equipment, and supplies and materials;\n27. The Bureau of Lands, for the survey and subdivision of public agricultural lands and land management;\n28. The Bureau of Mines, for the transportation of mineral samples to and from the office for the geological, mineralogical and mineral land survey parties operating in the different parts of the Philippines;\n29. The Bureau of Fisheries, for the collection of marine specimens, inspection of experimental fish farms and distribution of seedlings;\n30. The Bureau of Soils, for carrying out soil survey and conservation work in the different regions of the country;\n31. The Bureau of Agricultural Extension, for carrying out its extension work and diffusing among the people, particularly those in rural areas, useful and practical information on agriculture, soil conservation, livestock, fisheries, forest conservation, public lands and natural resources laws, home economics and rural life by means of field demonstrations, lectures, conferences, publications and other means of disseminating information;\n32. The Parks and Wildlife Office, for the supervision of parks and recreational centers, and enforcement of regulations to conserve wildlife, game, fish, etc.\n33. The Fiber Inspection Service for carrying out its work of inspection and supervision of fiber grading-baling establishments, fiber improvement and demonstration work;\n34. The Department of Public Works and Communications, for gathering from its bureaus, offices and agencies, including those of other government offices and instrumentalities, of such data and information as are essentially material or pertinent to the formulation of long-range public works programs and in evaluation and checking of accomplishments and expenditures against duly approved programs of work;\n35. The Bureau of Public Works, for undertaking the construction of public works projects, inspection and supervision thereof, and for the procurement of construction supplies and materials;\n36. The Bureau of Public Highways, for carrying out its functions of construction and maintenance of roads and bridges and those activities connected therewith, inspection and supervision of highway and bridge construction and maintenance projects, and for the procurement of construction supplies and materials;\n37. The Bureau of Posts, for the operation of the postal service;\n38. The Bureau of Telecommunications, for the construction, repair, transfer and maintenance of telegraph, telephone and radio stations and circuits and the delivery of telegrams and radiograms;\n39. The Motor Vehicles Office, for the enforcement of the provision of the Motor Vehicle Law and for general service purposes;\n40. The Office of the Secretary of Education, for the inspection of public and private schools, public libraries, investigation of cases which require immediate attention, and performance of its supervisory functions;\n41. Trade and industrial, agricultural, rural and farm schools and other vocational schools, for instructional purposes requiring the use, demonstration and/or operation of motor or other powered vehicles and for transporting and marketing their finished products for public consumption;\n42. The Bureau of Private Schools, for the inspection of private schools that are out-of-the-way places, and for undertaking rush investigation of complaints from various sources;\n43. The Department of Labor, for the use of field personnel in the enforcement of labor laws throughout the Philippines and for the use of its headquarters entities in making field inspections, special investigations and economic surveys necessary for the administration of labor laws;\n44. The Bureau of Coast and Geodetic Survey, for carrying out field reconnaissance, triangulations, precise leveling and magnetic and gravity measurements, ship servicing, canvass, procurement and delivery of supplies, and delivery or receipt of official publications, documents and shipments;\n45. The Armed Forces of the Philippines, when on military operations or on active duty in the restoration and maintenance of peace and order;\n46. The Department of Health, for the use of the Division of Tuberculosis in BCG Vaccination and Traveling X-ray Examination Units, the Division of Health Education and Information in exhibiting health films and dissemination of health information in rural areas, the Public Health Research Laboratories in connection with health research including the distribution of vaccines, sera and other biological preparations;\n47. The Bureau of Hospitals and government hospitals, for ambulance service and procuring food supplies and materials for the subsistence of patients and personnel entitled thereto;\n48. The Bureau of Health, for health, sanitation and prevention and control of epidemics;\n49. The Bureau of Quarantine, whenever used by quarantine officers exclusively for quarantine work;\n50. The Office of the Secretary of Commerce and Industry, for the promotion of retail trade;\n51. The Civil Aeronautics Administration, for the operation and maintenance of its landing fields including supervision and reconstruction or repair of signaling equipment located thereat;\n52. The Weather Bureau, for the maintenance, operation and inspection of its meteorological stations, including the Manila International Airport Forecasting Center and the Diliman Geophysical and Astronomical Station, and delivery of supplies thereto;\n53. The Office of Economic Coordination, for use in inspecting projects being undertaken by government corporations, including private industrial establishments applying for tax exemption under Republic Act Numbered Thirty-five, and in gathering and transmitting data and information necessary for the efficient supervision and coordination of the activities of the said corporations;\n54. The Institute of Science and Technology, for visit and inspection of factories, for the collection of forest, plant, animal and marine by-products and agricultural wastes for use in research and laboratory investigations, including survey of sources of raw materials in different regions;\n55. The General Auditing Office, for the inspection of the delivery of equipment and supplies and materials to the various bureaus and offices of the Government, as well as to sites of public works construction, and for surprise examinations of disbursing officers;\n56. The Commission on Volcanology, for inspecting and observing volcanoes and warning people in danger areas;\n57. The National Economic Council, including the Office of the Chairman, Office of National Planning, Office of Foreign Aid Coordination, and Office of Statistical Coordination and Standards, for use in the follow up and execution of certain phases of the national program of economic and social development and the gathering of data and information for studies and research work being undertaken for the formulation of economic policies, including tariff structure and international commercial relations; for use in inspecting projects being undertaken by the Government jointly with the International Cooperation Administration and in gathering and transmitting data necessary for the efficient supervision and coordination of the activities of projects; for use in conducting surveys of statistical services of the Government with a view to reviewing, appraising and allotting activities among the statistical agencies; and for use by the ranking officials of the National Economic Council in attending conferences, and for gathering and compiling of data for the preparation of the agenda of the Council meetings and the distribution of notices of meetings to the different council members;\n58. The Bureau of Printing, for the delivery and/or shipment of printed matters, books and/or forms to various offices;\n59. The Forest Products Research Institute, for the transportation of logs, timber, lumber and other forest products as materials for research as well as supplies, materials, machinery, equipment and personnel necessary for research."}},{"id":"PH-H1819-A16","no":16,"noLabel":{"en":"Section 16."},"text":{"en":"Authority to pay representation allowance out of savings. —Heads of Departments and other members of the Cabinet, the Auditor General and the Secretary of the House of Representatives are hereby granted representation allowance at the rate of not exceeding two hundred and fifty pesos per month commutable monthly; and the Undersecretaries of Departments and officials with the same rank including the Chairman, Land Tenure Administration and the Judicial Superintendent of the Department of Justice at the rate of not exceeding two hundred pesos per month also commutable monthly: PROVIDED, That the said allowance shall be paid out of the savings in the appropriations provided in this Act for the respective departments and offices of the officials concerned."}},{"id":"PH-H1819-A17","no":17,"noLabel":{"en":"Section 17."},"text":{"en":"Proper use of government motor vehicles. — The use of government motor vehicles by bureaus and offices for the purposes enumerated in section fifteen hereof shall be authorized only through the issuance for each trip of a serially numbered ticket, duly signed by the chief or the administrative officer of the bureau or office concerned. These motor vehicles shall be used strictly for official business, bear government plates only and after office hours kept in the garage provided therefor by the bureau or office to which they belong, except when in use for strictly official business outside office hours."}},{"id":"PH-H1819-A18","no":18,"noLabel":{"en":"Section 18."},"text":{"en":"Use of more than one motor vehicle prohibited. —With the exception of the President, no government official or employee authorized to use any vehicle operated and maintained from the funds appropriated in this Act shall be allowed to use more than one such motor vehicle: PROVIDED, HOWEVER, That the Vice-president and the Speaker of the House of Representatives may be allowed to use two motor vehicles each: PROVIDED, FURTHER , That no official who has been furnished motor transportation allowance by any government corporation or any other official shall be allowed to use motor vehicle transportation operated and maintained from funds appropriated in this Act. The Auditor General is hereby empowered to issue rules and regulations for the proper implementation and enforcement of the provisions of this section and sections 14, 15, and 17."}},{"id":"PH-H1819-A19","no":19,"noLabel":{"en":"Section 19."},"text":{"en":"Disposition of motor vehicles not used by a bureau or office. —All motor vehicles owned by or assigned to the different departments, bureaus, offices and branches of the National Government not needed by the officials and for the purposes enumerated in sections thirteen and fifteen of this Act shall be disposed of to the highest bidder at public auction sales announced in newspaper of general circulation at least ten days before the sale: PROVIDED, That the former user thereof shall be given preference if he offers and pays a price equal to that of the highest bid by others."}},{"id":"PH-H1819-A20","no":20,"noLabel":{"en":"Section 20."},"text":{"en":"Prohibition against the use of appropriation for the payment of salaries and wages of officers or employees engaged in a strike against the Government. —Subject to existing civil service rules and regulations and the proper administrative proceedings, no part of the funds of, or available for expenditures by, any agency included in this Act shall be used to pay the salary or. wages of any officer or employee who engages in a strike against the Government of the Republic of the Philippines or who is a member of an organization of government employees that asserts the right to strike against the Government of the Republic of the Philippines, or who advocates, or is a member of an organization that advocates, the overthrow of the Government of the Republic of the Philippines by force or violence: PROVIDED , That for the Purposes hereof an affidavit shall be considered sufficient evidence that the person making the affidavit has not, contrary to the provisions of this section, engaged in a strike against the Government of the Republic of the Phil-i, is not a member of any organization of government employees that asserts the right to strike against the Government of the Republic of the Philippines, or that such person does not advocate, and is not a member of an organization that advocates, the overthrow of the Government of the Republic of the Philippines by force or violence."}},{"id":"PH-H1819-A21","no":21,"noLabel":{"en":"Section 21."},"text":{"en":"Per diems outside of the Philippines. —No per diems in excess of fifty pesos shall be paid to any official or employee traveling outside of the Philippines."}},{"id":"PH-H1819-A22","no":22,"noLabel":{"en":"Section 22."},"text":{"en":"No transfer of salary savings to the Government Service Insurance System. —The provisions of Republic Act No. 660 to the contrary notwithstanding, no savings from personal services under the general fund and the special, revolving, trust, depository and other funds shall be transferred to the Government Service Insurance System."}},{"id":"PH-H1819-A23","no":23,"noLabel":{"en":"Section 23."},"text":{"en":"Reinsurance of government buildings to be equitably distributed among private insurance companies in the Philippines. —In all cases where appropriations are provided in this Act for payment of premiums covering the insurance of government buildings with the Property Insurance Fund, reinsurance shall be equitably distributed among private insurance companies doing business in the Philippines at least sixty per cent of the capital stock of which are owned by citizens of the Philippines on uniform terms, conditions and rates of premiums."}},{"id":"PH-H1819-A24","no":24,"noLabel":{"en":"Section 24."},"text":{"en":"Authority to harmonize the appropriation structure with new terminology of classification of accounts. —The Commissioner of the Budget is hereby authorized to harmonize the appropriation structure with the new terminology of classification of accounts that may be, prescribed by law or regulations: PROVIDED, That such reclassification shall not increase or decrease the aggregate sum appropriated in this Act for the various objects affected under each Department, bureau, or office: PROVIDED, FURTHER , That the Commissioner of Budget shall submit to the Congress before the beginning of each session a report of such action."}},{"id":"PH-H1819-A25","no":25,"noLabel":{"en":"Section 25."},"text":{"en":"The Committee on Finance of the Senate and the Committee on Appropriations of the House of Representatives authorized to look into all matters relating to public expenditures. —The Committee on Finance of the Senate and the Committee on Appropriations of the House of Representatives are hereby authorized to look at anytime into all matters relating to funds for the expenditures of the National Government and for the payment of public indebtedness; auditing of accounts and expenditures of the National Government including government-owned or controlled Corporations; claims against the Government; and in general all matters relating to public expenditures. The authority herein granted shall be without prejudice to the right of any member of the Congress to request the Committee on Finance of the Senate or the Committee on Appropriations of the House as the case may be to look at any time into the matters referred to in this section either as member of the aforementioned committees or as a member of the Congress."}},{"id":"PH-H1819-A26","no":26,"noLabel":{"en":"Section 26."},"text":{"en":"Expenditure and disbursement of special funds. —No expenditure shall be incurred, nor any disbursement made, out of the appropriations authorized in this Act from special, revolving and trust funds and from receipts automatically appropriated which will exceed at any one time either the fund itself or the cash in the National Treasury pertaining to such fund, except when, in the opinion of the President, such expenditure or disbursement is required by the exigency of the service, and sufficient income or receipts are expected to accrue to such funds to cover said expenditures or disbursement, in which case the necessary amount may be advanced from the general fund."}},{"id":"PH-H1819-A27","no":27,"noLabel":{"en":"Section 27."},"text":{"en":"Appropriations chargeable against the Philippine Charity Sweepstakes Fund. —The appropriations Provided in this Act for carrying out the activities heretofore financed from the receipts of the Philippine Charity Sweepstakes Fund shall continue to be charged against the said Fund, and the Board of Directors of the Philippine Charity Sweepstakes shall allot the amounts thereof in the distribution of the Philippine Charity Sweepstakes Fund."}},{"id":"PH-H1819-A28","no":28,"noLabel":{"en":"Section 28."},"text":{"en":"Immediate payment of accounts. —In order to insure the immediate collection of income due any bureau or office for services rendered or sale of any commodity or article produced or manufactured by the same, no such service shall be rendered or sale made except on the cash basis. Any official or employee who allows such service to be rendered or sale to be made on account shall be held personally liable therefor and such act shall be considered sufficient ground for his removal from office: PROVIDED, That the provisions of this section shall apply only to transactions of the Government with private parties: AND PROVIDED, FURTHER , That government-owned or controlled corporations, and officials and employees of the Government holding regular positions shall not be considered as private parties."}},{"id":"PH-H1819-A29","no":29,"noLabel":{"en":"Section 29."},"text":{"en":"Remittance of premiums for life and retirement insurance with the Government Service Insurance System. —The provisions of Republic Act Numbered Six hundred sixty, as amended to the contrary notwithstanding, the premiums for life and retirement insurance of the employees of the National Government and its instrumentalities shall be remitted monthly to the Government Service Insurance System as they are due and collected."}},{"id":"PH-H1819-A30","no":30,"noLabel":{"en":"Section 30."},"text":{"en":"Maximum Number of Permanent Positions in a Bureau or Office. —Except as otherwise provided by law the maximum number of permanent positions in a bureau or office shall not exceed the number of permanent positions included in the schedules for the said bureau or office in the budget document."}},{"id":"PH-H1819-A31","no":31,"noLabel":{"en":"Section 31."},"text":{"en":"Authority to change designations of positions and assignments of personnel. —The heads or chiefs of bureaus and offices are hereby authorized to change the designations of positions and to make changes in the assignments of personnel as the exigencies of the service may require: PROVIDED, HOWEVER, That such changes shall not affect the tenure of office of incumbents of positions, shall not constitute a demotion, either in rank or salary, nor result in a change of status, and shall in all cases be subject to the approval of the Commissioner of Civil Service."}},{"id":"PH-H1819-A32","no":32,"noLabel":{"en":"Section 32."},"text":{"en":"Adjustment of Appropriations for Reorganized Agencies and Salaries of Personnel Thereof. —The appropriations herein provided for agencies to be reorganized in accordance with the approved reorganization plans are deemed appropriated for the agencies as reorganized in case the Reorganization Implementation Reports are approved and promulgated by the President. The Commissioner of the Budget is hereby authorized to make necessary adjustments in the appropriations to carry out the foregoing provisions of this section. Furthermore, the department head concerned, with the approval of the Commissioner of the Budget, is hereby authorized to make necessary salary adjustments resulting from final selection of personnel to fill the positions in the staffing patterns of reorganized agencies in order that no incumbent receives a reduction in salary, to make necessary salary adjustments resulting from new appointments, promotions or salary increases made in the interim, and to make necessary salary adjustments resulting from changes in the staffing patterns authorized by the Commissioner of the Budget to correct mistakes, discriminations or injustices that may, in his opinion, have been committed in the preparation thereof.\nNo provision of this Act shall be construed as repealing or modifying in any way the approved reorganizations plans under Republic Act No. 997, as amended."}},{"id":"PH-H1819-A33","no":33,"noLabel":{"en":"Section 33."},"text":{"en":"Change of designation of any position by WAPCO classification. —The change of designation of any Position authorized in this Act due to the classification of such position in accordance with the WAPCO Plan shall not affect the tenure of office of the incumbent, shall not constitute a demotion either in rank or salary nor result in a change of status or assignment and the incumbent snail in all cases be deemed to have been appointed in that Position and class."}},{"id":"PH-H1819-A34","no":34,"noLabel":{"en":"Section 34."},"text":{"en":"Priority for permanent civilian employment to officers and men who may resign their commission or active tour of duty or enlistment from the Armed Forces of the Philippines. —The President of the Philippines shall give priority for permanent civilian employment to officers and men who may resign their commission or active tour of duty or enlistment from the Armed Forces of the Philippines, to positions commensurate to their qualifications and background, the provisions of the Civil Service Law to the contrary notwithstanding."}},{"id":"PH-H1819-A35","no":35,"noLabel":{"en":"Section 35."},"text":{"en":"Effective date. —This Act shall take effect on July first, nineteen hundred and fifty-eight, except where otherwise provided.\nApproved, June 14, 1958, except the following items and provisions:\nB.— OFFICE OF THE PRESIDENT\n(1) Executive Office\n(f) Philippine Broadcasting Service VI. Special Provisions Paragraph 2, page 71.\nD.— DEPARTMENT OF FOREIGN AFFAIRS\nVI. Special Provisions\nParagraph 11, page 281.\nE.— DEPARTMENT OF FINANCE\n(3) Bureau of Internal Revenue VI. Special Provisions Paragraph 7, page 320.\nF.— DEPARTMENT OF JUSTICE\n(5) Public Service Commission VI. Special Provisions Paragraph 1, all provisos, page 492.\n(6) Land Registration Commission\nI. Personal Services\nItems 4, 11 and 21, page 494; items 73, 78, 79, 80, 82 and 84, page 496; items 90, 93, 99, 109 and 111, page 497; item 139, page 498; items 157 and 160, page 499; items 199 and 207, page 500; items 237 and 238, page 501; items 312, 315 and 326, page 504; item 352, page 505; items 407, 410, 411, 419, 429, 434 and 436, page 507; items 446, 447, 448, 454, 455, 458 and 459, page 508; item 482, page 509; items 560, 562 and 563, page 512; item 590, page 513; and item 652, page 515."}}],"pack":"ph-p25"};
  FT["PH-H1820"] = {"id":"PH-H1820","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1958/ra_2081_1958.html","fetchedAt":"2026-10-06","articleCount":5,"structureMode":"ARTICLE","title":{"zh":"修订第85号共和国法及其他相关法律，将复兴金融公司改为菲律宾开发银行以提供中长期信贷，授权该行协助设立省市私人开发银行，并为其他目的","en":"An Act to Amend Republic Act Numbered Eighty-Five and Other Pertinent Laws, to Provide Facilities for Intermediate and Long-Term Credit by Converting the Rehabilitation Finance Corporation into the Development Bank of the Philippines, Authorizing the Said Bank to Aid in the Establishment of Provincial and City Private Development Banks, and for Other Purposes","orig":"An Act to Amend Republic Act Numbered Eighty-Five and Other Pertinent Laws, to Provide Facilities for Intermediate and Long-Term Credit by Converting the Rehabilitation Finance Corporation into the Development Bank of the Philippines, Authorizing the Said Bank to Aid in the Establishment of Provincial and City Private Development Banks, and for Other Purposes"},"level":"law","status":"active","topics":["company","tax"],"docNumber":"Republic Act No. 2081","issuingBody":"Congress of the Philippines","promulgatedDate":"1958-06-14","completenessNote":"全文，共 5 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1958/ra_2081_1958.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H1820-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"Sections one, two and three of Republic Act Numbered Eighty-five are amended to read as follows:\n\"Sec. 1. Purposes, Name and Domicile. To provide credit facilities for the rehabilitation and development and expansion of agriculture and industry, the reconstruction of property damaged by war and the broadening and diversification of the national economy, and to promote the establishment of private development banks in provinces and cities, there is hereby created a body corporate to be known as the development bank of the Philippines, hereinafter called the Bank, which shall have its principal place of business in the City of Manila and shall exist for a period of fifty years.\n\"Sec. 2. Corporate powers. The Development Bank of the Philippines shall have the power:\n\"(a) To grant loans for home building or home financing projects and for the rehabilitation, the establishment or development of any agricultural and/or industrial enterprise, including public utilities, mining, livestock industry and fishing, whether offshore or inland;\n\"(b) To purchase preferred redeemable shares of stock, securities other than shares of stock, and obligations of, and to grant loans to, any agricultural and industrial enterprises mentioned in paragraph (a), to finance their fixed and operating capital requirements. All purchases of preferred redeemable shares, securities and obligations and all loans shall be of such sound value or so secured, as reasonably to assure retirement of such shares, securities or obligations or repayment of the loan; and shall be granted only under such terms, conditions and restrictions as the said board shall determine: Provided, That no loan shall have a maturity period longer than ten years except that any loan granted for the purpose of constructing industrial facilities may have a maturity of ten years plus such additional period as may be necessary not only to complete such construction, but also to repay the loans in accordance with the released regulations to be determined by the board;\n\"(c) To grant loans to provincial, city and municipal governments for the rehabilitation, construction or reconstruction of public markets, waterworks, toll bridges, slaughterhouses, for cadastral surveys and other self-liquidating or income-producing services, including the purchase and acquisition of municipal electric power plants and to agencies and corporations owned or controlled by the Government of the Republic of the Philippines for the production and distribution of electrical power, for the purchase and subdivision of rural and urban estates, for housing projects, for irrigation and waterworks systems, and for other essential industrial and agricultural enterprises;\n\"(d) To grant loans to cooperative associations to facilitate production, the marketing of crops, and the acquisition of essential commodities;\n\"(e) To grant loans to employees in a Government-owned or controlled corporation or private corporation engaged in the development and/or expansion of agriculture or industry, for the purpose of buying shares of stock in such corporations: Provided, That the yearly amortization of such loans shall not exceed ten per cent of the total annual salaries and wages of the employees: Provided, further, That such loans shall be payable in full within a period of not exceeding ten years;\n\"(f) To underwrite, purchase, own, sell, mortgage or otherwise dispose of stocks, bonds, debentures, securities and other evidences of indebtedness issued for or in connection with any project or enterprise referred to in the preceding paragraphs;\n\"(g) To issue bonds, debentures, securities, collaterals, and other obligations upon recommendation of the Secretary of Finance and with the approval of the President, but in no case to exceed at any one time an aggregate amount equivalent to one hundred per centum of its subscribed capital and surplus. These bonds and other obligations shall be redeemable at the option of the Bank at or before maturity and in such manner as may be stipulated therein and shall bear such rate of interest as may be fixed by the Bank. Such obligations shall be secured by the assets of the bank including the stocks, bonds, debentures and other securities underwritten, purchased or held by it under the provisions of this Act. The bank shall provide for appropriate reserves for the redemption or retirement of said obligations. Such obligations may be issued and offered for sale at such price or prices as the Bank may determine, and shall be exempt from taxation both as to principal and interest. The said obligations shall be and are hereby fully and unconditionally guaranteed both as to principal and interest by the Government of the Republic of the Philippines and such guaranty shall be expressed on the face thereof.\n\"In the event that the Bank shall be unable to pay debentures, bonds, collaterals, notes or other such obligations issued by it, the Secretary of Finance shall pay the amount thereof, which is hereby appropriated out of any moneys in the National Treasury not otherwise appropriated, and thereupon, to the extent of the amounts so paid, the Government of the Republic of the Philippines shall succeed to all the rights of the holders of such bonds, notes, debentures, collaterals, or other obligations.\n\"Subject to the above provisions, the Bank is also authorized to issue 'Rehabilitation and development bonds' in denominations of not less than fifty pesos nor more than one thousand pesos redeemable by the Bank on demand at the option of the holder of said bonds, which may be of the following types: (1) rehabilitation and development bonds at progressive staggered interest with cumulative face value; and (2) rehabilitation and development bonds bearing interests as may be determined by the Board of Governors with the advice and consent of the Secretary of Finance and upon approval by the Monetary Board, said interest to become due and payable semi-annually and payment thereof to be annotated on the back of each bond certificate. Maturity of both types of bonds shall be fixed by the Board of Governors but in no case to exceed ten years.\n\"The Board of Governors shall have the power to prescribe rules and regulations for the registration of the bonds issued by the bank at the request of the holders of such bonds.\n\"(h) To adopt, alter, and use a corporate seal which shall be judicially noticed; to make contracts; to borrow money; to issue or own real and personal property; and to sell, mortgage or otherwise dispose of the same; to sue and be sued; to employ such officers and personnel as may be necessary to carry out the business of the Bank; and otherwise to do and perform any and all things that may be necessary or proper to carry out the purposes of the Bank.\n\"(i) To subscribe out of its funds to the capital stock of private provincial and city development banks created pursuant to the provisions of this Act: Provided, That the aggregate of such subscription shall not exceed twenty-five million pesos.\n\"(j) To rediscount intermediate and long term notes, loans and/or mortgages of the Philippine National Bank.\n\"Sec. 3. Capital Stock. The capital stock of the Bank shall be five hundred million pesos divided into five hundred thousand shares having a par value of one thousand pesos each. The said capital stock shall be fully subscribed by the Government of the Republic of the Philippines.\n\"The provisions of section three of Republic Act Numbered Seventeen hundred eighty-nine to the contrary notwithstanding, an amount equivalent to fifty per cent of the proceeds from the sale of reparations goods and services for fifteen years following the approval of this Act, is hereby appropriated to cover the payment of the unpaid subscription of the government to the capital stock of the Bank: Provided, That seventy-five million pesos of such amount shall be set aside as a trust fund for the purpose of aiding the establishment of private provincial and city development banks as provided in this Act."}},{"id":"PH-H1820-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"The same Act is amended by adding after section three thereof the following new sections:\n\"Sec. 4. Loans . The Bank may grant loans against security of real estate and/or other acceptable assets including, subject to the provision of existing laws, leasehold rights and permits from the government: Provided, That not more than forty-five per cent of its authorized capital stock shall be available for industrial loans, not more than thirty-five per cent of such capital stock shall be available for agricultural loans and not more than twenty per cent of such capital stock shall be available for miscellaneous loans including loans for home building or home financing projects: Provided, further, That the same proportion hereinabove stated shall be observed in the grant of loans for industrial, agricultural and miscellaneous purpose: Provided, further, That of the amount available for agricultural loans, not more than twenty per cent thereof shall be made available for any agricultural crop and that of the latter amount not more than five per cent thereof shall be loaned to any individual, association or corporation: Provided, further, That no person shall be granted a loan for home building in excess of thirty thousand pesos: Provided, further, That any provision of law to the contrary notwithstanding the Bank is authorized to grant loans on the security of real estate without torrens title if the said real estate has been declared for purposes of taxation continuously for at least ten years and the applicant for loan and his predecessors in interest have been in continuous and uninterrupted possession thereof in the concept of owner for at least ten years, such possession to be established by affidavits of the owners of all the properties adjoining such real estate and other evidences that the board of governors may deem necessary: Provided, further, That the Bank shall set aside twenty-five per cent of its loanable funds for each quarter for the purchase of such mortgage bonds as the Philippine National Bank shall issue for the grant of medium and long-term development loans: Provided, finally, That such bonds sold by the Philippine National Bank to the Bank shall be guaranteed by the government both as to principal and interest.\n\"Sec. 5. The provision of any law to the contrary notwithstanding, twenty-five per cent of the investible funds of the Government Service Insurance System and the Social Security System accumulating monthly shall be invested by the said systems in bonds issued by the Bank.\n\"Sec. 6. The establishment of private development banks in provinces and cities shall be encouraged and shall be given preference and assistance by the government as herein below provided.\n\"Sec. 7. There shall be three classes or categories of private development banks, namely: class A, class B, and class C.\nClass A private development banks shall have a paid-up capital of at least four million pesos; class B shall have a paid-up capital of at least two million pesos; and Class C shall have a paid-up capital of at least one million pesos.\n\"Sec. 8. A private development bank shall be incorporated under the provisions of the General Banking Act for mortgage banks and shall exercise all the powers and shall assume all the obligations of a mortgage bank as defined in the said Act, except as otherwise provided herein: Provided, That no private development bank shall be operated without a certificate of authority from the monetary board of the Central Bank which shall be issued upon compliance with the provisions of this law.\n\"Any existing domestic bank may be converted into a private development bank in the province or city in which it is located: Provided, That it complies with the requirements prescribed in this Act: Provided, further, That at least sixty per cent of its capital stock is owned by citizens of the Philippines.\n\"Sec. 9. A private development bank shall be organized in the form of a stock corporation and its paid-up capital stock shall not be less than four million pesos for class A, two million pesos for class B, and one million pesos for class C: Provided, That at least sixty per cent of the capital stock subscribed by the private sector shall be owned and held by citizens of the Philippines: Provided, further, That if said subscription of private shareholders to the capital stock of a private development bank cannot be secured or is not available, the Bank on representation of the said private shareholders and with the approval of its Board of Governors shall, with thirty days from date of said approval by the Board of Governors, subscribe to the capital stock of such development banks, which shall be paid in full at the time of subscription out of the trust fund hereinabove mentioned, in an amount equal to the full paid subscribed capital of the private stockholders: Provided, further, That the Board of Governors shall act on the representation made by the private shareholders within thirty days from the date it is filled: Provided, further, That such shares of stock subscribed by the bank shall be preferred shares entitled to cumulative dividends at a rate of one per cent during the first five years, two per cent during the following five years, and three per cent thereafter, shall be preferred as against common and other preferred stockholders in the distribution of assets in the event of liquidation, and shall be entitled to voting privileges: Provided, finally, That such preferred shares of the bank may be sold at any time at par to private individuals who are citizens of the Philippines, and in the sale thereof the qualified registered stockholders shall have the right of preemption within one year from the date of offer in proportion to their respective holdings, but in the absence of such buyers, preference shall be given to residents of the province or city where the development bank is located. All members of the board of directors of the private development banks shall be citizens of the Philippines.\n\"Sec. 10. Private development banks organized under this Act shall be known by the name of the province or city it is to operate followed by the words \"Development Bank.\" Should there be in a province or city more than one such private development bank, the name of the banks organized subsequently shall be preceded by the word second or third and so on following the order of their authorization.\n\"In the implementation of the provisions of this Act, the Central Bank and the bank shall see to it that, before a second or subsequent private development bank is organized in a particular province or city, ample provision be made to provide for capital assistance in the organization of private development banks in other provinces and cities still without such banks.\n\"Sec. 11. The Central Bank shall advance, within thirty days from the date of the organization and authorization of the first provincial or city private development bank, sums of money not to exceed at any one time ten million pesos for the trust fund payment of the same to be guaranteed by the reparations payments prescribed above.\nThe loanable funds of the private development bank shall be invested in medium and long-term loans for economic development purpose and in no case shall the bank invest more than twenty-five per cent of such loanable funds in short-term loans.\n\"Sec. 12. The trust fund shall be used by the Bank in assisting private development banks as follows:\n\"(a) To pay for its subscription to preferred shares of stock in said private development banks in the manner and subject to the terms and conditions prescribed in section nine hereof;\n\"(b) To rediscount promissory notes and other credit instruments held by the private development bank under the following conditions and limitations:\n\"(1) It charges such rediscount or interest rates as it may determine taking into account that the main objective of the private development banks is to engage in medium and long-term loans for economic development. The determination of such rediscount or interest rates acceptable to the bank for purposes of this provision shall be made by the said bank upon or immediately after the commencement of operations of a private development bank;\n\"(2) Funds so acquired shall be used only to finance the establishment and operation of projects within the development program of the National Economic Council or along such projects and activities as the National Economic Council may, from time to time, approve.\n\"Sec. 13. The provisions of Republic Act Numbered Three hundred and thirty-seven, insofar as they are applicable and not in conflict with any provision of this Act, are hereby made applicable to private development banks."}},{"id":"PH-H1820-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"Section four to seventeen of the same Act are hereby redesignated as Section fourteen to twenty-seven, respectively."}},{"id":"PH-H1820-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"After section seventeen of the same Act, herein redesignated as section twenty-seven, the following new sections are added:\n\"Sec. 28. Whenever the phrase \"Rehabilitation Finance Corporation\" and the word 'corporation' appear in Republic Act Numbered Eighty-five or in any other Act or Executive Order, the same shall mean and refer to the 'Development Bank of the Philippines' and the 'Bank', respectively.\n\"Upon the approval of this Act, all the assets and liabilities as well as the personnel of the Rehabilitation Finance Corporation are hereby transferred to the Bank.\n\"Sec. 29. Nothing in this Act shall authorize the Bank to layoff or separate from the service any official or employee of the Rehabilitation Finance Corporation by reason of the approval of this Act.\n\"Sec. 30. In the event that any provision of this Act or the applicability of such provision to any person or circumstance is declared invalid, the remainder of the Act or the application of said provision to other persons or circumstances shall not be affected by such declaration.\""}},{"id":"PH-H1820-A5","no":5,"noLabel":{"en":"Section 5."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 14, 1958"}}],"pack":"ph-p25","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act to Amend Republic Act Numbered Eighty-Five and Other Pertinent Laws, to Provide Facilities for Intermediate and Long-Term Credit by Converting the Rehabilitation Finance Corporation into the Development Bank of the Philippines, Authorizing the Said Bank to Aid in the Establishment of Provincial and City Private Development Banks, and for Other Purposes","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H1821"] = {"id":"PH-H1821","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1958/ra_2082_1958.html","fetchedAt":"2026-10-06","articleCount":2,"structureMode":"ARTICLE","title":{"zh":"修订第663号共和国法第5条（经第2017号共和国法修正）的法案","en":"An Act to Further Amend Section Five of Republic Act Numbered Six Hundred and Sixty-Three, as Amended by Republic Act Numbered Two Thousand Seventeen","orig":"An Act to Further Amend Section Five of Republic Act Numbered Six Hundred and Sixty-Three, as Amended by Republic Act Numbered Two Thousand Seventeen"},"level":"law","status":"active","topics":["general"],"docNumber":"Republic Act No. 2082","issuingBody":"Congress of the Philippines","promulgatedDate":"1958-06-14","completenessNote":"全文，共 2 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1958/ra_2082_1958.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H1821-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"Section five of Republic Act Numbered Six hundred and sixty-three, as amended by Republic Act Numbered Two thousand seventeen, is hereby further amended to read as follows:\n\"Sec. 5. In order to enable the Corporation to exercise the powers and duties vested in it by this Act:\n\"(a) The Corporation is hereby exempted from the payment of import duty on rice and corn, and on such supplies, machinery and equipment such as fertilizer and lime as may be necessary for demonstration farming: Provided, That the exemptions granted under this Act shall be availed of only upon recommendation of the Board of Directors of the Corporation and certified by the Secretary of Agriculture and Natural Resources and upon certification by the President that there is a rice or corn shortage, and only for the amount specified in said certification: Provided, further, That all exemptions from taxes granted under this Act shall be for a period of not exceeding one year from the enactment hereof: And Provided, finally, That no corn or rice imported by the Corporation under this Act shall be converted into starch in commercial quantity and any person or corporation violating this Act shall, upon conviction by competent court, be punished by imprisonment of not less than five years nor more than eight years and a fine of eight thousand pesos. If the violation is committed by a corporation, the official of the corporation responsible for the violation shall suffer the penalties provided in this Act.\""}},{"id":"PH-H1821-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 14, 1958."}}],"pack":"ph-p25","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act to Further Amend Section Five of Republic Act Numbered Six Hundred and Sixty-Three, as Amended by Republic Act Numbered Two Thousand Seventeen","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H1822"] = {"id":"PH-H1822","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1958/ra_2083_1958.html","fetchedAt":"2026-10-06","articleCount":4,"structureMode":"ARTICLE","title":{"zh":"修订第2-A号重组方案中关于标准薪酬的某些规定并为其他目的法案","en":"An Act to Amend Certain Provisions of Reorganization Plan Numbered Two-A Relative to Standardized Pay, and for Other Purposes","orig":"An Act to Amend Certain Provisions of Reorganization Plan Numbered Two-A Relative to Standardized Pay, and for Other Purposes"},"level":"law","status":"active","topics":["general"],"docNumber":"Republic Act No. 2083","issuingBody":"Congress of the Philippines","promulgatedDate":"1958-06-14","completenessNote":"全文，共 4 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1958/ra_2083_1958.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H1822-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"All provincial salary ranges commencing from Range No. 14 to Range No. 75, in paragraph 1 of Reorganization Plan No. 2-A, are hereby abolished, and all officials and employees assigned in the province shall receive the compensation indicated in their corresponding range."}},{"id":"PH-H1822-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"Subsection (a) of section three of the same plan is amended to read as follows:\n\"(a) All salaries are expressed as annual rates in pesos, and represent full compensation for full-time employment in a forty-hour work week regardless of where the work is performed. Any food, lodging or other thing or service provided to any employee shall have its value established by the Budget Commission, and such value may be deducted from the salary. When the established work week is other than forty hours compensation may be adjusted proportionately.\""}},{"id":"PH-H1822-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"To carry out the provisions of this Act, the sum of ten million eight hundred thousand pesos or so much thereof as may be necessary to cover the adjustment of salaries of employees now receiving the provincial rate is appropriated out of any funds in the National Treasury not otherwise appropriated."}},{"id":"PH-H1822-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 14, 1958."}}],"pack":"ph-p25","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act to Amend Certain Provisions of Reorganization Plan Numbered Two-A Relative to Standardized Pay, and for Other Purposes","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H1823"] = {"id":"PH-H1823","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1958/ra_2084_1958.html","fetchedAt":"2026-10-06","articleCount":19,"structureMode":"ARTICLE","title":{"zh":"促进稻米与玉米生产的法案","en":"An Act to Promote Rice and Corn Production","orig":"An Act to Promote Rice and Corn Production"},"level":"law","status":"active","topics":["environment"],"docNumber":"Republic Act No. 2084","issuingBody":"Congress of the Philippines","promulgatedDate":"1958-06-14","completenessNote":"全文，共 19 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1958/ra_2084_1958.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H1823-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"This Act shall be known as the Rice and Corn Production Act of 1958."}},{"id":"PH-H1823-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"It is hereby declared to be the national policy to attain self-sufficiency in rice and corn at the earliest possible time and to provide adequate measures to insure permanent stability in the production of these cereals by marshalling all government agencies to increase rice and corn production at a minimum cost."}},{"id":"PH-H1823-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"To achieve this objective of increased production, a four-year rice and corn production program shall be planned and executed under the direct control and management of a Rice and Corn Coordinating Council to be composed of the Secretary of Agriculture and Natural Resources, as Chairman and Coordinator, the Directors of the Bureaus of Plant Industry, Public Works, Soils, Agricultural Extension, Animal Industry, Lands, and Mines, the Dean of the U.P. College of Agriculture, a representative of the Department of General Services, the Administrator of the Agricultural Credit and Cooperative Financing Administration (ACCFA), and the Manager of the National Rice and Corn Corporation (NARIC), as members. The Council shall be responsible for the success of the promotion of rice and corn production; it shall formulate the overall policies and methods that will guide the implementation of the program. The Chairman and Coordinator shall be the presiding officer of the Council and shall be primarily responsible for the execution of the policies and methods that the Council shall formulate from time to time, with powers to direct participating agencies to perform their part in the program. The Coordinator, with the approval of the Coordinating Council, is hereby authorized to promulgate the necessary rules and regulations to implement the provisions of this Act. In the attainment of the objectives of the program, the Coordinator may organize such teams of technical men from the Bureaus of Plant Industry, Agricultural Extension, Animal Industry, Soils, Lands, Mines, and Public Works, the Department of General Services, the U.P College of Agriculture, ACCFA, NARIC and such other agencies that he may designate after consultation and approval of the Council, to supervise the execution of the program and such other personnel as are necessary for the successful prosecution of the plans as outlined in the four-year rice and corn production program: Provided, however, That the amount for personnel shall not exceed five per centum of the appropriation authorized by this Act: And provided, further, That all appointments of additional personnel shall be subject to the approval of the Coordinating Council."}},{"id":"PH-H1823-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"The rice and corn production program envisioned in this Act shall cover the following phases considered necessary to achieve the immediate objective of increased production of rice and corn, as follows: (1) research and experimentation of seed varieties for both rice and corn; (2) production and distribution of registered and certified seeds; (3) procurement and distribution of certified fertilizers and soil conditioners; (4) control of plant pests and plant animal diseases; (5) public agricultural information, including demonstration farms; and (6) purchase of modern rice and corn processing mills."}},{"id":"PH-H1823-A5","no":5,"noLabel":{"en":"Section 5."},"text":{"en":"During the first, second, third, and fourth years of the program, there shall be established under the direct supervision and control of the Coordinating Council the following administrative divisions, namely: (1) Fertilizer and Soil Conditioner Development, (2) Irrigation Development, and (3) Mechanization Development. These three divisions are created to plan, organize, and execute the long-range objectives of the program, to insure permanent stability in the production of rice and corn, The major functions, respectively, shall be (1) to make surveys of fertilizer and soil conditioner sources in the Philippines; (2) to administer the plans for aid in the construction of self-help communal irrigation system in unirrigated rice regions by duly organized communal irrigation associations with a view to increasing acreage of irrigated ricelands for rice production; and (3) to acquire, purchase, and make available all mechanized farm implements acquired under this Act and to administer tractor pools that the Coordinating Council may organize for the purpose of increasing acreage for corn production."}},{"id":"PH-H1823-A6","no":6,"noLabel":{"en":"Section 6."},"text":{"en":"The ACCFA under the supervision of the Rice and Corn Coordinating Council is charged with the purchase, distribution, sale and collection of payments for fertilizers and soil conditioners purchased under this Act and sold or advanced to farmers under the loan plan herein provided, in accordance with such policies, rules and regulations approved by the Council as will insure the equitable distribution of fertilizers and soil conditioners to farmers based on a farmers census consisting of such farmers registered as directly cooperating in the increased production program and to insure further that fertilizers and soil conditioners issued under this Act shall be used for the purpose they are intended and not channeled to the black market: Provided, That fertilizers and soil conditioners shall be sold in cash or advanced, payable in palay corn at the end of the harvest; that the quantity of fertilizers and soil conditioners to be sold to farmers per hectare shall be in accordance with a schedule determined by the Council on the basis of the farm area actually under cultivation; that if sold in cash, payment shall not exceed fifty per cent of procurement, handling, and storage cost; that if advanced, payable in palay or corn, computation shall be based on cash value of fifty per cent of the procurement, handling and storage of the fertilizer and soil loner and the government price for palay or corn: Provided, further, That fertilizers and soil conditioners shall be procured first from locally produced supplies which shall not exceed the cost of imported fertilizers and the balance shall be filled through importation after a public bidding conducted by a Committee composed of the Secretary of Finance or his representative as Chairman, the Secretary of Agriculture and Natural Resources or his representative, the Secretary of General Services or his representative and the Administrator of the ACCFA or his representative as members: Provided, finally, That no fertilizer and soil conditioner shall be sold to farmers without prior soil analysis.\nNo fertilizer, soil conditioner or selected seeds shall be resold by any farmer receiving the same from the government. The distributing agency of fertilizer, soil conditioner or selected seeds shall take all steps to prevent the waste and blackmarketing of the same, and shall provide the greatest publicity concerning the distribution, giving such information to the barrio councils or to any other civic organization requesting such information.\nAll funds derived from the sale of fertilizers and soil conditioners shall be used exclusively for supplying the fertilizer and soil conditioner needs of the four-year program."}},{"id":"PH-H1823-A7","no":7,"noLabel":{"en":"Section 7."},"text":{"en":"The Bureau of Plant Industry shall be charged with the production and administration of certified seeds, until later changed by law, including its purchase and sale to bona fide farmers with priority to farmers included in the census of registered farmers under the supervision and control of the Rice and Corn Coordinating Council in accordance with rules and regulations promulgated by the Council: Provided, That the price for certified seeds shall not exceed the government procurement cost, including handling and storage charges: Provided, further, That the recipients of such selected seeds shall not resell or utilize the same for purposes other than for planting.\nAll funds derived from sale of certified seeds shall be used exclusively for the prosecution of the seed production program."}},{"id":"PH-H1823-A8","no":8,"noLabel":{"en":"Section 8."},"text":{"en":"Insecticides, pesticides, and other supplies used for pest control shall be sold for cash not to exceed fifty per cent of procurement, handling and storage cost or may be advanced payable in palay or corn at harvest time. If payable in palay or corn, computation shall be based on the cash value and government price of the cereal at the time of harvest. The importation of insecticides shall be exempt from the payment of all taxes, including import duties. All funds derived from the sale of insecticides, pesticides and other supplies, shall be used exclusively for the prosecution of the pest control program under this. Act."}},{"id":"PH-H1823-A9","no":9,"noLabel":{"en":"Section 9."},"text":{"en":"Any person who violates any provision of this Act or of any rule or regulation promulgated in accordance therewith or who purchases or otherwise acquires fertilizers and soil conditioners and/or selected seeds in violation of this Act, or who, being an officer or employee of the government, violates, abets, or tolerates the violation of any provision of this Act or of such rule and regulation, shall be punished by a fine of two thousand pesos and by imprisonment of one year. In case the offender is an officer or employee of the government, he shall, in addition, suffer the penalty of perpetual disqualification to hold public office."}},{"id":"PH-H1823-A10","no":10,"noLabel":{"en":"Section 10."},"text":{"en":"There shall be appropriated out of any funds in the National Treasury not otherwise appropriated, the sum of ten million pesos, fifteen million pesos, twenty million pesos and twenty million pesos for the fiscal years nineteen hundred fifty-eight-nineteen hundred fifty-nine, nineteen hundred fifty-nine-nineteen hundred sixty, nineteen hundred sixty-nineteen hundred sixty-one and nineteen Hundred sixty-one-nineteen hundred sixty-two, respectively, for the purpose of this Act."}},{"id":"PH-H1823-A11","no":11,"noLabel":{"en":"Section 11."},"text":{"en":"Subject to adjustments that the Council may deem necessary, the financing of the four-year rice and production program should follow the following schedule:\n1958-59 1959-60 1960-61 1961-63 Item (Million) (Million) (Million) (Million)\n(1) Research .25 .375 .5 .5\n(2) Seed Production .75 .75 .75 .5\n(3) Fertilisers and Soil Conditioners\n7.0\n1.5\n1.5\n1.0\n(4) Pest Control\n1.0\n1.5\n2.0\n2.0\n(5) Administration\n1.0\n1.5\n2.0\n2.0\n(6) Communal Irrigation Projects None\n7.5\n10.0\n10.0\n(7) Rice and Corn Processing Mills None .375\n1.25\n2.0\n(8) Mechanization None\n7.5\n2.0\n2.0"}},{"id":"PH-H1823-A12","no":12,"noLabel":{"en":"Section 12."},"text":{"en":"The budget, together with the production plan for each year of the four-year rice and corn production program, shall be prepared by the Coordinator in consultation with the Council and shall be submitted through the National Economic Council to the President for approval. All balances at the close of each fiscal year shall, upon the recommendation of the Rice and Corn Coordinating Council, be used to make up the appropriation of the succeeding years in the contemplation of this Act: Provided, That the total appropriation shall not be more than twenty million pesos."}},{"id":"PH-H1823-A13","no":13,"noLabel":{"en":"Section 13."},"text":{"en":"All irrigation projects for areas included under the rice and corn production program under this Act shall be communal in nature and the same shall be constructed and administered by the Bureau of Public Works."}},{"id":"PH-H1823-A14","no":14,"noLabel":{"en":"Section 14."},"text":{"en":"It shall be the function of the Mechanization Development Division created under this Act to coordinate the procurement activities of the Council with the Department of General Services for the purchase of tractors: Provided, however, That to complement the mechanization program, the Bureau of Animal Industry shall procure from the funds thereof additional work animals for sale to farmers on installments basis: Provided, however, That irrespective of source, the small diesel-fed and multi-purpose tractor which will not displace farm labor shall be preferred. The Coordinating Council, upon the advice of the Director of Animal Industry, shall promulgate the policies, rules and regulations on disposition of work animals acquired under this Act.\nThe Mechanization Development Division shall organize and maintain tractor pools under the direct administration of the Office of the Highway District Engineer where such tractor pools are located. The Council shall promulgate the policies, rules and regulations on the disposition of mechanized equipment acquired under this Act."}},{"id":"PH-H1823-A15","no":15,"noLabel":{"en":"Section 15."},"text":{"en":"The President of the Philippines shall, from time to time and through executive orders, direct and define the participation of the provincial, city, municipal, municipal district and barrio elective officials in the implementation of the said national policy."}},{"id":"PH-H1823-A16","no":16,"noLabel":{"en":"Section 16."},"text":{"en":"The Monetary Board shall give up top priority in the allocation of the necessary foreign exchange for the purchase of fertilizers, soil conditioners, insecticides, pesticides, materials and equipment needed in the implementation of this Act. Failure to comply with this provision without valid reason shall subject the Chairman and the members of the Monetary Board to prosecution and punishment provided for in section nine hereof."}},{"id":"PH-H1823-A17","no":17,"noLabel":{"en":"Section 17."},"text":{"en":"The rules and regulations herein authorized to be promulgated as well as the amendments thereto shall take effect thirty days after their publication in the Official Gazette or in a newspaper of general circulation in Manila."}},{"id":"PH-H1823-A18","no":18,"noLabel":{"en":"Section 18."},"text":{"en":"The Rice and Corn Coordinator shall render a yearly report to the President of the Philippines, the President of the Senate and the Speaker of the House of Representatives on the operation of the program."}},{"id":"PH-H1823-A19","no":19,"noLabel":{"en":"Section 19."},"text":{"en":"This Act shall take effect upon its approval.\nApproved, June 15, 1958."}}],"pack":"ph-p25","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act to Promote Rice and Corn Production","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H1824"] = {"id":"PH-H1824","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1958/ra_2085_1958.html","fetchedAt":"2026-10-06","articleCount":3,"structureMode":"ARTICLE","title":{"zh":"拨款12.3万比索用于公共学校局医疗与牙科服务处驱虫、营养不良与健康教育单位的运作与维护","en":"An Act to Appropriate One Hundred Twenty-Three Thousand Pesos for the Operation and Maintenance of the Deworming, Malnutrition and Health Education Units of the Medical and Dental Services, Bureau of Public Schools, Donated by the Cooperative for American Remittances to Everywhere, Inc. (CARE)","orig":"An Act to Appropriate One Hundred Twenty-Three Thousand Pesos for the Operation and Maintenance of the Deworming, Malnutrition and Health Education Units of the Medical and Dental Services, Bureau of Public Schools, Donated by the Cooperative for American Remittances to Everywhere, Inc. (CARE)"},"level":"law","status":"active","topics":["company","education","health"],"docNumber":"Republic Act No. 2085","issuingBody":"Congress of the Philippines","promulgatedDate":"1958-06-14","completenessNote":"全文，共 3 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1958/ra_2085_1958.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H1824-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"Upon approval of this Act, the support, maintenance and operation of the deworming, malnutrition and health education units of the Medical and Dental Services of the Bureau of Public Schools which is donated by the Cooperative for the American Remittances to Everywhere, Inc., (CARE) shall be paid by the National Government."}},{"id":"PH-H1824-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"To carry out the provisions of this Act for the year nineteen hundred fifty-eight, there is hereby appropriated, out of any funds in the National Treasury not otherwise appropriated, the sum of one hundred twenty-three thousand pesos. Thereafter, such sums as may be necessary for the operation and maintenance of these units in subsequent years shall be included in the annual General Appropriations Act."}},{"id":"PH-H1824-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 14, 1958."}}],"pack":"ph-p25","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act to Appropriate One Hundred Twenty-Three Thousand Pesos for the Operation and Maintenance of the Deworming, Malnutrition and Health Education Units of the Medical and Dental Services, Bureau of Public Schools, Donated by the Cooperative for American Remittances to Everywhere, Inc. (CARE)","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H1825"] = {"id":"PH-H1825","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1958/ra_2086_1958.html","fetchedAt":"2026-10-06","articleCount":2,"structureMode":"ARTICLE","title":{"zh":"经费拨款法","en":"An Act Appropriating Annually the Sum of One Hundred Thousand Pesos as Aid to the Music Promotion Foundation","orig":"An Act Appropriating Annually the Sum of One Hundred Thousand Pesos as Aid to the Music Promotion Foundation"},"level":"law","status":"active","topics":["general"],"docNumber":"Republic Act No. 2086","issuingBody":"Congress of the Philippines","promulgatedDate":"1958-06-14","completenessNote":"全文，共 2 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1958/ra_2086_1958.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H1825-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"There is hereby appropriated annually, out of any funds in the National Treasury not otherwise appropriated, the sum of one hundred thousand pesos as aid of the Government to the Music Promotion Foundation in the prosecution of the objectives of the said Foundation."}},{"id":"PH-H1825-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 14, 1958."}}],"pack":"ph-p25"};
  FT["PH-H1826"] = {"id":"PH-H1826","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1958/ra_2087_1958.html","fetchedAt":"2026-10-06","articleCount":5,"structureMode":"ARTICLE","title":{"zh":"给予菲律宾前总统遗孀终身养老金与免费邮递特权的法案","en":"An Act Granting Life Pension and Franking Privilege to Widows of Former Presidents of the Philippines","orig":"An Act Granting Life Pension and Franking Privilege to Widows of Former Presidents of the Philippines"},"level":"law","status":"active","topics":["general"],"docNumber":"Republic Act No. 2087","issuingBody":"Congress of the Philippines","promulgatedDate":"1958-06-14","completenessNote":"全文，共 5 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1958/ra_2087_1958.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H1826-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"The widow of any former President of the Philippines shall be entitled to a life pension, tax free, of twenty-four thousand annually, payable at the rate of two thousand pesos monthly, if such President was not removed by impeachment: Provided, That if such widow of any President re-marries she shall lose the benefits of this Act."}},{"id":"PH-H1826-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"All mail matters of such widow, addressed for delivery within the Philippines, shall be received, transmitted and delivered in the mails of the Philippines free of postage if the envelope or wrapper of such mail matter bears on the left upper corner her name. Any person who violates the provisions of this section shall be punished by a fine of not more than five hundred pesos."}},{"id":"PH-H1826-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"Republic Act Numbered Two hundred eight is repealed."}},{"id":"PH-H1826-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"There is appropriated annually, out of any funds in the National Treasury not otherwise appropriated, such sum as may be necessary to carry out the purposes of this Act."}},{"id":"PH-H1826-A5","no":5,"noLabel":{"en":"Section 5."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 22, 1958."}}],"pack":"ph-p25","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act Granting Life Pension and Franking Privilege to Widows of Former Presidents of the Philippines","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H1827"] = {"id":"PH-H1827","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1958/ra_2088_1958.html","fetchedAt":"2026-10-06","articleCount":3,"structureMode":"ARTICLE","title":{"zh":"将卡皮斯省Mambusao中学改设为国立农业学校并授权为此拨款的法案","en":"An Act Converting the Mambusao High School in the Province of Capiz into a National Agricultural School, Authorizing the Appropriation of Funds Therefor","orig":"An Act Converting the Mambusao High School in the Province of Capiz into a National Agricultural School, Authorizing the Appropriation of Funds Therefor"},"level":"law","status":"active","topics":["education","environment"],"docNumber":"Republic Act No. 2088","issuingBody":"Congress of the Philippines","promulgatedDate":"1958-06-22","completenessNote":"全文，共 3 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1958/ra_2088_1958.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H1827-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"The Mambusao High School in the Municipality of Mambusao, Province of Capiz, is hereby converted into a national agricultural school of the Iloilo National Agricultural School type, to be known as the Panay National Agricultural School. The Secretary of Education is hereby empowered to reorganize said school accordingly."}},{"id":"PH-H1827-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"The sum of two hundred and fifty thousand pesos is hereby authorized to be appropriated, out of any funds in the National Treasury not otherwise appropriated, for the operation and maintenance of said school for the school year nineteen hundred and fifty-eight to nineteen hundred and fifty-nine. The necessary funds for the purpose shall be included in the annual General Appropriations Act."}},{"id":"PH-H1827-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 22, 1958."}}],"pack":"ph-p25","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act Converting the Mambusao High School in the Province of Capiz into a National Agricultural School, Authorizing the Appropriation of Funds Therefor","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H1828"] = {"id":"PH-H1828","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1958/ra_2089_1958.html","fetchedAt":"2026-10-06","articleCount":5,"structureMode":"ARTICLE","title":{"zh":"修订第 515 号共和国法的法案","en":"An Act to Amend Republic Act Numbered Five Hundred Fifteen","orig":"An Act to Amend Republic Act Numbered Five Hundred Fifteen"},"level":"law","status":"active","topics":["general"],"docNumber":"Republic Act No. 2089","issuingBody":"Congress of the Philippines","promulgatedDate":"1958-06-22","completenessNote":"全文，共 5 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1958/ra_2089_1958.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H1828-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"The title of Republic Act Numbered Five hundred fifteen is amended to read as follows:\n\"An Act granting the Silliman University a temporary permit to establish, maintain and operate radio broadcasting stations for non-profit, religious, educational, and cultural purposes.\""}},{"id":"PH-H1828-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"Section one of the same Act is amended to read as follows:\n\"Sec. 1. The Silliman University, hereinafter referred to as ‘grantee,’ is hereby granted a temporary permit to construct, maintain and operate, subject to the approval of the Secretary of Public Works and Communications, radio broadcasting stations in the Philippines and the corresponding electrical communication laboratories, for non-profit, religious, educational and cultural purposes only.\""}},{"id":"PH-H1828-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"Section two of the same Act is amended to read as follows:\n\"Sec. 2. This temporary permit shall continue for a period of twenty-five years from the date the said stations shall be put in operation, and is made upon the express condition that the same shall be void unless the construction of at least one station be begun within six months from the date of approval of this Act and be completed within two years from said date. Frequencies for other stations shall be granted upon request, subject to rules and regulations prescribed by the Secretary of Public Works and Communications governing said matters, existing at the time of application.\""}},{"id":"PH-H1828-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"Section twelve of the same Act is amended to read as follows:\n\"Sec. 12. The grantee shall not lease, transfer, grant the usufruct of, sell or assign this temporary permit nor the rights and privileges acquired thereunder to any person, firm, company, corporation, or other commercial or legal entity, nor merge with any other company or corporation organized for the same purpose, without the approval of the Congress of the Philippines first had, Provided, That the rights and privileges of this franchise shall be shared with the Philippine Federation of Christian Churches. Any corporation to which this temporary permit may be sold, transferred, or assigned, shall be subject to the corporation laws of the Philippines now existing or hereafter enacted, and any person, firm, company, corporation or other commercial or legal entity to which this temporary permit is sold, transferred, or assigned shall be subject to all the conditions, terms, restrictions and limitations of this temporary permit as fully and completely and to the same extent as if the temporary permit had been originally granted to the said person, firm, company, corporation or other commercial or legal entity.\""}},{"id":"PH-H1828-A5","no":5,"noLabel":{"en":"Section 5."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 22, 1958."}}],"pack":"ph-p25","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act to Amend Republic Act Numbered Five Hundred Fifteen","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H1829"] = {"id":"PH-H1829","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1958/ra_2090_1958.html","fetchedAt":"2026-10-06","articleCount":17,"structureMode":"ARTICLE","title":{"zh":"授予 Felix Alberto 公司设立国内与远洋电信无线电台的特许经营权法案","en":"An Act Granting Felix Alberto and Company, Incorporated, a Franchise to Establish Radio Stations for Domestic and Transoceanic Telecommunications","orig":"An Act Granting Felix Alberto and Company, Incorporated, a Franchise to Establish Radio Stations for Domestic and Transoceanic Telecommunications"},"level":"law","status":"active","topics":["investment","data","company"],"docNumber":"Republic Act No. 2090","issuingBody":"Congress of the Philippines","promulgatedDate":"1958-06-22","completenessNote":"全文，共 17 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1958/ra_2090_1958.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H1829-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"Subject to the provisions of the Constitution and the provisions of Act Numbered Three thousand eight hundred and forty-six, entitled \"An Act providing for the regulation of radio stations and radio communications in the Philippine Islands, and for other purposes;\" Commonwealth Act Numbered One hundred forty-six, known as the Public Service Act, and their amendments, and other applicable laws, there is hereinafter granted to Felix Alberto and Company, Incorporated, its successors or assigns, and hereunder referred to as the \"grantee,\" the right and privilege of constructing, installing, establishing and operating in the Philippines, at such places as Felix Alberto and Company, Incorporated, may select and the Secretary of Public Works and Communications may approve, radio stations for the reception and transmission of messages on radio stations in the foreign and the domestic public fixed point-to-point and public base, aeronautical and land mobile stations, including coastal marine service with the corresponding relay stations for the reception and transmission of wireless messages on radiotelegraphy and/or radiotelephony, radioteletype, radiophoto, facsimile, music, pictures, advertisement and such other types of emission from or to foreign countries and within the Philippines and with vessels at sea and aircrafts over the air; irrespective of whether such vessels and aircrafts are within or without the Philippines."}},{"id":"PH-H1829-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"A special right is reserved to the President of the Philippines in times of war, rebellion, public peril, calamity, disaster or disturbance of peace or order, to take over and operate the said stations or to authorize the temporary use and operation thereof by any department of the Government without compensating the grantee for the use of said stations during the period when they shall be so operated."}},{"id":"PH-H1829-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"The President of the Philippines shall have the power and authority to permit the construction of said stations or any of them on any land of the public domain upon such terms and conditions as he may prescribe."}},{"id":"PH-H1829-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"This franchise shall continue for a period of fifty years from the date the first of said stations shall be placed in operation, and is granted upon the express condition that same shall be void unless the construction of said station be begun within two years from the date of the approval of this Act and be completed within ten years from said date."}},{"id":"PH-H1829-A5","no":5,"noLabel":{"en":"Section 5."},"text":{"en":"(a) This franchise shall not take effect nor shall any power thereunder be exercised by the grantee until the Secretary of Public Works and Communications shall have allotted to the grantee the frequencies and wave lengths to be used thereunder and determined the stations to and from which each frequency and wave length may be used, and issued to the grantee a license for such use. (b) The Secretary of Public Works and Communications, on reasonable notice to the grantee, may at any time change, or cancel, or modify, in whole or in part, any or all of the allotments of frequencies or wave lengths to be used. He may take such action: (1) whenever in his judgment such frequencies and wave lengths have been used, or there is danger that they will be used by the grantee to impair electrical communications, or stifle competition, or to obtain a monopoly in electrical communication or to secure unreasonable rates for such communication, or to violate otherwise the laws or public policy of the Philippine Republic; (2) whenever in his judgment the public interests of the Republic of the Philippines require that such frequencies or wave lengths should be used for other purposes than those of the grantee, either by the Government of the Philippines or by other individuals or corporations licensed by it; and (3) whenever in his judgment, for any reason, the public interests of the Philippines so require."}},{"id":"PH-H1829-A6","no":6,"noLabel":{"en":"Section 6."},"text":{"en":"The stations of the grantee shall be so constructed and operated and the wave lengths so selected as to avoid interference with existing stations and to permit the expansion of the grantee's services."}},{"id":"PH-H1829-A7","no":7,"noLabel":{"en":"Section 7."},"text":{"en":"The grantee shall hold the National, provincial, and municipal governments of the Philippines harmless from all claims, accounts, demands or actions arising out of accidents or injuries, whether to property or to persons, caused by the construction or operation of the stations of the grantee."}},{"id":"PH-H1829-A8","no":8,"noLabel":{"en":"Section 8."},"text":{"en":"No private property shall be taken for any purpose by the grantee without proper condemnation proceedings and just compensation paid or tendered therefor, and any authority to take and occupy land contained herein shall not apply to the taking, use, or occupation of any land except such as is required for the actual necessary purposes for which this franchise is granted."}},{"id":"PH-H1829-A9","no":9,"noLabel":{"en":"Section 9."},"text":{"en":"The grantee shall keep an account of the gross receipts of its business and shall furnish the Auditor General and the Treasurer of the Philippines with a copy of such account not later than the thirty-first day of January of each year for the preceding year. All the books and accounts of the grantee pertaining to its business shall be subject to the official inspection of the Auditor General or his authorized representatives, and the audit and approval of such accounts shall be final and conclusive evidence as to the amount of said gross receipts, except that the grantee shall have the right to appeal to the courts under the terms and conditions provided in the laws of the Philippines."}},{"id":"PH-H1829-A10","no":10,"noLabel":{"en":"Section 10."},"text":{"en":"The grantee shall not lease, transfer, grant the usufruct of, sell or assign this franchise nor the rights and privileges acquired thereunder to any person, firm, company, corporation or other commercial or legal entity nor merge with any other person, company or corporation organized for the same purpose, without the approval of the Congress of the Philippines first had. Any corporation to which this franchise may be sold, transferred, or assigned, shall be subject to the corporation laws of the Philippines now existing or hereafter enacted, and any person, firm, company, corporation or other commercial or legal entity to which this franchise is sold, transferred, or assigned shall be subject to all conditions, terms, restrictions and limitations of this franchise as fully and completely and to the same extent as if the franchise had been originally granted to the said person, firm, company, corporation or other commercial or legal entity."}},{"id":"PH-H1829-A11","no":11,"noLabel":{"en":"Section 11."},"text":{"en":"The grantee, its successors or assigns, shall be subject to the corporation laws of the Philippines now existing or hereafter enacted."}},{"id":"PH-H1829-A12","no":12,"noLabel":{"en":"Section 12."},"text":{"en":"The grantee shall file a bond in the amount of fifty thousand pesos to guarantee the full compliance and fulfillment of the conditions under which this franchise is granted. If after four years from the date of the approval of this Act, the grantee shall have fulfilled said conditions, or as soon thereafter as the grantee shall have fulfilled the same, the bond aforesaid shall be cancelled by the Government."}},{"id":"PH-H1829-A13","no":13,"noLabel":{"en":"Section 13."},"text":{"en":"In the event of any competing individual, partnership or corporation receiving from the Congress a similar franchise in which there shall be any term or terms more favorable than those herein granted or tending to place the herein grantee at any disadvantage, then such term or terms shall ipso facto become a part of the terms hereof and shall operate equally in favor of the grantee as in the case of said competing individual, partnership or corporation."}},{"id":"PH-H1829-A14","no":14,"noLabel":{"en":"Section 14."},"text":{"en":"(a) The grantee shall be liable to pay the same taxes on its real estate, buildings and personal property, exclusive of the franchise, as other persons or corporations are now or hereafter may be required by law to pay. (b) The grantee shall further pay to the Treasurer of the Philippines each year, within ten days after the audit and approval of the accounts as prescribed in this Act one and one-half per centum of all gross receipts from the business transacted under this franchise by the said grantee."}},{"id":"PH-H1829-A15","no":15,"noLabel":{"en":"Section 15."},"text":{"en":"The franchise hereby granted shall be subject to amendment, alteration, or repeal by the Congress of the Philippines when the public interest so requires."}},{"id":"PH-H1829-A16","no":16,"noLabel":{"en":"Section 16."},"text":{"en":"This franchise shall not be interpreted to mean as an exclusive grant of the privileges herein provided for."}},{"id":"PH-H1829-A17","no":17,"noLabel":{"en":"Section 17."},"text":{"en":"This Act shall take effect upon its approval.\nEnacted without Executive approval, June 22, 1958."}}],"pack":"ph-p25","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act Granting Felix Alberto and Company, Incorporated, a Franchise to Establish Radio Stations for Domestic and Transoceanic Telecommunications","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H1830"] = {"id":"PH-H1830","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1958/ra_2091_1958.html","fetchedAt":"2026-10-06","articleCount":3,"structureMode":"ARTICLE","title":{"zh":"修订第765号共和国法（题为“授予Henry R. Canoy在卡加延-德奥罗市建设、维护与运营广播电台的临时许可”）","en":"An Act to Amend Republic Act Numbered Seven Hundred Sixty-Five, Entitled “An Act Granting Henry R. Canoy a Temporary Permit to Construct, Maintain and Operate a Radio Broadcasting Station in the City of Cagayan De Oro”","orig":"An Act to Amend Republic Act Numbered Seven Hundred Sixty-Five, Entitled “An Act Granting Henry R. Canoy a Temporary Permit to Construct, Maintain and Operate a Radio Broadcasting Station in the City of Cagayan De Oro”"},"level":"law","status":"active","topics":["general"],"docNumber":"Republic Act No. 2091","issuingBody":"Congress of the Philippines","promulgatedDate":"1958-06-22","completenessNote":"全文，共 3 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1958/ra_2091_1958.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H1830-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"Section one of Republic Act Numbered Seven hundred sixty-five is amended to read as follows:\n\"Sec. 1. Subject to the provisions of the Constitution as well as of Act Numbered Three thousand eight hundred forty-six, entitled \"An Act providing for the regulations of radio stations and radio communications in the Philippine Islands, and for other purposes;\" Act Numbered Three thousand nine hundred ninety-seven, known as the Radio Broadcasting Law; Commonwealth Act Numbered One hundred forty-six, known as the Public Service Act, and their amendments, and other applicable laws, Henry R. Canoy is hereby granted a temporary permit to construct, maintain and operate, for commercial purposes and in the public interest radio broadcasting stations in the Philippines: Provided, That this temporary permit shall be void unless the construction of the radio broadcasting stations be begun within one year from the date of approval of this Act and be completed within two years for said date: Provided, further, That the grantee shall provide adequate public service time to enable the Government, through the stations herein authorized to reach the population on important public issues; shall assist in the functions of public information and education; and shall not use said stations for the broadcasting of obscene or indecent language or speech, or for the dissemination of deliberately false information or willful misrepresentation, or to the detriment of the public health, or to incite, encourage or assist in subversive or treasonable acts.\""}},{"id":"PH-H1830-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"The title of the same Act is amended to read as follows:\n\"An Act granting Henry C. Canoy a temporary permit to construct, maintain and operate radio broadcasting stations in the Philippines.\""}},{"id":"PH-H1830-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 22, 1958."}}],"pack":"ph-p25","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act to Amend Republic Act Numbered Seven Hundred Sixty-Five, Entitled “An Act Granting Henry R. Canoy a Temporary Permit to Construct, Maintain and Operate a Radio Broadcasting Station in the City of Cagayan De Oro”","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H1831"] = {"id":"PH-H1831","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1958/ra_2092_1958.html","fetchedAt":"2026-10-06","articleCount":14,"structureMode":"ARTICLE","title":{"zh":"授予 Tarlac Development Corporation 在菲律宾境内建设、设立、维护和运营私人固定点对点、海岸与陆基无线电台的临时许可的法案","en":"An Act Granting the Tarlac Development Corporation a Temporary Permit to Construct, Establish, Maintain and Operate Private Fixed Point-to-Point, Private Coastal and Private Land Based Radio Stations for the Reception and Transmission of Radio Communications Within the Philippines","orig":"An Act Granting the Tarlac Development Corporation a Temporary Permit to Construct, Establish, Maintain and Operate Private Fixed Point-to-Point, Private Coastal and Private Land Based Radio Stations for the Reception and Transmission of Radio Communications Within the Philippines"},"level":"law","status":"active","topics":["general"],"docNumber":"Republic Act No. 2092","issuingBody":"Congress of the Philippines","promulgatedDate":"1958-06-22","completenessNote":"全文，共 14 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1958/ra_2092_1958.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H1831-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"Subject to the provisions of the Constitution and the provisions of Act Numbered Three thousand eight hundred and forty-six, entitled \"An Act providing for the regulation of radio stations and radio communications in the Philippine Islands, and for other purposes;\" Commonwealth Act Numbered One hundred forty-six, known as the Public Service Act, and their amendments, and other applicable laws, there is hereby granted to the Tarlac Development Corporation a temporary permit to construct, establish, maintain and operate in the Philippines, at such places as the grantee may select, subject to the approval of the Secretary of Public Works and Communications, private fixed point-to-point, private coastal and private land based radio stations, for the reception and transmission of wireless messages on radiotelegraphy or radiotelephony, each station to be provided with a radio transmitting apparatus and a radio receiving apparatus."}},{"id":"PH-H1831-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"The President of the Philippines shall have the power and authority to permit the location of said private fixed point-to-point, private coastal and private land based radio stations or any of them on lands of the public domain upon such terms as he may prescribe."}},{"id":"PH-H1831-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"This temporary permit shall continue to be in force during the time that the Government has not established similar service at the places selected by the grantee, and is granted upon the express condition that the same be void unless the construction of at least one of the said stations be begun within one and one-half years from the date of approval of this Act."}},{"id":"PH-H1831-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"The grantee shall not engage in domestic business of telecommunications in the Philippines without further special assent of the Congress of the Philippines, it being understood that the purpose of this temporary permit is to secure to the grantee the right to construct, establish, maintain and operate private fixed point-to-point radio stations, private coastal and private land based and radio mobile units at such places in the Philippines as the interest of the corporation and of its business may justify."}},{"id":"PH-H1831-A5","no":5,"noLabel":{"en":"Section 5."},"text":{"en":"This temporary permit shall not take effect until the Secretary of Public Works and Communications shall have allotted to the grantee the frequencies and wave lengths to be used thereunder, but the grantee may use the international distress frequency of five hundred kilocycles and the high distress frequency of eight thousand two hundred eighty kilocycles whenever necessary."}},{"id":"PH-H1831-A6","no":6,"noLabel":{"en":"Section 6."},"text":{"en":"No fees are chargeable, as the radio stations that may be established by virtue of this Act shall engage in communications regarding the grantee’s business only."}},{"id":"PH-H1831-A7","no":7,"noLabel":{"en":"Section 7."},"text":{"en":"The grantee shall so construct and operate its radio stations as not to interfere with the operation of other radio stations maintained and operated in the Philippines."}},{"id":"PH-H1831-A8","no":8,"noLabel":{"en":"Section 8."},"text":{"en":"The grantee shall hold the National, provincial, and municipal governments of the Philippines harmless from all claims, accounts, demands, or actions arising out of accidents or injuries, whether to property or to persons, caused by the construction or operation of its radio stations."}},{"id":"PH-H1831-A9","no":9,"noLabel":{"en":"Section 9."},"text":{"en":"The grantee shall not lease, transfer, grant the usufruct of, sell or assign this temporary permit, nor the rights or privileges acquired thereunder to any person, firm, company, corporation or other commercial or legal entity, nor merge with any other person, firm, company, or corporation organized for the same purpose, without approval of the Congress of the Philippines first had. Any corporation to which this temporary permit may be sold, transferred, or assigned, shall be subject to the corporation laws of the Philippines now existing or hereafter enacted, and any person, firm, company, corporation or other commercial or legal entity to which this temporary permit is sold, transferred, or assigned shall be subject to all conditions, terms, restrictions and limitations of this temporary permit as fully and completely and to the same extent as if the temporary permit had been originally granted to the said person, firm, company, corporation or other commercial or legal entity."}},{"id":"PH-H1831-A10","no":10,"noLabel":{"en":"Section 10."},"text":{"en":"A special right is hereby reserved to the President of the Philippines in time of war, insurrection, public peril, emergency, calamity or disaster to cause the closing of the grantee’s radio stations or to authorize the temporary use or possession thereof by any department of the Government upon payment of just compensation."}},{"id":"PH-H1831-A11","no":11,"noLabel":{"en":"Section 11."},"text":{"en":"The grantee shall file a bond in the amount of fifty thousand pesos to guarantee the full compliance and fulfillment of the conditions under which this temporary permit is granted. If after four years from the date of the approval of this Act the grantee shall have fulfilled said conditions or as soon thereafter as the grantee shall have fulfilled the same, the bond aforesaid shall be cancelled by the Government."}},{"id":"PH-H1831-A12","no":12,"noLabel":{"en":"Section 12."},"text":{"en":"Wherever in this permit the term \"grantee\" is used, it shall be held and understood to mean \"Tarlac Development Corporation,\" its representatives, successors or assigns, unless the context indicates otherwise."}},{"id":"PH-H1831-A13","no":13,"noLabel":{"en":"Section 13."},"text":{"en":"This temporary permit shall be subject to amendment, alteration, or repeal by the Congress of the Philippines when the public interest so requires, and shall not be interpreted as an exclusive grant of the privileges herein provided for."}},{"id":"PH-H1831-A14","no":14,"noLabel":{"en":"Section 14."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 22, 1958."}}],"pack":"ph-p25","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act Granting the Tarlac Development Corporation a Temporary Permit to Construct, Establish, Maintain and Operate Private Fixed Point-to-Point, Private Coastal and Private Land Based Radio Stations for the Reception and Transmission of Radio Communications Within the Philippines","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H1832"] = {"id":"PH-H1832","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1958/ra_2093_1958.html","fetchedAt":"2026-10-06","articleCount":20,"structureMode":"ARTICLE","title":{"zh":"经费拨款法","en":"An Act Appropriating Funds for Public Works and for Other Purposes","orig":"An Act Appropriating Funds for Public Works and for Other Purposes"},"level":"law","status":"active","topics":["general"],"docNumber":"Republic Act No. 2093","issuingBody":"Congress of the Philippines","promulgatedDate":"1958-07-07","completenessNote":"全文，共 20 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1958/ra_2093_1958.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H1832-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"The following sums or so much thereof as may be necessary are hereby appropriated out of the general funds in the National Treasury not otherwise appropriated, subject to the provisions hereinafter set forth, for the purposes mentioned hereunder:\n[Itemized portion omitted due to lack of space] Total Appropriation from General Fund ....................................\n₱66,951,050.00"}},{"id":"PH-H1832-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"Apportionment of Portworks Special Fund. — The following sums or so much thereof as may be necessary are hereby apportioned out of the Portworks Special Fund that have accrued under Act No. 3592 as amended by Commonwealth Act No. 130 and by Republic Act No. 1216, not otherwise apportioned, to be released by the Secretary of Public Works and Communications pursuant to the provisions hereinafter set forth and for the purposes mentioned hereunder:\nTotal Appropriations from Portworks Special Fund ....................\n₱7,084,000.00"}},{"id":"PH-H1832-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"The following sums or so much thereof as may be necessary are hereby appropriated in consonance with Republic Act Numbered 1789, subject to the provisions and for the purposes hereunder set forth;\na. For the prefabrication of materials into school-room units for elementary school buildings, including the purchase or necessary spare parts, tools, materials other than lumber, and supplies and the erection thereof: Provided, That the President of the Philippines may authorize the pre-cutting and crating of school-room units by contract thru public bidding with operators of private sawmills or lumber yards in every Congressional District of the Philippines, where the capacity of such sawmills or lumber yards is adequate, to handle contracts amounting to not more than P20,000 at one time, in which case the school-room units so produced shall be allocated in accordance with the proportion established in Republic Act No. 836 as amended ₱5,000,000.00\nb. For the partial implementation of the remaining phases of the elementary school building program provided in Re public Act No. 836 as amended ₱5,000,000.00\nc. Reparations goods for the dredging phases of river control and seaports projects, especially in Mindanao ₱5,000,000.00"}},{"id":"PH-H1832-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"Program of Work Required before Prosecuting Public Works. —Before prosecuting any public works, the district, city or project engineer concerned shall prepare, and secure competent approval thereof, a program of work which shall include among other things the total cost of materials and labor required, the anticipated duration of the work in men-days, the margin of contingencies above his estimates if the work is to be undertaken by administration, and in addition, an estimate of what he deems as a reasonable profit for the contractor if the work is to be undertaken by contract. In no case, however, may this margin of contingencies be more than ten per cent of the cost of the work nor the allowance for profit be more than ten per cent. For work being undertaken by administration, the engineer concerned may, however, be allowed to submit a revised program of work before the completion of the project if, due to unforeseen rise in price of materials or to changes in field conditions or to other such circumstance, it becomes evident that the allowance for contingencies is not sufficient to absorb the increase and, therefore, he cannot successfully accomplish the work according to his original program. With the exception of projects the estimated cost of any of which is ten thousand pesos or less, under no circumstance shall the District or City or Project Engineer start work without first securing approval of the corresponding program of work from the Head of the Bureau or Office concerned or from the latter's duly designated representative, and no program of work for any project which requires special site investigation, survey and construction plans shall be approved unless such plans are used as basis of the program. The Auditor General or his authorized representative shall be furnished a copy of the program of work for his guidance and shall have access to the data on which the program was based."}},{"id":"PH-H1832-A5","no":5,"noLabel":{"en":"Section 5."},"text":{"en":"Recognition of Civic Organizations in the Prosecution of Community Improvement Projects. —Whenever the appropriation amounting to not more than fifteen thousand pesos for any project authorized in this Act is released and made available for expenditure, wholly or partly, such project may be undertaken by administration, the provisions of existing laws or regulations to the contrary notwithstanding.\nWhen any such project does not require complicated methods of construction or highly specialized techniques, it may be awarded through a negotiated contract to the most concerned civrc organization in the locality which has filed an application therefor in the manner herein provided. The application shall be filed by the organization concerned with the District Engineer or his official counterpart, as the case may be, specifying, among other things, the payment to be received for the work. After evaluating the offer and the terms proposed by comparing them with the corresponding program of work and estimate, the project may be awarded by the official concerned to the applicant through a negotiated contract for an amount not to exceed ninety percent of the cost of the work as originally estimated and programmed pursuant to section four of this act. In case two or more civic organizations offer to undertake the project, the official concerned shall award the contract to the organization offering the lowest quotation, determined by sealed bidding be opened in the municipal building of the municipality where the project is located within ten days, but not earlier than seven days, after notice of such bidding is Posted on the public Bulletin Board of said municipality: Provided, That, in prequalifying bidders and awarding contracts, no bid nor performance bonds will be required.\nThe authority of the District Engineer or his official art to undertake any work by administration or negotiated contract as herein provided for shall be deemed to have been duly secured upon receipt by the Provincial or City Auditor of the official advice to the head of the bureau or office concerned to so prosecute the work.\nUnder no circumstance shall the provisions of this section be construed to deprive the District Engineer or his official counterpart, as the case may be, of his supervisory control over any of the projects referred to in this section nor to relieve him of any responsibility, administrative or otherwise, for any defect in procedure, control or technical surveillance, resulting in waste of money, destruction of, or damage to, property or lowering of engineering standards. In cases where the work is undertaken through negotiated contract with a civic organization, the District Engineer, or his counterpart, may not charge against the fund of the project any expense for inspection by him or his assistant but he may designate as his representative and assign to the project as worker-inspector any competent craftsman whose compensation and travel expenses for the duration of the assignment shall be chargeable against the funds of the project but not against the contract and shall not exceed one percent of the contract price. The District Engineer, or his official counterpart, may make any other suitable arrangement to enable him to maintain supervisory control over the project without however exceeding the compensation limitation herein imposed."}},{"id":"PH-H1832-A6","no":6,"noLabel":{"en":"Section 6."},"text":{"en":"Prohibition in Use of Sums Appropriated herein. —No appropriation herein authorized shall be used to pay obligations or overdrafts previously incurred, nor be made available for the purchase of office equipment, supplies and automobiles or station wagons, nor be used to pay salaries of employees except those directly engaged in the work or assigned officially to projects and as specifically provided in Title I, Section one of this Act: Provided, That the rates of compensation shall not be higher than those authorized under the General Appropriation Act for the same rank or position in the Bureau concerned."}},{"id":"PH-H1832-A7","no":7,"noLabel":{"en":"Section 7."},"text":{"en":"Suspension of Work Done by Administration Before General Elections. —The provisions of any existing law to the contrary notwithstanding, regardless of the source of funds, within forty-five days before every general election, no laborer shall be employed or money spent in any public works project even if the money is actually released before or within such period except for:\na. Ordinary maintenance work on existing and/or completed public works projects: Provided, That there is no increase over the number of usual laborers or employees employed therein sixty days prior to the beginning of this forty-five-day period: Provided, further, That no extra gang of laborers are employed within the said period of forty-five days;\nb. Work undertaken by contract through public bidding held before the forty-five-day period: Provided, That work for the purpose of this section undertaken under the so-called \"takay\" or \"paquiao\" system shall not be considered as work by contract;\nc. Payment for the usual cost of preparation of working drawings, specifications, bills of materials, estimates, and other procedures preparatory to actual construction, including the purchase of materials and equipment, and all incidental expenses for wages of watchmen and other laborers employed for such work in the central offices and field storehouses before the beginning of such period: Provided, That the number of such laborers shall not be increased over the number hired when the project or projects were commenced;\nd. Emergency work necessitated by the occurrence of a public calamity, but such work shall be limited to the restoration of the damaged facility and shall further be \"rnited to funds available for maintenance."}},{"id":"PH-H1832-A8","no":8,"noLabel":{"en":"Section 8."},"text":{"en":"Payment of Labor and Readjustment of Contracts. —All contracts for the furnishing of materials or supplies and for the construction of any project authorized in this Act executed by any person, association or corporation with the government shall contain provisions adequately covering the following:\na. The contractor shall provide and have on hand every payday, in addition to the usual requirement of cash outlay for the prosecution of the contract work, a labor fund in an amount sufficient to cover each fifteen-day labor payroll for the project and payment to the laborers and employees shall be made within three days after the end of every pay period. Payment of wages and salaries to laborers and employees engaged in the project shall be witnessed by the engineer incharge of the work or his representatives, who shall certify to such payment. Upon failure of the contractor to pay his laborers and employees within the period herein stated, the government shall forthwith make such payment out of the funds of the project, in which case the sum paid out plus a surcharge of one per cent shall be deducted from any amount due or to become due the contractor without prejudice to the right of the government to rescind the contract.\nb. Should the government, at any time during the effectivity of a contract, impose, abolish, modify any tax, custom duties, license, impost, fee or other similar charges, or enact, amend or repeal any law affecting the number of hours of labor permissible a day or the number of days a week or the wages or salaries to be paid to laborers and employees, which would directly increase or decrease the cost of materials or the cost of the construction work beyond or under the amount stipulated in the contract, the contract amount shall be readjusted accordingly by a committee, hereby created for this purpose, composed of the Auditor General as Chairman, the Secretary of Public Works and Communications and the Commissioner of the Budget as members: Provided, That the party seeking adjustment shall first apply for same in writing, stating therein the reasons justifying the change as well as the data and computations in sufficient detail which would determine accurately the amount of the change."}},{"id":"PH-H1832-A9","no":9,"noLabel":{"en":"Section 9."},"text":{"en":"Preference to Local Labor. —In the execution and construction of community projects and of school building projects, preference shall be given to laborers the place or municipality where the project is being undertaken."}},{"id":"PH-H1832-A10","no":10,"noLabel":{"en":"Section 10."},"text":{"en":"Use of Excess Funds. —Whenever any school building project or other community project is completed and a balance of appropriation remains, the district or city engineer, as the case may be, may use such balance for the purchase or acquisition of essential school equipment or for any urgent improvement work within the school premises and for covering deficiency of appropriation of any project of the same category within the municipality."}},{"id":"PH-H1832-A11","no":11,"noLabel":{"en":"Section 11."},"text":{"en":"Publication of Call for Bids in Newspaper Sufficient. —Any law, rule or regulation to the contrary notwithstanding, in the calling for bids, as required by law, for the execution of any project with appropriation in this Act or in any of the previous Public Works Acts, advertisement thereof in any newspaper of general circulation in Manila and/or the locality, or province, or region where the project is located is sufficient compliance to the pertinent provisions of the Revised Administrative Code."}},{"id":"PH-H1832-A12","no":12,"noLabel":{"en":"Section 12."},"text":{"en":"Purchase of Project Sites Included in Appropriation. —Unless otherwise specified in the project item, appropriations herein authorized for any construction of project shall be understood as including the acquisition or purchase of sites if such acquisition or purchase is impliedly necessary for the prosecution and completion of the project."}},{"id":"PH-H1832-A13","no":13,"noLabel":{"en":"Section 13."},"text":{"en":"Engineering Surcharges. —Any provision of law, rule or regulation to the contrary notwithstanding, no personal surcharge shall be collected from the appropriations or expenditures authorized in this Act; and provincial surcharge on appropriations or expenditures Jded herein shall not exceed two per cent."}},{"id":"PH-H1832-A14","no":14,"noLabel":{"en":"Section 14."},"text":{"en":"Public Works Appropriations under This Act are National Disbursing Funds: Exceptions. —Any provision of existing law to the contrary notwithstanding, all appropriated under the provisions of this Act shall, leased, be carried in the account books of the treasurers as national disbursing funds and all the projects herein specified are classified as national projects unless such funds are appropriated specifically as aid to the provinces, chartered cities and municipalities, as the case may be: Provided, That provincial funds allocated as counterpart shall not be considered as national funds."}},{"id":"PH-H1832-A15","no":15,"noLabel":{"en":"Section 15."},"text":{"en":"Except for projects under paragraphs (f) and (g) of Title M and projects already started or continuing in character, the sums appropriated under this Act shall, be released only after the appropriations under previous Public Works Acts have been released: Provided, That appropriations released for paragraph (f) of Title \"M\" of section one shall be prorated to all Congressional Districts and made available simultaneously."}},{"id":"PH-H1832-A16","no":16,"noLabel":{"en":"Section 16."},"text":{"en":"Rental of Equipment. —Rental of equipment shall not be deducted at the time of the release of funds for public works or ever in anticipation of use of the equipment but shall be paid based on actual use: Provided, That no rental shall be charged or collected for use of equipment on any project authorized under this Act or under previous Public Works Acts when undertaken by administration."}},{"id":"PH-H1832-A17","no":17,"noLabel":{"en":"Section 17."},"text":{"en":"All appropriations under Republic Act Numbered Nine hundred and twenty remaining unreleased upon the approval of this Act are repealed."}},{"id":"PH-H1832-A18","no":18,"noLabel":{"en":"Section 18."},"text":{"en":"Any violation of any provision of sections four, six, seven and fifteen of this Act shall be a crime punishable with imprisonment from six months to six years and a fine of from five hundred to five thousand pesos; if the offender is a public officer or employer, he shall be in addition to the above penalty, be dismissed from the service with prejudice to reinstatement and deprived of all retirement benefits and privileges."}},{"id":"PH-H1832-A19","no":19,"noLabel":{"en":"Section 19."},"text":{"en":"Reports. —Thirty days before the opening day of every regular session of Congress, the proper Department Head shall make a report to both Houses of and to the President, in printed and bound form, which shall include the appropriations unexpended balances, released portions of said appropriations as of date of said report and the percentage of work accomplished and work yet to be done to accomplish the program of broad categories of public works including his recommendations, if any, for transfer of appropriations or for program changes to be incorporated in the next Public Works Appropriation Act: Provided, That report on individual projects incorporating the aforementioned data will be supplied whenever deemed relevant."}},{"id":"PH-H1832-A20","no":20,"noLabel":{"en":"Section 20."},"text":{"en":"This Act shall take effect upon its approval.\nApproved, July 7, 1958, except sections 15, 16 and 18 and the following provisions of subsection f, Title M, section 1: \" Provided, That the various appropriations for the different projects under this subsection f shall, upon formal written request by the representative of the district where such project or projects are located, be partially or wholly allocated by the Secretary of the Department of Public Works and Communications to cover new or different projects as may be indicated by said representative in said written request: Provided, further, That the same shall apply to community projects in Republic Acts Nos. 1613 and 1900.\""}}],"pack":"ph-p25"};
  FT["PH-H1833"] = {"id":"PH-H1833","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1959/ra_2094_1959.html","fetchedAt":"2026-10-06","articleCount":2,"structureMode":"ARTICLE","title":{"zh":"划定达沃省Hagonoy市镇边界的法案","en":"An Act Defining the Boundaries of the Municipality of Hagonoy, Province of Davao","orig":"An Act Defining the Boundaries of the Municipality of Hagonoy, Province of Davao"},"level":"law","status":"active","topics":["general"],"docNumber":"Republic Act No. 2094","issuingBody":"Congress of the Philippines","promulgatedDate":"1959-03-03","completenessNote":"全文，共 2 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1959/ra_2094_1959.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H1833-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"The boundaries of the Municipality of Hagonoy, Province of Davao, shall be, on the north, and imaginary line cutting the Digos-Malalag-Makar National Road at Km. 311, running due west from the shoreline of the Davao Gulf up to an imaginary north-south line with longitude 125º 14� E., thence due south along this line to its intersection with an imaginary line running due west from the shoreline of the Davao Gulf and cutting the Digos-Malalag-Makar National Road at Km. 318.1, so that the territory of said municipality shall include the barrios of Kibuaya, Upper Sacub, Lower Sacub, Maliit-Digos, La Union, Malabang, Tulogan, Malinao, Guihing, Pawa, Hagonoy, Balutakay, Leling, and Sinayawan, and the sitios of Quezon and Polopolo."}},{"id":"PH-H1833-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: March 3, 1959."}}],"pack":"ph-p25","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act Defining the Boundaries of the Municipality of Hagonoy, Province of Davao","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H1834"] = {"id":"PH-H1834","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1959/ra_2095_1959.html","fetchedAt":"2026-10-06","articleCount":2,"structureMode":"ARTICLE","title":{"zh":"设立Salcedo市","en":"An Act Converting the Sitio of Balud in the Municipality of Salcedo, Province of Samar, into a Barrio, to be Known as the Barrio of Balud","orig":"An Act Converting the Sitio of Balud in the Municipality of Salcedo, Province of Samar, into a Barrio, to be Known as the Barrio of Balud"},"level":"law","status":"active","topics":["general"],"docNumber":"Republic Act No. 2095","issuingBody":"Congress of the Philippines","promulgatedDate":"1959-03-22","completenessNote":"全文，共 2 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1959/ra_2095_1959.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H1834-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"The sitio of Balud in the Municipality of Salcedo, Province of Samar, is converted into a barrio of said municipality, to be known as the barrio of Balud."}},{"id":"PH-H1834-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: March 22, 1959."}}],"pack":"ph-p25"};
  FT["PH-H1835"] = {"id":"PH-H1835","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1959/ra_2096_1959.html","fetchedAt":"2026-10-06","articleCount":2,"structureMode":"ARTICLE","title":{"zh":"将伊莎贝拉省圣阿古斯丁市镇乌尔多甘村更名为拉瓦格村的法案","en":"An Act Changing the Name of the Barrio of Uldogan in the Municipality of San Agustin, Province of Isabela, to Laoag","orig":"An Act Changing the Name of the Barrio of Uldogan in the Municipality of San Agustin, Province of Isabela, to Laoag"},"level":"law","status":"active","topics":["general"],"docNumber":"Republic Act No. 2096","issuingBody":"Congress of the Philippines","promulgatedDate":"1959-03-22","completenessNote":"全文，共 2 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1959/ra_2096_1959.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H1835-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"The name of the barrio of Uldogan in the Municipality of San Agustin, Province of Isabela, is changed to Laoag."}},{"id":"PH-H1835-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: March 22, 1959."}}],"pack":"ph-p25","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act Changing the Name of the Barrio of Uldogan in the Municipality of San Agustin, Province of Isabela, to Laoag","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
